window.HADITH_DATA=[{"id": "65050", "number": 1, "title": "Revelation at the age of forty", "section": 1, "sectionTitle": "Receiving revelation", "slug": "01-revelation-at-the-age-of-forty", "ref": "Sahih al-Bukhari 3851", "primary": "https://sunnah.com/bukhari:3851", "source": "https://hadeethenc.com/en/browse/hadith/65050", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/65050", "ar": "عَنِ ‌ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أُنْزِلَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ ابْنُ أَرْبَعِينَ، فَمَكَثَ بِمَكَّةَ ثَلَاثَ عَشْرَةَ سَنَةً، ثُمَّ أُمِرَ بِالْهِجْرَةِ، فَهَاجَرَ إِلَى الْمَدِينَةِ، فَمَكَثَ بِهَا عَشْرَ سِنِينَ، ثُمَّ تُوُفِّيَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ.", "en": "Ibn ‘Abbās (may Allah be pleased with him) reported: The Messenger of Allah (may Allah’s peace and blessings be upon him) received divine revelation at the age of forty. He spent 13 years in Makkah. Then, he was commanded to immigrate, and he immigrated to Madīnah, where he stayed for 10 years. Then, he (may Allah’s peace and blessings be upon him) passed away.", "ur": "ابن عباس رضی اللہ عنہما سے مروی ہے، وہ کہتے ہیں: رسول اللہ ﷺ پر چالیس سال کی عمر میں وحی نازل ہوئی۔ پھر آپ تیرہ سال مکہ مکرمہ میں رہے۔ اس کے بعد آپ کو ہجرت کا حکم ہوا تو آپ نے مدینہ طیبہ کی طرف ہجرت فرمائی اور آپ نے وہاں دس برس قیام فرمایا۔ اس کے بعد آپ ﷺ نے وفات پائی۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "Ibn ‘Abbās (may Allah be pleased with him) reports that revelation was sent down to the Messenger of Allah (may Allah's peace and blessings be upon him) and his prophetic mission began at the age of forty, and he stayed in Makkah for 13 years after the revelation. Thereafter, he was commanded to immigrate to Madīnah, where he stayed for 10 years. Then, he (may Allah's peace and blessings be upon him) passed away at the age of sixty-three.", "explanationUr": "عبداللہ بن عباس رضی اللہ عنہما بتا رہے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم پر وحی کے نزول کا آغاز اور آپ کی بعثت چالیس سال کی عمر میں ہوئی۔ نزول وحی کے بعد آپ تیرہ سال تک مکہ میں رہے۔ اس کے بعد آپ کو مدینے کی طرف ہجرت کا حکم دیا گیا اور آپ نے وہاں دس سال قیام کیا۔ پھر آپ ترسٹھ سال کی عمر میں وفات پا گئے۔", "hints": ["The Hadīth shows the Companions' interest in the Prophet's biography."], "hintsUr": ["صحابۂ کرام نبی صلی اللہ علیہ وسلم کی سیرت کا خاص اہتمام کیا کرتے تھے۔"], "explanationAr": "يخبر ابن عباس رضي الله عنهما: أن الوحي أنزل على رسول الله صلى الله عليه وسلم وبُعث وعمره أربعون سنة، \nفأقام بمكة ثلاث عشرة سنة بعد الوحي، \nثم أُمِرَ بالهجرة إلى المدينة وأقام بها عشر سنين، \nثم توفي صلى الله عليه وسلم وعمره ثلاثٌ وستون سنة.", "hintsAr": ["اهتمام الصحابة بسيرة النبي صلى الله عليه وسلم."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Ibn Abbas"}, {"id": "66304", "number": 2, "title": "The call after the pause", "section": 1, "sectionTitle": "Receiving revelation", "slug": "02-the-call-after-the-pause", "ref": "Sahih al-Bukhari 4", "primary": "https://sunnah.com/bukhari:4", "source": "https://hadeethenc.com/en/browse/hadith/66304", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/66304", "ar": "عَنْ أبي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الوَحْيِ، فَقَالَ فِي حَدِيثِهِ: «بَيْنَا أَنَا أَمْشِي إِذْ سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي، فَإِذَا المَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَرُعِبْتُ مِنْهُ، فَرَجَعْتُ فَقُلْتُ: زَمِّلُونِي، فَأَنْزَلَ اللَّهُ تَعَالَى: {يَا أَيُّهَا المُدَّثِّرُ1 قُمْ فَأَنْذِرْ} [المدثر: 2] إِلَى قَوْلِهِ {وَالرُّجْزَ فَاهْجُرْ} [المدثر: 5]. فَحَمِيَ الوَحْيُ وَتَتَابَعَ».", "en": "Abu Salamah ibn ‘Abdur-Rahmān reported that Jābir ibn ‘Abdullah al-Ansāri (may Allah be pleased with him and his father) said: While narrating about the halt in revelation, he said in his Hadīth: \"While I was walking, I heard a voice from the sky. I looked up, and there was the angel who had come to me at Hirā’, sitting on a chair between the heaven and the earth. I was terrified of him, so I returned and said: Cover me! Then Allah Almighty revealed: {O you covered [in your cloak], arise and warn} [Surat al-Muddaththir: 1-2] until His saying: {and shun idol worshiping.} [Surat al-Muddaththir: 5] After that, the revelation became intense and continuous.\"", "ur": "ابو سلمہ بن عبد الرحمن سے روایت ہے کہ جابر بن عبد اللہ انصاری رضی اللہ عنہما نے وحی کے توقف کے زمانے کا ذکر کرتے ہوئے اپنی حدیث میں فرمایا: \"میں چل رہا تھا کہ اچانک میں نے آسمان سے ایک آواز سنی، میں نے اپنی نظر اٹھائی تو کیا دیکھتا ہوں کہ وہی فرشتہ جو میرے پاس حرا میں آیا تھا آسمان اور زمین کے درمیان ایک کرسی پر بیٹھا ہوا تھا۔ میں اس سے بہت ڈر گیا، چنانچہ میں واپس آیا اور کہا: مجھے کپڑا اوڑھا دو، تو اللہ تعالیٰ نے یہ آیات نازل فرمائیں: {يَا أَيُّهَا المُدَّثِّرُ1 قُمْ فَأَنْذِرْ} سے لے کر {وَالرُّجْزَ فَاهْجُرْ} تک۔ پھر کثرت سے اور مسلسل وحی آنے لگی۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "The Prophet (ﷺ), while recounting the halt in revelation at the beginning of his mission, said: As I was walking through the alleys of Makkah, I suddenly heard a voice from the sky. I looked up, and there was the angel Jibrīl (Gabriel)—the same one who had come to me in the cave of Hirā’—sitting on a chair between the sky and the earth. I was filled with fear and dread of him, so I returned to my family and said: Wrap me in a cloak. So Allah Almighty revealed: {O you covered} in your cloak, {arise} to call people to the message, {and warn} those who have not yet believed in your message. {And your Lord}—your only true God—{proclaim His greatness} and praise and exalt Him. {And your garments} and clothes {purify them} and clean them from impurities. {And shun the filth}, i.e., the worship of idols and false gods, {and keep away from it} completely. After that, the revelation became strong and continuous.", "explanationUr": "نبی ﷺ نے اپنی بعثت کے ابتدائی زمانے میں وحی کے رک جانے اور اس کے نزول کے بند ہو جانے کا واقعہ بیان کرتے ہوئے فرمایا: میں مکہ کی گلیوں میں چل رہا تھا کہ اچانک میں نے آسمان سے ایک آواز سنی، تو میں نے اپنی نگاہ اٹھائی، تو کیا دیکھتا ہوں کہ وہی فرشتہ جبرئیل علیہ السلام جو میرے پاس غارِ حراء میں تشریف لائے تھے، آسمان اور زمین کے درمیان ایک کرسی پر تشریف فرما ہیں، جس پر میں ان سے مرعوب اور خوف زدہ ہو گیا، چنانچہ میں اپنے اہل خانہ کے پاس واپس آیا اور کہا: ”مجھے کپڑا اوڑھا دو۔“ پھر اللہ تعالیٰ نے نازل فرمایا: {يَا أَيُّهَا المُدَّثِّرُ} یعنی اپنے کپڑوں میں لپٹنے والے، {قُمْ} دعوت کے لیے کھڑے ہو جائیے {فَأَنْذِرْ} اور ان کو خبردار کیجیے جو آپ کی رسالت پر ایمان نہیں لائے ہیں۔ {وَرَبَّكَ} اپنے معبود کی، {فَكَبِّرْ} حمد وعظمت بیان کریں۔ {وَثِيَابَكَ} اپنے لباس کو {فَطَهِّرْ} نجاستوں سے پاک صاف رکھیں، {وَالرُّجْزَ} بتوں اور مورتیوں کی عبادت کو {فَاهْجُرْ} چھوڑ دیں، اس کے بعد وحی میں تیزی آگئی اور کثرت سے نازل ہونے لگی۔", "hints": ["The revelation to the Prophet (ﷺ) ceased for a short period after the descent of Allah's word: {Read}.\r", "It is permissible for a person to speak about the hardships he experienced after they have passed, as an expression of gratitude to Allah Almighty.\r", "The first revelation after: {Read in the name of your Lord Who created} was Allah's saying: {O you covered [in your cloak]}.\r", "The grace of Allah Almighty upon His Prophet (ﷺ) is shown in that He continuously bestowed revelation upon him without interruption until the Prophet (ﷺ) departed from this world.\r", "The obligation to call to Allah Almighty, warning those who turn away, and giving glad tidings to those who obey.\r", "The obligation to purify one's clothes for prayer, as inferred from Allah's saying: {And purify your garments}.\r", "The obligation to believe in the angels and in what Allah has empowered them to do of tasks and other matters."], "hintsUr": ["اللہ عز و جل کے فرمان {اقْرَأْ} کے نزول کے بعد نبی ﷺ پر وحی کا سلسلہ کچھ عرصے کے لیے منقطع ہو گیا۔\r", "آزمائشوں کے زائل ہو جانے کے بعد، اللہ تعالیٰ کا شکر ادا کرتے ہوئے ان کا تذکرہ کرنے کا جواز۔\r", "{اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ} کے نزول کے بعد سب سے پہلے اللہ تعالیٰ کا فرمان {يَا أَيُّهَا الْمُدَّثِّرُ} نازل ہوا۔\r", "اللہ سبحانہ وتعالیٰ کا اپنے نبی ﷺ پر فضل کہ آپ ﷺ پر بغیر انقطاع کے وحی نازل فرماتا رہا، یہاں تک کہ آپ ﷺ دنیا کو چھوڑ گئے۔\r", "دعوت الی اللہ کو قائم کرنے، اعراض کرنے والوں کو ڈرانے  اور اطاعت گزاروں کو بشارت دینے کا وجوب۔\r", "نماز کے لیے کپڑوں کو پاک صاف کرنا واجب ہے، اس پر اللہ تعالی کے فرمان {وَثِيَابَكَ فَطَهِّرْ} سے استدلال کیا گیا ہے۔\r", "فرشتوں پر اور ان اعمال وغیرہ پر جن کی اللہ نے انہیں قدرت دی ہے، ایمان لانا واجب ہے۔"], "explanationAr": "أخبر النبي صلى الله عليه وسلم وهو يحدِّث عن توقُّف الوحي واحتباسه عن النزول في أول بعثته: بينما أنا أمشي في أزقت مكة إذ سمعت صوتًا من السماء، فرفعت بصري، فإذا المَلَك جبريل الذي جاءني بغار حراء جالس على كرسي بين السماء والأرض، فرُعِبْت وفَزعت منه، فرجعت إلى أهلي فقلت: لفُّوني بثوب.\n\n فأنزل الله تعالى: {يَا أَيُّهَا المُدَّثِّرُ} المتلفِّف بثوبه، {قُمْ} بالدعوة {فَأَنْذِرْ} وحذِّر مَن لم يؤمن برسالتك.\n\n {وَرَبَّكَ} وإلهك المعبود {فَكَبِّرْ} واحمده وعظمه.\n\n {وَثِيَابَكَ} وملابسك {فَطَهِّرْ} وخلصها من النجاسات، {وَالرُّجْزَ} بعبادة الأصنام والاوثان {فَاهْجُرْ} واترك، فقَوِيَ الوحيُ بعد ذلك وتكاثر.", "hintsAr": ["انقطاع الوحي عن النبي صلى الله عليه وسلم يسيرًا بعد نزول قوله عز وجل: {اقْرَأْ}.", "جواز تحدُّث الإنسان بما حصل له من المِحن بعد زوالها، شكرًا لله تعالى.", "أول ما نزل قوله تعالى: {يَا أَيُّهَا الْمُدَّثِّرُ} بعد نزول: {اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ}.", "فضل الله سبحانه وتعالى على نبيه صلى الله عليه وسلم حيث أفاض عليه وحيه دون انقطاع حتى فارق الدنيا.", "وجوب القيام بالدعوة إلى الله تعالى، وإنذار المُعرِضين وتبشير المطيعين.", "وجوب تطهير الثياب للصلاة، وقد استدلوا على ذلك بقوله تعالى: {وَثِيَابَكَ فَطَهِّرْ}.", "وجوب الإيمان بالملائكة وبما أقدرهم الله عليه من الأعمال وغيرها."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Jabir ibn Abdullah"}, {"id": "10840", "number": 3, "title": "The ways revelation came", "section": 1, "sectionTitle": "Receiving revelation", "slug": "03-the-ways-revelation-came", "ref": "Sahih al-Bukhari 2", "primary": "https://sunnah.com/bukhari:2", "source": "https://hadeethenc.com/en/browse/hadith/10840", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/10840", "ar": "عن عائشة أُمِّ المؤمنين رضي الله عنها أنَّ الحارثَ بن هشام رضي الله عنه سأل رسولَ الله صلى الله عليه وسلم فقال: يا رسولَ الله، كيف يأْتِيكَ الوَحْيُ؟ فقال رسول الله صلى الله عليه وسلم : «أحْيانًا يَأْتِيني مِثْلَ صَلْصَلَة الجَرَس، وهو أَشدُّه عليَّ، فيَفْصِمُ عنِّي وقد وَعَيْتُ عنه ما قال، وأحيانًا يتمثَّلُ لي المَلَكُ رَجُلًا فيُكَلِّمُني فأَعِي ما يقول». قالت عائشة رضي الله عنها : ولقد رأيتُه ينزِل عليه الوَحْيُ في اليومِ الشديدِ البرْدِ، فيَفْصِمُ عنه وإنَّ جَبِينَه لَيَتَفَصَّدُ عَرَقًا.", "en": "‘Ā'ishah (may Allah be pleased with her) reported: Al-Hārith ibn Hishām (may Allah be pleased with him) asked the Messenger of Allah (may Allah's peace and blessings be upon him): \"O Messenger of Allah, how does the revelation come to you?\" The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Sometimes it comes to me like the ringing of a bell, and that is the hardest for me. When it leaves me I remember what it has said. And sometimes the angel appears to me in the shape of a man, he talks to me, and I understand what he says.\" ‘Ā'ishah (may Allah be pleased with her) said: \"I saw him when the revelation was descending upon him on a very cold day. When it had left him, his forehead was dripping with sweat.\"", "ur": "اُم المومنین عائشہ رضی اللہ عنہا سے روایت ہے وہ کہتی ہیں کہ حارث بن ہشام رضی اللہ عنہ نے نبی ﷺ سے پوچھا اور کہا یا رسول اللہﷺ! آپ پر وحی کیسے آتی ہے؟ تو آپ ﷺ نے فرمایا: کبھی تو ایسے آتی ہے جیسے گھنٹے کی آواز ہو، اور یہ وحی مجھ پر بہت سخت گزرتی ہے، چنانچہ جب فرشتے کی ساری باتیں مجھے یاد ہو جاتی ہیں تو یہ موقوف ہو جاتی ہے، اور کبھی فرشتہ انسان کی شکل میں میرے پاس آتا ہے، چنانچہ وہ مجھ سے بات کرتا ہے تو میں وہ جو کچھ کہتا ہے اُسے یاد کر لیتا ہوں، عائشہ رضی اللہ عنہا بیان کر تی ہیں کہ میں نے رسول اللہ ﷺ کو دیکھا کہ سخت جاڑے کے دن آپ پر وحی اترتی پھر ختم ہو جاتی اور آپ ﷺ کی پیشانی سے پسینہ پھوٹ نکلتا۔", "grade": "Authentic hadith", "gradeAr": "صحيح", "attribution": "Narrated by Bukhari & Muslim", "explanation": "Al-Hārith ibn Hishām (may Allah be pleased with him) asked the Messenger of Allah (may Allah's peace and blessings be upon him) how the revelation came to him. The Messenger of Allah (may Allah's peace and blessings be upon him) told him that the angel, Jibrīl, would sometimes come to him and his voice communicating the revelation was as strong as the sound of a bell. This form was the hardest on the Prophet (may Allah's peace and blessings be upon him) and afterwards he would be overwhelmed and severely distressed and then it would lift. After this he fully understood and had memorized what the angel had said to him. The angel would make a loud sound when he came down with the revelation to distract the Prophet (may Allah's peace and blessings be upon him) from matters of the worldly life and to make him focus on the sound. The Prophet (may Allah's peace and blessings be upon him) would understand what the angel said to him, as he heard nothing but the angel's voice. \nAt other times, the angel would come to the Prophet (may Allah's peace and blessings be upon him) in the form of a man, such as Dihyah (may Allah be pleased with him) or another man, and communicate the revelation to him, and the Prophet would understand it. \n‘Ā'ishah (may Allah be pleased with her) said that on very cold days, the Prophet's forehead would sweat due to the stress of receiving the revelation.", "explanationUr": "حارث بن ہشام رضی اللہ عنہ نے نبی ﷺ سےپوچھا اور کہا یا رسول اللہﷺ! آپ پر وحی کیسے آتی ہے؟ تو آپ ﷺ نے انہیں بتایا کہ کبھی تو فرشتے (اور وہ جبریل علیہ السلام ہیں جو) وحی لے کر آتے ہیں چنانچہ اس وحی لانے والے فرشتے کی آواز قوت میں گھنٹی کی آواز کی طرح ہوتی ہے اور یہ وحی نبی ﷺ پر بہت سخت اور تکلیف دہ ہوتی تھی جس کی وجہ سے نبی ﷺ بہت سخت مصیبت اور پریشانی میں پڑ جاتے، چنانچہ جب فرشتے کی بتائی ساری باتیں نبیﷺ کو یاد ہو جاتیں اور انہیں سمجھ لیتے تو یہ کیفیت ختم ہو جاتی۔ اس قدر تیز آواز میں وحی آنے کا مقصد یہ ہوتا کہ آپ ﷺ دنیا سے ایک دم غافل ہو جائیں اور ان کا ذہن خالی ہو جائے جس کی بنا پر نبیﷺ اسے سمجھ لیتے کیونکہ اب انہیں اس وحی کے علاوہ ان کے کان اور دل کو کوئی اور آواز سنائی نہیں دیتی۔ نیز آپ ﷺ نے حارث بن ہشام کو مزید بتایا کہ کبھی تو جبریل علیہ السلام انسان کی شکل میں مثلاً دِحیہ کلبی صحابی کی شکل میں، یا ان کے علاوہ کسی دوسرے کی شکل میں میرے پاس آتے ہیں، چنانچہ وہ مجھ سے بات کرتے ہیں تو میں ان کا کہا یاد کر لیتا ہوں۔ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ انہوں نے رسول اللہ ﷺ کو سخت جاڑے کے دن میں آپ پر وحی اترتے ہوئے دیکھا ، پھر جب وحی ختم ہو جاتی تو وحی کی شدت سے آپ ﷺ کی پیشانی سے پسینہ پھوٹ نکلتا، ایسا اس لیے ہوتا کہ وحی کی وجہ سے نبی ﷺ کو بہت سخت مصیبت اور پریشانی ہوتی تھی۔", "hints": [], "hintsUr": [], "explanationAr": "سأل الحارث بن هشام رضي الله عنه رسول الله صلى الله عليه وسلم فقال: يا رسول الله، كيف يأتيك الوحيُ؟ فأخبره رسول الله صلى الله عليه وسلم أنه أحيانًا يأتيه الملك -وهو جبريل- بالوحي فيكون صوت الملك بالوحي مشابهًا لصوت الجرس في قوته، وهو أشد شيء وأصعبه عليه صلى الله عليه وسلم ، وتغشاه شدة وكرب شديد ثم ينكشف عنه، وقد فهم وحفظ عن الملك ما قال، وإنما يأتيه الوحي بهذا الصوت الشديد؛ ليشغله عن أمور الدنيا، ويفرغ حواسه للصوت الشديد، فكان صلى الله عليه وسلم يفهم عنه؛ لأنه لم يبق في سمعه مكان لغير صوت الملك ولا في قلبه.\nوأخبره صلى الله عليه وسلم أنه أحيانًا أخرى يأتيه جبريل في صورة رجل مثل دحية أو غيره، فيكلمه بالوحي فيفهم ما يقوله له ويحفظه.\nوأخبرت عائشة رضي الله عنها أنها كانت ترى النبي صلى الله عليه وسلم عند نزول الوحي عليه في اليوم الشديد البرد فتنكشف عنه شدة الوحي وجبينه يسيل عرقًا من شدة ما يلقاه من الكرب والمعاناة.", "hintsAr": ["شدة الوحي وصعوبته على النبي -صلى الله عليه وسلم-.", "من الصفات التي كان ينزل بها الوحي على النبي -صلى الله عليه وسلم-, أن يكون صوت الملك بالوحي مشابهًا لصوت الجرس في قوته وهو أشد شيء وأصعبه عليه -صلى الله عليه وسلم-، كما كان جبريل يأتيه بالوحي في صورة رجلٍ أحيانًا.", "أن السؤال عن الكيفية لطلب المعرفة أو الطمأنينة لا يقدح في اليقين.", "جواز السؤال عن أحوال الأنبياء من الوحي وغيره.", "أن أصحاب رسول الله -صلى الله عليه وسلم- كانوا يسألونه -صلى الله عليه وسلم- عن كثير من المعاني، وكان رسول الله -صلى الله عليه وسلم- يجيبهم، ويعلمهم، وكانت طائفة منهم تسأل، وطائفة تحفظ، وكلهم أدّى، وبلّغ ما علم، ولم يكتم حتى أكمل الله دينه."], "words": [{"word": "صَلْصَلَة", "meaning": " صوت."}, {"word": "فيَفْصِمُ عنِّي", "meaning": " يُقلع عني وينجلي ما يغشاني منه."}, {"word": "وَعَيْتُ", "meaning": " حفظت الذي ذكره"}, {"word": "يتمثَّل", "meaning": " يتصوَّر."}, {"word": "جَبِينه", "meaning": " ما بين منبت الشعر والحاجبين."}, {"word": "يَتَفَصَّدُ", "meaning": " يسيل."}, {"word": "الوحي", "meaning": " في اللغة الإشارة والرسالة والكتابة, وكل ما ألقي إلى شخص ليعلمه وحي كيف كان, ثم غلب استعمال الوحي فيما يلقى إلى الأنبياء من عند الله -تعالى-."}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Aishah"}, {"id": "10841", "number": 4, "title": "The weight of revelation", "section": 1, "sectionTitle": "Receiving revelation", "slug": "04-the-weight-of-revelation", "ref": "Sahih Muslim 2334", "primary": "https://sunnah.com/muslim:2334", "source": "https://hadeethenc.com/en/browse/hadith/10841", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/10841", "ar": "عن عبادة بن الصامت رضي الله عنه ، قال: «كان نبيُّ اللهِ صلى الله عليه وسلم إذا أُنْزِلَ عليه الوحيُ كُرِبَ لذلك وتَرَبَّدَ وجهُه».", "en": "‘Ubādah ibn As-Sāmit (may Allah be pleased with him) reported: When the Messenger of Allah (may Allah's peace and blessings be upon him) received revelation, he felt distressed and the color of his face changed", "ur": "عبادہ بن صامت رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: ”جب اللہ کے نبی ﷺ پر وحی نازل ہوتی، تو اس کی وجہ سے آپ کو تکلیف پہنچتی اور آپ کے چہرے کا رنگ متغیر ہو جاتا تھا“۔", "grade": "Authentic hadith", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "Whenever the Prophet (may Allah's peace and blessings be upon him) received revelation, he would experience hardship and distress to the extent that the color of his face would change due to the gravity and difficulty of that matter. Besides, the Prophet (may Allah's peace and blessings be upon him) paid much attention and care to the revelation and showed great awe to whatever he was asked to observe, such as fulfilling the rights of servitude, showing due gratefulness to Allah, the Almighty, and glorifying His commands and reports.", "explanationUr": "نبی ﷺ پر جب وحی نازل ہوتی تھی ،تو نزول وحی کے بوجھ اور اس کے حصول کی پریشانی کی وجہ سے آپ کو بے چینی و تکلیف لاحق ہوتی اور آپ کے چہرے کا رنگ متغیر ہو جاتا تھا۔ آپ ﷺ وحی کا بشدت اہتمام کرتے، حقوقِ بندگی اور شکرِ الٰہی کی بجا آوری کے متعلق مطالبۂ وحی سے ڈرتے تھے اور اللہ تعالیٰ کے حکم و خبر کی تعظیم کرتے تھے۔", "hints": [], "hintsUr": [], "explanationAr": "كان النبي صلى الله عليه وسلم إذا نزل عليه الوحي أصابه الكرب والشدة لذلك وتغير وجهه؛ لثقل نزول الوحي وصعوبة حصوله، وقد كان صلى الله عليه وسلم يهتم بأمر الوحي أشد الاهتمام، ويهاب مما يطالَب به من حقوق العبودية والقيام بشكر الله تعالى ويعظم أمر الله -تعالى وخبره.", "hintsAr": ["ما كان يحصل للنبي -صلى الله عليه وسلم- من الكرب والتغير أثناء نزول الوحي؛ لعظم موقعه, كما قال الله -تعالى-: {إنا سنلقي عليك قولًا ثقيلًا}.", "في هذا الحديث بيان أحد الصفات التي كان ينزل بها الوحي على النبي -صلى الله عليه وسلم-."], "words": [{"word": "كُرِبَ", "meaning": " أَصَابَهُ الْكَرْبُ لِشِدَّةِ نُزُولِ الوحي عليه وَصُعُوبَةِ حُصُولِهِ."}, {"word": "تَرَبَّدَ", "meaning": " تغير."}, {"word": "الوحي", "meaning": " هو في اللغة الإشارة والرسالة والكتابة, وكل ما ألقي إلى الغير ليعلمه وحي كيف كان, ثم غلب استعمال الوحي فيما يلقى إلى الأنبياء من عند الله -تعالى-."}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Ubadah ibn al-Samit"}, {"id": "10843", "number": 5, "title": "Listening before reciting", "section": 1, "sectionTitle": "Receiving revelation", "slug": "05-listening-before-reciting", "ref": "Sahih al-Bukhari 5", "primary": "https://sunnah.com/bukhari:5", "source": "https://hadeethenc.com/en/browse/hadith/10843", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/10843", "ar": "عن ابن عباس رضي الله عنهما في قوله تعالى: {لا تُحَرِّكْ به لسانَك} [القيامة: 16]، قال: «كان النبيُّ صلى الله عليه وسلم يُعالِجُ مِن التنزيل شِدَّةً، وكان يُحَرِّكُ شَفَتَيْهِ» فقال لي ابنُ عباس: فأنا أُحَرِّكُهما لك كما كان رسولُ الله صلى الله عليه وسلم يُحَرِّكُهما، فقال سعيد: أنا أُحَرِّكُهما كما كان ابنُ عباس يُحَرِّكُهما، فحرَّك شَفَتَيْهِ فأنزل اللهُ -عزَّ وجلَّ-: {لا تُحَرِّكْ به لسانَك لِتَعْجَلَ به إنَّ علينا جَمْعَه وقُرآنَه} [القيامة: 17]، قال: «جَمْعَه في صدرك ثم تقرؤه»، {فإذا قرأناه فاتَّبِعْ قُرآنه} [القيامة: 18] قال: «فاستمِع له وأَنْصِتْ، ثم إنَّ علينا أن تقْرَأه، قال: فكان رسول الله صلى الله عليه وسلم إذا أتاه جبريل عليه السلام استمع، فإذا انطلقَ جبريلُ قرأه النبي صلى الله عليه وسلم كما أقرَأَه».", "en": "Ibn ‘Abbās (may Allah be pleased with him) commented about the verse: {Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur'an} [Sūrat al-Qiyāmah: 16], saying: \"The Prophet (may Allah's peace and blessings be upon him) used to experience hardship while the revelation was being sent down upon him, and he used to move his lips (quickly) with what was being revealed to him.\" Ibn ‘Abbās moved his lips saying: \"I am moving my lips in front of you as the Messenger of Allah (may Allah's peace and blessings be upon him) used to move his.\" Sa‘īd (the sub-narrator) also moved his lips saying: \"I am moving my lips just as I saw Ibn ‘Abbās moving his.\" Ibn ‘Abbās added: \"So Allah revealed the following verses: {Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur'an. Indeed, upon Us is its collection [in your heart] and [to make possible] its recitation.} [Sūrat al-Qiyāmah: 16-17] which means that Allah will make him (the Prophet) remember the portion of the Qur'an which was revealed to him at that time by heart and recite it. Then the verse that followed these two was: {So when We have recited it [through Jibrīl], then follow its recitation} [Sūrat al-Qiyāmah: 18] It means ''listen to it and be silent. Then, it is (for Allah) to make you recite it.\" Afterwards, the Messenger of Allah (may Allah's peace and blessings be upon him) used to listen to Jibrīl whenever he came to him, and after his departure he used to recite it just as Jibrīl taught him to recite it.\"", "ur": "ابن عباس رضی اللہ عنہما سے روايت ہے کہ انہوں نے اللہ تعالیٰ کے فرمان: ﴿لا تُحَرِّكْ به لسانَكَ﴾ (القیامۃ: 16) کی تفسیر میں فرمایا کہ نبی ﷺ نزولِ قرآن کے وقت بہت سختی محسوس فرمایا کرتے تھے اور اپنے ہونٹوں کو ہلاتے تھے۔ مجھے ابن عباس رضی اللہ عنہما نے کہا کہ میں تمہیں ویسے ہی اپنے ہونٹ ہلا کر دکھاتا ہوں جس طرح آپ ﷺ ہلاتے تھے۔ سعید بن جبیر رحمہ اللہ کہتے ہیں کہ میں بھی اپنے ہونٹ ویسے ہی ہلاتا ہوں جیسے ابن عباس رضی اللہ عنہما نے ہلائے۔ یہ کہہ کر انہوں نے اپنے ہونٹ ہلائے۔ پھر یہ آیت نازل ہوئی: ﴿لا تُحَرِّكْ به لسانَك لِتَعْجَلَ به إنَّ علينا جَمْعَه وقُرآنَه﴾ ”اے محمد! قرآن کو جلد جلد یاد کرنے کے لیے اپنی زبان نہ ہلاؤ، اس کا جمع کر دینا اور پڑھا دینا ہمارے ذمہ ہے“۔ (القیامۃ: 17)\nابن عباس رضی اللہ عنہما کہتے ہیں کہ اس سے مراد ہے ”قرآن آپ ﷺ کے دل میں جمع دینا اور پڑھا دینا ہمارے ذمہ ہےں، ﴿فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ﴾ ”پھر جب ہم پڑھ چکیں تو اس پڑھے ہوئے کی اتباع کرو“ (القیامۃ: 18)\nابن عباس رضی اللہ عنہما فرماتے ہیں: (اس کا مطلب یہ ہے) کہ آپ اس کو خاموشی کے ساتھ سنتے رہیں۔ پھر یقیناً یہ ہماری ذمہ داری ہے کہ آپ اس کو پڑھیں (یعنی اس کو محفوظ کر سکیں)۔ چنانچہ اس کے بعد جب رسول الله ﷺ کے پاس جبرائیل علیہ السلام آتے تو آپ ﷺ اسے (توجہ سے) سنتے۔ جب وہ چلے جاتے تو نبی ﷺ اس (وحی) کو اسی طرح پڑھتے جس طرح جبرائیل علیہ السلام نے اسے پڑھایا ہوتا تھا۔", "grade": "Authentic hadith", "gradeAr": "صحيح", "attribution": "Narrated by Bukhari & Muslim", "explanation": "Ibn ‘Abbās (may Allah be pleased with him) says that the Prophet (may Allah's peace and blessings be upon him) used to experience hardship and intense stress while the revelation was being sent down upon him. He used to move his lips with what he received from Jibrīl before Jibrīl had finished the revelation, fearing that he would not be able to memorize it before Jibrīl left. Ibn ‘Abbās described to his student Sa‘īd ibn Jubayr how the Prophet moved his lips. This indicates that Ibn ‘Abbās had seen the Prophet in that state. Sa‘īd, likewise, described it to his students. Allah, the Exalted, sent down a verse commanding the Prophet not to move his tongue with the Qur'an to hasten in receiving it, for Allah ensured that the Qur'an would be collected in the Prophet's heart. Then, Allah, the Almighty, revealed another verse telling the Prophet to listen attentively when Jibrīl recited the Qur'an to him, for Allah ensured that the Prophet would recite it just as Jibrīl had recited it. Later on, when Jibrīl came to the Prophet with revelation, the Prophet would listen to him, and when Jibrīl had departed, the Prophet would read the Qur'an as Jibrīl taught him to read it.", "explanationUr": "ابن عباس رضی اللہ عنہما بتا رہے ہیں کہ نبی ﷺ نزولِ وحی کے وقت بہت زیادہ سختی اور بے چینی محسوس کرتے تھے۔ جبرائیل علیہ السلام کے وحی مکمل کرنے سے پہلے ہی آپ ﷺ جو کچھ ان سے سنتے اسے اپنے ہونٹوں کو ہلا کر پڑھنا شروع کر دیتے اس اندیشے کے پیش نظر کہ کہیں یہ نہ ہو کر آپ ﷺ کے یاد کر لینے سے پہلے ہی جبرائیل علیہ السلام چلے جائیں۔ ابن عباس رضی اللہ عنہ نے اپنے شاگرد سعید بن جبیر رحمہ اللہ کے سامنے بیان کیا کہ نبی ﷺ کیسے اپنے ہونٹوں کو حرکت دیا کرتے تھے جس سے یہ معلوم ہوتا ہے کہ ابن عباس رضی اللہ عنہ نے رسول اللہ ﷺ کو اس حالت میں دیکھا تھا اور اس کو سعید بن جبیر رحمہ اللہ نے بھی اپنے شاگردوں کے سامنے بیان کیا۔\nاس پر اللہ تعالیٰ نے یہ آیت نازل فرمائی ﴿لا تُحَرِّكْ به لسانَك لِتَعْجَلَ به إنَّ علينا جَمْعَه وقُرآنَه﴾ یعنی قرآن کو جلدی جلدی لینے کی غرض سے اپنی زبان کو نہ ہلاؤ۔ اسے جمع کرنا اور تمہارے سینے میں بٹھا دینا ہماری ذمہ داری ہے۔ پھر اللہ تعالیٰ نے فرمایا ﴿فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ﴾ یعنی جب جبرائیل پڑھ کر فارغ ہو جائیں تو (اس کے پیچھے پیچھے پڑھو) اور خاموشی کے ساتھ سنو۔ پھر تمہارا بعینہ اسی طرح پڑھانا ہماری ذمہ داری ہے۔ اس کے بعد رسول اللہ ﷺ کے پاس جب بھی جبرائیل علیہ السلام تشریف لاتے تو آپ ﷺ خاموشی سے سنتے اور جب وہ چلے جاتے تو نبی ﷺ اس وحی کو ویسے ہی پڑھتے جیسے جبرائیل علیہ السلام نے آپ ﷺ کو پڑھایا ہوتا۔", "hints": [], "hintsUr": [], "explanationAr": "يخبر ابن عباس رضي الله عنهما أن النبي صلى الله عليه وسلم كان يعاني عند نزول الوحي شدة وهمًّا عظيمًا، فكان يحرك شفتيه بما قد سمعه من جبريل قبل إتمام جبريل الوحي، مخافة أن يذهب عنه جبريل قبل أن يحفظه، وقد وصف ابن عباس لتلميذه سعيد بن جبير كيفية تحريك النبي صلى الله عليه وسلم لشفتيه، مما يدل على أن ابن عباس قد شاهد رسول الله صلى الله عليه وسلم في تلك الحالة، ووصف سعيد ذلك أيضًا لتلاميذه،\nفأنزل اللهُ -عزَّ وجلَّ-: {لا تُحَرِّكْ به لسانَك لِتَعْجَلَ به إنَّ علينا جَمْعَه وقُرآنَه}، أي: لا تحرك لسانك بالقرآن لتسارع بأخذه، فإن علينا جمعه وضمه في صدرك، ثم قال تعالى : {فإذا قرأناه فاتَّبِعْ قُرآنه} أي: إذا فرغ جبريل من قراءته فاستمع وأنصت. ثم إنَّ علينا أن تقرأه كما هو، قال: فكان رسول الله صلى الله عليه وسلم بعد ذلك إذا أتاه جبريل -عليه السلام- استمع، فإذا انطلق جبريلُ قرأه النبي صلى الله عليه وسلم كما أقرأه جبريل.", "hintsAr": ["بيان ما كان النبي -صلى الله عليه وسلم- يلقاه من معالجة الشدة عند نزول الوحي عليه، وذلك لثقل الوحي، كما قال الله -تعالى-: {إِنَّا سَنُلْقِي عَلَيْكَ قَوْلًا ثَقِيلًا} [المزمل: 5].", "أنه -صلى الله عليه وسلم- كان يحرك شفتيه، لئلا ينسى، وقيل: إنما كان يفعل ذلك من حبه له، وحلاوته في لسانه، فنهي عن ذلك حتى يجتمع، لأن بعضه مرتبط لبعضه.", "أن الله -تعالى- تكفل لرسوله -صلى الله عليه وسلم- أن لا ينسى القرآن، وأنه كان بعد نزول هذه الآية يستمع، وينصت لجبريل، فإذا انتهى جبريل من قراءته، وذهب من عنده، قرأه النبي -صلى الله عليه وسلم- على أصحابه كما أقرأه، من غير زيادة، ولا نقص، كما قال -تعالى-: {سَنُقْرِئُكَ فَلَا تَنْسَى} [الأعلى: 6].", "وجوب اتباع القرآن والإنصات إليه.", "أن فيه إشارة إلى أن أحدًا لا يحفظ القرآن إلا بعون الله -تعالى- وفضله، كما قال الله -تعالى-: {وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ (17)} [القمر: 17]."], "words": [{"word": "يُعالِج", "meaning": " يتحمل ويعاني."}, {"word": "لتَعْجل به", "meaning": " لتأخذه على عجلة."}, {"word": "قُرآنه", "meaning": " قراءته."}, {"word": "فاستمع له، وأنصِتْ", "meaning": " الاستماع أخص من الإنصات، لأن الاستماع: الإصغاء، والإنصات: السكوت، ولا يلزم من السكوت الإصغاء، فقد يستمع، ولا ينصت، فلهذا جُمِعَ بينهما، كما قال الله -تعالى-: {فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا} [الأعراف: 204]."}, {"word": "في قوله -تعالى", "meaning": " أي في توضيحِ معانيه، وبيان سبب نزوله."}, {"word": "فَإِذَا قَرَأْنَاهُ", "meaning": " أي إذا تلاه عليك جبريل -عليه السلام-."}, {"word": "فَاتَّبِعْ قُرْآنَهُ", "meaning": " فاستمع له، ثم اقرأه كما أقرأك."}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Ibn Abbas"}, {"id": "65051", "number": 6, "title": "Recognizing the surah divisions", "section": 1, "sectionTitle": "Receiving revelation", "slug": "06-recognizing-the-surah-divisions", "ref": "Sunan Abi Dawud 788", "primary": "https://sunnah.com/abudawud:788", "source": "https://hadeethenc.com/en/browse/hadith/65051", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/65051", "ar": "عَنِ ‌ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَليهِ وَسَلَّمَ لا يَعْرِفُ فَصْلَ السُّورةِ حَتَّى تَنْزِلَ عَليْهِ {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ}.", "en": "Ibn ‘Abbās (may Allah be pleased with him) reported: The Prophet (may Allah’s peace and blessings be upon him) did not know where Surahs were to be separated until \"In the name of Allah, the Most Compassionate, the Most Merciful\" was revealed to him.", "ur": "ابن عباس رضی اللہ عنہما سے مروی ہے، وہ کہتے ہیں: نبی کریم ﷺ کو ایک سورت ختم ہوکر دوسری سورت شروع ہونے کا علم اس وقت تک نہ ہوتا، جب تک آپ پر «بسم الله الرحمن الرحيم» نہ اترتی۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Abu Dāwūd", "explanation": "Ibn ‘Abbās (may Allah be pleased with him) points out that the Qur’an's surahs would reveal to the Prophet (may Allah's peace and blessings be upon him) while he did not know where they should end and be separated, until \"In the name of Allah, the Most Compassionate, the Most Merciful\" was revealed to him; thereupon, he knew that the previous surah came to an end and this was the beginning of a new surah.", "explanationUr": "عبداللہ بن عباس رضی اللہ عنمہا بتا رہے ہیں کہ قرآن کریم کی سورتیں اللہ کے نبی صلی اللہ علیہ وسلم پر اترتیں اور آپ کو یہ پتہ نہیں چلتا کہ ایک سورت ختم ہوکر دوسری سورت کہاں ختم ہو رہی ہے، یہاں تک کہ (بسم اللہ الرحمن الرحیم) نازل ہوتی، جس سے آپ سمجھ جاتے کہ سابقہ سورت ختم ہوگئی ہے اور ایک نئی سورت شروع ہونے والی ہے۔", "hints": ["Basmalah \"In the name of Allah, the Most Compassionate, the Most Merciful\" separates between surahs, except between Surat al-Anfāl and Surat at-Tawbah."], "hintsUr": ["بسم اللہ کے ذریعہ دو سورتوں کے درمیان فاصلہ ڈالا جاتا ہے سوائے سورہ انفال اور سورہ توبہ کے۔"], "explanationAr": "يُبَيِّن ابن عباس رضي الله عنهما أن سور القرآن الكريم كانت تنزل على النبي صلى الله عليه وسلم ولا يَعرف انفصالَها وانتهاءها، حتى تنزل عليه: \"بسم الله الرحمن الرحيم\"، فيَعلم أن السورة السابقة قد خُتمت، وأنها بداية لسورة جديدة.", "hintsAr": ["البسملة يُفصَل بها بين السُّور، إلا بين سورة الأنفال وسورة التوبة."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Ibn Abbas"}, {"id": "65231", "number": 7, "title": "Revelation as an enduring sign", "section": 1, "sectionTitle": "Receiving revelation", "slug": "07-revelation-as-an-enduring-sign", "ref": "Sahih al-Bukhari 4981", "primary": "https://sunnah.com/bukhari:4981", "source": "https://hadeethenc.com/en/browse/hadith/65231", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/65231", "ar": "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَا مِنَ الأَنْبِيَاءِ نَبِيٌّ إِلَّا أُعْطِيَ مَا مِثْلهُ آمَنَ عَلَيْهِ البَشَرُ، وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَاهُ اللَّهُ إِلَيَّ، فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ القِيَامَةِ».", "en": "Abu Hurayrah (may Allah be pleased with him) reported: The Prophet (ﷺ) said: \"There was no prophet among the prophets except that he was given miracles through which people believed in him. But what I have been given is a revelation which Allah has revealed to me, and I hope to have the most followers among them on the Day of Judgment.\"", "ur": "ابو ہریرہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ اللہ کے نبی ﷺ نے فرمایا: \"ہر نبی کو ایسی نشانیاں دی گئیں جن کی مثل پر لوگ ایمان لائے، اور مجھے جو (معجزہ) دیا گیا ہے وہ وحی ہے جو اللہ نے میری طرف بھیجی ہے، چنانچہ میں امید کرتا ہوں کہ قیامت کے دن میرے پیروکار ان سب سے زیادہ ہوں گے\"۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "The Prophet (ﷺ) mentioned that all the prophets were supported by Allah and were given miraculous signs that served as proof of their prophethood and led those who witnessed them to believe in their truthfulness. These miracles were beyond human ability to challenge or resist, though some people might still deny them out of stubbornness and arrogance. As for the Prophet (ﷺ), his sign and miracle is the Qur’an that Allah revealed to him, for it contains a clear and everlasting miracle due to its immense benefit and universal guidance. It includes the call to truth, decisive proof, and knowledge of what is yet to come. Thus, its benefit extends to those present and absent, to those who have existed and those who will exist. Then he said: I hope to be the one among them with the greatest number of followers on the Day of Judgment.", "explanationUr": "نبی ﷺ نے ذکر فرمایا کہ اللہ تعالى نے تمام انبیاء کرام کی تائید فرمائی اور انہیں ایسی خارق عادت آیات اور معجزات عطا فرمائے جن سے آپ کی نبوت پر استدلال کیا جاتا ہے اور جو آپ کے دیکھنے والوں سے آپ کی سچائی پر ایمان لانے کا تقاضا کرتے ہیں، نیز یہ کہ چیلنج کے مقابلے میں وہ عاجز آجاتا ہے، اس طور پر کہ وہ اسے خود سے دفع کرنے کی استطاعت نہیں رکھتا، لیکن بسا اوقات وہ انکار کرتا اور عناد برتتا ہے۔ آپﷺ کا معجزہ اور نشانی وہ قرآن ہے جسے اللہ نے آپ کی طرف وحی کی۔ یہ اپنے کثیر فائدے، عمومی افادیت، دعوت وحجت اور مستقبل کی خبروں پر مشتمل ہونے کی وجہ سے ایک واضح اور دائمی معجزہ ہے۔ چنانچہ اس کی افادیت ہر حاضر وغائب اور ہر موجود اور آئندہ آنے والے کے لیے عام ہو گئی۔ پھر آپ ﷺ نے فرمایا: اس لیے مجھے امید ہے کہ قیامت کے دن سب سے زیادہ پیروکار میرے ہوں گے۔", "hints": ["Affirmation of the miracles granted to the prophets, and this is from Allah's mercy and grace upon the nations.\r", "Highlighting the greatness of the Prophet's miracle.\r", "Highlighting the great status of the Prophet (ﷺ) and his superiority over all other prophets.\r", "Ibn Hajar said regarding the Prophet's words: \"But what I have been given is revelation which Allah has revealed to me\": The meaning is not to confine all his miracles to this one, nor to deny that he was granted other miracles like those given to previous prophets; rather, the intent is that the Qur’an is his greatest and most distinctive miracle, unique to him alone.\r", "An-Nawawi said: (And I hope to have the most followers among them)— this is one of the signs of his prophethood, for the Prophet (ﷺ) said this at a time when the number of Muslims was very small. Then Allah Almighty bestowed His grace, granted victory to the Muslims, and blessed them until Islam spread far and wide to the extent we see today—and all praise is due to Allah."], "hintsUr": ["انبیاء کے لیے نشانیوں کا اثبات امتوں پر اللہ تعالیٰ کی رحمت اور اس کا فضل ہے۔\r", "نبی ﷺ کے عظیم معجزے کا بیان۔\r", "نبی ﷺ کی عظمتِ شان اور تمام انبیائے کرام پر آپ ﷺ کی فضیلت وبرتری کا بیان۔\r", "ابن حجر آپ ﷺ کے فرمان ”وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَاهُ اللَّهُ إِلَيَّ“ کے بارے میں فرماتے ہیں: اس سے مراد آپ ﷺ کے معجزات کو اسی میں محصور کرنا نہیں ہے، اور نہ یہ کہ آپ ﷺ کو وہ معجزات عطا نہیں ہوئے جو آپ سے پہلے انبیاء کو دیے گئے تھے، بلکہ مراد یہ ہے کہ یہ (قرآن) وہ عظیم ترین معجزہ ہے جس کے ذریعہ آپ ﷺ کو دیگر انبیاء پر فضیلت دی گئی ہے۔\r", "امام نووی فرماتے ہیں: ”فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا“ یہ نبوت کی نشانیوں میں سے ایک نشانی ہے، کیونکہ آپ ﷺ نے اس کی خبر مسلمانوں کی قلت کے زمانے میں دی تھی، پھر اللہ تعالیٰ نے احسان فرمایا، مسلمانوں کو فتوحات عطا کیں اور ان میں برکت ڈالی، یہاں تک کہ مسلمانوں کا معاملہ اس معروف حد تک جا پہنچا اور وسیع ہو گیا، وللہ الحمد۔"], "explanationAr": "ذكر النبي صلى الله عليه وسلم أن الأنبياء كلهم أيَّدَهم الله وأعطاهم الآيات والمعجزات الخوارق التي يستدل بها على نبوته وتقتضي إيمان من شاهدها بصدقهم، وأنه مغلوب عليه في التحدي بحيث لا يستطيع دفعها عن نفسه، لكن قد يجحد فيعاند.\n\nوإنما هو صلى الله عليه وسلم آيته ومعجزته القرآن الذي أوحاه الله إليه؛ لما اشتمل عليه من الإعجاز الواضح المستمر لكثرة فائدته وعموم نفعه، لاشتماله على الدعوة والحجة والإخبار بما سيكون، فعم نفعه من حضر ومن غاب ومن وجد ومن سيوجد، ثم قال: فأرجو أن أكون أكثرهم أتباعًا يوم القيامة.", "hintsAr": ["إثبات الآيات للأنبياء، وهذا من رحمة الله تعالى وفضله على الأمم.", "بيان عظم معجزة النبي صلى الله عليه وسلم.", "بيان عظم منزلة النبي صلى الله عليه وسلم وأفضليته على سائر الأنبياء.", "قال ابن حجر في قوله: \"وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَاهُ اللَّهُ إِلَيَّ\": وليس المراد حصر معجزاته فيه، ولا أنه لم يؤتَ من المعجزات ما أوتي مَن تقدَّمه، بل المراد أنه المعجزة العظمى التي اختص بها دون غيره.", "قال النووي: \"(فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا) علم من أعلام النبوة، فإنه أخبر صلى الله عليه وسلم بهذا في زمن قلة المسلمين، ثم منَّ الله تعالى وفتح على المسلمين وبارك فيهم حتى انتهى الأمر واتسع الأمر في المسلمين إلى هذه الغاية المعروفة ولله الحمد."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Hurayrah"}, {"id": "4217", "number": 8, "title": "Revelation near the end of his life", "section": 1, "sectionTitle": "Receiving revelation", "slug": "08-revelation-near-the-end-of-his-life", "ref": "Sahih al-Bukhari 4982", "primary": "https://sunnah.com/bukhari:4982", "source": "https://hadeethenc.com/en/browse/hadith/4217", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/4217", "ar": "عن أنس بن مالك رضي الله عنه مرفوعاً: إن الله عز وجل تابع الوحي على رسول الله صلى الله عليه وسلم قبل وفاته حتَّى تُوُفِّيَ أكثر ما كان الوحي.", "en": "Anas ibn Mālik (may Allah be pleased with him) reported: Allah, Exalted and Glorified, sent down the Divine Revelation to the Messenger of Allah (may Allah's peace and blessings be upon him) abundantly during the period preceding his death until he died at a time when the revelation had never been more abundant.", "ur": "انس بن مالک رضی اللہ عنہ سے روایت ہے وہ فرماتے ہیں کہ اللہ عز و جل رسول اللہ ﷺ کی وفات سے پہلے آپ پر پہ در پہ وحی نازل فرماتا رہا یہاں تک کہ آپ ﷺ کی وفات اس وقت ہوئی جب کثرت کے ساتھ وحی نازل ہو رہی تھی۔", "grade": "Authentic hadith", "gradeAr": "صحيح", "attribution": "Narrated by Bukhari & Muslim", "explanation": "Allah, Exalted and Glorified, increased the revelation that was sent down to the Messenger of Allah (may Allah's peace and blessings be upon him) before his death to complete the Shariah, up until the Messenger (may Allah's peace and blessings be upon him) died at a time when the revelation was most abundant.", "explanationUr": "اللہ عز و جل نے رسول اللہ ﷺ پر آپ ﷺ کی وفات سے پہلے کثرت کے ساتھ وحی نازل کی تاکہ شریعت مکمل ہوجائے یہاں تک کہ جب کثرت کے ساتھ وحی کا نزول ہو رہا تھا تو اس وقت آپ ﷺ کی وفات ہوئی۔", "hints": [], "hintsUr": [], "explanationAr": "أكثر الله عز وجل من إنزال الوحي على رسول الله صلى الله عليه وسلم قبل وفاته؛ حتى تكمل الشريعة؛ حتى توفي الرسول صلى الله عليه وسلم في وقت كثرة نزوله.", "hintsAr": ["تكامل نزول الوحي قبل وفاته -صلى الله عليه وسلم-.", "تتابع الوحي في آخر الرسالة بخلاف أولها حين انقطع فترة."], "words": [{"word": "تابع الوحي", "meaning": " أي: أكثر إنزال ما يوحى إلى النبي -صلى عليه وسلم- من قرآن وشرائع قُرب وفاته."}, {"word": "حتى توفي أكثر ما كان الوحي", "meaning": " أي: توفي النبي -صلى الله عليه وسلم- وقت نزول الوحي بكثرة."}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Anas ibn Malik"}, {"id": "4947", "number": 9, "title": "Obedience and the path to Paradise", "section": 2, "sectionTitle": "Following the Messenger", "slug": "09-obedience-and-the-path-to-paradise", "ref": "Sahih al-Bukhari 7280", "primary": "https://sunnah.com/bukhari:7280", "source": "https://hadeethenc.com/en/browse/hadith/4947", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/4947", "ar": "عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ إِلَّا مَنْ أَبَى»، قَالُوا: يَا رَسُولَ اللهِ، وَمَنْ يَأْبَى؟ قَالَ: «مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى».", "en": "Abu Hurayrah (may Allah be pleased with him) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Everyone of my Ummah will enter Paradise except those who refuse.\" They said: \"And who would refuse, O Messenger of Allah?\" He said: \"He who obeys me will enter Paradise, and who disobeys me has refused.\"", "ur": "ابوھریرہ رضی اللہ عنہ سے روایت ہے کہ اللہ کے رسول ﷺ نے فرمایا: \"میری امت کے سب لوگ جنت میں داخل ہوں کے، ماسوا ان لوگوں کے جنھوں نے انکار کیا۔\" پوچھا گیا کہ اے اللہ کے رسول! انکار کرنے والے کون ہوں گے؟ آپ ﷺ نے فرمایا : \"جس نے میری اطاعت کی، وہ جنت میں داخل ہو گا اور جس  نے میری نافرمانی کی، اس نے انکار کیا۔\"", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Al-Bukhāri", "explanation": "The Prophet (may Allah's peace and blessings be upon him) informed that all his Ummah will enter Paradise except those who refuse!\r\n\r\nThereupon, the Companions (may Allah be pleased with them) said: And who would refuse, O Messenger of Allah?!\r\n\r\nIn reply to them, he explained that he who obeys and follows the Messenger (may Allah's peace and blessings be upon him) will enter Paradise. In contrast, he who disobeys and does not comply with the Shariah has refused to enter Paradise on account of his bad deeds.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم بتا رہے ہیں کہ آپ کی امت کے سب لوگ جنت میں داخل ہوں گے، ان کو چھوڑ کر جنھوں نے جنت میں جانے سے منع کر دیا۔\r\n\r\nایسے میں صحابہ رضی اللہ عنھم نے آپ سے پوچھا کہ اے اللہ کے رسول! بھلا جنت جانے سے انکار کون کرے گا؟!\r\n\r\nآپ نے جواب دیا کہ جس نے اللہ کے رسول صلی اللہ علیہ و سلم کی اطاعت و فرماں برداری کی وہ جنت میں داخل ہوگا اور جس نے نافرمانی کی اور شریعت پر عمل کرنے سے گریز کیا، اس نے دراصل اپنے برے کاموں کے توسط سے جنت میں داخل ہونے سے انکار کیا۔", "hints": ["Obeying the Messenger (may Allah's peace and blessings be upon him) is part of obedience to Allah, and disobeying him is disobedience to Allah.\r", "Obedience to the Prophet (may Allah's peace and blessings be upon him) leads one to Paradise, and disobeying him leads one to Hellfire.\r", "The Hadīth gives good news to the righteous people in this Ummah that they all will enter Paradise except those who disobey Allah and His Messenger.\r", "It shows the Prophet's compassion towards his Ummah and keenness to guide them."], "hintsUr": ["اللہ کے رسول صلی اللہ علیہ و سلم کی اطاعت اللہ کی اطاعت کا ایک حصہ ہے اور آپ کی معصیت اللہ کی معصیت کا ایک حصہ ہے۔\r", "اللہ کے نبی صلی اللہ علیہ و سلم کی اطاعت جنت واجب کرتی ہے اور آپ کی نافرمانی جہنم واجب کرتی ہے۔\r", "اس امت کے فرماں بردار لوگوں کے لیے یہ خوش خبری کہ وہ جنت میں داخل ہوں گے۔ جنت میں داخل ہونے سے وہی لوگ رہ جائیں گے، جنھوں نے اللہ اور اس کے رسول صلی اللہ علیہ و سلم کی نافرمانی کی۔\r", "اپنی امت پر آپ صلی اللہ علیہ و سلم کی شقفت اور آپ کی یہ حرص کہ لوگ صحیح راستے پر آ جائیں۔"], "explanationAr": "يُخبرُ النبيُّ صلى الله عليه وسلم أنَّ كلَّ أُمَّتِه يدخلون الجنة إلا مَن امتنع!\n\nفقال الصحابة رضي الله عنهم: ومَن يمتنع يا رسول الله؟!\n\nفأجابهم عليه الصلاة والسلام: أنَّ مَن انقاد واتَّبع وأطاعَ الرسولَ صلى الله عليه وسلم دَخَلَ الجنة، وأما مَن عصى ولم يَنْقَدْ للشرع فقد امتنع من دخول الجنة بأعمالِه السيئة.", "hintsAr": ["أن طاعة الرسول صلى الله عليه وسلم من طاعة الله، ومعصيته من معصية الله.", "طاعة النبي صلى الله عليه وسلم توجب الجنة، ومعصيته توجب النار.", "بشارة للطائعين من هذه الأمة، وأنهم كلَّهم يدخلون الجنة إلا من عصى الله ورسوله.", "شفقته صلى الله عليه وسلم على أُمته، وحرصه على هدايتهم."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Hurayrah"}, {"id": "3272", "number": 10, "title": "Believing in the Messenger", "section": 2, "sectionTitle": "Following the Messenger", "slug": "10-believing-in-the-messenger", "ref": "Sahih Muslim 153", "primary": "https://sunnah.com/muslim:153", "source": "https://hadeethenc.com/en/browse/hadith/3272", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/3272", "ar": "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه عَنْ رَسُولِ اللهِ صلى الله عليه وسلم أنه قال: «وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَا يَسْمَعُ بِي أَحَدٌ مِنْ هَذِهِ الْأُمَّةِ يَهُودِيٌّ وَلَا نَصْرَانِيٌّ، ثُمَّ يَمُوتُ وَلَمْ يُؤْمِنْ بِالَّذِي أُرْسِلْتُ بِهِ إِلَّا كَانَ مِنْ أَصْحَابِ النَّارِ».", "en": "Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"By the One in Whose Hand Muhammad's soul is, there is nobody of this Ummah (community), whether they be Jewish or Christian, who hears of me and then dies without believing in what I was sent with except that he will be among the people of Hellfire.\"", "ur": "ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا : \"قسم ہے اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! اس امت کا کوئی بھی انسان جو میرے بارے میں سنے، وہ یہودی ہو یا نصرانی اور وہ اس شریعت پر ایمان نہ لائے، جسے دے کر میں بھیجا گیا ہوں اور اسی حالت میں اس کی موت ہو جائے، تو وہ جہنمی ہوگا\"۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "The Prophet (may Allah's peace and blessings be upon him) swears by Allah that none of this nation, be he Jewish or Christian or otherwise, who hears of the Prophet (may Allah's peace and blessings be upon him) and of his message then dies without believing in him except that he will be among the dwellers of Hellfire who will reside therein forever.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم اللہ کی قسم کھا کر بتا رہے ہیں کہ اس امت کا جو بھی شخص آپ کے بارے میں سنے گا، خواہ یہودی ہو ، عیسائی ہو یا کوئی اور، پھر وہ آپ پر ایمان لائے بغیر ہی مر جائے گا، تو وہ جہنمی ہوگا اور اس میں ہمیشہ رہے گا۔", "hints": ["It demonstrates the generality of the Prophet's message that addresses the whole world, the obligation of following him, and the fact that his Shariah has abrogated all the previous legislations.\r", "Whoever disbelieves in the Prophet (may Allah's peace and blessings be upon him), his belief in other prophets (peace be upon all of them) will not be of any avail to him.\r", "Those who have not heard about the Prophet (may Allah's peace and blessings be upon him) and the call of Islam has not reached them are excused and their case in the Hereafter is left to Allah Almighty.\r", "A person can embrace Islam even shortly before death, even if he is in severe illness, so long as the soul did not reach the throat (did not witness death).\r", "Belief in the soundness of the disbelievers' religion, including the Jews and the Christians, is disbelief.\r", "The reference in this Hadīth to the Jews and the Christians indicates that the ruling includes the people of other faiths as well. If this is the case with the Jews and the Christians, who received divine scriptures, then it is more emphatic for those who have no scripture, for everyone must embrace Islam and obey its Messenger (may Allah's peace and blessings be upon him)."], "hintsUr": ["اللہ کے نبی صلی اللہ علیہ و سلم کی رسالت سارے عالم کے لیے عام ہے، آپ کی اتباع واجب ہے اور آپ کی شریعت کے ذریعے پچھلی ساری شریعتیں منسوخ ہو چکی ہیں۔\r", "جس نے اللہ کے نبی صلی اللہ علیہ و سلم کا انکار کر دیا، اسے دیگر نبیوں پر ایمان رکھنے کا دعوی کچھ فائدہ نہ دے گا۔\r", "جس نے اللہ کے نبی صلی اللہ علیہ و سلم کے بارے میں نہيں سنا اور اس کے پاس آپ کی دعوت نہیں پہنچی، وہ معذور ہے اور آخرت میں اس کا معاملہ اللہ کے ہاتھ میں ہوگا۔\r", "انسان کو اسلام قبول کرنے کا فائدہ ملے گا، چاہے سخت بیماری میں اور موت سے کچھ دیر پہلے ہی کیوں نہ اسلام قبول کرے، جب کہ روح حلق تک نہ پہنچ جائے۔\r", "کافروں - جن میں یہود ونصاری بھی شامل ہیں- کے دین کو صحیح قرار دینا کفر ہے۔\r", "اس حدیث میں یہودیوں اور عیسائیوں کا ذکر ان کے علاوہ دیگر مذاہب کے ماننے والوں کے بارے میں تنبیہ کرنے کے لیے ہوا ہے۔ کیوں کہ ان دونوں قوموں کے پاس کتابیں موجود تھیں اور اس کے باوجود ان کا یہ حال ہے، تو دیگر ان قوموں کا حال کیا ہوگا، جن کے پاس کتاب نہیں ہے؟ سچائی یہ ہے کہ دنیا کی ساری قوموں پر آپ کے دین کو قبول کرنا اور آپ کی اتباع کرنا واجب ہے۔"], "explanationAr": "يَحْلِفُ النبيُّ صلى الله عليه وسلم بالله أنه لا يَسمعُ به أَحَدٌ مِن هذه الأمة، يَهوديٌّ أو نصرانيٌّ أو غيرُهما تَبْلُغُه دعوةُ النبي صلى الله عليه وسلم ثم يموت ولم يؤمن به إلا كان من أصحاب النار خالدًا فيها أبدًا.", "hintsAr": ["عموم رسالةِ النبيِّ صلى الله عليه وسلم إلى جميع العالم، ووجوب اتِّباعِه، ونسخ جميع الشرائع بشرعه.", "مَن كَفَرَ بالنبي صلى الله عليه وسلم لم ينفعه زَعْمُه إيمانَه بغيرِه من الأنبياء صلوات الله عليهم أجمعين.", "من لم يَسمع بالنبي صلى الله عليه وسلم، ولم تَبْلغْه دعوةُ الإسلام فهو معذور، وأَمْرُه في الآخرة إلى الله تعالى.", "يتحقق الانتفاع بالإسلام وإن كان قُبيل الموت، ولو في المرض الشديد، ما لم تبلغ الروح الحلقوم.", "تصحيح دين الكفار -ومنهم اليهود والنصارى- كُفْرٌ.", "ذكر اليهودي والنصراني -في الحديث- تنبيهًا على من سواهما؛ وذلك لأن اليهود والنصارى لهم كتاب، فإذا كان هذا شأنهم، فغيرهم ممن لا كتاب له أولى، فكلُّهم يجب عليهم الدخول في دينه وطاعته صلى الله عليه وسلم."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Hurayrah"}, {"id": "66529", "number": 11, "title": "Holding firmly to the Sunnah", "section": 2, "sectionTitle": "Following the Messenger", "slug": "11-holding-firmly-to-the-sunnah", "ref": "Sunan Abi Dawud 4607", "primary": "https://sunnah.com/abudawud:4607", "source": "https://hadeethenc.com/en/browse/hadith/66529", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/66529", "ar": "عَنْ أَبِي نَجِيحٍ العِرْبَاضِ بْنِ سَارِيَةَ رضي الله عنه قَالَ: وَعَظَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَوْعِظَةً وَجِلَتْ مِنْهَا القُلُوبُ، وَذَرَفَتْ مِنْهَا العُيُونُ، فَقُلْنَا: يَا رَسُولَ اللهِ! كَأَنَّهَا مَوْعِظَةُ مُوَدِّعٍ؛ فَأَوْصِنَا، قَالَ: «أُوصِيكُمْ بِتَقْوَى اللَّهِ، وَالسَّمْعِ وَالطَّاعَةِ، وَإِنْ تَأَمَّرَ عَلَيْكُمْ عَبْدٌ، فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ بَعْدِي فَسَيَرَى اخْتِلَافًا كَثِيرًا، فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الخُلَفَاءِ الرَّاشِدِينَ المَهْدِيينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ، وَإِيَّاكُمْ وَمُحْدَثَاتِ الأُمُورِ؛ فَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ».", "en": "Abu Najīh al-‘Irbād ibn Sāriyah (may Allah be pleased with him) reported: The Messenger of Allah (ﷺ) gave us an exhortation at which hearts trembled and eyes shed tears. So we said: O Messenger of Allah, it is as though this is the exhortation of one bidding farewell; so advise us. He said: \"I advise you to fear Allah, and to listen and obey even if a slave is appointed as your leader. Whosoever among you shall live after me will see much discord. So hold fast to my Sunnah and the Sunnah of the Rightly-Guided Caliphs, and cling to them firmly. Beware of new things (in religion) because every religious innovation is a misguidance.\"", "ur": "ابو نجیح عرباض بن ساریہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہيں: (ایک مرتبہ) رسول اللہ ﷺ نے ہمیں ایک موثر وعظ فرمایا جس سے دل کانپ اٹھے اور آنکھیں بھر آئیں۔ ہم  نے کہا: اے اللہ کے رسول ﷺ! یہ وعظ تو گویا کسی الوداع کہنے والے کے وعظ کی طرح ہے۔ لہٰذا آپ ہمیں وصیت فرمائیں۔ رسول اللہ ﷺ نے فرمایا: ”میں تمہیں اللہ سے ڈرنے اور (امیر کی بات) سننے اور ماننے کی وصیت کرتا ہوں، اگرچہ تم پر کوئی حبشی غلام امیر بن جائے۔ (یاد رکھو!)تم میں سے جو میرے بعد زندہ رہے گا وہ یقینا بہت اختلاف دیکھے گا۔ چنانچہ تم میری سنت کو اور ہدایت یافتہ خلفائے راشدین کے طریقے کو لازم پکڑنا، انہیں دانتوں سے خوب جکڑ لینا اور دین میں نئے نئے کام ایجاد کرنے سے بچنا، کیونکہ ہر بدعت گمراہی ہے۔“", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Abu Dāwūd and At-Tirmidhi", "explanation": "The Prophet (may Allah's peace and blessings be upon him) delivered an eloquent sermon that filled the Companions' hearts with fear and filled their eyes with tears. They said: O Messenger of Allah, it seems as if it is an admonition by one who will soon leave us - seeing his earnest effort in doing so. Hence, they asked him to give them advice that they would hold onto after him. He said: I advise you to fear Allah Almighty by carrying out duties and avoiding prohibitions. And to hear and obey, i.e., hear and obey the rulers, even if your ruler or the one who seized authority over you is a slave. In other words, if the most inferior among people became your ruler, you should not disdain to obey him, out of fear of turbulence and strife, for whoever lives from you after me will see a great discord. Then, he (may Allah's peace and blessings be upon him) clarified that the way out of this discord is by adhering firmly to his Sunnah and to the Sunnah of the rightly guided Caliphs after him, namely Abu Bakr as-Siddīq, ‘Umar ibn al-Khattāb, ‘Uthmān ibn ‘Affān, and ‘Ali ibn Abi Tālib (may Allah be pleased with them all), and by biting onto it with the molar teeth, i.e., by strictly observing and holding fast to the Sunnah. He (may Allah's peace and blessings be upon him) also warned them against the newly introduced matters in religion, as every religious innovation is a misguidance.", "explanationUr": "ایک دن اللہ کے نبی صلی اللہ علیہ و سلم  نے وعظ فرمایا۔ وعظ اتنا متاثر کرنے والا تھا کہ اس سے لوگوں کے دل دہل گئے اور آنکھوں سے آنسو بہہ پڑے۔ یہ منظر دیکھ کر صحابہ نے کہا کہ اے اللہ کے رسول! ایسا معلوم ہوتا ہے کہ یہ ایک الوداع کہنے والے کی جانب سے پیش کیا جانے والا خطاب ہے۔ کیوں کہ انھوں  نے دیکھا کہ اللہ کے نبی صلی اللہ علیہ و سلم  نے خطاب کرتے وقت اپنا کلیجہ نکال کر رکھ دیا۔ لہذا انھوں نے آپ سے کچھ وصیت کرنے کو کہا، تاکہ آپ کے بعد اسے مضبوطی سے پکڑے رہیں۔ چنانچہ آپ نے کہا: میں تم کو اللہ عز وجل کا خوف رکھنے کی وصیت کرتا ہوں۔ یہاں یہ یاد رہے کہ اللہ سے ڈرنے کا مطلب ہے واجبات کو ادا کرنا اور محرمات سے اجتناب کرنا۔ اسی طرح میں تم کو حکمرانوں کا حکم سننے اور ماننے کی وصیت کرتا ہوں۔ خواہ تمھارا حکمراں کوئی حبشی غلام ہی کیوں نہ ہو۔ یعنی ایک معمولی سے معمولی انسان بھی اگر تمھارا حکمراں بن جائے، تو تم اس سے بدک کر دور مت ہٹو۔ تم اس کی بات مانو، تاکہ فتنے سر نہ اٹھا سکیں۔ کیوں کہ تم میں سے جو لوگ زندہ رہيں گے، وہ بہت سارا اختلاف دیکھیں گے۔ پھر اللہ کے نبی صلی اللہ علیہ سلم  نے اپنے صحابہ کو اس اختلاف سے نکلنے کا راستہ بتایا۔ راستہ یہ ہے کہ آپ کی سنت اور آپ کے بعد مسند خلافت سنبھالنے والے نیک ہدایت یاب خلفا؛ ابو بکر صدیق، عمر بن خطاب، عثمان بن عفان اور علی بن ابو طالب رضی اللہ عنہم کی سنت کو مضبوطی سے تھام کر رکھا جائے۔ آپ نے اسے داڑھوں سے پکڑنے کا حکم دیا۔ یعنی ہر حال میں سنت کو لازم پکڑا جائے اور اس پر قائم رہا جائے۔ اس کے بعد آپ نے ان کو دین کے نام پر سامنے آنے والی نت نئی چیزوں یعنی بدعات و محدثات سے خبردار کیا۔ کیوں کہ دین کے نام پر سامنے آنے والی ہر نئی چیز گمراہی ہے۔", "hints": ["The importance of following and adhering to the Sunnah.\r", "Attention should be given to admonitions and softening of hearts.\r", "The commandment to follow the four rightly guided Caliphs, namely Abu Bakr, ‘Umar, ‘Uthmān, and ‘Ali (may Allah be pleased with them all), after the Prophet.\r", "The prohibition of introducing new things into the religion, and the fact that all religious innovations are misguidance.\r", "Hearing and obeying whoever is in charge of the believers without disobeying Allah.\r", "The importance of fearing Allah Almighty at all times and in all situations.\r", "Discord will inevitably occur in this Ummah and when it occurs, Muslims must refer and adhere to the Sunnah of the Prophet (may Allah's peace and blessings be upon him) and to that of the rightly guided Caliphs."], "hintsUr": ["سنت کو مضبوطی سے تھامے رکھنے اور اس کا اتباع کرنے کی اہمیت۔\r", "پند و موعظت اور دلوں کو نرم کرنے پر توجہ۔\r", "اللہ کے نبی صلی اللہ علیہ و سلم کے بعد مسند خلافت پر فائز ہونے والے چاروں صالح اور ہدایت یاب خلفا یعنی ابو بکر، عمر، عثمان اور علی رضی اللہ عنہم کے اتباع کا حکم۔\r", "دین کے نام پر نئی چیزیں ایجاد کرنے کی ممانعت اور اس بات کا اعلان کہ دین کے نام پر سامنے آنے والی ہر نئی چیز بدعت ہے۔\r", "مسلمانوں کی زمام حکومت سنبھالنے والے لوگوں کی بات سننا اور ماننا ضروری ہے، جب تک کہ وہ کسی گناہ کے کام کا حکم نہ دیں۔\r", "ہر وقت اور ہر حال میں اللہ کا خوف رکھنے کی اہمیت۔\r", "اس امت میں اختلافات سامنے آتے رہيں گے اور اس طرح کے حالات میں اللہ کے رسول صلی اللہ علیہ و سلم اور خلفائے راشدین کی سنت کی جانب لوٹنا لازم ہوگا۔"], "explanationAr": "وَعَظَ النبيُّ صلى الله عليه وسلم أصحابَه مَوعظةً بَلِيْغَةً خافتْ منها القلوبُ ودَمَعتْ منها العيونُ، فقالوا: يا رسول الله كأنها مَوعظةُ مُودِّعٍ لِمَا رأوا مِن مبالغتِه صلى الله عليه وسلم في الموعظة، فطلبوا وصيةً ليتمسكوا بها مِن بعده، قال: أوصيكم بتقوى الله عز وجل، وذلك بفعل الواجبات وترك المحرمات، والسمع والطاعة، أي: للأمراء، وإنْ تَأَمَّر عليكم عَبْدٌ أو استولى عليكم، أي صار أدنى الخَلْقِ أميرًا عليكم فلا تَسْتَنْكِفُوا عن ذلك وأطيعوه، مخافةَ إثارةِ الفتن، فإنه مَن يعِش منكم فسيرى اختلافًا كثيرًا، ثم بَيَّنَ لهم المَخْرَجَ مِن هذا الاختلاف، وذلك بالتمسُّك بِسُنَّتِهِ وسُنّةِ الخلفاء الراشدين المهديين مِن بعده، أبي بكر الصديق، وعمر بن الخطاب، وعثمان بن عفان، وعلي بن أبي طالب رضي الله عنهم أجمعين، والعَضُّ عليها بالنواجذ أي –الأضراس الأخيرة-: يعني بذلك الجِدُّ في لزوم السنة والتمسك بها، وحَذَّرَهم من الأمور المُحدَثة المُبْتَدَعة في الدِّين، فإنِّ كلَّ بدعةٍ ضلالةٌ.", "hintsAr": ["أهمية التَّمَسُّكِ بالسُّنّة واتباعها.", "العناية بالمواعظ وترقيق القلوب.", "الأمر باتباع الخُلَفاء الراشدين المهديين الأربعة مِن بعده، وهم أبو بكر وعمر وعثمان وعلي رضي الله عنهم.", "النهيُ عن الابتداع في الدِّين، وأنّ كل البدع ضلالة.", "السمع والطاعة لمَن تولَّى أمر المؤمنين في غير معصية.", "أهمية تقوى الله عز وجل في كل الأوقات والأحوال.", "الاختلاف واقع في هذه الأمة، وعند حدوثِهِ يلزم الرجوعُ إلى سُنّة رسول الله صلى الله عليه وسلم والخلفاء الراشدين."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Al-Irbad ibn Sariyah"}, {"id": "65005", "number": 12, "title": "The authority of the Prophetic teaching", "section": 2, "sectionTitle": "Following the Messenger", "slug": "12-the-authority-of-the-prophetic-teaching", "ref": "Jami at-Tirmidhi 2664", "primary": "https://sunnah.com/tirmidhi:2664", "source": "https://hadeethenc.com/en/browse/hadith/65005", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/65005", "ar": "عن المقدام بن معدِيْكَرِب رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «أَلَا هَلْ عَسَى رَجُلٌ يَبْلُغُهُ الْحَدِيثُ عَنِّي وَهُوَ مُتَّكِئٌ عَلَى أَرِيكَتِهِ فَيَقُولُ: بَيْنَنَا وَبَيْنَكُمْ كِتَابُ اللهِ، فَمَا وَجَدْنَا فِيهِ حَلَالًا اسْتَحْلَلْنَاهُ، وَمَا وَجَدْنَا فِيهِ حَرَامًا حَرَّمْنَاهُ، وَإِنَّ مَا حَرَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَمَا حَرَّمَ اللهُ».", "en": "Al-Miqdām ibn Ma‘dikarib (may Allah be pleased with him) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Lo! Soon a Hadīth from me will be conveyed to a man, while he is reclining on his couch, and he says: ‘Between us and you is Allah’s Book. So, whatever we find in it that is lawful, we consider lawful, and whatever we find in it that is unlawful, we consider unlawful.’ Indeed, whatever the Messenger of Allah made unlawful, it is the same as what Allah made unlawful.\"", "ur": "مقداد بن معدیکرب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خبردار رہو! قریب ہے کہ کوئی آدمی اپنے آراستہ تخت پر ٹیک لگائے بیٹھا ہو اور اس کے پاس میری حدیث پہنچے تو کہے: ہمارے اور تمہارے درمیان (فیصلے کی چیز) بس اللہ کی کتاب ہے۔ اس میں جو چیز ہم حلال پائیں گے اسی کو حلال سمجھیں گے اور اس میں جو چیز حرام پائیں گے اسی کو ہم حرام جانیں گے۔ یاد رکھو! بلاشک و شبہ رسول اللہ ﷺ نے جو چیز حرام قرار دے دی ہے، وہ ویسے ہی حرام ہے، جیسے کہ اللہ کی حرام کی ہوئی چیز\"۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Abu Dāwūd, At-Tirmidhi, and Ibn Mājah", "explanation": "The Prophet (may Allah's peace and blessings be upon him) reports that there will soon come a time in which some type of people will be sitting, with one of them reclining on his couch, and when a Hadīth from the Prophet (may Allah's peace and blessings be upon him) reaches him, he will say: What decides the matters between you and us is the noble Qur’an. It is sufficient for us. What we find therein as lawful, we act upon it, and what we find therein as unlawful, we avoid it. Then, the Prophet (may Allah's peace and blessings be upon him) pointed out that anything he prohibited or forbade in his Sunnah is the same as what Allah prohibited in His Book, for he only conveys from his Lord.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ وسلم نے اس حدیث میں بتایا ہے کہ وہ وقت قریب آچکا ہے، جب ایسے لوگ ظاہر ہوں گے کہ ان میں سے ایک آدمی اپنی مسند پر بیٹھا ہوگا اور جب اس کے پاس اللہ کے نبی صلی اللہ علیہ وسلم کی حدیث پہنچے گی، تو وہ کہے گا کہ تمام معاملات میں ہمارے اور تمہارے درمیان فیصلہ کرنے والی چیز قرآن مجید ہے۔ وہی ہمارے لیے کافی ہے۔ ہم اس میں جو چیز حلال پائیں گے، اسی پر عمل کریں گے اور اس میں جو چیز حرام پائیں گے، اسی سے اجتناب کریں گے۔ اس کے بعد اللہ کے نبی صلی اللہ علیہ وسلم نے وضاحت فرما دی کہ ہر وہ چیز جسے آپ  نے اپنی سنت میں حرام ٹھہرایا یا اس سے منع فرمایا، اس کا بھی حکم وہی ہے، جو حکم قرآن میں اللہ کی حرام کردہ چیزوں کا ہے، کیوں کہ آپ اپنے رب کی جانب سے دین پہنچانے والے کی حیثیت سے آئے تھے۔", "hints": ["The Sunnah should be highly valued and observed like the Qur’an.\r", "Obedience to the Messenger is obedience to Allah Almighty and disobeying him is disobedience to Allah.\r", "It establishes the authority of the Sunnah and responds to those who reject the Sunnah or deny it.\r", "Whoever turns away from the Sunnah and claims that he only adheres to the Qur’an does actually turn away from both of them, and his claim about following the Qur’an is false.\r", "This is one of the proofs of the Prophet's prophethood, as he informed about certain things that would happen in the future, and it did happen as he informed."], "hintsUr": ["حدیث کی تعظیم بھی اسی طرح کی جائے گی جس طرح قرآن کی کی جاتی ہے اور اس پر عمل بھی قرآن ہی طرح کیا جائے گا۔\r", "رسول کی اطاعت در اصل اللہ کی اطاعت ہے اور رسول کی نافرمانی در اصل اللہ تعالی کی نافرمانی ہے۔\r", "حدیث کی حجیت کا ثبوت اور احادیث کا رد یا انکار کرنے والے  کی تردید۔\r", "جو شخص حدیث سے اعراض کرے اور صرف قرآن پر اکتفا کرنے کا دعوی کرے، وہ در اصل قرآن و حدیث دونوں سے اعراض کرنے والا ہے اور اتباع قرآن کے دعوے میں جھوٹا ہے۔\r", "نبی صلی اللہ علیہ وسلم کی نبوت کی ایک نشانی یہ بھی ہے کہ آپ نے مستقبل میں کسی چیز کے واقع ہونے کی پیشین گوئی فرمائی اور وہ چیز ہوبہو اسی طرح واقع ہو بھی گئی۔"], "explanationAr": "أخبر النبي صلى الله عليه وسلم أنه قد اقترب زمان يكون فيه صنف من الناس جالس، أحدهم متكئ على فراشه، يبلغه الحديث عن النبي صلى الله عليه وسلم، فيقول: الذي يَفْصِلُ بيننا وبينكم في الأمور هو القرآن الكريم فهو يكفينا، فما وجدنا فيه من حلال عملنا به، وما وجدنا فيه من حرام ابتعدنا عنه. \nثم بَيَّن النبي صلى الله عليه وسلم أن كل شيء حرّمه أو نهى عنه في سنته فهو في الحكم مثل ما حرّمه الله في كتابه؛ لأنه المبلغ عن ربه.", "hintsAr": ["تعظيم السنة كما يُعَظَّم القرآن ويؤخذ بها.", "طاعة الرسول هي طاعة لله ومعصيته هي معصية لله تعالى.", "ثبوت حُجِيّة السنة والرد على من يَرُدُّ السُّننَ أو ينكرها.", "مَن أعرض عن السُّنَّة وادعى الاقتصار على القرآن فهو مُعرِضٌ عنهما جميعًا كاذبٌ في دعوى اتباع القرآن.", "من دلائل نبوته صلى الله عليه وسلم إخباره عن شيء بأنه سيقع في المستقبل، ووقع كما أخبر."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Al-Miqdam ibn Madikarib"}, {"id": "4792", "number": 13, "title": "Deeds must belong to the religion", "section": 2, "sectionTitle": "Following the Messenger", "slug": "13-deeds-must-belong-to-the-religion", "ref": "Sahih al-Bukhari 2697", "primary": "https://sunnah.com/bukhari:2697", "source": "https://hadeethenc.com/en/browse/hadith/4792", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/4792", "ar": "عَنْ عَائِشَةَ رضي الله عنها قَالَتْ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: «مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ فِيهِ فَهُوَ رَدٌّ» متفق عليه.\nولمسلم: «مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ».", "en": "‘Ā’ishah (may Allah be pleased with her) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever introduces into this matter of ours (Islam) something that does not belong to it shall have it rejected.\" [Agreed upon] A narration by Muslim reads: \"Whoever does something that is not in accordance with this matter of ours shall have it rejected.\"", "ur": "عائشہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہیں کہ رسول اللہ ﷺ نے فرمایا : ”جس نے ہمارے اس دین میں کوئی ایسی بات ایجاد کی، جو اس کا حصہ نہیں ہے، تو وہ قابل قبول نہیں ہے“۔ ایک اور روایت میں ہے: ”جس نے کوئی ایسا عمل کیا، جس کے متعلق ہمارا حکم نہیں ہے، تو وہ قابل قبول نہيں ہے“۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "The Prophet (may Allah's peace and blessings be upon him) clarifies that whoever innovates something in the religion or does something that is not supported by evidence from the Qur’an and Sunnah will have it rejected and Allah will not accept it from him.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم بتا رہے ہیں کہ جس  نے دین کے اندر ایسی کوئی نئی چیز ایجاد کی یا ایسا کوئی نیا کام کیا، جو قرآن اور حدیث سے ثابت نہ ہو، تو اسے اسی کے منہ پر مار دیا جائے گا اور اللہ کے یہاں قبول نہیں کیا جائے گا۔", "hints": ["Acts of worship are based on what is prescribed in the Qur’an and Sunnah. We worship Allah Almighty only in accordance with what He has prescribed and not in accordance with religious innovations and heresies.\r", "Religion is not based on reason or juristic discretion; rather, it is based on following the Messenger of Allah (may Allah's peace and blessings be upon him).\r", "This Hadīth is proof of the perfection of the religion.\r", "\"Bid‘ah\" (religious innovation): It is every belief, saying, or act that is newly introduced in the religion, which neither existed during the time of the Prophet (may Allah's peace and blessings be upon him) nor during the time of his Companions.\r", "This Hadīth represents one of the fundamentals of Islam. It acts as a criterion for deeds. Every deed that is not exclusively devoted to Allah Almighty, its doer will not be rewarded for it and the same rule applies to every deed that does not conform with the Prophet's Sunnah will be rejected upon its doer.\r", "The prohibited innovations are those related to religion and not those related to worldly affairs."], "hintsUr": ["عبادتوں کی بنیاد قرآن اور حدیث ہے۔ لہذا ہم اللہ کی عبادت قرآن اور حدیث کے بتائے ہوئے طریقے کے مطابق ہی کریں گے۔ بدعتوں اور عبادت کی نت نئی شکلوں سے ہر حال میں دور رہيں گے۔\r", "دین کی بنیاد رائے اور استحسان پر نہیں ہے۔ دین کی بنیاد اتباع رسول پر ہے۔\r", "یہ حدیث دین کے کامل ہونے کی دلیل ہے۔\r", "بدعت ہر اس عقیدہ، قول یا عمل کو کہتے ہیں، جسے دین کے ایک جزء کے طور پر ایجاد کیا گیا ہو اور وہ اللہ کے رسول صلی اللہ علیہ و سلم اور آپ کے صحابہ کے زمانے میں موجود نہ رہا ہو۔\r", "یہ حدیث اسلام کے ایک اساس کی حیثیت رکھتی ہے۔ یہ اعمال کے میزان کی طرح ہے۔ جس طرح جب کسی عمل کا مقصد اللہ کی رضامندی کا حصول نہ ہو، تو کرنے والے کو اس کا کوئی ثواب نہيں ملتا، اسی طرح جو عمل اللہ کے رسول صلی اللہ علیہ و سلم کی تعلیمات کے مطابق نہ کیا جائے، اسے کرنے والے کے منہ پر مار دیا جاتا ہے۔\r", "منع صرف ان نئی چیزوں سے کیا گیا ہے، جن کا تعلق دین سے ہو، ان سے نہيں، جن کا تعلق دنیا سے ہو۔"], "explanationAr": "يُبَيِّنُ النبيُّ صلى الله عليه وسلم أنَّ مَن اخترَعَ في الدِّينِ أو عَمِلَ عملًا لم يَدُل عليه دليلٌ من الكتاب والسنة، فهو مَردودٌ على صاحبِه غير مقبول عند الله.", "hintsAr": ["العبادات مبناها على ما جاء في الكتاب والسنة، فلا نعبد الله تعالى إلا بما شَرَعَ لا بالبدع والمُحْدَثات.", "الدين ليس بالرأي والاستحسان، وإنما بالاتباع للرسول صلى الله عليه وسلم.", "هذا الحديث دليلٌ على كمال الدين.", "البدعة هي كل ما أُحْدِثَ في الدين ولم يَكنْ على عهدِ النبي صلى الله عليه وسلم وأصحابه من عقيدةٍ أو قولٍ أو عملٍ.", "هذا الحديث أصلٌ من أصول الإسلام، وهو كالميزان للأعمال، فكما أنَّ كلَّ عَمَلٍ لا يُراد به وجه الله تعالى، فليس لعامله فيه ثواب، فكذلك كلُّ عمل لا يكون وِفْقَ ما جاء به رسول الله صلى الله عليه وسلم فهو مردود على عامله.", "المُحْدَثات المنهي عنها ما كان من أمور الدين وليس الدنيا."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Aishah"}, {"id": "4725", "number": 14, "title": "Commands within our ability", "section": 2, "sectionTitle": "Following the Messenger", "slug": "14-commands-within-our-ability", "ref": "Sahih al-Bukhari 7288", "primary": "https://sunnah.com/bukhari:7288", "source": "https://hadeethenc.com/en/browse/hadith/4725", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/4725", "ar": "عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «ما نهيتكم عنه فاجتنبوه، وما أمرتكم به فأْتُوا منه ما استطعتم، فإنما أَهلَكَ الذين من قبلكم كثرةُ مسائلهم واختلافهم على أنبيائهم».", "en": "Abu Hurayrah (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"Avoid what I have forbidden you from; and do as much as you can, of what I have ordered you. Indeed, those before you were ruined because of their excessive questioning and disagreeing with their prophets.\"", "ur": "ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”میں جس بات سے تمہیں منع کروں اس سے اجتناب کرو اور جس بات کا حکم دوں اسے مقدور بھر سر انجام دو۔ تم سے پہلی امتوں کی ہلاکت کا سبب ان کا بہت زیادہ سوالات کرنا اور ان کی اپنے انبیاء کی مخالفت کرنا بنا تھا“۔", "grade": "Authentic hadith", "gradeAr": "صحيح", "attribution": "Narrated by Bukhari & Muslim", "explanation": "The Messenger of Allah (may Allah's peace and blessings be upon him) informed us that if he forbade us from something, we must avoid it without exception, and if he ordered us to do something, we have to do it as much as we can. He then warned us against being like some of the previous nations, who asked their prophets excessive questions and disagreed with them, so Allah punished them with different types of destruction and ruin. We should therefore avoid being like them, so we will not be destroyed in the ways that they were.", "explanationUr": "رسول اللہ ﷺ نے ہماری رہنمائی کی اور فرمایا کہ جب آپ ﷺ ہمیں کسی چیز سے منع کردیں تو ہم پر لازم ہے کہ ہم بلا استثناء اس سے اجتناب کریں اور جب آپ ﷺ ہمیں کسی شے کے کرنے کا حکم دیں تو ہم پر واجب ہیں کہ ہم مقدور بھر اسے سر انجام دیں۔\nپھر آپ ﷺ نے ہمیں اس بات سے ڈرایا کہ ہم سابقہ امتوں کی طرح نہ ہو جائیں جنہوں نے اپنے انبیاء سے بہت زیادہ سوالات کیے اور پھر اس کے ساتھ ساتھ انہوں نے ان کی مخالفت بھی کی۔ اس پر اللہ تعالیٰ نے انہیں ہلاکت و بربادی کے مختلف قسم کے عذاب میں مبتلا کر دیا۔ لہذا مناسب یہ ہے کہ ہم ان کی طرح نہ ہوں، کہیں ایسا نہ ہو کہ ہم بھی ویسے ہی ہلاک ہو جائیں جیسے وہ ہوئے۔", "hints": ["It enjoins compliance with the commands and prohibitions.", "We are not permitted to do anything of the prohibitions. With regard to the commands, however, we are required to comply according to our abilities. This is because the abandonment of something falls within one’s capacity, whereas taking a certain action requires ability.", "It is prohibited to ask a lot of questions. The scholars divided questions into two types, one of which aims at learning things needed in the religion. This type is required, and it applies to questions the Companions used to ask. The other type is such questions that are posed by way of obstinacy and affectation, which is prohibited.", "It warns the Ummah of disobeying the Prophet (may Allah’s peace and blessings be upon him), as happened in the past nations.", "When something is prohibited, this applies to any part of it, great or small, for avoiding it requires avoidance of the action altogether. For example, we are prohibited from usury, and this applies to any amount of it, big or small.", "We are required to shun the means conducive to something prohibited, for this falls under the meaning of avoidance.", "Man has certain capacity and ability, as indicated by his words: “As much as you can.” This refutes the claim by the Jabriyyah (Determinism) doctrine that man has no ability because he is forced to do whatever he does; even when a person moves his hand during his speech, this, according to them, is out of his control and he is compelled to do so. This view is undoubtedly wrong, and it results in great evils.", "When a person hears a command from the Prophet (may Allah’s peace and blessings be upon him), he should not ask whether it is obligatory or recommended; for he said: “Do it as much as you can.”", "Whatever the Prophet (may Allah’s peace and blessings be upon him) commanded or prohibited is part of the Shariah, whether it exists in the Qur’an or not. We should observe the Sunnah if introduced something not in the Qur’an, be it a command or a prohibition.", "One of the means to ruin is posing a lot of questions, especially about things that cannot be realized, like matters related to the unseen, the names and attributes of Allah, and the events on the Day of Judgment. Do not ask a lot about such matters, lest you ruin your life and become an obstinate and unnecessarily inquisitive person.", "The past nations were ruined due to their frequent questioning and disobeying their prophets."], "hintsUr": ["اوامر کی بجا آوری اورنواہی سے بچنے کا حکم۔", "نہی کے ارتکاب کی ذرا بھی اجازت نہیں دی گئی ہے، جب کہ امر کو استطاعت کے ساتھ مقید کردیا گیا ہے، کیوں کہ آدمی ترک کی قدرت رکھتا ہے اور فعل کے لیے مامور بہ کام کو انجام دینے کی قدرت کی ضرورت ہوتی ہے۔", "زیادہ سوال کرنے کی ممانعت۔ علما نے سوال کی دوقسمیں کی ہیں: ایک، جو دین کی ضروری بات سیکھنے کےلیے ہو۔ یہ ماموربہ ہے۔ صحابۂ کرام کے سوالات اسی نوع کے ہوتے تھے۔ دوسری جو بہ طور تکلّف اور پریشان کرنے کے لیے ہو۔ اسی سے روکا گیا ہے۔", "اس امّت کو سابقہ قوموں کی طرح اپنے نبیﷺ کی مخالفت میں پڑنے سے متنبہ کیا گیا ہے۔", "کسی چیز کی ممانعت میں اس کا قلیل اور کثیر دونوں شامل ہوتا ہے۔ کیوں اس سے (مکمل طور پر) اسی وقت بچا جاسکتاہے، جب اس کے کم اور زیادہ مقدار دونوں سے بچاجائے۔ مثال کے طورپر ہمیں سود سے منع کیا گیا ہے، تو اس میں اس کی کم اور زیادہ مقدار دونوں شامل ہوگی۔", "حرام تک پہنچانے والے اسباب کو چھوڑدینا چاہیے، اس لیے کہ یہ اجتناب کے معنیٰ میں داخل ہے۔", "انسان صاحب استطاعت اور قدرت والا ہے، کیوں کہ آپ کا فرمان ہے: \"مَا استَطَعْتُمْ\" جتنی تمہیں طاقت ہو۔ چناںچہ اس میں جبریہ کی تردید ہے، جو کہتے ہیں کہ انسان کے پاس کوئی استطاعت نہیں ہے اور وہ عمل پر مجبور ہے، یہاں تک کہ انسان گفتگو کے وقت اپنے ہاتھ سے جو حرکت کرتا ہے، ان کے قول کے مطابق ہاتھ کی وہ حرکت بھی اس کی استطاعت میں نہیں ہے۔ وہ بالکل مجبور ہے۔ بلاشبہ یہ باطل قول ہے، جس پر بڑے مفاسد مرتب ہوتے ہیں۔", "کسی انسان کے لیے مناسب نہیں کہ جب وہ رسولﷺکا حکم سنے توکہےکہ کیا یہ واجب ہے یا مستحب؟ کیوں کہ آپ کا فرمان ہے: \"فَأْتُوا مِنْهُ مَا استَطَعْتُمْ\". یعنی تم اس میں سے اپنے مقدور بھر سر انجام دو۔", "نبیﷺ جس بات کا حکم دیں یا جس سے منع فرمائیں، وہ شریعت ہے، خواہ وہ قرآن میں ہو یا نہ ہو۔ لہذا سنت سے ثابت ان اوامر اور نواہی پر بھی عمل کیا جائے گا، جو قرآن میں نہیں ہیں۔", "زیادہ سوال کرنا ہلاکت کا سبب ہے، بالخصوص ایسی باتوں کے بارے میں جن کا جان پانا ممکن نہ ہو، جیسے اللہ کے اسما و صفات اور قیامت کے احوال۔ ان کے بارے میں زیادہ سوال نہ کرو، ورنہ ہلاک ہوجاؤ گے اور تمھارا شمار غلو کرنے والوں ہوگا۔", "گزشتہ امتیں کثرت سوال اور اپنے انبیا کے بارے میں زیادہ اختلاف کرنے کے سبب ہلاک ہوگئیں۔"], "explanationAr": "دلنا رسول الله صلى الله عليه وسلم أنه إذا نهانا عن شيء وجب علينا اجتنابه بدون استثناء، وإذا أمرنا بشيء فعلينا أن نفعل منه ما نطيق.\nثم حذرنا حتى لا نكون كبعض الأمم السابقة حينما أكثروا من الأسئلة على أنبيائهم مع مخالفتهم لهم فعاقبهم الله بأنواع من الهلاك والدمار، فينبغي أن لا نكون مثلهم حتى لا نهلك كما هلكوا.", "hintsAr": ["الأمر بامتثال الأوامر، واجتناب النواهي.", "النهي لم يرخص في ارتكاب شيء منه، والأمر قيد بالاستطاعة؛ لأن الترك مقدور والفعل يحتاج إلى قدرة على إيجاد الفعل المأمور به.", "النهي عن كثرة السؤال، قد قسم العلماء السؤال إلى قسمين: أحدهما: ما كان على وجه التعليم لما يحتاج إليه من أمر الدين، فهذا مأمور به ومن هذا النوع أسئلة الصحابة. والثاني: ما كان على وجه التعنت والتكلف وهذا هو المنهي عنه.", "تحذير هذه الأمة من مخالفة نبيها، كما وقع في الأمم التي قبلها.", "المنهي عنه يشمل القليل والكثير، لأنه لا يتأتّى اجتنابه إلا باجتناب قليله وكثيره، فمثلاً: نهانا عن الرّبا فيشمل قليله وكثيره.", "ترك الأسباب المفضية إلى المحرم، لأن ذلك من معنى الاجتناب.", "الإنسان له استطاعة وقدرة، لقوله: \"مَا استَطَعْتُمْ\" فيكون فيه رد على الجبرية الذين يقولون: إن الإنسان لا استطاعة له، لأنه مجبر على عمله، حتى الإنسان إذا حرّك يده عند الكلام، فيقولون تحريك اليد ليس باستطاعته، بل مجبر، ولا ريب أن هذا قول باطل يترتب عليه مفاسد عظيمة.", "لا ينبغي للإنسان إذا سمع أمر الرسول -صلى الله عليه وسلم- أن يقول: هل هو واجب أم مستحبّ؟ لقوله: \"فَأْتُوا مِنْهُ مَا استَطَعْتُمْ\".", "ما أمر به النبي -صلى الله عليه وسلم- أو نهى عنه فإنه شريعة، سواء كان ذلك في القرآن أم لم يكن، فُيعمل بالسنة الزائدة على القرآن أمراً أو نهياً.", "كثرة المسائل سبب للهلاك ولا سيّما في الأمور التي لا يمكن الوصول إليها مثل مسائل الغيب كأسماء الله وصفاته، وأحوال يوم القيامة، لاتكثر السؤال فيها فتهلك، وتكون متنطّعًا متعمّقًا.", "الأمم السابقة هلكوا بكثرة المسائل، وهلكوا بكثرة الاختلاف على أنبيائهم."], "words": [{"word": "نهيتكم", "meaning": " النهي: طلب الكفّ على وجه الاستعلاء."}, {"word": "فاجتنبوه", "meaning": " اتركوه."}, {"word": "من قبلكم", "meaning": " من الأمم السابقة."}, {"word": "واختلافهم", "meaning": " مخالفتهم."}, {"word": "مسائلهم", "meaning": " أسئلتهم."}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Hurayrah"}, {"id": "6078", "number": 15, "title": "Following a balanced Sunnah", "section": 2, "sectionTitle": "Following the Messenger", "slug": "15-following-a-balanced-sunnah", "ref": "Sahih Muslim 1401", "primary": "https://sunnah.com/muslim:1401", "source": "https://hadeethenc.com/en/browse/hadith/6078", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/6078", "ar": "عَنْ أَنَسٍ رضي الله عنه: أَنَّ نَفَرًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَأَلُوا أَزْوَاجَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ عَمَلِهِ فِي السِّرِّ؟ فَقَالَ بَعْضُهُمْ: لَا أَتَزَوَّجُ النِّسَاءَ، وَقَالَ بَعْضُهُمْ: لَا آكُلُ اللَّحْمَ، وَقَالَ بَعْضُهُمْ: لَا أَنَامُ عَلَى فِرَاشٍ، فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، فَقَالَ: «مَا بَالُ أَقْوَامٍ قَالُوا كَذَا وَكَذَا؟ لَكِنِّي أُصَلِّي وَأَنَامُ، وَأَصُومُ وَأُفْطِرُ، وَأَتَزَوَّجُ النِّسَاءَ، فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي».", "en": "Anas (may Allah be pleased with him) reported: A group from among the Prophet's Companions asked the wives of the Prophet (may Allah's peace and blessings be upon him) about his deeds in private. Some of them said: I will not marry women. Others said: I will not eat meat. Some others said: I will not sleep on a bed. So, he praised Allah and commended Him and said: \"What is the matter with those people who said such-and-such? But indeed, I pray and sleep, I fast and break the fast, and I marry women. Whoever turns away from my Sunnah does not belong to me.\"", "ur": "انس رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: نبی ﷺ کے کچھ صحابہ نے نبی ﷺ کی ازواجِ مطہرات سے نبی ﷺ کی تنہائی کے معمول کے بارے میں پوچھا۔ (آپ ﷺ کی عبادت کا معمول سن کر) ان میں سے کسی نے کہا کہ میں عورتوں سے شادی نہیں کروں گا، کسی نے کہا کہ میں گوشت نہیں کھاؤں گا اور کسی نے کہا کہ میں بستر پر نہیں سوؤں گا۔ (نبی ﷺ تک جب یہ بات پہنچی) تو آپ ﷺ نے اللہ تعالی کے حمد و ثنا کے بعد فرمایا: \"کچھ لوگوں کو کیا ہو گیا ہے کہ انہوں نے اس اس طرح کى باتیں کى ہیں؟ میں تو نماز بھی پڑھتا ہوں اور سوتا بھی ہوں، کبھی روزہ رکھتا ہوں اور کبھی نہیں رکھتا اور میں عورتوں سے شادی بھی کرتا ہوں۔ جس نے میری سنت سے گریز کیا اس کا مجھ سےکوئی تعلق نہیں۔\"", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "A group of the Companions (may Allah be pleased with them) came to the houses of the wives of the Prophet (may Allah's peace and blessings be upon him) asking about his private acts of worship inside his home. When they were informed, it seemed as though they considered it little, so they said: Where are we in comparison to the Prophet (may Allah's peace and blessings be upon him)? His past and future sins have been forgiven, unlike those who do not know if they have attained forgiveness, so they need to exaggerate in worship in the hope of attaining it. Then some of them said: I will not marry women. Others said: I will not eat meat. Some others said: I will not sleep on a bed. When this reached the Prophet (may Allah's peace and blessings be upon him), he became angry and gave a sermon to the people. He praised Allah and commended Him and said: What is the matter with people who said such-and-such? By Allah, I am the most fearful of Allah among you and the most conscious of Him, but I sleep to strengthen myself for standing in prayer, I break my fast to strengthen myself for fasting, and I marry women. Whoever turns away from my way, sees perfection in something else, and follows a path other than that of mine does not belong to me.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم کے کچھ صحابہ آپ کی بیویوں کے گھروں میں آئے۔ ان کا مقصد یہ جاننا تھا کہ اللہ کے رسول صلی اللہ علیہ و سلم گھر کے اندر کس طرح عبادت کرتے ہيں؟ جب ان کو آپ کی عبادت کے بارے میں بتایا گیا، تو گویا انھوں نے اسے کم سمجھا اور کہنے لگے: اللہ کے نبی صلی اللہ علیہ و سلم کا مقام کہاں اور ہم کہاں؟ آپ کے تو اگلے اور پچھلے تمام گناہ بخش دیے گئے ہیں۔ اس کے برخلاف جسے معلوم نہ ہو کہ اسے بخشا جائے گا یا نہيں، اسے زیادہ سے زیادہ عبادت کی ضرورت ہے، تاکہ بخشش کا سامان ہو جائے۔ اس کے بعد ان میں سے کسی نے کہا کہ میں شادی نہیں کروں گا۔ کسی نے کہا کہ میں گوشت نہيں کھاؤں گا۔ جب کہ کسی نے کہا کہ میں بستر پر نہیں سوؤں گا۔ اس کی اطلاع جب اللہ کے نبی صلی اللہ علیہ و سلم کو ملی، تو آپ نے ناراضگی ظاہر کی۔ لوگوں سے خطاب کیا۔ اللہ کی حمد و ثنا کی اور فرمایا: کچھ لوگوں کو کیا ہو گیا ہے کہ اس اور اس طرح کی بات کر رہے ہیں؟ اللہ کی قسم، میں تمھارے درمیان اللہ کى خشیت سے سب سے زیادہ متصف اور اس کا سب سے زیادہ تقوى رکھنے والا انسان ہوں۔ لیکن اس کے باوجود میں سوتا ہوں، تاکہ پورے نشاط کے ساتھ تہجد کی نماز پڑھ سکوں، روزے کے بغیر رہتا ہوں، تاکہ روزے کی طاقت حاصل کر سکوں اور عورتوں سے شادی بھی کرتا ہوں۔ لہذا جس نے میرے طریقے سے منہ موڑا، کسی اور طریقے کو کامل طریقہ جانا اور میرے علاوہ کسى اور کى راہ کو اختیار کیا، وہ مجھ میں سے نہیں ہے۔", "hints": ["The Companions' love for goodness and their desire to attain it and to follow the example of their Prophet (may Allah's peace and blessings be upon him).\r", "The tolerance and ease of this Shariah based on its Prophet's practice and guidance.\r", "Goodness and blessing lie in following the example of the Prophet (may Allah's peace and blessings be upon him) and adhering to his noble conditions.\r", "The deterrence of overburdening oneself in worship beyond one's capacity, as this is a characteristic of the innovators in religion.\r", "Ibn Hajar said: Adopting an overburdening approach in worship leads to boredom that can sever its very foundation. Moreover, sticking only to obligatory acts, for example, and neglecting voluntary acts leads to a preference for idleness and a lack of enthusiasm for worship, and moderation is the best in all affairs.\r", "It indicates the importance of pursuing the conditions of great people to follow their example, and if it is difficult to know about this from men, it is permissible to know about it through women.\r", "It includes admonition, presenting knowledge-related issues, clarifying rulings to those who are religiously accountable, and clearing the doubts of those who strive hard in religion.\r", "The command to be lenient in worship while maintaining it along with the obligatory and voluntary acts, so that a Muslim can fulfill the rights of others upon him.\r", "The Hadīth indicates the merit of marriage and encourages it."], "hintsUr": ["صحابہ رضی الله عنہم خیر کے کاموں سے محبت کرتے تھے، اس کی رغبت رکھتے تھے اور اپنے نبی صلى الله عليہ وسلم کى اقتدا کى چاہت ان کے اندر بھرى ہوئى تھى۔\r", "اسلامی شریعت ایک کشادہ اور آسان شریعت ہے۔ اس کی یہ خوبی اس کے نبی صلی اللہ علیہ و سلم کے عمل اور طریقے سے ظاہر وباہر ہے۔\r", "خیر و برکت اللہ کے نبی صلی اللہ علیہ و سلم کى اقتدا اور اتباع میں پنہاں ہے۔\r", "اپنے نفس پر طاقت سے بڑھ کر عبادت کا بوجھ ڈالنے کی ممانعت اور یہ وضاحت کہ یہ اہل بدعت کی روش ہے۔\r", "ابن حجر کہتے ہيں: عبادت میں شدت پسند رویہ اکتاہٹ کا سبب بنتا ہے، جو عبادت سے کنارہ کشی کی جانب لے جاتی ہے۔ جب کہ فرائض پر اکتفا اور نوافل سے احتراز سستی اور عبادت میں عدم نشاط  کا سبب بنتا ہے۔ بہتر راستہ اعتدال کا راستہ ہے۔\r", "اس حدیث سے معلوم ہوتا ہے اکابر کے حالات، ان کے نقش قدم پر چلنے کے لیے، معلوم کیے جا سکتے ہيں۔ اگر مردوں سے معلوم کرنا دشوار ہو تو عورتوں سے بھی دریافت کیا جا سکتا ہے۔\r", "اس حدیث سے وعظ، علمی مسائل بیان کرنے، مکلفین کے آگے شرعی احکام بیان کرنے اور مجتہدین کے شبہات کو دور کرنے کی تعلیم ملتی ہے۔\r", "عبادت، بطور خاص فرائض ونوافل کی پابندی کے ساتھ اس میں میانہ روی اختیار کرنے کا حکم دیا گیا ہے، تاکہ دوسروں کے حقوق بھی ادا کیے جا سکیں۔\r", "یہ حدیث نکاح کی فضیلت اور اس کی ترغیب پر دلالت کرتی ہے۔"], "explanationAr": "جَاءَ نَفَرٌ من الصحابة رضي الله عنهم إلى بيوت أزواج النبي صلى الله عليه وسلم، يسألون عن عبادته في السر داخل بيته، فلما أُخبروا كأنهم تَقَالُّوها، فقالوا: \nوأين نحن من النبي صلى الله عليه وسلم؟ قد غُفر له ما تقدم من ذنبه وما تأخر، بخلاف مَن لم يعلم بحصول المغفرة له فيحتاج إلى المبالغة في العبادة عسى أن يَحصُل عليها.\n\nثم قال بعضهم: لا أتزوج النساء. \n\nوقال بعضهم: لا آكل اللحم.\n\nوقال بعضهم: لا أنام على فراش.\n\nفبلغ ذلك النبيَّ صلى الله عليه وسلم، فغضب، وخطب الناس، فحمد الله وأثنى عليه وقال: \n\nما شَأْنُ أقوامٍ قالوا كذا وكذا؟! والله إني لأخشاكم لله وأتقاكم له، لكني أنام لأتقوى على القيام، وأفطر لأتقوَّى على الصوم، وأتزوج النساء، فمن أعرض عن طريقتي ورأى الكمال في غيرها، وأخذ بطريقة غيري فليس مني.", "hintsAr": ["حب الصحابة رضي الله عنهم للخير، ورغبتهم فيه وفى الاقتداء بنبيهم صلى الله عليه وسلم.", "سماحة هذه الشريعة ويسرها، أخذًا من عمل نبيها صلى الله عليه وسلم وهديه.", "الخير والبركة في الاقتداء بالنبي صلى الله عليه وسلم، واتباع أحواله الشريفة.", "الزَّجْر عن التشديد على النفس في العبادات بما لا تطيق، وأن هذا من حال المبتدعين.", "قال ابن حجر: الأخذ بالتشديد في العبادة يُفضي إلى المَلَل القاطِع لأصلها، وملازمة الاقتصار على الفرائض مثلًا، وترك التنفُّل يفضي إلى إيثار البطالة، وعدم النشاط إلى العبادة، وخير الأمور الوسط.", "فيه تتبُّع أحوال الأكابر للتأسِّي بأفعالهم، وأنه إذا تعذَّرت معرفته من الرجال جاز استكشافه من النساء.", "فيه الوعظ وإلقاء مسائل العلم وبيان الأحكام للمكلَّفين، وإزالة الشبهة عن المجتهدين.", "الأمر بالترفُّق في العبادة، مع المحافظة عليها وعلى الفرائض والنوافل؛ ليراعي المسلم حقوق غيره عليه.", "في الحديث دلالة على فضل النكاح والترغيب فيه."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Anas ibn Malik"}, {"id": "65121", "number": 16, "title": "The Prophet knew Allah best", "section": 2, "sectionTitle": "Following the Messenger", "slug": "16-the-prophet-knew-allah-best", "ref": "Sahih al-Bukhari 20", "primary": "https://sunnah.com/bukhari:20", "source": "https://hadeethenc.com/en/browse/hadith/65121", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/65121", "ar": "عَنْ عَائِشَةَ أُمِّ المُؤْمِنينَ رَضِيَ اللهُ عَنْها قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَمَرَهُمْ أَمَرَهُمْ مِنَ الأَعْمَالِ بِمَا يُطِيقُونَ، قَالُوا: إِنَّا لَسْنَا كَهَيْئَتِكَ يَا رَسُولَ اللَّهِ، إِنَّ اللَّهَ قَدْ غَفَرَ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ، فَيَغْضَبُ حَتَّى يُعْرَفَ الغَضَبُ فِي وَجْهِهِ، ثُمَّ يَقُولُ: «إِنَّ أَتْقَاكُمْ وَأَعْلَمَكُمْ بِاللَّهِ أَنَا».", "en": "‘Ā’ishah, the Mother of the Believers (may Allah be pleased with her), reported: Whenever the Messenger of Allah (ﷺ) instructed his Companions to do something, he would command them only with what they were able to bear. They said: O Messenger of Allah, we are not like you; Allah has forgiven your past and future sins. He would then become angry until his anger would be visible on his face, and say: \"Indeed, I am the most God-fearing among you and the most knowledgeable of Allah.\"", "ur": "امّ المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہيں: رسول اللہ ﷺ جب انہیں اعمال کا حکم دیتے تو انہی کا حکم دیتے جن کی وہ طاقت رکھتے تھے۔ صحابہ عرض کرتے: ”اے اللہ کے رسول! ہم آپ کی طرح نہیں ہیں، اللہ تعالیٰ نے تو آپ کے اگلے پچھلے سب گناہ معاف فرما دیے ہیں“۔ اس پر آپ ﷺ غضب ناک ہو جاتے یہاں تک کہ غصہ آپ کے چہرۂ مبارک پر نمایاں ہو جاتا، پھر آپ ﷺ فرماتے:  ”یقیناً تم میں سب سے زیادہ اللہ سے ڈرنے والا اور اسے جاننے والا میں ہی ہوں۔“", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Al-Bukhāri", "explanation": "The Mother of the Believers ‘Ā’ishah (may Allah be pleased with her) informs that the Prophet (ﷺ), when commanding people to perform deeds, would instruct them to do only what was easy for them and not burdensome—out of concern that they might be unable to maintain it consistently. He himself acted upon what he commanded of moderation and ease. However, they requested to be tasked with more difficult acts, believing that they needed to exert greater effort in worship to attain higher ranks and perhaps reach a status close to his. They would say: Our situation is not like yours, O Messenger of Allah, for Allah has forgiven all your past and future sins. He would then become angry—so much so that the anger could be seen on his face—and he would say: I am the most God-fearing and the most knowledgeable among you about Allah. So, do as I command you.", "explanationUr": "ام المومنین عائشہ رضی اللہ عنہا بتاتی ہیں کہ نبی ﷺ جب لوگوں کو کسی عمل کا حکم دیتے تو انہیں اسی کام کا حکم دیتے جو ان کے لیے آسان ہوتا، نہ کہ مشکل کام کا؛ اس اندیشے سے کہ کہیں وہ اس پر ہمیشگی اختیار کرنے سے عاجز نہ ہو جائیں۔ آپ ﷺ خود بھی اسی آسانی پر عمل فرماتے جس کا آپ ﷺ انہیں حکم دیتے تھے۔ لیکن صحابہ نے آپ ﷺ سے مشقت والے کاموں کا مکلف بنانے کی درخواست کی، کیونکہ ان کا خیال تھا کہ آپ ﷺ کے برعکس انہیں بلند درجات حاصل کرنے کے لیے عمل میں مبالغہ کرنے کی ضرورت ہے۔ چنانچہ صحابہ عرض کرتے: یا رسول اللہ! ہمارا حال آپ کے جیسا نہیں ہے، بے شک اللہ نے آپ کے اگلے پچھلے تمام گناہ معاف فرما دیے ہیں۔ اس پر آپ ﷺ غضبناک ہو جاتے یہاں تک کہ غصہ آپ ﷺ کے چہرہ مبارک پر ظاہر ہو جاتا، پھر آپ ﷺ فرماتے: بے شک تم میں سب سے زیادہ متقی اور اللہ کو سب سے زیادہ جاننے والا میں ہی ہوں۔ لہذا وہی کرو جس کا میں تمہیں حکم دیتا ہوں۔", "hints": ["Ibn Hajar said: He only commanded them with what was easy for them so that they would do it consistently, as he said in another Hadīth: \"The most beloved deeds to Allah are those done consistently.\"\r", "A righteous man should not abandon striving in good deeds, relying merely on his righteousness.\r", "It is permissible for a person to speak about his own virtue when there is a need to do so, provided he is safe from pride and arrogance.\r", "The best approach in worship is moderation and consistency—not exaggeration that leads to abandonment.\r", "Ibn Hajar said: When a servant reaches the highest level in worship and its fruits, that should make him even more persistent in maintaining it, in order to preserve the blessing and increase it through gratitude.\r", "It is permissible to show anger when a religious command is violated, and to reproach a knowledgeable or intelligent person who fails to understand the intended meaning—in order to urge him to be more attentive.\r", "The Prophet (ﷺ) showed gentleness toward his Ummah, demonstrating that the religion is one of ease and that the Shariah is upright and tolerant.\r", "The strong desire of the Companions for worship and their eagerness to increase in goodness.\r", "Adhering to the limits set by the Legislator—whether in strict obligations or permitted concessions—and believing that choosing the easier option, when it aligns with the Shariah, is better than taking the harder path that goes against it."], "hintsUr": ["ابن حجر نے فرمایا: آپ ﷺ نے انہیں اسی عمل کا حکم دیا جو ان کے لیے آسان ہو، تاکہ وہ اس پر مداومت برتیں، جیسا کہ دوسری حدیث میں ہے: اللہ کے نزدیک سب سے بہتر عمل وہ ہے جس پر ہمیشگی برتی جائے۔\r", "نیک وصالح آدمی کو چاہیے کہ وہ اپنے نیک ہونے پر بھروسہ کر کے عمل میں جد وجہد سے دست کش نہ ہو۔\r", "کسی شخص کا حسبِ ضرورت اپنی فضیلت بیان کرنا جائز ہے، جب فخر اور تکبر کا خوف نہ ہو۔\r", "عبادت میں اولیٰ میانہ روی اور ہمیشگی ہے، نہ کہ ایسی مبالغہ آمیزی جو ترک کا باعث بنے۔\r", "ابن حجر کہتے ہیں: بندہ جب عبادت اور اس کے ثمرات میں انتہا کو پہنچ جاتا ہے تو یہ اسے اس عمل پر ہمیشگی اختیار کرنے پر مزید آمادہ کرتی ہے، کیونکہ اس کے ذریعے نعمت باقی رہتی ہے اور اس پر شکر کرنے سے اس میں اضافہ ہوتا ہے۔\r", "شرعی حکم کی مخالفت پر غضہ ہونے کی مشروعیت، اور فہمِ معنی کے اہل ذہین وفطین شخص کے فہم میں کوتاہی کرنے پر اس کی نکیر کرنا، تاکہ اسے بیدار مغزی پر ابھارا جائے۔\r", "اپنی امت پر نبی ﷺ کی شفقت، دین کی آسانی اور شریعت کی رواداری اور وسعت۔\r", "صحابہ کرام عبادت میں شدید رغبت رکھتے تھے اور زیادہ سے زیادہ خیر حاصل کرنے کے خواہاں تھے۔\r", "شارع کی مقرر کردہ عزیمت اور رخصت کی حد پر ٹھہرنا اور یہ عقیدہ رکھنا کہ شریعت کے موافق آسان ترین بات پر عمل کرنا، اس مشکل ترین کام سے اولیٰ ہے جو اس کے مخالف ہو۔"], "explanationAr": "تُخبر أمُّ المؤمنين عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان إذا أمر الناس بعمل من الأعمال أمرهم بما يسهل عليهم دون ما يشق، خشية أن يعجزوا عن الدوام عليه، وعمل هو بنظير ما يأمرهم به من التخفيف، لكنهم طلبوا منه التكليف بما يشق، لاعتقادهم احتياجهم إلى المبالغة في العمل لرفع الدرجات دونه.\n\n فيقولون: إنا ليس حالنا كحالك يا رسول الله، فإن الله قد غفر لك ما تقدم من ذنبك وما تأخر، فيغضب حتى يعرف الغضب في وجهه، ثم يقول: إن أتقاكم وأعلمكم بالله أنا، فافعلوا ما آمركم به.", "hintsAr": ["قال ابن حجر: إنما أمرهم بما يسهل عليهم ليداوموا عليه كما قال في الحديث الآخر: \"أحب العمل إلى الله أدومه\".", "الرجل الصالح ينبغي ألا يترك الاجتهاد في العمل اعتمادًا على صلاحه.", "جواز تحدث المرء بما فيه من فضل بحسب الحاجة لذلك عند الأمن من المباهاة والتعاظم.", "الأولى في العبادة القصد والملازمة، لا المبالغة المفضية إلى الترك.", "قال ابن حجر: العبد إذا بلغ الغاية في العبادة وثمراتها كان ذلك أدعى له إلى المواظبة عليها، استبقاء للنعمة، واستزادة لها بالشكر عليها.", "مشروعية الغضب عند مخالفة الأمر الشرعي، والإنكار على الحاذق المتأهل لفهم المعنى إذا قصر في الفهم، تحريضًا له على التيقظ.", "رفق النبي صلى الله عليه وسلم بأمته، وأن الدين يسر، وأن الشريعة حنيفية سمحة.", "شدة رغبة الصحابة في العبادة، وطلبهم الازدياد من الخير.", "الوقوف عند ما حد الشارع من عزيمة ورخصة، واعتقاد أن الأخذ بالأرفق الموافق للشرع أولى من الأشق المخالف له."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Aishah"}, {"id": "5518", "number": 17, "title": "Understanding the religion", "section": 3, "sectionTitle": "Learning and transmission", "slug": "17-understanding-the-religion", "ref": "Sahih al-Bukhari 71", "primary": "https://sunnah.com/bukhari:71", "source": "https://hadeethenc.com/en/browse/hadith/5518", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/5518", "ar": "عن معاوية رضي الله عنه قال: سمعت النبي صلى الله عليه وسلم يقول: «مَنْ يُرِدِ اللهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ، وَإِنَّمَا أَنَا قَاسِمٌ، وَاللهُ يُعْطِي، وَلَنْ تَزَالَ هَذِهِ الْأُمَّةُ قَائِمَةً عَلَى أَمْرِ اللهِ، لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ، حَتَّى يَأْتِيَ أَمْرُ اللهِ».", "en": "Mu‘āwiyah (may Allah be pleased with him) reported: I heard the Prophet (may Allah's peace and blessings be upon him) say: \"When Allah intends good for someone, He grants him the understanding of the religion. Indeed, I am only a distributor, and Allah is the Giver. This Ummah will continue to follow Allah's laws, not being harmed by those who oppose them, until Allah's command comes to pass.\"", "ur": "معاویہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ میں نے اللہ کے رسول صلی اللہ علیہ و سلم کو کہتے ہوئے سنا ہے : ”جس کے ساتھ اللہ خیر کا ارادہ کرتا ہے، اسے دین کی سمجھ عطا کر دیتا ہے۔ میں تو بس تقسیم کرنے والا ہوں، دینے والا اللہ ہے۔ یہ امت اللہ کے دین پو قائم رہے گی، اس کی مخالفت کرنے والے اسے نقصان نہیں پہنچا سکیں گے، یہاں تک کہ اللہ کا امر آجائے“۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "The Prophet (may Allah's peace and blessings be upon him) informs that when Allah wills to do good to someone, He endows him with the understanding of His religion. He also states that he is only a distributor who distributes the sustenance, knowledge, and other things that Allah Almighty gave him, and that the true Giver is Allah, and all else are mere causes that can only bring benefit with Allah's permission. He adds that this Ummah will continue to hold onto Allah's laws and not be harmed by those who oppose them until the Hour comes.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم بتا رہے ہیں کہ اللہ جس کے ساتھ خیر کا ارادہ کرتا ہے، اسے اپنے دین کی سمجھ عطا کرتا ہے۔ دوسری بات یہ ہے اللہ کے رسول صلی اللہ علیہ و سلم کی ذات ایک بانٹنے والے کی ہے۔ آپ اللہ کا دیا ہوا مال اور علم وغیرہ لوگوں کے بیچ بانٹنے کا کام کرتے ہيں۔ جب کہ اصل دینے والا اللہ ہے۔ اس کے سوا دوسرے لوگ اسباب ہیں، جو اللہ کی اجازت کے بغیر کسی کا کچھ بھلا نہیں کر سکتے۔ تیسری بات آپ نے یہ بتائی کہ یہ امت قیامت کے دن تک اللہ کے دین پر قائم رہے گی اور اس کی مخالفت کرنے والے اسے نقصان نہیں پہنچا سکیں گے۔", "hints": ["The Hadīth shows the greatness and merit of the Shar‘i knowledge and its learning and urges us to seek it.\r", "Adherence to the truth must exist within this Ummah. If one group forsakes it, another will follow it.\r", "Understanding of the religion is part of Allah's intention of goodness for His servants.\r", "The Prophet (may Allah's peace and blessings be upon him) only gives according to Allah's Command and His Will, and he himself possesses nothing."], "hintsUr": ["شرعی علم  کی عظمت، اسے سیکھنے کی فضیلت اور زیورِ علم  سے آراستہ ہونے کی ترغیب۔\r", "اس امت کے اندر سچے دین پر عمل کرنے والے  ہمیشہ موجود رہیں گے۔ اگر ایک گروہ اس سے بے رخی برتے گا تو دوسرا گروہ اس پر قائم ہوجائے گا۔\r", "کسی شخص کو دین کی سمجھ اس وقت حاصل ہوتی ہے، جب اللہ اس کے ساتھ خیر کا ارادہ کرتا ہے۔\r", "اللہ کے نبی صلی اللہ علیہ و سلم اللہ کے حکم اور اس کی مشیت سے دیتے ہيں۔ آپ کسی چیز کے مالک نہيں ہیں۔"], "explanationAr": "يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ مَن أراد اللهُ به خيرًا فإنه يرزقه فَهمًا في دينه سبحانه، وأنه عليه الصلاة والسلام قاسِمٌ يَقْسِمُ ويُوَزِّعُ ما آتاه الله تعالى من الرزق والعلم وغيرِه، وأنَّ المُعطِي حقيقةً هو الله، وأما غيرُه فهم أسبابٌ لا تَنْفَعُ إلا بإذن الله، وأنه لن تزال هذه الأمةُ قائمةً على أمر الله، لا يضرهم مَن خالفهم، حتى تقوم الساعة.", "hintsAr": ["عَظَمة وفَضْل العلم الشرعي وتَعَلُّمُه والحثُّ عليه.", "القيام بالحق لا بد من وجودِه في هذه الأمة، فإذا تخلَّت عنه طائفة قام به غيرُها.", "التَّفَقُّهُ في الدين مِن إرادةِ اللهِ تعالى الخيرَ لعبدِه.", "النبي صلى الله عليه وسلم إنما يُعْطِي بأمر الله ومشيئته، وأنه لا يملك شيئًا."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Muawiyah"}, {"id": "4233", "number": 18, "title": "Guidance is like life-giving rain", "section": 3, "sectionTitle": "Learning and transmission", "slug": "18-guidance-is-like-life-giving-rain", "ref": "Sahih al-Bukhari 79", "primary": "https://sunnah.com/bukhari:79", "source": "https://hadeethenc.com/en/browse/hadith/4233", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/4233", "ar": "عَنْ أَبِي مُوسَى رَضيَ اللهُ عنه عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَثَلُ مَا بَعَثَنِي اللَّهُ بِهِ مِنَ الهُدَى وَالعِلْمِ كَمَثَلِ الغَيْثِ الكَثِيرِ أَصَابَ أَرْضًا، فَكَانَ مِنْهَا نَقِيَّةٌ، قَبِلَتِ المَاءَ، فَأَنْبَتَتِ الكَلَأَ وَالعُشْبَ الكَثِيرَ، وَكَانَتْ مِنْهَا أَجَادِبُ، أَمْسَكَتِ المَاءَ، فَنَفَعَ اللَّهُ بِهَا النَّاسَ، فَشَرِبُوا وَسَقَوْا وَزَرَعُوا، وَأَصَابَتْ مِنْهَا طَائِفَةً أُخْرَى، إِنَّمَا هِيَ قِيعَانٌ لاَ تُمْسِكُ مَاءً وَلاَ تُنْبِتُ كَلَأً، فَذَلِكَ مَثَلُ مَنْ فَقُهَ فِي دِينِ اللَّهِ وَنَفَعَهُ مَا بَعَثَنِي اللَّهُ بِهِ، فَعَلِمَ وَعَلَّمَ، وَمَثَلُ مَنْ لَمْ يَرْفَعْ بِذَلِكَ رَأْسًا، وَلَمْ يَقْبَلْ هُدَى اللَّهِ الَّذِي أُرْسِلْتُ بِهِ».", "en": "Abu Mūsa (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"The guidance and knowledge with which Allah has sent me are like abundant rain that fell on some ground. A part of it was good, absorbing the water, so it brought forth abundant herbage and pasture; and there were some bare patches in it that retained the water by which Allah gave benefit to people who drank, watered, and grew plants. But some of it fell on another flat portion that could not retain the water or produce herbage. That is like the one who becomes versed in Allah's religion and receives benefit from the message entrusted to me by Allah, so he knows for himself and teaches others; and it is like the one who does not show regard to that and does not accept Allah's guidance with which I have been sent.\"", "ur": "ابو موسی اشعری رضی اللہ عنہ سے روایت ہے کہ نبی ﷺ نے فرمایا: ”اللہ عزوجل نے جس علم و ہدایت کے ساتھ مجھ کو مبعوث کیا ہے اس کی مثال اس بارش کی طرح ہے جو زمین پر برسی، زمین کا کچھ حصہ اچھا تھا جس نے اس پانی کو جذب کر لیا اور اس نے چارہ اور بہت سا سبزہ اگایا اور زمین کا بعض حصہ سخت تھا ، اس نے پانی کو روک لیا جس سے اللہ تعالیٰ نے لوگوں کو نفع دیا ، انہوں نے وہ پانی خود پیا ، جانوروں کو پلایا اور کھیتیاں کیں۔ جب کہ زمین کا بعض حصہ چٹیل میدان تھا ، جس پر بارش ہوئی تو اس نے نہ پانی کو روکا اور نہ کسی قسم کی گھاس اگائی۔ پہلی مثال ان لوگوں کی ہے جنہوں نے اللہ کے دین کو سمجھا اور اس کا فیض پہنچایا اور اللہ تعالیٰ نے جس ہدایت کے ساتھ مجھے مبعوث کیا ہے اس کا علم حاصل کیا اور وہ علم آگے پہنچایا (آنے والی نسلوں تک منتقل کیا) اور دوسری مثال ان لوگوں کی ہے جنہوں نے اس کی طرف سر اٹھاکر نہیں دیکھا اور جس ہدایت کے ساتھ مجھے مبعوث کیا گیا ہے اس کو قبول نہیں کیا“۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "The Prophet (may Allah's peace and blessings be upon him), expressing amazement, likened the one who benefits from what he brought—of guidance and the path that leads to the ultimate goal—and from religious knowledge to a land upon which abundant rain falls. This land, in turn, is of three types: The first type: a pure and fertile land that absorbs the rainwater, causing abundant vegetation—both fresh and dry—to grow, from which people benefit. The second type: land that holds water but does not grow vegetation. It retains the water, allowing people to benefit from it—drinking from it, watering their animals, and irrigating their crops. And the third type: a flat, smooth land that neither retains water nor grows any vegetation. It neither benefits itself from the rainwater, nor does it benefit others. Likewise are those who hear what the Prophet (may Allah's peace and blessings be upon him) was sent with—of knowledge and guidance. The first type: the scholar who understands the religion of Allah, acts upon his knowledge, and teaches it to others. He is like the fertile land that absorbs the water, benefiting itself and causing the growth of the plantation, and thereby benefiting others. The second type: the one who memorizes and preserves knowledge but does not have a deep understanding or the ability to derive rulings. He collects knowledge and spends his time doing so, but he either does not act upon its supererogatory aspects or does not comprehend what he has gathered. He is like a tool for others— benefiting them—and is similar to land that holds water, from which people benefit. The third type: the one who hears knowledge but neither preserves it, nor acts upon it, nor conveys it to others. He is like a barren or smooth land that has no vegetation, neither absorbing water nor allowing others to benefit from it.", "explanationUr": "آپ ﷺ نے فرمایا ” اللہ عزوجل نے جس علم و ہدایت کے ساتھ مجھ کو مبعوث کیا ہے اس کی مثال اس بارش کی طرح ہے جو زمین پر برسی“ آپ ﷺ نے علم و ہدایت کے ذریعے دوسروں کو نفع پہنچانے والوں کو زمین کی پیداوار پر ہونے والی بارش سے تشبیہ دی ہے۔\nزمین کی تین قسمیں ہیں: پاک زمین جس نے پانی کو قبول کر لیا اور بہت ساری گھاس اور کھیتی اُگائی، لوگ اس سے نفع حاصل کرتے ہیں۔\nدوسری وہ زمین جو کچھ اُگاتی تو نہیں تاہم پانی جمع کر لیتی ہے، لوگ اس پانی سے نفع حاصل کرتے ہیں، اس سے پانی پیتے ہیں، آسودہ ہوتے ہیں، اور اس سے اپنے کھیت سیراب کرتے ہیں۔\nتیسری وہ زمین جو نہ ہی پانی کو روکتی ہے اور نہ ہی کچھ اُگاتی ہے۔\nاسی طرح اللہ تعالیٰ کے اپنے نبی کو دیے ہوئے علم وہدایت کے اعتبار سے لوگوں کی مختلف قسمیں ہیں۔\nبعض لوگ اللہ کے دین کی سمجھ رکھتے ہیں، علم حاصل کرکے دوسروں کو سکھاتے ہیں اور لوگ بھی اس کے علم سے مستفید ہوتے ہیں اور وہ خود بھی مستفید ہوتا ہے۔\nدوسری قسم میں وہ لوگ جو ہدایت یافتہ ہیں، لیکن انہیں دین میں تفقّہ حاصل نہیں، بایں طور کہ وہ علم اور حدیث کو روایت کرتے ہیں، لیکن علمِ فقہ ان کے پاس نہیں۔\nتیسری قسم میں وہ لوگ جو علم و ہدایت بالکل بھی حاصل نہ کریں، اس سے اعراض کر کے لاپرواہی کا مظاہرہ کریں۔ یہ لوگ نہ خود علم سے فائدہ حاصل کرتے ہیں اور نہ ہی دوسروں کو نفع پہنچاتے ہیں۔", "hints": ["A clarification of the virtue of seeking knowledge and teaching it, and a warning against turning away from both.\r", "Using parables and analogies helps clarify meanings for people.\r", "Al-Qurtubi said: Just as rain revives dead land, religious knowledge revives the dead heart. Then, the Prophet (may Allah's peace and blessings be upon him) likened those who hear this knowledge to the various types of land upon which the rain falls.\r", "People vary in their ranks in terms of their reception of religious knowledge."], "hintsUr": [], "explanationAr": "شَبّه النبي صلى الله عليه وسلم متعجبًا من ينتفع بما جاء به من الدلالة والطريق الذي يوصل للمطلوب، والعلم الشرعي بالأرض التي ينزل عليها المطر الكثير؛ فكانت أقسامًا ثلاثة: \n\nأولها: أرض نقية طيبة، تقبل ماء الأمطار، فتنبت النبات الكثير رطبًا ويابسًا، فانتفع الناس بها. \n\nوثانيها: أرض ممسكة للماء لكنها لا تنبت زرعًا، فهي تحفظ الماء لينتفع به الناس؛ فيشربون ويسقون مواشيهم وزروعهم. \n\nوثالثها: أرض مستوية ملساء لا تمسك ماء ولا تنبت زرعًا، فهي لم تنتفع بذلك الماء في نفسها، ولم ينتفع الناس منها. \n\nفكذا السامعين لما بُعث به النبي صلى الله عليه وسلم من العلم والهدى. \n\nفالأول: العالم المتفقه في دين الله، العامل بعلمه، المعلم لغيره؛ فهو بمنزلة الأرض الطيبة شربت فانتفعت في نفسها، وأنبتت فنفعت غيرها. \n\nوالثاني: الحافظ للعلم لكن ليس له فهم واستنباط، فهو جامع للعلم، مستغرق لزمانه في ذلك، غير أنه لم يعمل بنوافله، أو لم يفقه ما جمع؛ فهو أداة لغيره، وهو بمنزلة الأرض التي يستقر فيها الماء فينتفع الناس به. \n\nوالثالث: من يسمع العلم فلا يحفظه، ولا يعمل به، ولا ينقله لغيره؛ فهو بمنزلة الأرض السبخة أو الملساء التي لا نبات فيها ولا تقبل الماء أو تفسده على غيرها.", "hintsAr": ["بيان فضل طلب العلم وتعليمه، والتحذير من الإعراض عنهما.", "ضرب الأمثال لتقريب المعاني للناس.", "قال القرطبي: فكما أن الغيث يحيي البلد الميت فكذا علوم الدين تحيي القلب الميت، ثم شبه السامعين له بالأرض المختلفة التي ينزل بها الغيث.", "الناس في الأخذ بالعلم الشرعي مراتب."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Musa al-Ashari"}, {"id": "6820", "number": 19, "title": "Conveying what we hear accurately", "section": 3, "sectionTitle": "Learning and transmission", "slug": "19-conveying-what-we-hear-accurately", "ref": "Jami at-Tirmidhi 2657", "primary": "https://sunnah.com/tirmidhi:2657", "source": "https://hadeethenc.com/en/browse/hadith/6820", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/6820", "ar": "عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رضي الله عنه قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا شَيْئًا فَبَلَّغَهُ كَمَا سَمِعَ، فَرُبَّ مُبَلِّغٍ أَوْعَى مِنْ سَامِعٍ».", "en": "‘Abdullah ibn Mas‘ūd (may Allah be pleased with him) reported: I heard the Prophet (may Allah's peace and blessings be upon him) say: \"May Allah brighten the person who hears something from us and conveys it as he heard it, for perhaps the one to whom it is conveyed is more mindful than the hearer.\"", "ur": "عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ میں نے اللہ کے نبی صلی اللہ علیہ و سلم کو کہتے ہوئے سنا: ”اللہ اس شخص کو تروتازہ (اور خوش) رکھے، جس نے مجھ سے کوئی بات سنی، پھر اس نے اسے جیسے مجھ سے سنا تھا ہو بہو ویسے ہی دوسروں تک پہنچا دیا، کیونکہ بہت سے لوگ جنہیں بات (حدیث) پہنچائی جائے پہنچانے والے سے کہیں زیادہ بات کو سمجھنے والے ہوتے ہیں“۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by At-Tirmidhi, Ibn Mājah, and Ahmad", "explanation": "The Prophet (may Allah's peace and blessings be upon him) prayed for brightness, joy, and beauty in this world, and that Allah grants the person the radiance, bliss, and bloom of Paradise in the Hereafter for whoever hears his Hadīth and memorizes it to convey it to others. Perhaps the one to whom the Hadīth is conveyed understands it better, has deeper insight, and is more capable of deriving rulings than the one who originally transmitted it. The first excels in memorization and transmission, while the second excels in understanding and deduction.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم نے دنیا میں تازگی و سرسبزی اور آخرت میں سرسبزی وشادابی اور نعمتوں کے حصول کی دعا ہر اس شخص کے لیے فرمائی ہے، جو آپ کی حدیث سنے، اسے یاد رکھے اور دوسروں کو پہنچا دے۔ کیوں کہ بارہا ایسا ہوتا ہے کہ ناقل حدیث کے مقابلے میں اس سے اخذ کرنے والا ہی کہیں زیادہ یاد رکھنے والا، سمجھنے والا اور استنباط کی صلاحیت رکھنے والا ہوتا ہے۔ ایسے میں پہلا شخص حفظ ونقل کا کام بہتر انداز سے کرتا ہے اور دوسرا فہم واستنباط کا کام بہتر طریقے سے کرتا ہے۔", "hints": ["Encouraging the memorization of the Prophetic Sunnah and its conveyance to people.\r", "Highlighting the merit of the people of Hadīth and the honor of seeking such knowledge.\r", "The merit of scholars, who are the people of deduction and understanding.\r", "The merit of the Companions (may Allah be pleased with them), as they are the ones who heard the Hadīth of the Messenger of Allah (may Allah's peace and blessings be upon him) and conveyed it to us.\r", "Al-Munāwi said: He clarified here that comprehension is not a condition for the Hadīth narrator; rather, memorization is a condition. However, understanding and reflection are required from the jurist.\r", "Ibn ‘Uyaynah said: No one who seeks Hadīth except that there is brightness in his face because of this Hadīth.\r", "Memorization, according to the scholars of Hadīth, is of two types: memorization of the heart and mind, and memorization through writing in books and lines. Both types are included in the supplication mentioned in the Hadīth.\r", "People vary in their level of understanding, for perhaps the one to whom knowledge is conveyed is better at understanding than the hearer, and perhaps the one carrying the knowledge of Fiqh (Islamic jurisprudence) is not himself a jurist."], "hintsUr": ["اللہ کے نبی صلی اللہ علیہ و سلم کی سنت کو یاد کرنے اور اسے لوگوں کو پہنچانے کی ترغیب۔\r", "اہلِ حدیث اور طلب حدیث کے مقام ومرتبہ کا بیان۔\r", "ان علما کی فضیلت جو استنباط اور فہم کی صلاحیت رکھتے ہيں۔\r", "صحابہ رضی اللہ عنہم کی فضیلت، جنھوں نے اللہ کے رسول صلی اللہ علیہ و سلم کی حدیث سنی اور اسے ہم تک پہنچایا۔\r", "مناوی کہتے ہيں: اس حدیث سے معلوم ہوتا ہے کہ راوی حدیث کے لیے فقیہ ہونا شرط نہیں ہے۔ اس کے لیے شرط یاد رکھنا ہے۔ فہم وتدبر کا کام فقیہ کا ہے۔\r", "ابن عیینہ کہتے ہیں: طالب حدیث کے چہرے سے ہمیشہ تازگی جھلکتی ہے۔\r", "محدثین کے یہاں حفظ کی دو قسمیں ہیں۔ حفظ قلب وصدر اور حفظ کتاب وسطر۔ دونوں اس حدیث میں کی گئی دعا میں شامل ہیں۔\r", "لوگوں کی سمجھ مختلف ہوتی ہے۔ کیوں کہ بہت سے پہنچائے گئے لوگ سننے والے سے زیادہ یاد رکھنے والے ہیں اور بہت سے فقہ کے حامل لوگ فقیہ نہیں ہوا کرتے۔"], "explanationAr": "دَعَا النبيُّ صلى الله عليه وسلم بالنَّضَارة والبَهْجَة والحُسْن في الدنيا، وأنْ يُوصله الله إلى نَضْرَة الجنة ونعيمها ونَضَارتها في الآخرة؛ لمن سمع حديثه فحَفِظَه حتى يُبلِّغَه لغيره، فربما يكون المنقول له الحديث أَوعى وأفقه وأقدر على الاستنباط من ناقِل الحديث، فيكون الأول يُتْقِنُ الحفظ والنقل، ويكون الثاني يتقن الفهم والاستنباط.", "hintsAr": ["الحث على حفظ السنة النبوية، وتبليغها للناس.", "بيان فضل أهل الحديث، وشَرَف طلبه.", "فضل العلماء، الذين هم أهل الاستنباط والفهم.", "فضل الصحابة رضوان الله عليهم، فهم من سمعوا حديث رسول الله صلى الله عليه وسلم وبَلَّغوه لنا.", "قال المناوي: بَيَّنَ به أنَّ راوي الحديث ليس الفقه مِن شَرْطِه، إنما شَرْطُه الحفظ، وعلى الفقيه التَّفَهُّم والتدبُّر.", "قال ابن عيينة: ما من أحد يطلب الحديث إلا وفي وجهه نَضْرة لهذا الحديث.", "الحِفْظ عند المُحدِّثين على نوعين: حِفْظ قَلْب وصَدْر، وحِفظ كتاب وسَطْر، وكلاهما يشمله الدعاء في الحديث.", "فهوم الناس مُتَفَاوِتَة، فرُبّ مبلغ أوعى من سامع، ورب حامل فقه ليس بفقيه."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abdullah ibn Masud"}, {"id": "3686", "number": 20, "title": "Convey faithfully and avoid falsehood", "section": 3, "sectionTitle": "Learning and transmission", "slug": "20-convey-faithfully-and-avoid-falsehood", "ref": "Sahih al-Bukhari 3461", "primary": "https://sunnah.com/bukhari:3461", "source": "https://hadeethenc.com/en/browse/hadith/3686", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/3686", "ar": "عن عبد الله بن عمرو رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «بَلِّغُوا عَنِّي وَلَوْ آيَةً، وَحَدِّثُوا عَنْ بَنِي إِسْرَائِيلَ وَلَا حَرَجَ، وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ».", "en": "‘Abdullāh ibn ‘Amr (may Allah be pleased with him) reported: The Prophet (may Allah's peace and blessings be upon him) said: \"Convey from me even if one verse, and narrate from the Children of Israel, and there is no sin in doing that. And whoever intentionally tells a lie about me, let him occupy his seat in Hellfire.\"", "ur": "عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ اللہ کے نبی ﷺ نے فرمایا: ”میری طرف سے لوگوں کو پہنچا دو، اگرچہ ایک آیت ہی ہو۔ بنی اسرائیل سے روایت کرو، ان سے بیان کرنے میں کوئی حرج نہیں ہے۔ جس نے مجھ پر جان بوجھ کر جھوٹ باندھا، وہ اپنا ٹھکانہ جہنم میں بنا لے“۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Al-Bukhāri", "explanation": "The Prophet (may Allah's peace and blessings be upon him) commands us to convey knowledge from him, from the Qur’an or the Sunnah, even if it is something short, like a verse from the Qur’an or a Hadīth, provided that a person should have knowledge of what he conveys and invites people to it. Then, the Prophet (may Allah's peace and blessings be upon him) points out that there is no sin in narrating about the Children of Israel and the events that happened to them, in a way that does not run counter to our Shariah. Then, he warns against telling lies about him and states that whoever intentionally lies about him should occupy his dwelling in Hellfire.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم آپ سے نقل شدہ علم کو پہنچانے کا حکم دے رہے ہیں، چاہے وہ قرآن کی صورت میں ہو یا حدیث کی صورت میں۔ وہ علم کم، مثلا قرآن کی ایک آیت یا ایک حدیث ہی کیوں نہ ہو۔ بس شرط یہ ہے کہ انسان جو کچھ پہنچا رہا ہے اور جس کی دعوت دے رہا ہے، اس کے پاس اس کی جان کاری ہو۔ پھر اللہ کے نبی صلی اللہ علیہ و سلم نے بتایا کہ بنی اسرائیل کے زمانے میں وقوع پزیر ہونے والے ایسے واقعات کو بیان کرنے میں کوئی حرج نہيں ہے، جو ہماری شریعت سے ٹکراتی نہ ہوں۔ اس کے بعد آپ نے اپنی طرف جھوٹ کی نسبت کرنے سے ڈرایا ہے اور بتایا ہے کہ جس نے آپ کی جانب جان بوجھ کر جھوٹ کی نسبت کی، وہ اپنا ٹھکانہ جہنم میں بنا لے۔", "hints": ["This hadith encourages us to convey the Shariah of Allah and indicates that a person should pass on what he learns and understands, even if it is something little.\r", "It is obligatory to seek knowledge of the Shariah, so that we can worship Allah and convey His religion in a correct way.\r", "We are obligated to ascertain the authenticity of any Hadīth before we convey and spread it, lest we fall under this stern warning.\r", "We are urged to be truthful and cautious in our speech, lest we fall into telling lies, particularly when it comes to the Shariah of Allah Almighty."], "hintsUr": ["اللہ کی شریعت کو پہنچانے کی ترغیب اور اس بات کی نشان دہی کہ انسان کی ذمے داری بنتی ہے کہ اس نے جو کچھ یاد کیا ہے اور سمجھ رکھا ہے، اسے دوسروں کو پہنچا دے، چاہے وہ کم ہی کیوں نہ ہو۔\r", "شرعی علم طلب کرنے کا وجوب، تاکہ بندہ اللہ کی عبادت اور اس کی شریعت کی تبیلغ جیسے کام صحیح طریقے سے کر سکے۔\r", "کسی بھی حدیث کو دوسروں تک پہنچانے یا اسے عام کرنے سے پہلے اس کی صحت کا یقین حاصل کر لینا ضروری ہے، تاکہ انسان اس سخت وعید کی چپیٹ میں نہ آ جائے۔\r", "بات کرتے وقت سچ بولنے اور حدیث نقل کرتے وقت احتیاط سے کام لینے کی ترغیب۔ خاص طور سے اللہ کی شریعت کے معاملے میں‘ تاکہ انسان جھوٹ میں نہ پڑ جائے۔"], "explanationAr": "يأمرُ النبيُّ صلى الله عليه وسلم بتبليغ العلم عنه من كتاب أو سنة، ولو كان الشيء قليلًا كآية من القرآن أو حديث، بشرط أن يكون عالمًا بما يبلِّغُ به ويدعو إليه. \nثم بيَّن صلى الله عليه وسلم أنه لا بأس بالتحديث عن بني إسرائيل بما وقع لهم من وقائع بما لا يتعارض مع شرعنا. \nثم حذَّر من الكذب عليه، وأنَّ من كذَب عليه متعمِّدًا فليتخذْ لنفسه مَنزلًا في النار.", "hintsAr": ["الترغيب في تبليغ شريعة الله، وأن المرء عليه أنْ يؤديَ ما حفِظَ وفَهِمَ ولو كان يسيرًا.", "وجوب طلب العلم الشرعي؛ ليتمكَّن من عبادة الله وتبليغ شريعته بصورة صحيحة.", "وجوب التأكد من صحة أي حديث قبل تبليغه أو نشره حذرًا من الدخول في هذا الوعيد الشديد.", "الحث على الصدق في الكلام والحيطة في الحديث، حتى لا يقع في الكذب، وخاصة في شرع الله عز وجل."], "words": [{"word": "لا حرج", "meaning": " لا إثم ولا ذنب."}, {"word": "بنو إسرائيل", "meaning": " هم بنو يعقوب بن إسحاق بن إبراهيم، فإسرائيل لقب ليعقوب. والمراد أتباع دينهم من اليهود والنصارى."}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abdullah ibn Amr"}, {"id": "65043", "number": 21, "title": "Never attribute a deliberate lie", "section": 3, "sectionTitle": "Learning and transmission", "slug": "21-never-attribute-a-deliberate-lie", "ref": "Sahih al-Bukhari 110", "primary": "https://sunnah.com/bukhari:110", "source": "https://hadeethenc.com/en/browse/hadith/65043", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/65043", "ar": "عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ».", "en": "Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever tells a lie about me intentionally, let him take his seat in Hellfire.\"", "ur": "ابو ہریرہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ اللہ کے رسول ﷺ نے فرمایا: \"جو شخص مجھ پر جان بوجھ کر جھوٹ بولے وہ اپنا ٹھکانہ جہنم میں بنا لے۔\"", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "The Prophet (may Allah's peace and blessings be upon him) clarified that whoever deliberately tells a lie about him, by falsely attributing a statement or action to him, will have a seat in Hellfire in the Hereafter as a recompense for lying about him.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم  نے بتایا کہ جس نے آپ پر جھوٹ بولا، یعنی کسی قول یا عمل کی جھوٹی نسبت آپ کی طرف کر دی، اسے اس جھوٹ کے بدلے میں آخرت میں جہنم میں جگہ دی جائے گی۔", "hints": ["Telling lies about the Prophet (may Allah's peace and blessings be upon him) deliberately and intentionally is a means of entering Hellfire.\r", "Telling a lie about the Prophet (may Allah's peace and blessings be upon him) is not like telling a lie about all other people because the former leads to serious evils in terms of religious and worldly affairs.\r", "Warning against spreading Hadīths before verifying them and making sure of their authentic attribution to the Prophet (may Allah's peace and blessings be upon him)."], "hintsUr": ["جان بوجھ کر اللہ کے نبی صلی اللہ علیہ و سلم پر جھوٹ بولنا جہنم میں دخول کا سبب ہے۔\r", "اللہ کے نبی صلی اللہ علیہ و سلم پر جھوٹ بولنا دیگر لوگوں پر جھوٹ بولنے کی طرح نہيں ہے۔ کیوں کہ آپ پر بولی جانے والی جھوٹ کے نتیجے میں دین اور دنیا  میں  بہت سارے مفاسد ظاہر ہوجاتے ہیں۔\r", "پوری چھان بین اور اللہ کے رسول صلی اللہ علیہ و سلم کی جانب نسبت کے صحیح ہونے کا اطمینان حاصل کیے بغیر حدیثوں کو عام کرنے کی ممانعت۔"], "explanationAr": "بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ مَن كَذَبَ عليه مُتعمدًا بنِسبةِ قولٍ أو فعلٍ له كَذبًا، فإنّ له في الآخرة مَجلسًا في النار؛ جزاء له على كذبه عليه.", "hintsAr": ["الكَذب على النبيِّ صلى الله عليه وسلم بالقصد والعَمْد سببٌ لدخول النار.", "الكذب على النبي عليه الصلاة والسلام ليس كالكذب على سائر الناس، لِمَا يَترتَّب على ذلك من مفاسد عظيمة في الدين والدنيا.", "التحذير من نشر الأحاديث قبل التثبُّت والتأكد من صحة نسبتها إلى النبي صلى الله عليه وسلم."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Hurayrah"}, {"id": "65077", "number": 22, "title": "Recording the Prophetic teaching", "section": 3, "sectionTitle": "Learning and transmission", "slug": "22-recording-the-prophetic-teaching", "ref": "Sunan Abi Dawud 3646", "primary": "https://sunnah.com/abudawud:3646", "source": "https://hadeethenc.com/en/browse/hadith/65077", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/65077", "ar": "عن عبدِ الله بن عمرو رضي الله عنهما قال: كنتُ أكتبُ كلَّ شيءٍ أسمعُه من رسولِ الله صلَّى الله عليه وسلم أُريدُ حفْظَه، فنهتْني قريشٌ، وقالوا: أتكْتبُ كلَّ شيءٍ تَسمَعُه من رسول الله صلَّى الله عليه وسلم، ورسولُ الله صلَّى الله عليه وسلم بَشَرٌ يتكلَّمُ في الغضَبِ والرِّضا؟ فأمسَكتُ عن الكتاب، فذكرتُ ذلك لرسول الله صلَّى الله عليه وسلم، فأومأ بإصبَعِه إلى فيه، فقال: «اكتُبْ، فوالذي نفسي بيدِه، ما يَخرُجُ منه إلا حقٌّ».", "en": "‘Abdullāh ibn ‘Amr (may Allah be pleased with him) reported: I used to write down everything I heard from the Messenger of Allah (may Allah's peace and blessings be upon him) in order to memorize it. The Quraysh prohibited me, saying: \"Do you write down everything that you hear from the Messenger of Allah (may Allah's peace and blessings be upon him) while the Messenger of Allah (may Allah's peace and blessings be upon him) is a human being who speaks in anger and pleasure?\" So, I stopped writing and mentioned that to the Messenger of Allah (may Allah's peace and blessings be upon him). Thereupon, he pointed his finger to his mouth and said: \"Write down; for by the One in Whose Hand my soul is, nothing comes out of it except the truth.\"", "ur": "عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے، وہ کہتے ہیں : اللہ کے رسول صلی اللہ علیہ وسلم سے میں جو کچھ سنتا سب لکھ لیا کرتا تھا، تاکہ ان کو محفوظ رکھا جا سکے۔ لہذا قریش کے کچھ لوگوں نے مجھے اس سے منع کیا اور کہا کہ کیا تم اللہ کے رسول صلی اللہ علیہ و سلم سے سنی ہوئی ہر بات لکھ لیا کرتے ہو، جب کہ اللہ کے رسول صلی اللہ علیہ و سلم انسان ہیں، غصہ اور خوشی دونوں حالتوں میں گفتگو کرتے ہیں؟ لہذا میں نے لکھنا موقوف کردیا اور یہ بات رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا، تو آپ صلی اللہ علیہ وسلم نے اپنی انگلی سے اپنے دہن مبارک کی طرف اشارہ کرتے ہوئے فرمایا : \"لکھا کرو، قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے، اس سے سوائے حق کے کچھ اور نہیں نکلتا\"۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Abu Dāwūd", "explanation": "‘Abdullāh ibn ‘Amr (may Allah be pleased with him) reported: I used to write down everything I heard from the Messenger of Allah (may Allah's peace and blessings be upon him) in order to memorize it by writing, but men from the Quraysh forbade me from doing so, saying: The Messenger of Allah (may Allah's peace and blessings be upon him) is a human being who speaks in pleasure and anger and so he is likely to err. Therefore, I stopped writing.\r\n\r\nI told the Prophet (may Allah's peace and blessings be upon him) about what they said, and he pointed with his finger to his mouth and said: Write down, for the One in Whose Hand my soul is, nothing comes out of it except the truth, in all conditions and in pleasure and anger.\r\n\r\nAnd Allah Almighty says about His Prophet (may Allah's peace and blessings be upon him): {Nor does he speak out of his own desire*. It is but a revelation sent down [to him].} [Surat an-Najm: 3-4]", "explanationUr": "عبداللہ بن عمرو رضی اللہ عنہ کہتے ہيں کہ میں اللہ کے رسول صلی اللہ علیہ و سلم سے سنی ہوئی ہر بات کو لکھ لیا کرتا تھا، تاکہ اسے تحریری شکل میں محفوظ رکھا جا سکے۔ لیکن قریش کے کچھ لوگوں نے مجھے اس سے منع کیا اور کہا کہ اللہ کے رسول صلی اللہ علیہ و سلم ایک انسان ہیں اور غصہ اور خوشی دونوں حالتوں میں گفتگو کرتے ہیں۔ ہو سکتا ہے کہ آپ غلطی بھی کر بیٹھیں۔ (اس لیے آپ کی ہر بات کو لکھا مت کرو۔) چنانچہ میں نے لکھنا بند کر دیا۔\r\n\r\nپھر میں نے اللہ کے رسول صلی اللہ علیہ و سلم کے سامنے ان کی اس بات کا ذکر کیا، تو آپ نے اپنے دہن مبارک کی جانب اشارہ کرتے ہوئے کہا کہ تم لکھا کرو۔ اس ذات کی قسم جس کے ہاتھ میں میری جان ہے، اس سے ہر حال میں حق ہی نکلتا ہے۔ خوشی کی حالت میں بھی اور غصے کی حالت میں بھی۔\r\n\r\nاللہ تعالی نے بھی اپنے نبی صلی اللہ علیہ و سلم کے بارے میں فرمایا: {وَمَا یَنطِقُ عَنِ ٱلۡهَوَىٰۤ۔ إِنۡ هُوَ إِلَّا وَحۡیࣱ یُوحَىٰ} (اور نہ وه اپنی خواہش سے کوئی بات کہتے ہیں. وه تو صرف وحی ہے جو اتاری جاتی ہے.) [سورہ نجم : 3-4]", "hints": ["The Hadīth demonstrates the Prophet's infallibility in what he conveyed from his Lord, whether at times of pleasure or anger.\r", "The Companions (may Allah be pleased with them) were keen to memorize and convey the Sunnah.\r", "It is permissible to swear an oath, even without being asked to swear an oath, for the sake of a certain interest, like putting emphasis on something.\r", "Writing down knowledge is one of the main methods for preserving it."], "hintsUr": ["اللہ کے نبی صلی اللہ علیہ و سلم اللہ کا پیغام پہنچانے کے معاملے میں معصوم تھے۔ خوشی کی حالت میں بھی اور غصے کی حالت میں بھی۔\r", "صحابۂ کرام سنت کی حفاظت اور اس کی تبلیغ کے حریص تھے۔\r", "کسی مصلحت کے پیش نظر، جیسے کسی بات کی تاکید کے لیے قسم کے مطالبے کے بغیر بھی قسم کھانا جائز ہے۔\r", "علم کو لکھ لینا اسے محفوظ رکھنے کا ایک اہم ترین سبب ہے۔"], "explanationAr": "قال عبدُ الله بن عَمْرو رضي الله عنه: كنتُ أكتبُ كلَّ شيءٍ أسمعه مِن رسول الله صلى الله عليه وسلم لكي أحفَظَه بالكتابة، فنهاني رجالٌ من قريش، وقالوا: رسولُ الله صلى الله عليه وسلم بشرٌ يتكلَّم في الرِّضا والغضب، وقد يُخطئ، فتوقَّفت عن الكتابة.\n\nفأخبرتُ النبيَّ صلى الله عليه وسلم بما قالوه، فأشار بإصبعه إلى فَمِهِ فقال: اكتب، فوالذي نفسي بيده ما يَخرجُ منه إلّا حقّ على كل حال، وفي الرِّضا والغضب.\n\nوقد قال تعالى عن نبيه صلى الله عليه وسلم:\n﴿وَمَا یَنطِقُ عَنِ ٱلۡهَوَىٰۤ * إِنۡ هُوَ إِلَّا وَحۡیࣱ یُوحَىٰ﴾ [النجم ٣-٤].", "hintsAr": ["النبي صلى الله عليه وسلم معصوم فيما يُبَلِّغُه عن ربه عز وجل، في الرضا والغضب.", "حرص الصحابة رضي الله عنهم على حفظِ السنة وتبليغِها.", "جواز الحلف ولو بغير تحليفٍ لمصلحة، كتوكيد أمر.", "كتابة العلم من أهم الأسباب التي تحفظ العلم."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abdullah ibn Amr"}, {"id": "10849", "number": 23, "title": "Writing and its historical context", "section": 3, "sectionTitle": "Learning and transmission", "slug": "23-writing-and-its-historical-context", "ref": "Sahih Muslim 3004", "primary": "https://sunnah.com/muslim:3004", "source": "https://hadeethenc.com/en/browse/hadith/10849", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/10849", "ar": "عن أبي سعيد الخدري أن رسول الله صلى الله عليه وسلم قال: «لا تكتبوا عني، ومَن كتب عني غيرَ القرآن فَلْيَمْحُه، وحدِّثوا عنِّي ولا حَرَج، ومَن كذب عليَّ -قال همام: أحسِبه قال: مُتعمِّدًا- فَلْيَتَبوَّأ مَقْعَدَه مِن النار».", "en": "Abu Sa‘īd al-Khudri reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Do not write down anything from me, and he who wrote down anything from me except the Qur'an, he should erase it. But, narrate from me, for there is nothing wrong in doing so. Whoever attributes any falsehood to me - Hammām said: I think he also said 'deliberately' - let him occupy his seat in Hellfire.”", "ur": "ابو سعيد خدری رضی اللہ عنہ سے روایت ہےکہ رسول اللہ ﷺ نےفرمایا: میری کسی بات کو نہ لکھو۔ جس نے مجھ سے قرآن کےعلاوہ کوئی اور بات لکھی ہے وہ اسے مٹا دے، البتہ میری باتیں روایت کرو، اس میں کوئی حرج نہیں ہے لیکن جو شخص میری طرف كوئی جھوٹی بات منسوب کرے گا -ہمام رحمہ اللہ کہتے ہیں کہ میرے خیال میں انہوں نے ”جان بوجھ کر“ کے الفاظ بھی کہے تھے- وہ اپنا ٹھکانہ جہنم میں بنا لے۔", "grade": "Authentic hadith", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "The Prophet (may Allah's peace and blessings be upon him) forbade his Companions to write anything from him, and ordered anyone who wrote anything, other than the Qur'an, to erase it. Then, he allowed them to narrate from him without incurring sin in doing so. However, they have to be truthful in what they transmit from him. He also warned that whoever tells a lie intentionally about him, his punishment is Hellfire. \nThe prohibition to write Hadīth was later abrogated, for the Prophet (may Allah's peace and blessings be upon him) forbade it at an earlier time. But later on, when the Hadīths became numerous, and some of them might not be kept to memory, the Prophet (may Allah's peace and blessings be upon him) allowed writing them down. In this respect, he said in his sermon: ''Write for Abu Shāh'' when Abu Shāh asked for a written record. The Prophet (may Allah's peace and blessings be upon him) also allowed ‘Abdullāh ibn ‘Amr to write. He also commanded his Ummah to convey knowledge, which if not written, will be lost. \nThe prohibition in the Hadīth in hand is said to refer to the writing of Hadīth along with the Qur'an in the same scroll; or that it is specific to the time when the Qur'an was being revealed, so that it would not be confused with something else. Then the writing was later allowed. \nThe first probability, i.e. abrogation, is more preponderant.", "explanationUr": "نبی ﷺ نے (شروع میں) اپنے صحابہ کو اپنی کوئی بھی بات لکھنے سے منع کر دیا اور فرمایا کہ جس نے میری کسی بات کو لکھا ہو وہ اسے مٹا دے۔ پھر آپ ﷺ نے انہیں اپنی باتوں کو آگے بیان کرنے کی اجازت مرحمت فرمائی کہ ایسا کرنے میں ان پر کوئی گناہ نہیں بشرطیکہ وہ آپ ﷺ سے جس بات کو بھی نقل کریں اس میں سچائی کو پیش نظر رکھیں۔ آپ ﷺ نے انہیں تنبیہ فرمائی کہ جو شخص بھی آپ ﷺ کی طرف جان بوجھ کر کوئی جھوٹی بات منسوب کرے گا اس کی جزا جہنم کی آگ ہو گی۔\nحدیث کو لکھنے کی ممانعت منسوخ ہو چکی ہے کیونکہ آپ ﷺ نے اس سے شروع شروع میں منع فرمایا تھا۔ کیونکہ احادیث بہت زیادہ ہو گئیں اور ہو سکتا تھا کہ حافظہ کچھ باتوں کو محفوظ نہ رکھ سکے چنانچہ آپ ﷺ نے لکھنے کی اجازت دے دی۔ آپ ﷺ نے اپنے خطبہ (حجۃ الوادع) میں فرمایا کے لیے ”ابو شاہ کو لکھ کر دے دو“۔ آپ ﷺ نے ایسا اس وقت فرمایا جب ابو شاہ رضی اللہ عنہ نے آپ ﷺ سے (خطبہ میں بیان کردہ احکام کو) لکھ کر دینے کی درخواست کی تھی۔ آپ ﷺ کے بارے میں آتا ہے کہ آپ ﷺ نے عبد اللہ بن عمرو رضی اللہ عنہ کو لکھنے کی اجازت دی۔ رسول اللہ ﷺ نے اپنی امت کو تبلیغ کا حکم دیا ہے۔ جب لکھا نہیں جائے گا تو اس سے علم ضائع ہو جائے گا۔ کہا جاتا ہے کہ اس ممانعت کا تعلق محض اس صورت کے ساتھ خاص ہے جب حدیث کو قرآن کے ساتھ ایک ہی صحیفہ میں لکھا جائے تا کہ اس کی قرآن کے ساتھ آمیزش نہ ہو جائے اور یوں قاری اشتباہ میں پڑ جائے۔ یہ بھی کہا جاتا ہے کہ یہ ممانعت صرف نزولِ قرآن کے وقت کے ساتھ خاص تھی اس اندیشے کے تحت کہ کہیں قرآن کا کسی اور شے کے ساتھ التباس نہ ہو جائے۔ بعدازاں رسول اللہ ﷺ نے اس کی اجازت دے دی۔\nپہلا احتمال یعنی اس ممانعت کا منسوخ ہونا ہی زیادہ راجح ہے۔", "hints": [], "hintsUr": [], "explanationAr": "نهى النبي صلى الله عليه وسلم أصحابه أن يكتبوا عنه شيئًا، ومن كتب عنه شيئًا غير القرآن فليمحه، ثم أذن لهم أن يحدثوا عنه ولا إثم عليهم في ذلك، شريطة أن يتحروا الصدق فيما ينقلونه عنه صلى الله عليه وسلم ، وحذرهم بأن من كذب عليه متعمدًا فجزاؤه نار جهنم. \nوالنهي عن كتابة الحديث منسوخ؛ وذلك أنه صلى الله عليه وسلم نهى عنه في أول الأمر، فلأن الأحاديث تكثر وقد يفوت الحفظ شيئًا منها أجاز الكتابة، وقد قال صلى الله عليه وسلم في خطبته: «اكتبوا لأبى شاه» لما استكتبه، وجاء عنه صلى الله عليه وسلم أنه أذن لعبد الله بن عمرو في الكتابة، وقد أمر صلى الله عليه وسلم أمته بالتبليغ، فإذا لم يُكتب ذهب العلم، وقيل: إن هذا النهي إنما هو لكتابة الحديث مع القرآن فى صحيفة واحدة لئلا يختلط به، فيشتبه على القارئ، وقيل: إنّه خاصّ بوقت نزول القرآن خشية التباسه بغيره، ثم أذن فيه بعد ذلك.\nوالاحتمال الأول وهو النسخ أقرب.", "hintsAr": ["إباحة الحديث عنه -صلى الله عليه وسلم-، وتبليغ ما سمع منه، وقد جاءت الآثار بالحض على التبليغ والأمر به.", "التحذير من التساهل عند الحديث عنه -صلى الله عليه وسلم- مما لم يتحقق منه، والتنبيه على التحرز في ذلك لئلا يقع في الكذب.", "الوعيد الشديد على من كذب على النبي -صلى الله عليه وسلم- متعمدًا.", "مشروعية كتابة القرآن والسنة وغيرهما من العلم.", "النهي عن كتابة الحديث النبوي منسوخ, أو هو محمول على كتابته مع القرآن في صحيفة واحدة لكيلا يحصل خلط بينهما, أو أنه خاصّ بوقت نزول القرآن خشية التباسه بغيره."], "words": [{"word": "ولا حرج", "meaning": " ولا إثم عليكم."}, {"word": "فليتبوَّأ مقعده من النار", "meaning": " ينزل منزله من النار."}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Said al-Khudri"}, {"id": "6982", "number": 24, "title": "Responsibility for doubtful reports", "section": 3, "sectionTitle": "Learning and transmission", "slug": "24-responsibility-for-doubtful-reports", "ref": "Sahih Muslim Introduction", "primary": "https://sunnah.com/muslim/introduction", "source": "https://hadeethenc.com/en/browse/hadith/6982", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/6982", "ar": "عَنْ سَمُرَةَ بْنِ جُنْدَبٍ وَالْمُغِيرَةِ بْنِ شُعْبَةَ رضي الله عنهما قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ حَدَّثَ عَنِّي بِحَدِيثٍ يُرَى أَنَّهُ كَذِبٌ، فَهُوَ أَحَدُ الْكَاذِبِينَ».", "en": "Samurah ibn Jundab and Al-Mughīrah ibn Shu‘bah (may Allah be pleased with both of them) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever reports a Hadīth on my authority that is thought to be false is one of the two liars.\"", "ur": "سمرہ بن جندب اور مغیرہ بن شعبہ رضی اللہ عنہما سے روایت ہے، دونوں کہتے ہیں کہ اللہ کے رسول صلی اللہ علیہ و سلم  نے فرمایا : \"جس نے میری طرف منسوب کر کے کوئی حدیث بیان کی، حالاں کہ اسے لگ رہا ہو کہ وہ جھوٹ ہے، تو وہ بھی جھوٹوں میں سے ہو گا۔\"", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Muslim in his introduction", "explanation": "The Prophet (may Allah's peace and blessings be upon him) informs that if a person reports a Hadīth from him which he knows, thinks, or deems it highly likely to be false, he has lied about him (may Allah's peace and blessings be upon him). Sharing in the lying is the one who initially related it to him.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم بتا رہے ہیں کہ جس نے آپ کے حوالے سے کوئی حدیث نقل کی اور وہ جانتا ہو، اسے لگتا ہو یا پھر اس کا غالب گمان ہو کہ اس حدیث کی نسبت رسول صلی اللہ علیہ و سلم کی جانب  جھوٹی ہے، تو روایت کرنے والا بھی اس جھوٹ کے آغاز کرنے والے کا شریک ہے۔", "hints": ["It encourages due verification and authentication of the Hadīths reported from the Prophet (may Allah's peace and blessings be upon him) before narrating them.\r", "Lying applies to anyone who invents a lie as well as those who transmit and spread it among the people.\r", "It is forbidden to narrate a fabricated Hadīth if one knows it is fabricated or deems it is likely to be fabricated, except if the purpose is to warn against it."], "hintsUr": ["نبی صلی اللہ علیہ وسلم سے نقل کی گئی احادیث کی چھان بین کرنا اور انھیں روایت کرنے سے پہلے ان کے صحیح ہونے کا یقین حاصل کرنا ضروری ہے۔\r", "جھوٹ ایجاد کرنے والے کے ساتھ ساتھ اسے نقل کرنے والا اور پھیلانے والا بھی جھوٹا ہے۔\r", "کسی حدیث کے موضوع ہونے کا علم یا غالب گمان ہونے کے باوجود اسے نقل کرنا حرام ہے۔ ہاں، اس سے خبردار کرنے کے لیے نقل کیا جائے، تو بات الگ ہے۔"], "explanationAr": "يُخْبِرُ النبيُّ صلى الله عليه وسلم أن مَن نَقَلَ عنه حديثًا وهو يعلم أو يظن أو يغلِب على ظنه أنه كذبٌ عليه صلى الله عليه وسلم؛ فالراوي له يُشاركُ البادي بهذا الكذب.", "hintsAr": ["التثبُّت من الأحاديث المروية عن النبي صلى الله عليه وسلم، والتأكد من صحتها قبل روايتها.", "صفة الكذب تُطلق على كل من اختَرَعَ الكذب وعلى مَن قام بنقلِه ونشره بين الناس.", "يحرم رواية الحديث الموضوع على مَن عَرَف كونَه موضوعًا، أو غلب على ظنه وضعُه إلا إذا كان للتحذير منه."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Samurah ibn Jundab and al-Mughirah ibn Shubah"}, {"id": "5913", "number": 25, "title": "Learn the Quran and teach it", "section": 4, "sectionTitle": "Living by the Quran", "slug": "25-learn-the-quran-and-teach-it", "ref": "Sahih al-Bukhari 5027", "primary": "https://sunnah.com/bukhari:5027", "source": "https://hadeethenc.com/en/browse/hadith/5913", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/5913", "ar": "عن عثمان رضي الله عنه عن النبي صلى الله عليه وسلم قال: «خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ».", "en": "‘Uthmān ibn ‘Affān (may Allah be pleased with him) reported: The Prophet (may Allah’s peace and blessings be upon him) said: \"The best of you are those who learn the Qur’an and teach it.\"", "ur": "عثمان رضی اللہ عنہ سے روایت ہے کہ اللہ کے نبی صلی اللہ علیہ و سلم نے فرمایا : ”تم میں سب سے بہتر شخص وہ ہے جو قرآن سیکھے اور اسے سکھائے“۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Al-Bukhāri", "explanation": "The Prophet (may Allah's peace and blessings be upon him) informs that the best and higher-standing among Muslims in the sight of Allah are those who learn the Qur’an - in terms of recitation, memorization, tartīl (measured recitation), understanding, and interpretation - and teach others the knowledge of the Qur’an that they possess, along with acting upon it.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم بتا رہے ہیں کہ اللہ کے نزدیک سب سے افضل اور اونچے درجے والا مسلمان وہ ہے، جس نے قرآن سیکھا، یعنی اسے پڑھنا سیکھا، یاد کیا اور اس سے مسائل اخذ کرنا سیکھا اور اس کی تفسیر سیکھی اور ساتھ ہی اپنے پاس موجود قرآن کے علم پر عمل کرتے ہوئے اسے دوسروں کو سکھایا۔", "hints": ["The Hadīth highlights the excellence of the Qur’an and that it is the best speech, for it is the word of Allah.\r", "The best learners are those who teach others and do not keep the knowledge to themselves only.\r", "Learning the Qur’an and teaching it comprises its recitation, meanings, and rulings."], "hintsUr": ["قرآن کی فضیلت اور اس بات کا بیان کہ قرآن سب سے اچھا کلام ہے، کیوں کہ وہ اللہ کا کلام ہے۔\r", "سب سے بہتر سیکھنے والا وہ ہے، جو علم کو اپنی ذات تک محدود رکھنے کی بجائے دوسروں کو سکھائے بھی۔\r", "قرآن سیکھنے اور سکھانے کے اندر اس کی تلاوت، معانی اور احکام سب شامل ہیں۔"], "explanationAr": "يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ أفضلَ المسلمين وأعلاهم عند الله درجة: مَن تَعَلَّم القرآنَ، تلاوةً وحفظًا وترتيلًا وفقهًا وتفسيرًا، وعَلَّمَ غيرَه ما عنده من علوم القرآن مع عَمَلِهِ به.", "hintsAr": ["بيان شرف القرآن، وأنه خير الكلام؛ لأنه كلام الله.", "خير المُتعلمين مَن يُعَلِّمُ غيرَه لا مَن يَقتصِرُ على نفسِه.", "تَعَلُّمُ القرآنِ وتَعْلِيْمُه يشمل التلاوةَ والمعاني والأحكام."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Uthman ibn Affan"}, {"id": "10113", "number": 26, "title": "The diligent and the struggling reader", "section": 4, "sectionTitle": "Living by the Quran", "slug": "26-the-diligent-and-the-struggling-reader", "ref": "Sahih Muslim 798", "primary": "https://sunnah.com/muslim:798", "source": "https://hadeethenc.com/en/browse/hadith/10113", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/10113", "ar": "عَنْ عَائِشَةَ رضي الله عنها قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَالَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَتَعْتَعُ فِيهِ، وَهُوَ عَلَيْهِ شَاقٌّ، لَهُ أَجْرَانِ».", "en": "‘Ā’ishah (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"The proficient reciter of the Qur’an will be with the noble and obedient angel-scribes, and the one who recites the Qur’an stutteringly and finds it difficult will have two rewards.\"", "ur": "اُم المومنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”جو شخص قرآن کے پڑھنے میں ماہر ہو، وہ معزز اور نیک سفراء (فرشتوں) کے ساتھ ہو گا، اور جو شخص قرآن کو اٹک اٹک کر پڑھتا ہو اور اسے پڑھنے میں مشقت ہوتی ہو تو اس کو دو گنا ثواب ملتا ہے“۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "The Prophet (may Allah's peace and blessings be upon him) informed that the one who recites the Qur’an with strong memorization, precision, and proficiency will have the reward in the Hereafter of being in the rank of the noble and obedient angel-scribes. As for the one who recites the Qur’an while stuttering and rehearsing in his recitation due to weak memorization, yet continues to maintain his connection with the Qur’an despite its difficulty for him, he will have two rewards: one reward for his recitation and another for the difficulty and his rehearsing in his recitation.", "explanationUr": "عائشہ رضی اللہ عنہا کی حدیث میں ہے کہ اللہ کے رسول ﷺ نے فرمایا جو قرآن پڑھتا ہے اور وہ قرآن کا ماہر ہو وہ سفرۃ الکرام البررۃ (بزرگ اور پاکباز لکھنے والے) فرشتوں کےساتھ ہوگا۔ قرآن کا ماہر سے مراد جو قرآن کو تجوید کے مطابق پڑھے، اس سے مراد اچھی تلاوت کرنے والا جب کہ اسے قرآن یاد بھی اچھا ہو وہ سفرۃ الکرام البررۃ فرشتوں کے ساتھ ہوگا۔ ’’السفرة الكرام البررة‘‘ یہ فرشتے ہیں جیسے اللہ تعالیٰ نے فرمایا ﴿فِي صُحُفٍ مُّكَرَّمَةٍ، مَّرْفُوعَةٍ مُّطَهَّرَةٍ، بِأَيْدِي سَفَرَةٍ، كِرَامٍ بَرَرَةٍ﴾ ”یہ تو پر عظمت صحیفوں میں (ہے)، جو بلند وباﻻ اور پاک صاف ہے، ایسے لکھنے والوں کے ہاتھوں میں ہے، جو بزرگ اور پاکباز ہے“ (سورہ عبس: 13-16)\nقرآن کا ماہر فرشتوں کے ساتھ ہوگا، اس لیے کہ اللہ تعالیٰ نے اس قاری کے لیے قرآن کو آسان کیا ہے جیسے کہ ’’کرام بررۃ‘‘ فرشتوں پر اسے آسان کیا ہے، جس کی وجہ سے یہ قاری قرآن پڑھنے میں ان فرشتوں کی طرح ہیں اور اللہ کے ہاں دونوں کا ایک درجہ ہے۔ جب کہ وہ شخص جو کہ قرآن اٹک اٹک کے پڑھتا ہو اور یہ اس پر گراں گزرتا ہو، اس کے لیے دُہرا اجر ہوتا ہے۔ ایک تلاوت کا اور دوسرے تھکن اور مشقت کا۔", "hints": ["Encouraging memorization of the Qur'an, mastering its recitation, and frequently reciting it to attain the reward and recompense, along with highlighting the elevated status of those who do so.\r", "Al-Qādi said: It does not mean that the one who stutters in the recitation has a greater reward than the proficient reciter. Rather, the proficient reciter is superior and has a greater reward because he is with the angel-scribes and receives multiple rewards. This elevated status was not mentioned to anyone else. How could someone who has not shown the same dedication to the Book of Allah, its memorization, mastery, frequent recitation, and understanding until he has excelled in it be equal to him?!\r", "Ibn Bāz said: The one who recites the Qur’an proficiently, mastering its recitation and memorizing it well, will be with the noble and obedient angel-scribes, i.e., if he recites it both in word and action—not merely recitation alone. He excels in reciting it and acting upon it, i.e., he adheres to it both in word and meaning."], "hintsUr": [], "explanationAr": "أخبر النبي صلى الله عليه وسلم أن الذي يقرأ القرآن، وهو جيّد الحفظ مُتقن له، وماهر وحاذق بقراءته، له من الثواب في الآخرة أن تكون منزلته مع الملائكة السفرة الكرام البررة، وأن الذي يقرأ القرآن ويتتعتع فيه ويتردد في تلاوته؛ لِضَعف حفظه وهو مع ذلك يتعاهده، وهو عليه شديد وشاقٌّ فله أجران؛ أجر بالقراءة وأجر للمشقة وتردده في تلاوته.", "hintsAr": ["الحث على حفظ القرآن وإتقانه وكثرة تلاوته لنوال الأجر والثواب، وبيان علو منزلة من فعل ذلك.", "قال القاضي: وليس معناه أن الذي يتتعتع عليه له من الأجر أكثر من الماهر به، بل الماهر أفضل وأكثر أجرًا؛ لأنه مع السفرة وله أجور كثيرة، ولم يذكر هذه المنزلة لغيره، وكيف يلحق به من لم يعتنِ بكتاب الله تعالى وحفظه وإتقانه وكثرة تلاوته ودرايته كاعتنائه حتى مَهَرَ فيه.", "قال ابن باز: الذي يقرأ القرآن وهو ماهِرٌ فيه، يُجيد قراءَته، ويحفظه جيدًا مع السَّفَرة الكرام البَرَرة، يعني: إذا كان يتلوه قولًا وعملًا، لا مجرّد التلاوة فقط، يُجيد تلاوته، ويعمل به، فهو قائم به لفظًا ومعنًى."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Aishah"}, {"id": "5907", "number": 27, "title": "Keep returning to the Quran", "section": 4, "sectionTitle": "Living by the Quran", "slug": "27-keep-returning-to-the-quran", "ref": "Sahih Muslim 791", "primary": "https://sunnah.com/muslim:791", "source": "https://hadeethenc.com/en/browse/hadith/5907", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/5907", "ar": "عن أبي موسى الأشعري رضي الله عنه عن النبي صلى الله عليه وسلم قال: «تَعَاهَدُوا هَذَا الْقُرْآنَ، فَوَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَهُوَ أَشَدُّ تَفَلُّتًا مِنَ الْإِبِلِ فِي عُقُلِهَا».", "en": "Abu Mūsa al-Ash‘ari (may Allah be pleased with him) reported: The Prophet (may Allah’s peace and blessings be upon him) said: \"Keep on reciting this Qur'an, for by the One in Whose Hand my soul is, the Qur'an slips away from memory faster than camels escaping their tying ropes.\"", "ur": "ابو موسی اشعری رضی اللہ عنہ سے روایت ہے کہ اللہ کے نبی صلی اللہ علیہ نے فرمایا : ”اس قرآن کی حفاظت (دیکھ بھال) کرو اور اس كى برابر تلاوت كيا كرو۔ قسم ہے اس ذات کی جس کے ہاتھ میں محمد کی جان ہے، یہ قرآن لوگوں کے سینوں سے نکل جانے میں اس اونٹ سے زیادہ تیز ہے جو رسی میں بندھا ہوا ہو“۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "The Prophet (may Allah's peace and blessings be upon him) ordered the Companions to recite the Qur'an regularly and not to forget it after they had learned it by heart. He emphasized this fact by swearing that the Qur'an slips away from one's memory faster than camels tied with ropes in the middle of their foreleg. If their shepherd pays attention to them, they remain with him, and if he releases them, they go away and will be lost.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم نے قرآن کا دھیان رکھنے اور پابندی سے اس کی تلاوت کرنے کا حکم دیا ہے، تاکہ قرآن یاد ہونے کے بعد انسان کے حافظے سے نکل نہ جائے۔ آپ نے اس بات کے اندر تاکید پیدا کرنے کے لیے قسم کھاکر بتایا کہ قرآن اونٹ کے بندھن توڑ کر بھاگنے سے بھی زیادہ تیزی سے انسان کے سینے سے نکل بھاگتا ہے۔ انسان خیال رکھے تو وہ رہتا ہے اور دھیان نہ دے، تو بھاگ کھڑا ہوتا ہے۔", "hints": ["If a memorizer of the Qur’an regularly recites it time and again, it remains in his heart; otherwise, it goes away from him and will be forgotten.\r", "Among the benefits of regular recitation of the Qur’an is obtaining reward and elevation of ranks on the Day of Judgment."], "hintsUr": ["اگر حافظ قرآن پابندی سے اس کی تلاوت کرتا رہے، تو وہ سینے میں محفوظ رہتا ہے، ورنہ حافظے سے نکل کر چلا جاتا ہے۔\r", "پابندی کے ساتھ قرآن پڑھتے رہنے کا فائدہ ایک تو یہ ہے کہ ثواب ملتا ہے اور دوسرا یہ ہے کہ اس سے قیامت کے دن انسان کے درجات اونچے ہوتے ہيں۔"], "explanationAr": "أَمَرَ النبيُّ صلى الله عليه وسلم بمُعاهَدةِ القرآنِ والمواظبةِ على تلاوتِهِ كي لا ينساه بعد أن كان حافظًا له في صدرِهِ، وأَكَّدَ ذلك بِحَلِفِهِ صلى الله عليه وسلم على أنَّ القرآنَ أشدُّ تَخَلُّصًا وذهابًا من الصدور مِن الإبل المَعقولة وهي المشدودة بحبلٍ في وسط الذراع، إنْ تَعاهدَها الإنسانُ أَمْسَكَها وإنْ أَطْلَقَها ذهبتْ وضاعتْ.", "hintsAr": ["إنْ واظَبَ حافظُ القرآنِ على تلاوتِه مرَّة بعد مرَّة بقي محفوظًا في قلبه، وإلا ذهبَ عنه ونسيَه.", "من فوائد تعاهُدِ القرآن: الأجر والثواب، ورفعة الدرجات يوم القيامة."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Musa al-Ashari"}, {"id": "3772", "number": 28, "title": "Wisdom that is practised and taught", "section": 4, "sectionTitle": "Living by the Quran", "slug": "28-wisdom-that-is-practised-and-taught", "ref": "Sahih al-Bukhari 73", "primary": "https://sunnah.com/bukhari:73", "source": "https://hadeethenc.com/en/browse/hadith/3772", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/3772", "ar": "عن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا حَسَدَ إلا في اثنتين: رجل آتاه الله مالا، فسَلَّطَه على هَلَكَتِهِ في الحَقِّ، ورجل آتاه الله حِكْمَة، فهو يقضي بها ويُعَلِّمَها».\nوعن ابن عمر رضي الله عنهما ، عن النبي صلى الله عليه وسلم قال: «لا حسد إلا في اثنتين: رجل آتاه الله القرآن، فهو يقوم به آناء الليل وآناء النهار، ورجل آتاه الله مالا، فهو ينفقه آناء الليل وآناء النهار».", "en": "Ibn Mas‘ūd (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"There should be no envy except in two (cases): A man whom Allah has given wealth and he spends it in the right way, and a man whom Allah has given wisdom and he judges according to it and teaches it to others.\"\n‘Abdullāh ibn ‘Umar (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"There should be no envy except in two (cases): a man whom Allah has given (knowledge of) the Qur'an, and he recites it during the night and day, and a man whom Allah has given wealth, and he spends it during the night and day (in a rightful way).”", "ur": "ابن مسعود رضي الله عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا : ”حسد صرف دو صورتوں میں جائز ہے۔ ایک تو یہ کہ کسی شخص کو اللہ نے دولت دی ہو اور وہ اسے اس کو راہ حق میں خرچ کرنے پر لگا دیا ہو اور دوسرا یہ کہ کسی شخص کو اللہ نے حکمت ( کی دولت) سے نوازا ہو اور وہ اس کے ساتھ فیصلہ کرتا ہو اور ( لوگوں کو) اس حکمت کی تعلیم دیتا ہو“۔\nابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”حسد صرف دو صورتوں میں جائز ہے؛ ایک تو یہ کہ کسی آدمی کو اللہ تعالی قرآن سے نوازے اور وہ دن رات اس (کی تلاوت اور تعلیم و تدریس) میں لگا رہے اور دوسرا وہ شخص جس کو اللہ مال عطا کرے اور وہ دن رات اسے (وجوہ خیر میں) خرچ کرتا رہے“۔", "grade": "Authentic hadith", "gradeAr": "صحيح", "attribution": "Al-Bukhari and Muslim with its two versions", "explanation": "The Prophet (may Allah's peace and blessings be upon him) pointed out in this Hadīth that envy is of different types. There is a type that is blameworthy and unlawful under Shariah; that is when a person wishes for the removal of some blessing from his brother. The permissible type of envy is when one sees someone enjoying a worldly blessing and he hopes to have the same for himself. There is also a praiseworthy type of envy which is recommended under Shariah. It is when one sees someone enjoying a religious blessing and wishes to have the same thing for oneself. This is what the Prophet (may Allah's peace and blessings be upon him) intended by his statement: \"There should be no envy except in two (cases)\". This means that envy has different types, and its ruling differs according to its type. It is not praiseworthy and recommended by Shariah except in two cases: 1. When there is a wealthy righteous man whom Allah has given lawful wealth, which he spends in the cause of Allah, the Almighty. So one hopes to be like him, and envies him, the kind of envy that is free from malice, for that blessing. 2. When there is a knowledgeable man whom Allah has given beneficial knowledge which he acts upon, teaches to others, and judges between the people according to. So, he wishes to be like him.", "explanationUr": "اس حدیث میں نبی ﷺ اس بات کی طرف اشارہ فرما رہے ہیں کہ حسد کی کئی قسمیں ہوتی ہیں۔ کوئی حسد تو وہ ہوتا ہے جو مذموم اورشرعا حرام ہوتا ہے۔ اس سے مراد وہ حسد ہے جس میں آدمی یہ تمنا کرتا ہے کہ اس کے بھائی سے نعمت چھن جائے۔ ایک حسد وہ ہوتا ہے جو مباح ہے۔ اس سے مراد وہ حسد ہے جس میں آدمی کسی دوسرے کے پاس کوئی دنیاوی نعمت دیکھتا ہے اور تمنا کرتا ہے کہ اسی طرح کی نعمت اسے بھی مل جائے۔ اسی طرح ایک حسد وہ ہوتا ہے جو شرعا قابل تعریف اور مستحب ہے۔ اس سے مراد یہ ہے کہ آدمی کسی اور کے پاس کوئی دینی نعمت دیکھے اور خواہش کرے کہ وہ اسے بھی مل جائے۔ نبی ﷺ کی یہاں آپ ﷺ کے فرمان ”حسد صرف دوصورتوں میں جائز ہے“ میں حسد سے مراد حسد کی یہی قسم ہے۔ یعنی یہ کہ حسد کی مختلف انواع کے اعتبار سے ان کا حکم بھی مخلتف ہوتا ہے اور یہ شرعی طور پر قابل تعریف اور مستحب صرف دو ہی صورتوں میں ہوتا ہے:\nپہلی صورت: کوئی ایسا شخص ہو جو مالدار بھی ہو اور صاحب تقوی بھی۔ اسے اللہ نے بہت سا حلال مال دیا ہو اور وہ اسے اللہ کے راستے میں خرچ کرے۔ اسے دیکھ کر آدمی تمنا کرے کہ کاش وہ بھی اس کی طرح کا ہو اور وہ اس نعمت پر اس پر رشک کرے۔\nدوسری صورت: کوئی ایسا عالم شخص ہو جسے اللہ نے علم نافع سے نوازا ہو جس پر وہ خود بھی عمل کرتا ہو اور دوسروں کو بھی اس کی تعلیم دیتا ہو اور اس کے ذریعے لوگوں کے مابین فیصلے کرتا ہو۔اسے دیکھ کر آدمی خواہش کرے کہ وہ بھی اس کی طرح کا ہو جائے۔", "hints": [], "hintsUr": [], "explanationAr": "يُشير النبي صلى الله عليه وسلم هنا إلى أن الحَسَدَ أنواع مختلفة فمنه حسد مَذْمُوم محرم شرعًا، وهو أن يتمنى المرء زوال النعمة عن أخيه، وحسد مباح وهو أن يرى نعمة دنيوية عند غيره فيتمنى لنفسه مثلها، وحسد محمود مستحب شرعًا، وهو أن يرى نعمة دينية عند غيره فيتمناها لنفسه. وهو ما عناه النبي صلى الله عليه وسلم بقوله: \"لا حَسَدَ إلا في اثنتين\" أي أن الحسد تختلف أنواعه وأحكامه حسب اختلاف أنواعه ولا يكون محمودًا مستحبًا شرعيًا إلا في أمرين: \nالأمر الأول: أن يكون هناك رجل غني تقي، أعطاه الله مالا حلالا، فينفقه في سبيل الله تعالى، فيتمنى أن يكون مثله، ويَغْبِطَه على هذه النعمة. \nالأمر الثاني: أن يكون هناك رجل عالم، أعطاه الله علما نافعا يعمل به، ويعلمه لغيره، ويحكم به بين الناس، فيتمنى أن يكون مثله.", "hintsAr": ["الحَسَدُ داء خطير يجب الابتعاد عنه والحذر منه.", "حسد الغِبْطَة محمود إذا كان في وجوه الخير.", "فضل الغني الذي لا يبخل بما آتاه الله .", "الواجب شكر المُنْعِم على ما أنعم به على العبد وذلك بأن يضعها العبد في موضعها.", "استحباب الإنفاق وبذل المال والخروج عنه بالكلية في وجوه الخير ما لم يؤد إلى حرمان الورثة أو سؤال الناس ونحو ذلك مما حَرَّمَه الشرع.", "فضل العلم بأحكام الدين وتعليم الناس ودعوتهم إلى التفقه في الدين."], "words": [{"word": "الحسد", "meaning": " الغبطة ، وهي: أن يتمنى مثله."}, {"word": "سلطه", "meaning": " مكنه الله من إنفاقه في وجوه الخير."}, {"word": "هلكته", "meaning": " وجوه إنفاقه ومجالات صرفه."}, {"word": "في الحق", "meaning": " في أنواع البر ونواحي الخير."}, {"word": "حكمة", "meaning": " وضع كل شيء في موضعه."}, {"word": "يقضي بها", "meaning": " يحكم ويفتي بين الناس بمقتضاها."}, {"word": "آناء", "meaning": " الآناء: الساعات"}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abdullah ibn Masud and Abdullah ibn Umar"}, {"id": "65285", "number": 29, "title": "We hear and we obey", "section": 4, "sectionTitle": "Living by the Quran", "slug": "29-we-hear-and-we-obey", "ref": "Sahih Muslim 125", "primary": "https://sunnah.com/muslim:125", "source": "https://hadeethenc.com/en/browse/hadith/65285", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/65285", "ar": "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ {لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ} [البقرة: 284]، قَالَ: فَاشْتَدَّ ذَلِكَ عَلَى أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَوْا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ بَرَكُوا عَلَى الرُّكَبِ، فَقَالُوا: أَيْ رَسُولَ اللهِ، كُلِّفْنَا مِنَ الأَعْمَالِ مَا نُطِيقُ، الصَّلَاةَ وَالصِّيَامَ وَالجِهَادَ وَالصَّدَقَةَ، وَقَدِ اُنْزِلَتْ عَلَيْكَ هَذِهِ الآيَةُ وَلَا نُطِيقُهَا، قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «أَتُرِيدُونَ أَنْ تَقُولُوا كَمَا قَالَ أَهْلُ الكِتَابَيْنِ مِنْ قَبْلِكُمْ سَمِعْنَا وَعَصَيْنَا؟ بَلْ قُولُوا: سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ المَصِيرُ»، قَالُوا: سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ المَصِيرُ، فَلَمَّا اقْتَرَأَهَا القَوْمُ، ذَلَّتْ بِهَا أَلْسِنَتُهُمْ، فَأَنْزَلَ اللهُ فِي إِثْرِهَا: {آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالمُؤْمِنُونَ كُلٌّ آمَنَ بِاللهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ المَصِيرُ} [البقرة: 285]، فَلَمَّا فَعَلُوا ذَلِكَ نَسَخَهَا اللهُ تَعَالَى، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {لَا يُكَلِّفُ اللهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا} [البقرة: 286] \" قَالَ: «نَعَمْ» {رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا} [البقرة: 286] قَالَ: «نَعَمْ» {رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ} [البقرة: 286] قَالَ: «نَعَمْ» {وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الكَافِرِينَ} [البقرة: 286] قَالَ: «نَعَمْ».", "en": "Abu Hurayrah (may Allah be pleased with him) reported: When the verse: {To Allah belongs all that is in the heavens and all that is on earth. Whether you reveal what is within yourselves or conceal it, Allah will call you to account for it. He forgives whom He wills and punishes whom He wills, for Allah is Most Capable of all things} [Surat al-Baqarah: 284] was revealed to the Messenger of Allah (ﷺ), he said: It was very hard on the Companions of the Messenger of Allah (ﷺ). They came to the Messenger of Allah (ﷺ), knelt down on their knees, and said:\nO Messenger of Allah, we have been commanded to do acts of worship we can bear—prayer, fasting, Jihad, and charity—but now this verse has been revealed to you, and we cannot endure it. The Messenger of Allah (ﷺ) said: \"Do you wish to say as the People of the Two Scriptures said before you: We hear and we disobey?Rather say: We hear and obey. Grant us Your forgiveness, our Lord, and to You is the [final] destination.\" So they said: We hear and obey. Grant us Your forgiveness, our Lord, and to You is the final destination. When they recited it and their tongues humbly uttered those words, Allah revealed thereafter: {The Messenger believes in what has been sent down to him from his Lord, as do the believers. All of them believe in Allah, His angels, His Books, and His messengers, [saying], “We make no distinction between any of His messengers.” And they say, “We hear and obey. Grant us Your forgiveness, our Lord, and to You is the [final] destination.”} [Surat al-Baqarah: 285] Then Allah Almighty, out of His mercy, abrogated the previous ruling and revealed: {Allah does not burden any soul greater than it can bear. For it is what it has earned, and against it is what it has incurred. Our Lord, do not hold us accountable if we forget or fall into error.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Our Lord, do not place on us such a burden as You have placed on those before us.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Our Lord, do not burden us with that which we cannot bear.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Pardon us, forgive us, and have mercy on us. You are our Protector, so give us victory over the disbelieving people.} [Surat al-Baqarah: 286] He said: \"Yes.\"", "ur": "ابو ہریرہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہيں: جب رسول اللہ ﷺ پر یہ آیت نازل ہوئی: ’’آسمانوں اور زمین کی ہر چیز اللہ تعالی ہی کی ملکیت ہے‘ تمہارے دلوں میں جو کچھ ہے اسے تم ظاہر کرو یا چھپاؤ‘ اللہ تعالی اس کا حساب تم سے لے گا۔ پھر جسے چاہے بخشے اور جسے چاہے سزا دے اور اللہ تعالی ہر چیز پر قادر ہے‘‘ [البقرة: 284]، تو یہ آیت صحابۂ کرام رضی اللہ عنہم پر بڑی گراں گزری۔ وہ رسول اللہ ﷺ کے پاس آئے، پھر گھٹنوں کے بل بیٹھ گئے اور کہا: اے اللہ کے رسول! ہمیں ان اعمال کا مکلف کیا گیا جن کی ہم طاقت رکھتے ہیں، (جیسے) نماز، روزہ، جہاد اور صدقہ۔ اور (اب) آپ پر یہ آیت نازل ہوئی ہے، یہ ہماری طاقت سے باہر ہے۔ رسول اللہ ﷺ نے فرمایا: «کیا تم وہی کہنا چاہتے ہو جو تم سے پہلے دونوں اہل کتاب نے کہا تھا کہ ہم نے سنا اور نافرمانی کی؟  بلکہ تم کہو: ہم نے سنا اور اطاعت کی۔ اے ہمارے رب! ہم تجھ سے بخشش مانگتے ہیں اور تیری ہی طرف پھرنا ہے»۔ انھوں نے کہا: ہم نے سنا اور اطاعت کی۔ اے ہمارے رب! ہم تجھ سے بخشش مانگتے ہیں اور تیری ہی طرف پھرنا ہے۔ جب لوگوں نے (یہ کلمات) پڑھے اور ان کے ساتھ ان کی زبانیں رواں ہو گئیں تو اللہ نے اس کے بعد یہ آیت نازل فرمائی: ’’رسول ایمان لایا اس چیز پر جو اس کی طرف اللہ تعالی کی جانب سے اتری اور مومن بھی ایمان لائے‘ یہ سب اللہ تعالی اور اس کے فرشتوں پر اور اس کی کتابوں پر اور اس کے رسولوں پر ایمان لائے‘ اس کے رسولوں میں سے سے کسی میں ہم تفریق نہیں کرتے‘ انہوں نے کہہ دیا کہ ہم نے سنا اور اطاعت کی‘ ہم تیری بخشش طلب کرتے ہیں اے ہمارے رب! اور ہمیں تیری ہی طرف لوٹنا ہے۔‘‘ [البقرة: 285]۔ جب انھوں نے ایسا کر لیا تو اللہ تعالی نے اسے منسوخ فرما دیا اور اللہ عز و جل نے یہ نازل فرمایا: ’’اللہ تعالی کسی جان کو اس کی طاقت سے زیادہ تکلیف نہیں دیتا‘ جو نیکی وہ کرے وہ اس کے لیے اور جو برائی وہ کرے وہ اس پر ہے‘ اے ہمارے رب! اگر ہم بھول گئے ہوں یا خطا کی ہو تو ہمیں نہ پکڑنا۔‘‘ [البقرة: 286] اللہ تعالی نے فرمایا: ’’ہاں۔‘‘ (پھر کہا:) ’’اے ہمارے رب! ہم پر اس طرح بوجھ نہ ڈالنا جس طرح تو نے ہم سے پہلے لوگوں پر ڈالا تھا۔‘‘ [البقرة: 286] اللہ تعالی نے فرمایا: ’’ہاں۔‘‘ (پھر کہا:) ’’اے ہمارے رب! ہم پر وہ بوجھ نہ ڈال جس کی ہمیں طاقت نہ ہو۔‘‘ [البقرة: 286] اللہ تعالی نے فرمایا: ’’ہاں۔‘‘ (پھر کہا:) ’’اور ہمیں بخش دے اور ہم پر رحم کر! تو ہی ہمارا مالک ہے‘ ہمیں کافروں کی قوم پر غلبہ عطا فرما۔‘‘ [البقرة: 286] اللہ تعالی نے فرمایا: ’’ہاں۔‘‘", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "When Allah Almighty revealed to His Prophet (ﷺ) His saying: {To Allah belongs all that is in the heavens and all that is on earth} in creation, ownership, control, and management. {Whether you reveal} show and declare {what is within yourselves} and in your hearts {or conceal it} and hide it in your hearts, {Allah will call you to account for it} on the Day of Judgment. {He forgives whom He wills} out of His grace and mercy {and punishes whom He wills} out of His justice, {for Allah is Most Capable of all things} and nothing is beyond His power. When the Companions heard this verse, it was hard on them, for it implied being held accountable even for the thoughts that pass through the heart. So they came to the Messenger of Allah (ﷺ) and knelt down on their knees, saying: O Messenger of Allah, we have been commanded with bodily acts of worship that we are able to perform—such as prayer, fasting, Jihad, and charity—but this verse has been revealed to you and we cannot bear it. The Prophet (ﷺ) said to them: Do you wish to say as the Jews and Christians said: {We hear and disobey}? Rather say: {We hear and obey. Grant us Your forgiveness, our Lord, and to You is the [final] destination.} The Companions obeyed the command of Allah and His Messenger and said: We hear and obey. Grant us Your forgiveness, our Lord, and to You is the [final] destination. When the Muslims spoke those words with their tongues and their hearts submitted to them, Allah revealed—as a commendation for the Prophet (ﷺ) and his Ummah—His saying: {The Messenger believes in what has been sent down to him from his Lord, as do the believers} and their tongues and hearts submitted to Allah's command. {All of them believe in Allah, His angels, His Books, and His messengers, [saying], “We make no distinction between any of His messengers.”} Rather, we believe in all of them. {And they say, “We hear} your words {and obey} Your command, and we seek {Your forgiveness, our Lord} and Your pardon, {and to You is the [final] destination”} and the return on the Day when the reckoning will take place. When they did that and said what they were commanded to say—openly declaring their willingness to hear and obey Allah's commands—Allah eased the burden upon this Ummah and abrogated that verse with His saying: {Allah does not burden any soul greater than it can bear} beyond its ability, strength, and effort. {For it is} the reward of {what it has earned} and performed of goodness, {and against it is} the punishment of {what it has incurred} of evil and sins. Thus, Allah does not hold anyone accountable for another's sin, nor for the whispers and passing thoughts within one's own self. {Our Lord, do not hold us accountable} and punish us {if we forget} and do not remember {or fall into error} and unintentionally deviate from what is right. So Allah responded to their supplication and said: Yes, I have done so. {Our Lord, do not place on us such a burden} hardship and load {as You have placed on those before us} from among the Children of Israel and others. So Allah responded to their supplication and said: Yes, I have done so. {Our Lord, do not burden us with that which we cannot bear} of duties, trials, or hardships beyond our strength. Allah said: Yes, I have done so. {Pardon us} and erase our sins, {forgive us} conceal them and overlook them, {and have mercy on us} through Your vast mercy. {You are our Protector} and Master, {so give us victory} by granting us steadfastness and triumph in battle and argument {over the disbelieving people} in fighting and striving against them. So Allah responded to their supplication and said: Yes, I have done so.", "explanationUr": "جب اللہ تعالیٰ نے اپنے نبی ﷺ پر اپنا یہ فرمان نازل فرمایا: {آسمانوں اور زمین کی ہر چیز اللہ تعالی ہی کی ملکیت ہے} تخلیق، ملکیت، تصرف اور تدبیر کے اعتبار سے، {وَإِنْ تُبْدُوا} یعنی تم ظاہر کرو اور اعلان کرو {مَا فِي أَنْفُسِكُمْ} اس چیز کا جو تمہارے دلوں اور سینوں میں ہے {أَوْ تُخْفُوهُ} یا اسے پوشیدہ رکھو اور اپنے دلوں میں چھپائے رکھو {يُحَاسِبْكُمْ بِهِ اللَّهُ} تو اللہ تعالیٰ قیامت کے دن تم سے اس کا حساب لے گا۔ ”جسے چاہے بخش دے“ اپنے فضل و رحمت کی بنا پر، ”اور جسے چاہے عذاب دے“ اپنے عدل کی بنا پر، ”اور اللہ تعالیٰ ہر چیز پر قادر ہے“ کوئی چیز اسے عاجز نہیں کر سکتی۔ جب صحابہ کرام نے یہ سنا تو یہ بات ان پر بہت شاق گزری، کیونکہ اس میں دل میں آنے والے خیالات پر بھی مواخذہ تھا۔ وہ رسول اللہ ﷺ کے پاس آئے، پھر گھٹنوں کے بل بیٹھ گئے اور کہا: اے اللہ کے رسول! اس سے پہلے ہمیں ان جسمانی اعمال کا مکلف کیا گیا تھا جنہیں انجام دینے کی ہم طاقت رکھتے ہیں؛ جیسے نماز، روزہ، جہاد اور صدقہ۔ لیکن اب آپ پر یہ آیت نازل ہوئی ہے اور یہ ہماری طاقت سے باہر ہے۔ تو آپ ﷺ نے ان سے فرمایا: ”کیا تم بھی ویسا ہی کہنا چاہتے ہو جیسا کہ یہود و نصاریٰ نے کہا تھا کہ ’ہم نے سنا اور نافرمانی کی‘؟ بلکہ یوں کہو: \"ہم نے سنا اور اطاعت کی، ہم تیری بخشش طلب کرتے ہیں اے ہمارے رب! اور ہمیں تیری ہی طرف لوٹنا ہے‘۔“ چنانچہ صحابہ نے اللہ اور اس کے رسول کا حکم مان لیا، اور کہا: ”ہم نے سنا اور اطاعت کی، ہم تیری بخشش طلب کرتے ہیں اے ہمارے رب! اور ہمیں تیری ہی طرف لوٹنا ہے۔“ جب مسلمانوں نے اپنی زبانوں سے اس کا اقرار کیا، اور ان کے دل اس کے مطیع ہو گئے؛ تو اللہ تعالیٰ نے نبی ﷺ اور آپ کی امت کے تزکیے کے لیے اپنا یہ فرمان نازل فرمایا: ”آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالمُؤْمِنُونَ“ اور ان کی زبانیں اور دل حکم الہی کے تابع ہو گئے۔ \"یہ سب اللہ تعالیٰ اور اس کے فرشتوں پر اور اس کی کتابوں پر اور اس کے رسولوں پر ایمان ﻻئے، اس کے رسولوں میں سے کسی میں ہم تفریق نہیں کرتے\"۔ بلکہ ہم ان سب پر ایمان لاتے ہیں اور کہتے ہیں کہ ہم نے تیرا فرمان سنا اور تیرے حکم کی اطاعت کی، اور اے ہمارے رب! ہم تیری بخشش اور درگزر طلب کرتے ہیں، اور حساب کے دن تیری ہی طرف لوٹنا ہے۔ جب انہوں نے ایسا کیا اور اللہ کے احکامات کے لیے سمع وطاعت کا اظہار کرتے ہوئے وہ کہہ دیا جس کا انہیں حکم دیا گیا تھا؛ تو اللہ نے اس امت کے تئیں تخفیف فرمائی اور اس آیت کو اپنے اس فرمان سے منسوخ فرما دیا: \"اللہ کسی جان کو اس کی طاقت سے زیادہ کا مکلف نہیں بناتا، اس نے جو نیکی کمائی اس کا ثواب اسی کے لیے ہے، اور اس نے جو گناہ اور برائی کی اس کا وبال اسی پر ہے\"، اور اللہ کسی کو دوسرے کے گناہ پر نہیں پکڑتا اور نہ ہی اس کے دل میں آنے والے وسوسوں پر۔ {رَبَّنَا لَا تُؤَاخِذْنَا} اے ہمارے رب! ہمیں نہ پکڑنا، یعنی ہمیں سزا نہ دینا، {إِنْ نَسِينَا} اگر ہم بھول گئے ہوں۔ یعنی ہمیں یاد نہ رہا ہو، {أَوْ أَخْطَأْنَا} یا خطا کی ہو۔ یعنی ہم نے جان بوجھ کر نہیں بلکہ غلطی سے صحیح بات کو چھوڑ دیا ہو، تو اللہ نے ان کی یہ دعا قبول فرمائی اور فرمایا: ہاں، میں نے ایسا کر دیا ہے۔ {رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا} اے ہمارے رب! اور ہم پر بوجھ نہ ڈال یعنی مشقت اور گرانی نہ ڈال، {كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا} جیسا کہ تو نے ہم سے پہلے لوگوں پر ڈالا تھا یعنی بنی اسرائیل اور ان کے علاوہ دوسروں پر، تو اللہ تعالیٰ نے دعا قبول فرمائی اور فرمایا: ہاں، میں نے ایسا کر دیا۔ {رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ} یعنی ایسی ذمہ داریاں، آزمائشیں اور معاملات ہم پر نہ ڈال جنہیں اٹھانے سے ہم عاجز ہیں، اللہ نے فرمایا: ہاں، میں نے ایسا کر دیا۔ {وَاعْفُ عَنَّا} ہمارے گناہوں کو مٹا کر ہم سے درگزر فرما، {وَاغْفِرْ لَنَا} ہمارے گناہوں کو بخش دے، ان پر پردہ ڈال دے اور ان سے تجاوز فرما، {وَارْحَمْنَا} اپنی وسیع رحمت سے ہم پر رحم فرما، {أَنْتَ مَوْلَانَا} تو ہی ہمارا مالک اور آقا ہے؛ {فَانْصُرْنَا} حجت اور غلبے کے ساتھ ہماری مدد فرما {عَلَى الْقَوْمِ الكَافِرِينَ} كافروں کے ساتھ قتال اور جہاد میں، تو اللہ نے یہ دعا قبول فرمائی، اور فرمایا: ہاں، میں نے ایسا کر دیا۔", "hints": ["A clarification of Allah's mercy toward this Ummah because of its Prophet (ﷺ)—the one about whom Allah said, in honoring his status: {We have not sent you [O Prophet] except as a mercy to the worlds.} [Surat al-Anbiyā’: 107]\r", "Affirming the abrogation in the Noble Qur’an, and that within it are verses that are still recited, yet their rulings have been abrogated and are no longer acted upon.\r", "The virtue of the Companions (may Allah be pleased with them) and their submission and obedience to the command of Allah, and their immediate compliance with the orders of His Messenger (ﷺ).\r", "The Prophet (ﷺ) was deeply concerned and fearful that his Ummah might follow the path of previous nations by rejecting the commands of Allah Almighty.\r", "It is obligatory to submit to the command of Allah Almighty and to beware of objecting to His command, for such objection resembles the behavior of the People of the Book.\r", "Highlighting the superiority of this nation over the previous nations, as they said to their prophets: We hear and disobey. But this nation said: We hear and obey.\r", "The virtue of this Ummah lies in Allah's mercy toward it—by removing hardship from it, answering its supplication not to be held accountable for forgetfulness or mistakes, lifting the burdens that were upon previous nations, and not charging it with what it cannot bear.\r", "Allah Almighty does not burden us with what we cannot bear, nor does He charge us with more than we can do. The passing thoughts and whispers that occur in our hearts do not harm us as long as we do not dwell upon them, feel content with them, or act upon them.\r", "Allah Almighty informed us of this supplication made by the Prophet (ﷺ) and the believers, and He placed it in His Book so that those who come after the Prophet (ﷺ) and his Companions (may Allah be pleased with them) would also recite it. Therefore, it is a supplication that should be memorized and frequently recited."], "hintsUr": ["اپنے نبی ﷺ کے سبب اس امت پر اللہ تعالیٰ کی رحمت کا بیان، جن کی عظمتِ شان کے بارے میں اللہ تعالیٰ نے فرمایا: ”اور ہم نے آپ کو تمام جہان والوں کے لئے رحمت ہی بنا کر بھیجا ہے۔“ [الأنبياء: 107]\r", "قرآن کریم میں نسخ کا ثبوت ہے، اور یہ کہ قرآن کا کچھ حصہ ایسا ہے جس کی تلاوت تو کی جاتی ہے لیکن اس کا حکم منسوخ کر دیا گیا ہے، چنانچہ اس پر عمل نہیں کیا جاتا۔\r", "صحابہ رضی اللہ عنہم کی فضیلت اور اللہ کے حکم کے آگے ان کی اطاعت و تسلیم اور اپنے رسول ﷺ کے حکم کی تعمیل۔\r", "نبی ﷺ کو اپنی امت کے بارے میں یہ شدید خدشہ تھا کہ وہ اللہ تعالیٰ کے احکامات کو رد کرنے میں سابقہ امتوں کا مسلک اختیار کر لے گی۔\r", "حکم الہی کو تسلیم کرنا اور اس پر اعتراض کرنے سے خبردار رہنا واجب ہے، کیونکہ اس میں اہل کتاب سے مشابہت ہے۔\r", "سابقہ امتوں پر اس امت کی فضیلت کا بیان، کیونکہ انہوں نے اپنے انبیاء سے کہا: ہم نے سنا اور نافرمانی کی، اور اس امت نے کہا: ہم نے سنا اور اطاعت کی۔\r", "امت کی فضیلت کہ اس سے تنگی اٹھا لی گئی، بھول چوک اور خطا پر مواخذہ نہ کرنے کی دعا قبول ہوئی، اس پر سے وہ بوجھ اتار دیے گئے جو ان سے پہلے لوگوں پر تھے اور اس پر اس کی طاقت سے زیادہ بوجھ نہیں ڈالا گیا۔\r", "اللہ سبحانہ و تعالیٰ ہم پر وہ بوجھ نہیں ڈالتا جس کی ہم میں طاقت نہ ہو، ہمیں ہماری طاقت سے زیادہ کا مکلف نہیں بناتا، اور یہ کہ وہ وسوسے جو ہمارے سینوں میں گردش کرتے ہیں، اگر ہم ان کی طرف مائل نہ ہوں، ان پر مطمئن نہ ہوں اور ان پر عمل نہ کریں تو وہ کوئی نقصان نہیں پہنچاتے۔\r", "اللہ تعالی نے نبی ﷺ اور مومنین کی اس دعا کو اپنی کتاب میں ذکر فرمایا ہے، تاکہ یہ نبی ﷺ اور صحابہ رضی اللہ عنہم کے بعد آنے والوں کی دعا بن جائے۔ یہ ان دعاؤں میں سے ہے جنہیں یاد کرنا اور کثرت سے مانگنا چاہیے۔"], "explanationAr": "لما أنزل الله تعالى على نبيه صلى الله عليه وسلم قوله سبحانه: {لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ} خَلْقًا ومُلكًا، وتصرُّفًا وتدبيرًا، {وَإِنْ تُبْدُوا} وتظهروا وتعلنوا {مَا فِي أَنْفُسِكُمْ} وصدوركم {أَوْ تُخْفُوهُ} فتسروه وتضمروه في قلوبكم {يُحَاسِبْكُمْ بِهِ اللَّهُ} يوم القيامة.\n\n{فَيَغْفِرُ لِمَنْ يَشَاءُ} بفضله ورحمته، {وَيُعَذِّبُ مَنْ يَشَاءُ} بعدله، {وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ} لا يعجزه شيء. \n\nفلما سمعها الصحابة شق عليهم ذلك؛ لأن فيها المؤاخذة حتى على ما في القلب من خطرات.\n\nفأتوا رسول الله صلى الله عليه وسلم، ثم بركوا جثيًا على الركب، فقالوا: يا رسول الله، كلفنا قبل ذلك من الأعمال البدنية ما نطيق الإتيان به؛ مثل الصلاة والصيام والجهاد والصدقة، ولكن قد أنزلت عليك هذه الآية ولا نطيقها.\n\nفقال لهم صلى الله عليه وسلم: أتريدون أن تقولوا كما قالت اليهود والنصارى: {‌سَمِعْنَا وَعَصَيْنَا}؟ بل قولوا: {سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ المَصِيرُ}، استجاب الصحابة لأمر الله ورسوله، فقالوا: سمعنا وأطعنا غفرانك ربنا وإليك المصير.\n\n فلما تكلم بها المسلمون بألسنتهم، وانقادت لها نفوسهم؛ أنزل الله تزكية للنبي وأمته بقوله: {آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالمُؤْمِنُونَ} وانقادت ألسنتهم وقلوبهم لأمر الله.\n\n{كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ}.\n\nبل نؤمن بهم كلهم {وَقَالُوا سَمِعْنَا} قولك {وَأَطَعْنَا} أمرك، ونطلب {غُفْرَانَكَ رَبَّنَا} وعفوك، {وَإِلَيْكَ الْمَصِيرُ} والمآب يوم يقوم الحساب، فلما فعلوا ذلك، وقالوا ما أمروا بقوله من إظهار السمع والطاعة لأوامر الله؛ خفف الله عن هذه الأمة ونسخ تلك الآية بقوله: {لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا} وقدرتها وطاقتها وجهدها، {لَهَا} ثواب {مَا كَسَبَتْ} وعملت من الخير، {وَعَلَيْهَا} عقاب {مَا اكْتَسَبَتْ} من وزر وإثم، ولا يؤاخذ الله أحدًا بذنب غيره، ولا بما وسوست به نفسه.\n\n{رَبَّنَا لَا تُؤَاخِذْنَا} وتعاقبنا {إِنْ نَسِينَا} فلم نتذكر، {أَوْ أَخْطَأْنَا} فتركنا الصواب لا عن عمد، فاستجاب الله لهم ذلك فقال: نعم، قد فعلت.\n\n{رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا} ومشقة وثقلًا {كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا} من بني إسرائيل وغيرهم، فاستجاب الله وقال: نعم، قد فعلت.\n\n {رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ} من التكاليف والبلاء والأمور التي نعجز عن حملها، قال الله: نعم قد فعلت، {وَاعْفُ عَنَّا} ذنوبنا وامحها عنا، {وَاغْفِرْ لَنَا} ذنوبنا واسترها علينا، وتجاوز عنها، {وَارْحَمْنَا} برحمتك الواسعة، {أَنْتَ مَوْلَانَا} وسيدنا؛ {فَانْصُرْنَا} بإقامة الحجة والغلبة {عَلَى الْقَوْمِ الكَافِرِينَ} في قتالهم وجهادهم، فاستجاب الله، فقال: نعم، قد فعلت.", "hintsAr": ["بيان رحمة الله تعالى لهذه الأمة بسبب نبيها صلى الله عليه وسلم الذي قال الله في تعظيم شأنه: {وَمَا أَرْسَلْنَاكَ إِلَّا ‌رَحْمَةً ‌لِلْعَالَمِينَ} [الأنبياء: 107] .", "ثبوت النسخ في القرآن الكريم، وأن من القرآن ما يُقرأ ولكن نُسِخ حُكمُه فلا يعمل به.", "فضل الصحابة رضى الله عنهم وإذعانهم و تسليمهم لأمر الله، وامتثالهم لأمر رسوله صلى الله عليه وسلم.", "ما كان عليه النبي صلى الله عليه وسلم من شدة خوفه على أمته أن تسلك مسلك الأمم السابقة في رد ما أتوا به من أوامر الله تعالى.", "وجوب التسليم لأمر الله تعالى، والحذر من الاعتراض على أمره، وأن هذا فيه مشابهة لأهل الكتاب.", "بيان فضل هذه الأمة على الأمم السابقة، حيث إنهم قالوا لأنبيائهم: سمعنا وعصينا، وهذه الأمة قالت: سمعنا وأطعنا.", "فضل الأمة في رفع الحرج عنها واستجابة الدعاء في عدم المؤاخذة بالنسيان والخطأ، ورفع الآصار عنها التي كانت على من قبلهم، وعدم تحميلها ما لا تطيق.", "الله سبحانه وتعالى لا يحملنا ما لا طاقة لنا به، ولا يكلفنا إلا وسعنا، وأن الوساوس التي تجول في صدورنا إذا لم نركن إليها، ولم نطمئن إليها، ولم نأخذ بها فإنها لا تضر.", "هذا الدعاء أخبر الله تعالى به عن النبي صلى الله عليه وسلم، والمؤمنين، وجعله في كتابه؛ ليكون دعاء من يأتي بعد النبي صلى الله عليه وسلم والصحابة رضي الله عنهم، فهو من الدعاء الذي ينبغي أن يحفظ، ويُدعى به كثيرًا."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Hurayrah"}, {"id": "10851", "number": 30, "title": "The Quran as an intercessor", "section": 4, "sectionTitle": "Living by the Quran", "slug": "30-the-quran-as-an-intercessor", "ref": "Sahih Muslim 804", "primary": "https://sunnah.com/muslim:804", "source": "https://hadeethenc.com/en/browse/hadith/10851", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/10851", "ar": "عن أبي أمامة الباهلي رضي الله عنه قال: سمعتُ رسول الله صلى الله عليه وسلم يقول: «اقرؤوا القرآنَ فإنَّه يأتي يوم القيامة شَفِيعًا لأصحابه، اقرؤوا الزَّهرَاوَين البقرةَ وسورةَ آل عِمران، فإنهما تأتِيان يوم القيامة كأنهما غَمَامَتان، أو كأنهما غَيَايَتانِ، أو كأنهما فِرْقانِ من طَيْر صَوافٍّ، تُحاجَّان عن أصحابهما، اقرؤوا سورة البقرة، فإن أخذها بَرَكة، وتركها حَسْرة، ولا تستطيعها البَطَلَة».", "en": "Abu ’Umāmah al-Bāhili (may Allah be pleased with him) reported: I heard the Messenger of Allah (may Allah's peace and blessings be upon him) say: \"Recite the Qur’an, for on the Day of Judgment it will come as an intercessor for those who recite it. Recite Az-Zahrāwayn (the two bright ones), Al-Baqarah, and Āl ‘Imrān, for on the Day of Judgment, they will come as two clouds or two shades, or two flocks of birds in ranks, pleading for those who recite them. Recite Surat al-Baqarah, for taking recourse to it is a blessing and abandoning it is a cause of grief, and magicians cannot confront it.\"", "ur": "ابو امامہ باہلی رضی اللہ تعالیٰ عنہ سے روایت ہے، انہوں نے کہا کہ میں نے رسول اللہ ﷺ کو یہ فرماتے ہوئے سنا: ”قرآن پڑھا کرو کیونکہ وہ قیامت کے دن اپنے پڑھنے والوں کا سفارشی بن کر آئےگا۔ دو روشن چمکتی ہوئی سورتیں:البقرہ اور آل عمران پڑھا کرو کیونکہ وہ قیامت کے دن اس طرح آئیں گی جیسے وہ دو بادل یا دو سائبان ہوں یا دو اڑتے ہوئے پرندوں کی قطاریں ہوں اور وہ اپنے پڑھنے والوں کی طرف سے حجت (دفاع) کریں گی۔ سورہ بقرہ پڑھا کرو کیونکہ اسے حاصل کرنا باعث برکت ہے اور اس کا ترک کرنا باعثِ حسرت ہے اور باطل پرست اس کی طاقت نہیں رکھتے“۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "The Prophet (may Allah's peace and blessings be upon him) encouraged the regular recitation of the Qur’an, for it will intercede on the Day of Judgment for those who recite it and act upon it. He then emphasized the recitation of Surat al-Baqarah and Āl ‘Imrān, referring to them as \"Az-Zahrāwayn\"—the two radiant ones—due to their light and guidance. The reward of reciting them, reflecting on their meanings, and acting upon their teachings will come on the Day of Judgment in the form of two clouds, or something similar, or two flocks of birds with outstretched wings joined together, offering shade to their companion and defending him. The Prophet (may Allah's peace and blessings be upon him) further emphasized the importance of consistently reciting Surat al-Baqarah, reflecting on its meanings, and acting upon its teachings. He stated that doing so brings immense blessing and benefit in both this world and the Hereafter, while abandoning it brings regret and sorrow on the Day of Judgment. Among the virtues of this surah is that magicians are unable to harm those who recite it.", "explanationUr": "قرآن پڑھا کرو اور اس کی تلاوت پر مداومت برتو کیونکہ یہ قیامت کے دن اپنی تلاوت کرنے اور اس پر عمل کرنے والوں کے لیے سفارش کرے گا۔ بالخصوص سورۂ بقرہ اور سورہ آل عمران پڑھا کرو کیونکہ ان دونوں کا نام دو چمکدار یعنی دو روشنیاں رکھا گیا ہے، اُن کے منور ہونے، ہدایت کے اعتبار سے اور عظیم اجر کے اعتبار سے -گویا کہ اللہ کے نزدیک دیگر سورتوں کے تناسب سے ایسے ہی ہے جیسے قمرین کو تما م ستاروں پر- ان دونوں کے پڑھنے کا ثواب یہ ہےکہ قیامت کے دن یہ دونوں دو بادلوں کی صورت میں اپنے پڑھنے والے پر روز محشر کی گرمی سے سایہ کیے ہوئے ہوں گی یا پھر ان کے پڑھنے کا ثواب پرندوں کی دو جماعتیں جو صفوں کی صورت میں ایک دوسرے کے ساتھ اپنے پر ملائے ہوئے کھڑے ہو ں گے جو اپنے پڑھنے والے کا دفاع کریں گی اور ان کو جہنم میں سے بچائیں گی۔\nاس میں کوئی مانع نہیں ہے کہ وہ آنے والا خود عملِ (قرآن) کی شکل میں آئے گا جیسا کہ حدیث کے ظاہر سے پتہ چل رہا، لیکن اگر یہ کہا جائے کہ وہ آنے والا خود اللہ کا کلام ہے، تو یہ درست نہیں۔ کیونکہ ’کلام‘ اللہ تعالیٰ کی صفات میں سے ہے اور صفتْ ذات سے الگ نہیں ہوتی اور جس چیز کو میزان میں رکھا جائے گا وہ بندے کافعل اور عمل ہو گا جیسا کہ ﴿وَاللَّـهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ﴾ ”اور اللہ ہی ہے جس نے تمہیں اور جو تم عمل کرتے ہو ان سب کو پیدا کیا ہے“ (سورہ الصافات: 96)\nنبی کریم ﷺ نے سورۂ بقرہ کی تلاوت کی تاکید فرمائی ہے کیونکہ اس کی تلاوت پر مداومت برتنے، اس کے معانی پر غور وفکر اور اس پر عمل کرنے میں بہت ساری برکتیں اور عظیم منافع موجود ہیں۔ اور اس سورت کو چھوڑنا، اس کی تلاوت نہ کرنا اور اس پر غور وفکر کرتے ہوئے اس پر عمل نہ کرنا قیامت کے دن حسرت و ندامت کا سبب بنے گا۔ اس سورت کا ایک بہت بڑا کمال یہ بھی ہے کہ اس کے پڑھنے والے اور اس پر غور و فکر کرتے ہوئے عمل کرنے والے کو جادو کسی بھی قسم کا نقصان پہنچانے کی طاقت نہیں رکھتا۔ اور (یہ بھی) کہا گیا ہے کہ جادوگر اس کے پڑھنے، اس میں تدبر کرنے، اس کے مطابق عمل کرنے کی طاقت نہیں رکھتے اورنہ ہی ان کو اس کی توفیق ملتی ہے ۔", "hints": ["The command to recite the Qur’an frequently, and that it will intercede for its companions on the Day of Judgment—those who recite it, adhere to its guidance, uphold what it commands, and refrain from what it forbids.\r", "The merit of Surat al-Baqarah and Āl ‘Imrān and their great reward.\r", "The merit of Surat al-Baqarah and that it protects its companion from magic."], "hintsUr": [], "explanationAr": "حث النبي صلى الله عليه وسلم على مداومة قراءة القرآن؛ فإنه يشفع يوم القيامة للتالين له العاملين به، ثم أكد على قراءة سورتي البقرة وآل عمران وسماهما الزهراوين المنيرتين؛ لنورهما وهدايتهما، وأن أجر وثواب تلاوتهما وتدبر معانيهما والعمل بما فيهما يأتي يوم القيامة كسحابتين أو غيرهما، أو كأنهما جماعتين من الطير باسطات أجنحتها متصلاً بعضها ببعض، تظلان صاحبهما وتدافعان عنه. \n\nثم أكد صلى الله عليه وسلم على الاستمرار في قراءة سورة البقرة وتدبر معانيها والعمل بما فيها، وأن ذلك فيه بركة ومنفعة عظيمة في الدنيا والآخرة، وترك ذلك فيه حسرة وندامة يوم القيامة، وأن من فضل هذه السورة أن السحرة لا تقدر أن تضر من يقرأها.", "hintsAr": ["الأمر بتلاوة القرآن والإكثار من ذلك، وأنه يشفع لأصحابه يوم القيامة، القارئين له، المتمسكين بهديه، القائمين بما أمر به، والتاركين لما نهى عنه.", "فضل قراءة سورة البقرة وآل عمران وعظيم أجرهما.", "فضل قراءة سورة البقرة، وأنها تحمي صاحبها من السحر."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Umamah al-Bahili"}, {"id": "10119", "number": 31, "title": "Being elevated through the Book", "section": 4, "sectionTitle": "Living by the Quran", "slug": "31-being-elevated-through-the-book", "ref": "Sahih Muslim 817", "primary": "https://sunnah.com/muslim:817", "source": "https://hadeethenc.com/en/browse/hadith/10119", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/10119", "ar": "عن عمر بن الخطاب رضي الله عنه : أن النبي صلى الله عليه وسلم قال: «إن اللهَ يَرفعُ بهذا الكِتابِ أقْواماً ويَضَعُ به آخَرِينَ».", "en": "‘Umar ibn al-Khattāb (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: “Indeed, Allah elevates some people with this Book and degrades others.”", "ur": "عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے فرمایا: ”اللہ تعالیٰ اس کتاب کے ذریعے بہت سے لوگوں کو بلند کرتا ہے اور اسی کتاب کے ذریعے بہت سے لوگوں کو پست و ذلیل کرتا ہے۔“", "grade": "Authentic hadith", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "This Hadīth means that the Qur'an is taken up by some people, who consequently read it. Allah elevates by means of the Qur'an some people in the world and afterlife, and demotes by means of which others in both worlds. Those who are elevated are those who follow the Qur'an, believe in its news, observe its commands and prohibitions, and take as their model the ethics it promotes. Allah will raise their status in this world and in the Hereafter because the Qur'an is the fountainhead of knowledge. Allah, the Almighty, says: {Allah will raise those who have believed among you and those who were given knowledge, by degrees} [Sūrat al-Mujādalah: 11]. In the Hereafter, these people will be elevated in the gardens of bliss. On the other hand, the people whom Allah degrades by means of the Qur'an are those who read the Qur'an and even recite it well, but are arrogant toward it. They neither believe in its news nor implement its rulings. They are arrogant in theory and practice. For example, when they come across stories of the previous Prophets or others, or information about the Last Day, they suspect and do not believe in them. They might even end up denying the Qur'an, although they read it. These Allah will demote in both worlds.", "explanationUr": "عمر رضی اللہ عنہ سے روایت ہے کہ اللہ کے رسول ﷺ نے فرمایا: \"اللہ تعالیٰ اس کتاب کے ذریعے بہت سے لوگوں کو بلند کرتا ہے اور اسی کتاب کے ذریعے بہت سے لوگوں کو پست و ذلیل کرتا ہے\"۔ یعنی جو لوگ اس قرآن کو سیکھتے ہیں، اس کی تلاوت کرتے اور پڑھتے ہیں، ان میں سے بعض کو اللہ تعالیٰ دنیا اور آخرت میں بلندیاں عطا فرماتا ہے اور بعض کو دنیا و آخرت میں ذلیل کرتا ہے۔ جو قرآنی کی بتائی ہوئی باتوں کی تصدیق کرکے اس کی احکامات پر عمل کرتا ہے اور نواہی سے بچتا ہے، اس سے راہ نمائی حاصل کرتا ہے، اس کے بیان کردہ اخلاق فاضلہ کے مطابق خود کو ڈھالتا ہے، تو اللہ تعالیٰ اسے دنیا و آخرت میں بلندیاں عطا کرتا ہے؛ کیوںکہ یہی قرآن اصل علم، علم کا سرچشمہ اور پورا علم ہے۔ اللہ تعالیٰ کا فرمان ہے: ﴿یرفَعِ اللَّـهُ الَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ﴾ ”اللہ تعالیٰ تم میں سے ان لوگوں کے، جو ایمان ﻻئے ہیں اور جو علم دیے گئے ہیں، درجے بلند کر دے گا اور آخرت میں اس کے ذریعے بہت ساری قوموں کو نعمتوں والی جنت میں بلندیاں عطا کریں گے۔\nجہاں تک ان لوگوں کی بات ہے، جنھیں اللہ قرآن کے ذریعے ذلیل کرتا ہے، تو یہ وہ لوگ ہیں، جو اس کی تلاوت بہتر انداز میں کرتے ہیں؛ لیکن اس سے تکبر کرتے ہیں، اس کی بتائی ہوئی باتوں کی تصدیق نہیں کرتے، اس کے احکامات پر عمل نہیں کرتے، اس کی خبروں کو جان بوجھ کر جھٹلاتے ہیں، جیسے گزشتہ انبیا کے واقعات یا آخرت کے بارے میں قرآن کی خبریں وغیرہ۔ ان تمام امور میں شک و شبہ کی روش اپناتے ہیں-والعیاذ باللہ- اور دل سے یقین نہیں کرتے۔ بسا اوقات ان کا یہ جان بوجھ کر انکار کا رویہ اس حد تک پہنچ جاتا ہے کہ وہ قرآن کی تلاوت کرتے ہوئے بھی اس کا انکار کرتے ہیں، اس کے احکامات سے روگردانی کرتے ہیں، اوامر پر عمل نہیں کرتے اور نہ ہی ممنوعات سے بچتے ہیں۔ یہی لوگ ہیں جنہیں اللہ تعالیٰ دنیا و آخرت میں رسوا کرے گا۔ والعیاذ باللہ!", "hints": [], "hintsUr": [], "explanationAr": "عن عمر بن الخطاب رضي الله عنه أن النبي صلى الله عليه وسلم قال: \"إن الله يرفع بهذا الكتاب أقواماً ويضع به آخرين\"، يعني: معناه أن هذا القرآن يأخذه أناس يتلونه ويقرءونه، فمنهم من يرفعه الله به في الدنيا والآخرة، ومنهم من يضعهم الله به في الدنيا والآخرة، من عمل بهذا القرآن تصديقاً بأخباره، وتنفيذاً لأوامره واجتناباً لنواهيه، واهتداء بهديه، وتخلقاً بما جاء به من أخلاق -وكلها أخلاق فاضلة-، فإن الله تعالى يرفعه به في الدنيا والآخرة، وذلك لأن هذا القرآن هو أصل العلم ومنبع العلم وكل العلم، وقد قال الله تعالى: (يرفع الله الذين آمنوا منكم والذين أوتوا العلم درجات)، أما في الآخرة فيرفع الله به أقواماً في جنات النعيم.\nوأما الذين يضعهم الله به فقوم يقرءونه ويحسنون قراءته، لكنهم يستكبرون عنه -والعياذ بالله- لا يصدقون بأخباره، ولا يعملون بأحكامه يستكبرون عنه عملاً، ويجحدونه خبراً إذا جاءهم شيء من القرآن كقصص الأنبياء السابقين أو غيرهم أو عن اليوم الآخر أو ما أشبه ذلك صاروا والعياذ بالله يشككون في ذلك ولا يؤمنون، وربما يصل بهم الحال إلى الجحد مع أنهم يقرءون القرآن، وفي الأحكام يستكبرون لا يأتمرون بأمره ولا ينتهون بنهيه، هؤلاء يضعهم الله في الدنيا والآخرة، والعياذ بالله.", "hintsAr": ["الحث على الاهتمام بكتاب الله تلاوة وحفظاً وفهماً وعملاً.", "العلم يرفع صاحبه في الدنيا والآخرة، ما لا يرفعه المال ولا الملك ولا غيرهما.", "الأمة المسلمة عزها وشرفها بتمسكها بدينها، والقيام بحق كتابها."], "words": [{"word": "يضع", "meaning": " يخفض."}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Umar ibn al-Khattab"}, {"id": "65059", "number": 32, "title": "Recognizing the greatest verse", "section": 4, "sectionTitle": "Living by the Quran", "slug": "32-recognizing-the-greatest-verse", "ref": "Sahih Muslim 810", "primary": "https://sunnah.com/muslim:810", "source": "https://hadeethenc.com/en/browse/hadith/65059", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/65059", "ar": "عَنْ ‌أُبَيِّ بْنِ كَعْبٍ رضي الله عنه قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «يَا أَبَا الْمُنْذِرِ، أَتَدْرِي أَيُّ آيَةٍ مِنْ كِتَابِ اللهِ مَعَكَ أَعْظَمُ؟» قَالَ: قُلْتُ: اللهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: «يَا أَبَا الْمُنْذِرِ، أَتَدْرِي أَيُّ آيَةٍ مِنْ كِتَابِ اللهِ مَعَكَ أَعْظَمُ؟» قَالَ: قُلْتُ: {اللهُ لا إِلَهَ إِلا هُوَ الْحَيُّ الْقَيُّومُ} [البقرة: 255]. قَالَ: فَضَرَبَ فِي صَدْرِي، وَقَالَ: «وَاللهِ لِيَهْنِكَ الْعِلْمُ، أَبَا الْمُنْذِرِ».", "en": "Ubayy ibn Ka‘b (may Allah be pleased with him) reported: The Messenger of Allah (may Allah’s peace and blessings be upon him) said: \"O Abu al-Mundhir, do you know which verse of Allah's Book that you have is the greatest?\" I replied: \"Allah and His Messenger know best.\" He said: \"O Abu al-Mundhir, do you know which verse of Allah's Book that you have is the greatest?\" I said: \"{Allah: none has the right to be worshiped except Him, the Ever-Living, All-Sustaining...} [Surat al-Baqarah: 255].\" Thereupon, he struck me on the chest and said: \"May knowledge be pleasant for you, O Abu al-Mundhir!\"", "ur": "ابی بن کعب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے ابو منذر! کیا تم جانتے ہو کہ تمھارے پاس موجود اللہ کی کتاب کی کون سی آیت سب سے عظیم ہے؟۔‘‘ ان کا کہنا ہے کہ میں نے عرض کیا: اللہ اوراس کے رسول ﷺ زیادہ جانتے ہیں۔ آپﷺ نے (دوبارہ) فرمایا: ’’اے ابو منذر! کیا تم جانتے ہو کہ تمھارے پاس موجود اللہ کی کتاب کی کون سی آیت سب سے عظیم ہے؟۔‘‘ ان کا کہنا ہے کہ میں نے عرض کیا: ﴿اللَّهُ لَا إِلہ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾ ان کا کہنا ہے کہ یہ سننے کے بعد آپﷺ نے میرے سینے پر ہاتھ مارا اور فرمایا: ’’اللہ کی قسم ! ابو منذر! تمھیں یہ علم مبارک ہو\"۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "The Prophet (may Allah's peace and blessings be upon him) asked Ubayy ibn Ka‘b about the greatest verse in Allah's Book. He initially hesitated about the answer and then said: {Allah: none has the right to be worshiped except Him, the Ever-Living, All-Sustaining...} The Prophet (may Allah's peace and blessings be upon him) agreed with him and struck him on the chest, indicating that it is filled with knowledge and wisdom. He also supplicated that this knowledge be pleasant and easy for him.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ وسلم نے ابی بن کعب سے کتاب الہی کی سب سے عظیم آیت کے بارے میں پوچھا، تو ان کو جواب دینے میں تردد اور پس وپیش ہونے لگا۔ لیکن پھر جواب دیا کہ وہ آیت الکرسی (الله لا إله إلا هو الحي القيوم) ہے، تو اللہ کے نبی صلی اللہ علیہ وسلم نے اس جواب کی تائید کی اور اس بات کا اشارہ کرنے کے لیے ان کے سینے پر ہاتھ مارا کہ ان کا سینہ علم وحکمت سے پُر ہے۔ نیز ان کے لیے یہ دعا کی کہ یہ علم ان کے لیے باعث سعادت ہو اور ان کی راہ میں آسانی ہی آسانی آئے۔", "hints": ["The Hadīth highlights great excellence for Ubayy ibn Ka‘b (may Allah be pleased with him).\r", "The verse of al-Kursī is the greatest verse in the Book of Allah Almighty. So, we should memorize it, ponder its meanings, and act accordingly."], "hintsUr": ["ابی بن کعب رضی اللہ عنہ کی عظیم منقبت۔\r", "آیۃ الکرسی کتاب الہی کی سب سے عظیم آیت ہے۔ اس لیے اس آیت کو حفظ کرنا چاہیے، اس کے معانی پر غور وفکر کرنا چاہیے اور اس پر عمل کرنا چاہیے۔"], "explanationAr": "سأل النبيُّ صلى الله عليه وسلم أبيَّ بن كعب عن أعظم آية في كتاب الله، \nفتردد في الإجابة، ثم قال: هي آية الكرسي: {الله لا إله إلا هو الحي القيوم}، \nفأيَّده النبي صلى الله عليه وسلم، وضرب النبي على صدره إشارة إلى امتلائه علمًا وحكمة، ودعا له بأن يَسعدَ بهذا العلم وأن يُيَسَّر له.", "hintsAr": ["منقبة عظيمة لأبي بن كعب رضي الله عنه.", "آية الكرسي أعظم آية في كتاب الله تعالى، فينبغي حفظها وتدبر معانيها والعمل بها."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Ubayy ibn Kab"}, {"id": "5795", "number": 33, "title": "Religion is a path of ease", "section": 5, "sectionTitle": "A balanced Prophetic path", "slug": "33-religion-is-a-path-of-ease", "ref": "Sahih al-Bukhari 39", "primary": "https://sunnah.com/bukhari:39", "source": "https://hadeethenc.com/en/browse/hadith/5795", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/5795", "ar": "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِنَّ الدِّينَ يُسْرٌ، وَلَنْ يُشَادَّ الدِّينَ أَحَدٌ إِلَّا غَلَبَهُ، فَسَدِّدُوا وَقَارِبُوا، وَأَبْشِرُوا، وَاسْتَعِينُوا بِالْغَدْوَةِ وَالرَّوْحَةِ وَشَيْءٍ مِنَ الدُّلْجَةِ».", "en": "Abu Hurayrah (may Allah be pleased with him) reported: The Prophet (may Allah's peace and blessings be upon him) said: \"Indeed, the religion is easy. No one overburdens himself in the religion except that he will be overwhelmed by it. So, seek uprightness (be moderate) and try to be close to it and receive the glad tidings. Seek help by worship in the Ghadwah (early morning), Rawhah (afternoon), and part of the Duljah (night).\"", "ur": "ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ اللہ کے نبی صلی اللہ علیہ و سلم  نے فرمایا : \"بے شک دین آسان ہے۔ جو شخص دین کے معاملے میں سختی اختیار کرے گا، اس پر دین غالب آ جائے گا۔ چنانچہ اپنے عمل میں راستگی اختیار کرو اور جہاں تک ممکن ہو میانہ روی برتو اور خوش ہو جاؤ، اور صبح و شام اور کسی قدر رات میں (عبادت کے ذریعہ) مدد حاصل کرو\"۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Al-Bukhāri", "explanation": "The Prophet (may Allah's peace and blessings be upon him) pointed out that the religion of Islam is built on facilitation and ease in all its affairs, and facilitation becomes more emphatic when there is an inability and need for it. Also, delving deeply into religious activities and abandoning moderateness finally leads to the inability and cessation of deeds, wholly or partially. Then, the Prophet (may Allah's peace and blessings be upon him) urged moderation and refraining from excessive. So, a person should neither neglect his duties nor be burdened with things beyond his capacity. If he is unable to do a certain deed altogether, he should perform what is close to it.\r\n\r\nThe Prophet (may Allah's peace and blessings be upon him) gave good tidings of a great reward for ongoing deeds, even if they are little, for those who are unable to perform the deeds completely. This is because if the inability is not due to their own fault, it does not entail a reduction in their reward.\r\n\r\nSince this world is in reality a place of travel and transfer to the Hereafter, the Prophet (may Allah's peace and blessings be upon him) commanded us to seek help, for the regular performance of worship, in the three times of activeness:\r\n\r\nFirst: Ghadwah: walking in the early morning - between the Fajr prayer and sunrise.\r\n\r\nSecond: Rawhah: walking in the afternoon.\r\n\r\nThird: Duljah: walking in the whole night or part of it. Since work at night is harder than the daytime, he enjoined part of it, saying: and part of the Duljah.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم نے بتایا کہ مذہب اسلام کی بنیاد تمام معاملات میں آسانی اور سہولت فراہم کرنے پر رکھی گئی ہے۔ یہ آسانی اور سہولت اس وقت کہیں زیادہ فراہم کی گئی ہے، جب عجز و حاجت موجود ہو۔ سچ تو یہ ہے کہ دینی اعمال میں تعمق اور ترک رفق کا انجام عجز اور انقطاع عمل کی صورت ہی میں ظاہر ہوتا ہے۔ اس کے بعد رسول صلی اللہ علیہ و سلم نے میانہ روی کی ترغیب دی۔ بندہ نہ تو شرعی احکام کی بجا آوری میں کوتاہی سے کام لے اور نہ اپنے اوپر ایسی چیزیں لادے، جنھیں اٹھانے کی طاقت نہ رکھتا ہو۔ اگر کامل ترین پر عمل نہ کر سکے، تو اس سے قریب ترین پر عمل کرے۔\r\n\r\nاس کے بعد اللہ کے رسول صلی اللہ علیہ و سلم نے ایسے شخص کو بڑے اجر و ثواب کی خوش خبری دی ہے، جو کامل ترین پر عمل نہ کر پانے کی وجہ سے تھوڑا سا عمل ہی کرتا ہو، لیکن اس میں تسلسل ہو۔ کیوں کہ عدم استطاعت میں اگر بندے کا عمل دخل نہ ہو، تو اس سے اس کے اجر و ثواب میں کمی نہیں آتی۔\r\n\r\nپھر چوں کہ دنیا سفر کی جگہ اور آخرت کی گزرگاہ ہے، اس لیے اللہ کے رسول صلی اللہ علیہ و سلم نے تین نشاط آمیز اوقات میں تسلسل کے ساتھ عبادت کے ذریعے مدد حاصل کرنے کا حکم دیا ہے۔ یہ تین اوقات اس طرح ہیں:\r\n\r\n1- الغدوۃ : دن کے پہلے حصے میں چلنا۔ دن کے پہلے حصے سے مراد فجر کی نماز سے لے کر سورج نکلنے کے درمیان کا وقت ہے۔\r\n\r\n2- الروحۃ : زوال کے بعد چلنا۔\r\n\r\n3- دلجۃ : پوری رات یا رات کے کچھ حصے میں چلنا۔ چوں کہ رات میں کام کرنا دن میں کام کرنے کے مقابلے میں کہیں زیادہ مشکل ہوتا ہے، اس لیے \"وشيءٍ من الدلجة\" کہہ کر اس کے کچھ حصے میں کام کرنے کا حکم دیا ہے۔", "hints": ["The Hadīth shows the ease and tolerance of Islamic Shariah and its middle position between excess and neglect.\r", "A person should fulfill a command to the best of his ability, neither taking it lightly nor overburdening himself with it.\r", "A person should choose the times of activeness for the performance of worship. In these three times in particular, one's body becomes most energetic for worship.\r", "Ibn Hajar al-‘Asqalāni said: It is as if the Prophet (may Allah's peace and blessings be upon him) was addressing a traveler to a destination, and these three times are the best times for the traveler. So, he alerted him to the times in which he is active. If a traveler travels during both the night and day, he will become weak and cut off. But if he is keen to travel during these energetic times, he will be able to continue without difficulty.\r", "Ibn Hajar said: There is a reference in the Hadīth to taking the Shar‘i dispensation, for choosing a determined course of action where a Shar‘i dispensation is available is regarded as immoderation. For example, a person refuses to perform Tayammum (dry ablution) when he is unable to use water, and his use of it leads to a harmful effect.\r", "Ibn al-Munīr said: In this Hadīth is one of the signs that prove the Prophet's prophethood, for we have seen and the people before us have seen that every extremist in the religion will be cut off. The purpose is not to prevent the pursuit of the most perfect form of worship, which is commendable. Rather, it is to prevent excess that leads to boredom, or exaggeration in voluntary acts that lead to abandoning what is better or performing an obligatory act beyond its time, such as someone who spends the whole night praying and then sleeps and does not offer the Fajr prayer in congregation, or until the sun rises and the time for the obligatory prayer has passed."], "hintsUr": ["اسلامی شریعت آسانى، کشادگى اور افراط و تفریط سے دور  اعتدال کی حامل شریعت ہے۔\r", "انسان کو کوئی بھی کام اپنی استطاعت کے مطابق کرنا چاہیے۔ نہ سستی کا عمل دخل ہو اور نہ انتہا پسندی کا۔\r", "انسان کو عبادت کے لیے ایسے اوقات کا انتخاب کرنا چاہیے، جب طبیعت میں نشاط اور چستی ہو۔ مذکورہ تین اوقات ایسے ہیں کہ ان میں جسم عبادت کی جانب سب سے زیادہ آمادہ رہتا ہے۔\r", "ابن حجر کہتے ہيں: یہاں ایک طرح سے اللہ کے رسول صلی اللہ علیہ و سلم نے کسی منزل کی جانب سفر کر رہے شخص کو مخاطب کیا ہے۔ چوں کہ اس حدیث میں مذکور تین اوقات سفر کے لیے سب سے مناسب اوقات ہیں، اس لیے اللہ کے رسول صلی اللہ علیہ و سلم نے ان کی نشان دہی فرما دی۔ کیوں کہ اگر مسافر رات دن چلتا ہی رہ جائے، تو کچھ دوری طے کرنے کے بعد تھک ہارکر بیٹھ جائے گا۔ اس کے برعکس اگر ان نشاط آمیز اوقات میں چلے اور اس کے بعد آرام کرے تو سفر کو جاری رکھنا آسان ہو جائے گا۔\r", "ابن حجر کہتے ہيں: اس حدیث میں اشارہ شرعی رخصت پر عمل کرنے کی جانب ہے۔ کیوں کہ جہاں رخصت ہو، وہاں عزیمت سے چپکے رہنا، انتہا پسندی ہے۔ مثلا کسی کے لیے پانی کا استعمال ممنوع ہو اور تیمم کے بجائے وضو کرنے پر مصر رہے اور اس کی وجہ سے اس کا نقصان بھی ہو جائے۔\r", "ابن المنیر کہتے ہیں: یہ حدیث محمد عربی صلی اللہ علیہ و سلم کے برحق نبی ہونے کی ایک بہت بڑی نشانی ہے۔ ہم نے اور ہم سے پہلے کے لوگوں نے دیکھا ہے کہ طاقت سے زیادہ عمل کا بوجھ  اٹھانے کی کوشش کرنے والا ہر شخص تھک ہار کر بیٹھ جاتا ہے۔ لیکن یہ بھی یاد رہے کہ یہاں عبادت کی کامل ترین روش پر گام زن ہونے سے منع نہیں کیا گیا ہے۔ یہ تو ایک قابل ستائش رویہ ہے۔ منع افراط سے کیا گیا ہے جو تھک ہار کر بیٹھ جانے کا سبب بنتا ہے، نفلی عبادتوں میں مبالغے سے منع کیا گیا ہے جو ترک افضل یا کسی فرض کو اس کے وقت سے مؤخر کرنے کا سبب بنتا ہے۔ جیسے کوئی رات بھر تہجد پڑھ کر سوگیا اور فجر کی نماز جماعت کے ساتھ ادا نہ کر سکا یا پھر سورج نکلنے تک سویا ہی رہ گیا۔"], "explanationAr": "بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ دينَ الإسلامِ مبنيٌّ على التيسير والسهولة في كل شؤونه، ويتأكد التيسير عند وجود سبب العجز والحاجة، ولأنَّ التعمُّقَ في الأعمال الدينية وترك الرفق عاقبتُه العجز والانقطاع عن العمل كله أو بعضه،\n \nثم حث صلى الله عليه وسلم على التوسط من غير مبالغة؛ فلا يُقصِّر العبد فيما أُمر به، ولا يتحمل ما لا يطيقه، فإن عجز عن العمل بالأكمل؛ فالعمل على ما يَقْرُبُ منه.\n\nوبشَّر صلى الله عليه وسلم بالثواب الجزيل على العمل الدائم وإن قلَّ لمَن عجز عن العمل بالأكمل؛ لأن العجز إذا لم يكن من صنيعه فلا يستلزم نقص أجره. \n\nوحيث أن الدنيا في الحقيقة دار سفر ونُقْلة إلى الآخرة أمر صلى الله عليه وسلم بالاستعانة على مداومة العبادة بإيقاعها في الأوقات الثلاثية المنشطة: \n\nالأول: الغَدوة: بسير أول النهار؛ ما بين صلاة الفجر وطلوع الشمس. \n\nالثاني: الرَّوحة: بالسير بعد الزوال. \n\nالثالث: الدُّلْجة: بسير الليل كله أو بعضه، ولأن عمل الليل أشق من عمل النهار أمر ببعضه بقوله: وشيءٍ من الدلجة.", "hintsAr": ["يُسر وسماحة الشريعة الإسلامية وتوسُّطها بين الإفراط والتفريط.", "على العبد أن يأتي بالأمر بقدر استطاعته، من دون تساهل أو تشديد.", "على العبد أن يختار أوقات النشاط في العبادة، وهذه الأوقات الثلاثة بخصوصها هي أروح ما يكون فيها البدن للعبادة.", "قال ابن حجر العسقلاني: كأنه صلى الله عليه وسلم خاطب مسافرًا إلى مقصدٍ، وهذه الأوقات الثلاثة أطيب أوقات المسافر، فنبهه على أوقات نشاطه؛ لأن المسافر إذا سافر الليل والنهار جميعًا عجز وانقطع، وإذا تحرَّى السير في هذه الأوقات المنشطة أمكنته المداومة من غير مشقة.", "قال ابن حجر: الإشارة في هذا الحديث إلى الأخذ بالرخصة الشرعية، فإنّ الأخذ بالعزيمة في موضع الرخصة تَنَطُّعٌ، كمن يترك التيمم عند العجز عن استعمال الماء فيفضي به استعماله إلى حصول الضرر.", "قال ابن المنير: في هذا الحديث عَلَمٌ من أعلام النبوة، فقد رأينا ورأى الناس قبلنا أن كل متنطع في الدين ينقطع، وليس المراد مَنْعِ طلب الأكمل في العبادة فإنه من الأمور المحمودة، بل منع الإفراط المؤدّي إلى الملال، أو المبالغة في التطوع المفضي إلى ترك الأفضل، أو إخراج الفرض عن وقته كمَن بات يصلي الليل كلَّه فنام عن صلاة الصبح في الجماعة، أو إلى أن طلعت الشمس فخرج وقت الفريضة."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Hurayrah"}, {"id": "6389", "number": 34, "title": "Choose ease within lawful limits", "section": 5, "sectionTitle": "A balanced Prophetic path", "slug": "34-choose-ease-within-lawful-limits", "ref": "Sahih al-Bukhari 3560", "primary": "https://sunnah.com/bukhari:3560", "source": "https://hadeethenc.com/en/browse/hadith/6389", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/6389", "ar": "عَنْ عَائِشَةَ أُمِّ المُؤْمِنينَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ: مَا خُيِّرَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَمْرَيْنِ إِلَّا أَخَذَ أَيْسَرَهُمَا، مَا لَمْ يَكُنْ إِثْمًا، فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ، وَمَا انْتَقَمَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِنَفْسِهِ إِلَّا أَنْ تُنْتَهَكَ حُرْمَةُ اللَّهِ، فَيَنْتَقِمَ لِلَّهِ بِهَا.", "en": "‘Ā’ishah, Mother of the Believers, (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) was never given a choice between two things except that he would choose the easier of the two unless it were a sin. If it were a sin, he would be the farthest of people from it. The Messenger of Allah (may Allah's peace and blessings be upon him) never took revenge for himself, but when the prohibitions of Allah were violated, he would take revenge for the sake of Allah.", "ur": "امّ المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہيں: جب بھی رسول اللہ ﷺ کو دو چیزوں میں سے ایک کا انتخاب کرنا ہوتا، تو آپ ﷺ ہمیشہ دونوں میں سے آسان کا انتخاب کرتے، بشرط کہ وہ آسان کام گناہ نہ ہوتا۔ اگر وہ گناہ ہوتا، تو آپ ﷺ اس سے سب سے زیادہ دور رہتے۔ رسول اللہ ﷺ نے کبھی اپنی ذات کے لیے انتقام نہیں لیا، ما سوا اس کے کہ اللہ کی حرمات میں سے کسی حرمت کو پامال کیا جائے۔ اس صورت میں آپ ﷺ اللہ تعالی کے لیے انتقام لیا کرتے تھے۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Agreed upon", "explanation": "‘Ā’ishah, Mother of the Believers (may Allah be pleased with her), informed about some of the morals of the Prophet (may Allah's peace and blessings be upon him). Among what she mentioned was that whenever the Prophet (may Allah's peace and blessings be upon him) was given a choice between two matters, he would choose the easier of the two, as long as the easier option did not lead to sin. If it led to sin, he would be the farthest of people from it and would then choose the more difficult option. The Prophet (may Allah's peace and blessings be upon him) never sought revenge for himself exclusively; rather, he would forgive and overlook his own rights. But when the sanctities of Allah were violated, he would seek revenge for the sake of Allah, and he was the most intense in anger for the sake of Allah.", "explanationUr": "ام المومنین عائشہ رضی اللہ عنہا اللہ کے نبی صلی اللہ علیہ و سلم کے اخلاق سے جڑی ہوئی کچھ باتیں بیان کر رہی ہیں۔ وہ بتا رہی ہیں اللہ کے رسول صلی اللہ علیہ و سلم کو جب بھی دو چیزوں میں سے کسی ایک کو چننے کا اختیار دیا جاتا، تو آپ زیادہ آسان کو چنتے، بشرطیکہ زیادہ آسان چيز گناہ کا سبب نہ ہو۔ اگر ایسا ہوتا تو آپ اس سے دوسرے لوگوں کے مقابلے میں کہيں زیادہ دور بھاگتے اور زیادہ مشکل کا انتخاب کرتے۔ اسی طرح اللہ کے رسول صلی اللہ علیہ و سلم نے خود اپنے لیے کبھی انتقام نہیں لیا۔ اپنا حق معاف کر دیتے اور درگزر سے کام لیتے تھے۔ ہاں، اگر اللہ کی حرمتوں کو پامال کیا جاتا، تو اللہ کے لیے انتقام لیتے۔ اللہ کے لیے آپ کو دوسروں کے مقابلے میں کہيں زیادہ غصہ آتا تھا۔", "hints": ["It is recommended to choose the easier option in matters, as long as it does not involve disobedience to Allah.\r", "The ease of Islam.\r", "The legitimacy of getting angry for the sake of Allah Almighty.\r", "The Prophet's forbearance, patience, and adherence to the truth in enforcing the limits set by Allah Almighty.\r", "Ibn Hajar said: It indicates refraining from choosing the difficult option, being content with ease, and abstaining from insistence on matters that are not necessary.\r", "Encouraging forgiveness except when it comes to the rights of Allah Almighty."], "hintsUr": ["زيادہ آسان چیز کا انتخاب کرنا مستحب ہے، جب تک کہ اس میں گناہ کا پہلو نہ ہو۔\r", "اسلام ایک آسان مذہب ہے۔\r", "اللہ تعالی کے لیے غضب ناک ہونا مشروع ہے۔\r", "نبی کریم صلى الله عليہ وسلم کے اندر اللہ کے حدود کو قائم کرنے کے سلسلے میں تحمل، صبر اور حق پر عمل پایا جاتا تھا۔\r", "ابن حجر کہتے ہيں: اس حدیث سے معلوم ہوتا ہے کہ دشوار چيز کو ترک کرنا چاہیے اور آسان چیز پر اکتفا کرنا چاہیے۔\r", "عفو ودرگزر سے کام لینے کی ترغیب، جب تک اللہ کے حقوق پامال نہ ہوتے ہوں۔"], "explanationAr": "أَخْبَرَتْ أمُّ المؤمنين عائشةُ رضي الله عنها عن بعض أخلاق النبي صلى الله عليه وسلم، ومما ذَكَرَتْ: أنه صلى الله عليه وسلم ما خُيّر بين أمرين إلا أَخَذَ أَسْهَلْهُما ما لم يكن الأسهل مُقتضيًا للإثم، فإنه يكون أبعد الناس عنه ويختار حينئذ الأشدّ.\n\n\nوما انتقم صلى الله عليه وسلم لنفسه خاصة بل كان يَسْمَحُ ويَعفو عن حقِّه إلا أنْ تُنْتَهَك حُرُمات الله فيكون لله ينتقم، وكان أشد الناس غضبًا لله.", "hintsAr": ["استحباب الأخذ بالأَيْسر في الأمور ما لم يكن فيه معصية.", "يُسْر الإسلام.", "مشروعية الغضب لله تعالى.", "ما كان عليه صلى الله عليه وسلم من الحِلْم والصبر والقيام بالحق في إقامة حدود الله تعالى.", "قال ابن حجر: وفيه ترك الأخذ بالشيء العَسِر، والاقتناع باليُسْر، وترك الإلحاح فيما لا يضطر إليه.", "الحث على العفو إلا في حقوق الله تعالى."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Aishah"}, {"id": "11282", "number": 35, "title": "Concern for the community", "section": 5, "sectionTitle": "A balanced Prophetic path", "slug": "35-concern-for-the-community", "ref": "Sahih al-Bukhari 1128", "primary": "https://sunnah.com/bukhari:1128", "source": "https://hadeethenc.com/en/browse/hadith/11282", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/11282", "ar": "عن عائشة رضي الله عنها ، قالت: «إنْ كان رسول الله صلى الله عليه وسلم لَيَدَعُ العمل، وهو يُحِبُّ أن يعملَ به خَشْيَة أن يعملَ به الناس، فَيُفْرَضَ عليهم، وما سَبَّح رسول الله صلى الله عليه وسلم سُبْحَة الضُّحى قَطُّ وإنِّي لَأُسَبِّحُهَا».", "en": "‘Ā’ishah (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) would give up a deed, even though he liked to perform it, for fear that people would follow him and perform it, and it would thus become obligatory for them. The Prophet (may Allah's peace and blessings be upon him) never prayed the Duha prayer, but I offer it.", "ur": "عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ ﷺ کسی کام کو چھوڑ دیتے، حالاں کہ آپ ﷺ کو اس کا کرنا پسند ہوتا، اس خیال سے کہ دوسرے لوگ بھی اس پر (آپ کو دیکھ کر) عمل شروع کر دیں اور اس طرح وہ کام ان پر فرض ہوجائے۔ رسول اللہ ﷺ نے چاشت کی نماز کبھی نہیں پڑھی، لیکن میں پڑھتی ہوں۔", "grade": "Authentic hadith", "gradeAr": "صحيح", "attribution": "Narrated by Bukhari & Muslim", "explanation": "‘Ā’ishah (may Allah be pleased with her) relates that the Prophet (may Allah's peace and blessings be upon him) would give up a deed, even though he liked to perform it, for fear that people would follow him and perform it, and it would thus become obligatory for them, and this might prove difficult for them. Then, she says that the Prophet would not perform the Duha prayer, but the scholars took this negation to refer to lack of regular performance; that is the Prophet would offer it sometimes, for its merit, and abandon it at other times lest it might beccome obligatory for people, as she mentions early in the Hadīth.", "explanationUr": "عائشہ رضی اللہ عنہا ذکر کرتی ہیں کہ نبی ﷺ کسی کام کو ترک فرما دیتے، حالاں کہ آپ ﷺ کو اس کا کرنا پسند ہوتا؛ تا کہ کہیں لوگ اس پر عمل نہ شروع کر دیں، یوں وہ ان پر فرض ہو جائے، پھر اس کی وجہ سے وہ مشقت میں مبتلا ہوں اور اس کو انجام نہ دے سکیں۔ پھر عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ نبی ﷺ چاشت کی نماز نہیں پڑھا کرتے تھے۔ علما نے اس نفی کو مداومت پر محمول کیا ہے۔ یعنی نبی ﷺ اس کی فضیلت کی وجہ سے کبھی اسے پڑھا کرتے تھے اور کبھی اس اندیشے کی تحت چھوڑ دیا کرتے تھے کہ کہیں یہ آپ ﷺ کی امت پر فرض نہ ہو جائے، جیسا کہ حدیث کی ابتدا میں عائشہ رضی اللہ عنہا نے بیان کیا ہے۔", "hints": [], "hintsUr": [], "explanationAr": "تذكر عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يترك العمل وهو يحب أن يفعله، لئلا يعمل به الناس، فيفرض عليهم، فيشق عليهم أو يعجزوا عنه؛ ثم تذكر رضي الله عنها أن النبي صلى الله عليه وسلم لم يكن يصلي صلاة الضُّحى، وحمل العلماء هذا النَّفي على المُدَاومة، أي أنه صلى الله عليه وسلم : كان يصليها في بعض الأوقات، لفضلها ويتركها في بعض الأوقات، خشية أن تفرض على أمَّته، كما ذكرت رضي الله عنها في بداية الحديث.", "hintsAr": ["استحباب صلاة الضحى والمداومة عليها مطلقا.", "بيان كمال شَفقته -صلى الله عليه وسلم- ورأفته بأُمَّته، فإنه يَخشى أن تفرض عليهم الأحكام ويعجزوا عن القيام بها.", "حرص عائشة -رضي الله عنها- على المحافظة على نوافل الطاعات .", "أنه -صلى الله عليه وسلم- لا يعلم الغيب؛ وجه ذلك أن خشيته دليل على عدم علمه بما سيكون.", "أنه إذا تعارضت المصالح قُدِّم أهمها ."], "words": [{"word": "لَيَدَعُ العمل", "meaning": " ليترك العمل."}, {"word": "سُبْحَة", "meaning": " السُّبحة: أي الصلاة، والصلاة تُسمى تسبيحا، قال تعالى: { وَسَبّحْ بِحَمْدِ رَبّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ}،[ق: 39]."}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Aishah"}, {"id": "3373", "number": 36, "title": "Calling others to guidance", "section": 5, "sectionTitle": "A balanced Prophetic path", "slug": "36-calling-others-to-guidance", "ref": "Sahih Muslim 2674", "primary": "https://sunnah.com/muslim:2674", "source": "https://hadeethenc.com/en/browse/hadith/3373", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/3373", "ar": "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الْأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ، لَا يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا، وَمَنْ دَعَا إِلَى ضَلَالَةٍ كَانَ عَلَيْهِ مِنَ الْإِثْمِ مِثْلُ آثَامِ مَنْ تَبِعَهُ، لَا يَنْقُصُ ذَلِكَ مِنْ آثَامِهِمْ شَيْئًا».", "en": "Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever calls to guidance shall receive a reward similar to the rewards obtained by those who followed him without diminishing anything from their rewards. And whoever calls to misguidance shall incur a sin similar to the sins incurred by those who followed him without diminishing anything from their sins.\"", "ur": "ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: \"جس نے کسی ہدایت کی طرف بُلایا، اسے اس کی پیروی کرنے والوں کے اجر کے برابر اجر ملے گا اور اس سے پیروی کرنے والوں کے اجر میں کوئی کمی نہیں ہوگی اور جس نے کسی گمراہی کی طرف بلایا اُس کے اوپر اس کی پیروی کرنے والوں کے برابر گناہ (کا بوجھ) ہوگا اور اس سے ان کے گناہوں میں کوئی کمی نہیں ہوگی۔\"", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "The Prophet (may Allah's peace and blessings be upon him) clarified that whoever guides people, leads them, and urges them, with words or deeds, to adopt a path of truth and goodness will attain a reward similar to that attained by those who followed him without diminishing the followers' reward in any way. On the other hand, whoever guides and leads people, with words or deeds, to a path of falsehood and evil that involves sin, misdeed, or something prohibited will incur guilt and sin similar to those incurred by the ones who followed him without diminishing their sins in any way.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ و سلم  نے بتایا کہ جس نے اپنے قول و عمل کے ذریعے لوگوں کو حق اور خیر کا راستہ دکھایا، اسے اس کے بعد اس راستے پر چلنے والے تمام لوگوں کے برابر اجر و ثواب ملے گا اور اس سے بعد میں چلنے والوں کے اجر و ثواب میں کوئی کٹوتی بھی نہيں ہوگی۔ اس کے برخلاف جس نے اپنے قول و عمل کے ذریعے لوگوں کو کسی برائی، گناہ یا کسی حرام کام کا راستہ دکھایا، اسے بعد میں اس راستے پر چلنے والے تمام لوگوں کے برابر گناہ ہوگا اور اس سے بعد کے لوگوں کے گناہ میں کوئی کمی بھی نہيں ہوگی۔", "hints": ["The merit of calling to guidance, whether little or great, and the fact that the caller obtains a reward similar to that of the doer, and this is out of Allah's great favor and perfect generosity.\r", "The danger of calling to misguidance, whether little or great, and the fact that the caller incurs a sin similar to that of the doer.\r", "Every deed has a recompense of the same kind, so, whoever calls to goodness will obtain a reward similar to that of the doer, and whoever calls to evil will incur a sin similar to that of the doer.\r", "A Muslim must beware of being taken as an example if he commits a sin publicly and people see him, as he will be held sinful because of those who imitate him, even if he does not urge them to do that."], "hintsUr": ["ہدایت کی دعوت دینے کی فضیلت۔ کم ہو یا زیادہ۔ دعوت دینے والے کو عمل کرنے والے کے برابر ثواب ملتا ہے۔ یہ دراصل اللہ کا بہت بڑا فضل و کرم ہے۔\r", "گمراہی کی دعوت دینے کا نقصان۔ گمراہی کم ہو یا زیادہ۔ گمراہی کی دعوت دینے والے کو اس پر عمل کرنے والے کے برابر ثواب ملتا ہے۔\r", "انسان کو اجر و ثواب اسی نوعیت کا ملتا ہے، جس نوعیت کا اس کا عمل ہوتا ہے۔ لہذا جو کسی اچھے کام کی دعوت دے گا، اسے اچھا کام کرنے والے کے برابر ثواب ملے گا اور جو کسی برے کام کی دعوت دے گا، اسے برا کام کرنے والے کے برابر گناہ ہوگا۔\r", "ایک مسلمان کو اس بات سے خبردار رہنا چاہیے کہ لوگوں کے سامنے اس کے کھلے عام گناہ کرنے کی وجہ سے کہیں دوسرے لوگ اسے دیکھ کر وہ گناہ نہ کرنے لگيں۔ کیوں کہ اسے دیکھ کر وہ برا کام کرنے والے دوسرے لوگوں کے گناہ کا بوجھ بھی اسے اٹھانا پڑے گا، چاہے اس نے ان کو ترغیب دی ہو یا نہ دی ہو۔"], "explanationAr": "بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ مَن أَرشَدَ وَدَلَّ وحَضَّ الناسَ على طريقٍ فيه حقٌّ وخيرٌ بقولٍ أو فعلٍ كان له مِثْلُ أجرِ مَن تَبِعَه دون أنْ ينقص ذلك من أجر التابع شيئًا. \nومَن أَرشَدَ ودَلَّ الناسَ إلى طريقِ باطلٍ وشرٍّ فيه ذنب وخطيئة أو أمر لا يَحِلّ، بقول أو فعل، كان عليه مِثْلُ وِزْرِ وإِثمِ مَن تَبِعَه مِن غير أن ينقص ذلك من آثامِهِم شيئًا.", "hintsAr": ["فضل الدعوة إلى الهدى، قليلًا كان أو كثيرًا، وأنَّ الدّاعي له مِثلُ أجر العامل، وذلك من عظيم فضل الله وكمال كرمه.", "خطورة الدعوة إلى الضلال، قليلًا كان أو كثيرًا، وأنّ الداعي عليه مِثل وِزْر العامل.", "الجزاء من جنس العمل، فمن دعا إلى الخير كان له مثل أجر فاعله، ومن دعا إلى الشر كان عليه مثل وزر فاعله.", "على المسلم أن يَحذَرَ مَن أن يُقتَدَى به بمجاهرته بالمعصية والناس يَرونه، فإنه يأثم بِمَن قَلَّدَه ولو لم يَحُثَّه على ذلك."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Hurayrah"}, {"id": "3506", "number": 37, "title": "Setting a beneficial example", "section": 5, "sectionTitle": "A balanced Prophetic path", "slug": "37-setting-a-beneficial-example", "ref": "Sahih Muslim 1017", "primary": "https://sunnah.com/muslim:1017", "source": "https://hadeethenc.com/en/browse/hadith/3506", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/3506", "ar": "عن جرير بن عبد الله رضي الله عنه قال: كُنَّا في صَدرِ النَّهَار عِند رسول الله صلى الله عليه وسلم فَجَاءه قَومٌ عُرَاةٌ مُجْتَابِي النِّمَار أَو العَبَاءِ، مُتَقَلِّدِي السُّيُوف، عَامَّتُهُم مِن مُضَر بَل كُلُّهُم مِن مُضَر، فَتَمَعَّر رسول الله صلى الله عليه وسلم لِمَا رَأَى بِهِم مِنَ الفَاقَة، فدَخَل ثُمَّ خَرج، فأَمَر بِلاَلاً فَأَذَّن وَأَقَام، فَصَلَّى ثُمَّ خَطَب، فقال: «(يا أيها الناس اتقوا ربكم الذي خلقكم من نفس واحدة) إلى آخر (إن الله كان عليكم رقيبًا) ، والآية الأخرى التي في آخر الحشر: (يا أيها الذين آمنوا اتقوا الله ولتنظر نفس ما قدمت لغد) تَصَدَّق رَجُلٌ مِن دِينَارِهِ، مِن دِرهَمِهِ، مِن ثَوبِهِ، مِن صَاعِ بُرِّهِ، مِنْ صَاعِ تَمرِهِ -حتَّى قال- وَلَو بِشِقِّ تَمرَة» فَجَاء رَجُلٌ مِنَ الأَنصَار بِصُرَّةٍ كَادَت كَفُّهُ تَعجَزُ عَنْهَا، بل قَد عَجَزَت، ثُمَّ تَتَابَع النَّاسُ حَتَّى رَأَيتُ كَومَين مِن طَعَامٍ وَثِيَابٍ، حَتَّى رَأَيتُ وَجهَ رَسُول الله صلى الله عليه وسلم يَتَهَلَّلُ كَأَنَّه مُذْهَبَة.ٌ فقال رسول الله صلى الله عليه وسلم : «مَنْ سَنَّ فِي الإِسلاَم سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا، وَأَجْرُ مَنْ عَمِلَ بِهَا بَعْدَهُ، مِنْ غَيرِ أَنْ يَنْقُصَ مِن أُجُورِهِم شَيءٌ، وَمَنْ سَنَّ فِي الإِسلاَم سُنَّةً سَيِّئَةً كَانَ عَلَيه وِزْرُهَا، وَوِزرُ مَنْ عَمِلَ بِهَا مِنْ بعدِه، من غير أن ينقُص مِن أَوزَارِهَم شيء».", "en": "Jābir ibn ‘Abdullāh (may Allah be pleased with him) reported: We were with Messenger of Allah (may Allah's peace and blessings be upon him) shortly after dawn when there came to him some people clad in woolen rags, or covered with sleeveless blankets; and with swords hanging down from their necks. Most of them, rather all of them, belonged to the Mudar tribe. The Prophet's face changed when he saw them starving. Then he went into his house and came out; then he commanded Bilāl to proclaim the Adhān. So he proclaimed the Adhān and recited Iqāmah and the Prophet led the prayer. Then he delivered a sermon saying: (O mankind, fear your Lord, who created you from one soul and created from it its mate and dispersed from both of them many men and women. And fear Allah, through whom you ask one another, and the wombs. Indeed Allah is ever, over you, an Observer) [Sūrat An-Nisā':1]. He also recited a verse at the end of Sūrat al-Hashr: (O you who believe, fear Allah and keep your duty to Him. And let every one look what he has sent forth for the tomorrow.) Thereafter, every man gave in charity dinar, dirham, clothes, measure-fulls of wheat and measure-fulls of dates till he said: \"(Give in charity) be it half a date.\" Then a man from the Ansār came with a bag which was difficult for him to hold in his hand. Thereafter, the people came successively (with charity) till I saw two heaps of food and clothes. I noticed that the Messenger's face was glowing like that of the bright moon or glittering gold. Then he said: \"Whosoever introduces a good practice in Islam, there is for him its reward and the reward of those who act upon it after him without anything being diminished from their rewards. And whosoever introduces an evil practice in Islam will shoulder its sin and the sins of all those who will act upon it, without diminishing in any way their burden.\"", "ur": "جریر بن عبد اللہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم دن کے آغاز میں رسولﷺکے پاس تھے کہ آپﷺکے پاس کچھ ایسے لوگ آئے، جو ننگے بدن تھے، وہ اون کی دھاری دار چادریں یا کمبل ڈالے ہوئے اور گردنوں میں تلوار لٹکائے ہوئے تھے۔ ان کی اکثریت مضر قبیلے سے بلکہ سارے ہی مضر سے تھے۔ جب رسول اللہﷺنے ان کی فاقہ زدگی کا مشاہدہ فرمایا، تو آپ کا چہرہ متغیر ہو گیا۔ آپ (گھر) کے اندر تشریف لے گئے اور باہر آگئے۔ پھر بلال رضی اللہ عنہ کو حکم دیا، انھوں نے اذان دی، (پھر جب لوگ نماز کے لیے جمع ہوگئے تو) تکبیر کہی اور آپﷺنے نماز پڑھائی۔ اس کے بعد لوگوں سے خطاب کرتے ہوئے فرمایا: (لوگو! اپنے اس رب سے ڈرو، جس نے تمھیں ایک جان سے پیدا فرمایا) یہاں سے (یقینا اللہ تمھاری خبر نگہبانی کرنے والا ہے۔)تک۔ (سورۂ نساء:۱) اس کے بعد سورۂ حشر کی آخری آیت پڑھی۔( اے ایمان والو ! اللہ سے ڈرو اور ہر نفس کو چاہیے کہ اس نے کل(قیامت) کے لیے جو آگے بھیجا ہے، اسے دیکھے)۔ ( اس کےبعد آپ نے صدقہ و خیرات کی ترغیب دی) فرمایا: ہر آدمی کو چاہیے کہ صدقہ کرے؛ دینار و درہم کا ، کپڑے کا، گندم کے صاع کا ، کھجور کے صاع کا، حتی کہ فرمایا گرچہ کھجور کا ایک ٹکڑا ہی کیوں نہ ہو۔ چنانچہ انصار میں سے ایک آدمی ایک تھیلی لے کر آیا، (جو اتنی بھاری تھی کہ) اس کی ہتھیلی اس کو اٹھانے سے عاجز آر ہی تھی؛ بلکہ عاجز ہو چکی تھی۔ پھر لوگ ( لے لے کر ) پے در پے آتے رہے، یہاں تک کہ میں نے دو ڈھیر دیکھے؛ ایک کھانے کے سامان کا اور دوسرا کپڑوں کا۔ تب میں نے دیکھا کہ رسول اللہﷺکا چہرۂ انور اس طرح چمک رہا تھا، گو یا سونے کا ٹکڑا ہو۔ پھر رسول اللہﷺنے فرمایا: \"جو شخص اسلام میں کوئي اچھا طریقہ جاری کرے گا، اسے اس کا اجر ملے گا اور اس کے بعد اس پر عمل کرنے والے تمام لوگوں کے برابر اجر ملے گا۔ جب کہ عمل کرنے والوں کے اجر میں کوئی کمی نہیں کی جاۓ گی اور جو اسلام میں کوئی بُرا طریقہ جاری کرے گا، اس پر اس کا گناہ ہوگا اور اس کے بعد اس پر عمل کرنے والے تمام لوگوں کے برابر گناہ ہوگا اور عمل کرنے والوں کے گناہ میں کوئی کمی نہیں کی جاۓ گی۔", "grade": "Authentic hadith", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "This Hadīth shows the Prophet's care and compassion towards his followers. As the Companions were with the Prophet, early in the day, there came a group of people, mostly or entirely from Mudar tribe, wearing very simple clothes, which indicated their poverty, and hanging their swords, a sign of readiness to receive order for Jihād. The Prophet's face changed when he saw their poor state despite belonging to Mudar, one of the noblest Arab tribes. So, he entered home and then went out. He ordered Bilāl to proclaim the Adhān and then he offered the prayer and addressed the people. Praising Allah, the Almighty, as usual, he recited the verses that reads: (O mankind, fear your Lord, who created you from one soul and created from it its mate and dispersed from both of them many men and women. And fear Allah, through whom you ask one another, and the wombs. Indeed Allah is ever, over you, an Observer) [Sūrat An-Nisā':1]; (O you who believe, fear Allah and keep your duty to Him. And let every one look what he has sent forth for the tomorrow. Indeed, Allah is Acquainted with what you do) [Sūrat al-Hashr: 18]. Then, he encouraged the people to give charity, and in response they began to give, and a man would give his dinar in charity, another would give a dirham, and others would give their garment or a Sā‘ of wheat or dates. Then, he encouraged charity even if it were half a date. The Companions (may Allah be pleased with them) were most keen on doing good, rushing and vying towards this. One of them came with a bundle that was almost too heavy for him to carry and placed it in front of the Prophet. Seeing all this goodness and generosity, which would meet the need of those poor people, the Prophet (may Allah's peace and blessings be upon him) was very pleased, and he said: \"Whosoever introduces a good practice in Islam, there is for him its reward and the reward of those who act upon it after him without anything being diminished from their rewards. And whosoever introduces an evil practice in Islam will shoulder its sin and the sins of all those who will act upon it, without diminishing in any way their burden.\" \"A good practice\" here refers to something already established and rooted in the religion, not contrived and added to it.", "explanationUr": "جریر بن عبد اللہ البجلی رضی اللہ عنہ کی یہ حدیث بہت عظیم حدیث ہے، جس سے نبیﷺکی اپنی امت پر شفقت اور مہربانی کا اندازہ ہوتا ہے۔ صحابۂ کرام دن کے ابتدائی حصے میں نبیﷺکے ساتھ بیٹھے تھے کہ اتنے میں کچھ لوگ آئے، جن میں سے اکثر یا سب کے سب مضر قبیلے سے تعلق رکھتے تھے۔ انھوں نے دھاری دار چادریں لپیٹ رکھی تھیں اور اپنی تلواریں لٹکائی ہوئے تھے۔ یعنی ہر انسان کے بدن پر ایک کپڑا تھا، جسے اس نے اپنا ستر چھپانے کے لیے لپیٹ رکھا تھا اور اپنی گردن پر باندھا ہوا تھا۔ ان کے پاس حکم کی بجا آوری کے لیے تلواریں تھیں۔ رضی اللہ عنہم۔\nان کی یہ حالت زار دیکھ کر نبیﷺ کا چہرۂ انور متغیر ہو گیا اور اس کا رنگ بدل گیا۔ یہ لوگ مضر قبیلے سے تھے جو عرب کے معزز ترین قبائل میں سے تھا۔ حاجت مندی کی وجہ سے ان کا یہ حال ہو گیا تھا۔ آپ ﷺ اپنے گھر میں داخل ہوئے اور پھر باہر تشریف لائے۔ پھر آپ ﷺنے بلال رضی اللہ عنہ کو اذان دینے کو کہا۔ لوگوں کو نماز پڑھائی اور پھر انھیں خطبہ دیا۔ آپ ﷺنے اپنی عادت کے مطابق اللہ تعالی کی حمد بیان کی اور پھر اللہ تعالی کا یہ فرمان تلاوت کیا: ﴿يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالاً كَثِيراً وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيباً﴾ (النساء:1) ترجمہ: ”اے لوگو اپنے رب سے ڈرو جس نے تمھیں ایک جان سے پیدا کیا اور اسی جان سے اس کا جوڑا بنایا اور ان دونوں سے بہت سے مرد اور عورتیں پھیلائیں۔ اس اللہ سے ڈرو، جس کا واسطہ دے کر تم ایک دوسرے سے اپنا حق مانگتے ہو اور رشتے داری کے تعلقات کو بگاڑنے سے بچو۔ بے شک الله تم پر نگرانی کر رہا ہے“۔\nاور اللہ تعالی کے اس فرمان کو بھی پڑھا: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ﴾ (الحشر: 18)ترجمہ: ”اے ایمان والو! الله سے ڈرو اور ہر شخص کو دیکھنا چاہیے کہ اس نے کل کے لیے کیا آگے بھیجا ہے اور الله سے ڈرو؛ کیوں کہ الله تمھارے کاموں سے خبردار ہے“۔\nپھر آپ ﷺ نے صدقہ کرنے کی ترغیب دی اور فرمایا: ”ہر آدمی کو چاہیے کہ صدقہ کرے؛ دینار و درہم کا ، کپڑے کا ، گندم کے صاع کا ، کھجور کے صاع کا ، حتی کہ فرمایا گو کھجور کا ایک ٹکڑا ہی ہو“۔\nصحابۂ کرام رضی اللہ عنہم خیر کے کاموں پر بہت زیادہ حریص تھے اور بہت تیزی کے ساتھ اور بڑھ چڑھ کر ان میں حصہ لیا کرتے تھے۔ وہ اپنا اپنا گھر گئے اور صدقے کا سامان لے کر آئے۔ یہاں تک کہ ایک شخص درہموں سے بھرا ایک تھیلا لے کر آیا، جسے اٹھانے میں اسے بہت مشکل ہو رہی تھی، بلکہ وہ اس سے اٹھ ہی نہیں رہا تھا۔ اس نے اسے نبی ﷺ کے سامنے رکھ دیا۔\nراوی حدیث نے کھانے اور کپڑوں وغیرہ کے دو بڑے ڈھیر دیکھے، جو مسجد میں جمع تھے۔ نبیﷺ کا چہرۂ انور جو پہلے متغیر ہو چکا تھا، اب ایسے چمک رہا تھا، جیسے سونا ہو۔ ان فقرا کی حاجت پوری کرنے کے لیے جیسے لوگوں نے بڑھ چڑھ کر حصہ لیا تھا، اس پرخوشی کی وجہ سے آپ ﷺ کے چہرے پر چمک اور روشنی تھی۔ آپ ﷺ نے فرمایا: ”جو شخص اسلام میں کوئي اچھا طریقہ جاری کرے گا، اسے اس کا اجر ملے گا اور اس کے بعد اس پر عمل کرنے والے تمام لوگوں کے برابر اجر ملے گا۔ جب کہ عمل کرنے والوں کے اجر میں کوئی کمی نہیں کی جاۓ گی اور جو اسلام میں کوئی بُرا طریقہ جاری کرے گا، تو اس پر اس کا گناہ ہوگا اور اس کے بعد اس پر عمل کرنے والے تمام لوگوں کے برابر گناہ ہوگا اور عمل کرنے والوں کے گناہ میں کوئی کمی نہیں کی جاۓ گی“۔\nنبی ﷺ کے فرمان: (مَنْ سَنَّ فِي الإِسْلامِ سُنَّةً حَسَنَةً) میں سنت سے مراد یہ ہے کہ جس نے کسی سنت پر عمل کا آغاز کیا۔ اس سے یہ مراد نہیں کہ جس نے کوئی نیا طریقہ ایجاد کیا، کیوں کہ جس نے اسلام میں کوئی نئی شے ایجاد کی، وہ مردود ہوتی ہے نہ کہ اچھی۔ یہاں مراد یہ ہے کہ جس نے سب سے پہلے عمل کا آغاز کیا، جیسے اس آدمی نے کیا تھا، جو تھیلا لے کر آیا تھا۔ رضی اللہ عنہ۔ اس حدیث سے معلوم ہوتا ہے کہ انسان کو جب توفیق ملتی ہے، تو وہ اسلام میں کسی سنت کو فروغ دیتا ہے، چاہے اس میں پہل کرکے ہو یا اسے زندہ کرکے۔", "hints": [], "hintsUr": [], "explanationAr": "حديث جرير بن عبد الله البجلي رضي الله عنه حديث عظيم يتبين منه حرص النبي صلى الله عليه وسلم وشفقته على أمته -صلوات الله وسلامه عليه-، فبينما هم مع رسول الله صلى الله عليه وسلم في أول النهار إذا جاء قوم عامتهم من مضر، أو كلهم من مضر مجتابي النمار، متقلدي السيوف رضي الله عنهم ، يعني أن الإنسان ليس عليه إلا ثوبه قد اجتباه يستر به عورته، وقد ربطه على رقبته، ومعهم السيوف؛ استعداداً لما يؤمرون به من الجهاد رضي الله عنهم .\nفتغيَّر وجه النبي صلى الله عليه وسلم وتلون؛ لما رأى فيهم من الحاجة، وهم من مضر، من أشرف قبائل العرب، وقد بلغت بهم الحاجة إلى هذا الحال، ثم دخل بيته -عليه الصلاة والسلام-، ثم خرج، ثم أمر بلالاً فأذن، ثم صلى، ثم خطب الناس -عليه الصلاة والسلام-، فحمد الله صلى الله عليه وسلم كما هي عادته، ثم قرأ قول الله تعالى : (يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالاً كَثِيراً وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيباً) ، وقوله تعالى : (يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ).\nثم حث على الصدقة، فقال: (تصدق رجل بديناره، وتصدق بدرهمه، تصدق بثوبه، تصدق بصاع بره، تصدق بصاع تمره، حتى ذكر ولو شق تمرة) وكان الصحابة رضي الله عنهم أحرص الناس على الخير، وأسرعهم إليه، وأشدهم مسابقة، فخرجوا إلى بيوتهم فجاءوا بالصدقات، حتى جاء رجل بصرة معه في يده كادت تعجز يده عن حملها، بل قد عجزت من فضة ثم وضعها بين يدي الرسول -عليه الصلاة والسلام-.\nثم رأى جرير كومين من الطعام والثياب وغيرها قد جُمِع في المسجد، فصار وجه النبي -عليه الصلاة والسلام- بعد أن تغيَّر يتهلل كأنه مذهبة؛ يعني من شدة بريقه ولمعانه وسروره -عليه الصلاة والسلام- لما حصل من هذه المسابقة التي فيها سد حاجة هؤلاء الفقراء، ثم قال صلى الله عليه وسلم : (من سن في الإسلام سنة حسنة فله أجرها، وأجر من عمل بها من غير أن ينقص من أجورهم شيء، ومن سن في الإسلام سنة سيئة فعليه وزرها ووزر من عمل بها من غير أن ينقص من أوزارهم شيء).\nوالمراد بالسنة في قوله صلى الله عليه وسلم : (من سن في الإسلام سنة حسنة) ابتدأ العمل بسنة، وليس من أحدث؛ لأن من أحدث في الإسلام ما ليس منه فهو رد وليس بحسن، لكن المراد بمن سنها، أي: صار أول من عمل بها، كهذا الرجل الذي جاء بالصرة رضي الله عنه .", "hintsAr": ["إشفاق النبي -صلى الله عليه وسلم-، وتألمه على الفقراء والمحتاجين.", "من واجب أهل الدثور واليسار أن يتفقدوا أصحاب الحاجة، ويبادروا إلى دفع الضرر عنهم.", "الحث على الصدقة والإنفاق ولو كان بشيء يسير؛ فإنَّ الكثير يكون من القليل.", "حسن توجيه النبي -صلى الله عليه وسلم- وحكمته في توثيق عرى الأخوة والمحبة بين المسلمين، ولفت النظر إلى ضرورة التعاون.", "أثر الإيمان بالله -تعالى- واليوم الآخر في سلوك المسلم والمبادرة إلى فعل الخير.", "سُرعة استجابة المسلمين لهدي الرسول -صلى الله عليه وسلم-، وتسابقهم إلى فعل الخيرات.", "سرور النبي -صلى الله عليه وسلم- لسرور الفقراء، وسعيه لجلب النفع لهم ومساعدتهم.", "الترغيب في فعل السنن التي تركت وهجرت.", "الحض على أن يكون المسلم قدوة صالحة في الخير والبر والإحسان، والتحذير من أن يكون قدوة سيئة في الباطل والمنكر.", "من سعى إلى خير كان له مثل أجر فاعله، ومن سعى في شر كان عليه مثل إثم مرتكبه."], "words": [{"word": "صَدر النَّهَار", "meaning": " أوَّله."}, {"word": "عُرَاةٌ", "meaning": " جمع عار، وهو المتجرِّد من الثياب."}, {"word": "مُجْتَابِي النِّمَار", "meaning": " كِسَاء من صُوف مُخَطَّط."}, {"word": "العَبَاءِ", "meaning": " كساء مشقوق واسع بلا كُمَّين يلبس فوق الثياب."}, {"word": "مُتَقَلِّدِي السُّيُوف", "meaning": " واضعي سيوفهم في أعناقهم."}, {"word": "مُضَر", "meaning": " قبيلة من قبائل العرب."}, {"word": "تَمَعَّر", "meaning": " تغيَّر."}, {"word": "الفّاقَّة", "meaning": " الحاجة والفقر."}, {"word": "اتقوا", "meaning": " التقوى: اسم مأخوذ من الوقاية، وهو أن يتخذ الإنسان ما يقيه من عذاب الله -تعالى-، والذي يقي من عذاب الله هو فعل أوامر الله -عز وجل-، واجتناب نواهيه."}, {"word": "رقِيبًا", "meaning": " حافظا لأعمالكم."}, {"word": "ما قدَّمَت لِغَد", "meaning": " ما أعدَّت من خير ليوم القيامة."}, {"word": "تَصَدَّق", "meaning": " ليتصدَّق."}, {"word": "دِينَارِه", "meaning": " الدينار: عملة نقدية من الذهب ووزنها: 4.25 جرامًا."}, {"word": "دِرهَمِه", "meaning": " الدرهم: قطعة نقدية من الفضة ووزنها: 2.812 جرامًا."}, {"word": "صَاعِ", "meaning": " الصاع: وحدة من وحدات الكيل، ويساوي 2172 جرامًا."}, {"word": "بُرِّه", "meaning": " البُر: القمح."}, {"word": "صُرَّة", "meaning": " ما يجمع فيه الشيء ويشد."}, {"word": "كَومَين", "meaning": " صبرتين."}, {"word": "يَتَهَلَّلُ", "meaning": " يستنير ويضيء."}, {"word": "مُذْهَبَة", "meaning": " كالذهب تعبير عن الصفاء والاستنارة."}, {"word": "سُنَّةٌ", "meaning": " طريقة."}, {"word": "وِزْرُهَا", "meaning": " الوِزر: الحِمل الثقيل والإثم."}], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Jarir ibn Abdullah", "narrator_note": "Narrator correction: the Arabic text, Urdu translation and Sahih Muslim 1017a identify Jarir ibn Abdullah. The publisher English translation says Jabir. That published text is retained unchanged; use Jarir for study and citation."}, {"id": "3395", "number": 38, "title": "Avoiding excess in religion", "section": 5, "sectionTitle": "A balanced Prophetic path", "slug": "38-avoiding-excess-in-religion", "ref": "Sunan Ibn Majah 3029", "primary": "https://sunnah.com/ibnmajah:3029", "source": "https://hadeethenc.com/en/browse/hadith/3395", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/3395", "ar": "عَنْ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَدَاةَ الْعَقَبَةِ وَهُوَ عَلَى نَاقَتِهِ: «الْقُطْ لِي حَصًى» فَلَقَطْتُ لَهُ سَبْعَ حَصَيَاتٍ، هُنَّ حَصَى الْخَذْفِ، فَجَعَلَ يَنْفُضُهُنَّ فِي كَفِّهِ وَيَقُولُ: «أَمْثَالَ هَؤُلَاءِ فَارْمُوا» ثُمَّ قَالَ: «أَيُّهَا النَّاسُ، إِيَّاكُمْ وَالْغُلُوَّ فِي الدِّينِ، فَإِنَّما أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ الْغُلُوُّ فِي الدِّينِ».", "en": "Ibn ‘Abbās (may Allah be pleased with him and his father) reported: On the morning of ‘Aqabah, when the Messenger of Allah (may Allah's peace and blessings be upon him) was atop his she-camel, he said: \"Pick up some pebbles for me.\" So I picked up seven pebbles for him, which were the size of pebbles used for flinging with fingers. He started shaking them in his hand and saying: \"Throw the like of these.\" Then, he said: \"O people, beware of immoderation in religion, for those before you were doomed because of immoderation in religion.\"", "ur": "ابن عباس رضی اللہ عنہما سے مروی ہے، وہ کہتے ہیں: اللہ کے رسول صلی اللہ علیہ وسلم نے عَقَبَہ کی صبح، جب کہ آپ اپنی اونٹنی پر سوار تھے، فرمایا: \"میرے لیے کچھ کنکر چن کر لاؤ۔\" چنانچہ میں نے سات کنکر چن کر پیش کیے، جو چنے کے دانے کے برابر تھے۔ آپ انھیں اپنی ہتھیلی میں رکھ کر جھاڑنے لگے اور کہنے لگے : \"اسی طرح کے کنکر مارا کرو\"۔ پھر فرمایا :  \"لوگو، دین میں غلو سے بچو۔ کیوں کہ دین میں غلو  نے ہی تم سے پہلے کے لوگوں کو ہلاک کیا ہے۔\"", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Ibn Mājah, An-Nasā’i, and Ahmad", "explanation": "Ibn ‘Abbās (may Allah be pleased with him and his father) reports that he was with the Prophet (may Allah's peace and blessings be upon him) on the Day of Nahr, the morning of stoning Jamrat al-‘Aqabah during the Farewell Hajj. He (may Allah's peace and blessings be upon him) ordered him to pick up pebbles for stoning the Jamrahs (stoning pillars), so he picked up seven pebbles for him, each was the size of a chickpea or a hazelnut. The Prophet (may Allah's peace and blessings be upon him) put them in his hand and then moved them and said: Throw pebbles that are equal in size to these ones. The Prophet (may Allah's peace and blessings be upon him), then, warned against immoderation, strictness, and exceeding the limits in religious matters because what destroyed the previous nations were immoderation, exaggeration, and strictness in religious matters.", "explanationUr": "عبداللہ بن عباس رضی اللہ عنہما بتا رہے ہیں کہ وہ حجۃ الوداع کے موقع پر، قربانی کے دن، جمرہ عقبہ میں کنکر مارنے کی صبح اللہ کے نبی صلی اللہ علیہ و سلم کے ساتھ تھے۔ اسی دوران آپ نے ان کو کچھ کنکر چن کر لانے کا حکم دیا۔ چنانچہ انھوں نے سات کنکر چن کر پیش کیے۔ ہر کنکر چنے کے دانے کے برابر تھا۔ اللہ کے نبی صلی اللہ علیہ و سلم نے ان کنکروں کو اپنی ہتھیلی میں رکھ کر ہلایا اور فرمایا : اسی سائز کے پتھر مارا کرو۔ اس کے بعد اللہ کے نبی صلی اللہ علیہ و سلم دینی معاملوں میں غلو و تشدد سے کام لینے اور حد سے آگے بڑھنے سے منع فرمایا۔ کیوں کہ دینی معاملوں میں یہی غلو، حد سے تجاوز، افراط اور انتہا پسندی نے پچھلی امتوں کو ہلاک کیا ہے۔", "hints": ["Prohibiting immoderation in religion and pointing out its bad consequences and the fact that it leads to destruction.\r", "Learning a lesson from the previous nations to avoid the mistakes they had made.\r", "Encouragement of adherence to the Sunnah."], "hintsUr": ["دین میں غلو سے ممانعت، اس کے برے انجام اور اس بات کا بیان کہ دین میں غلو ہلاکت کا سبب ہے۔\r", "پچھلی امتوں سے سرزد ہونے والی غلطیوں سے بچنے کے لیے ان سے عبرت حاصل کرنی چاہيے۔\r", "سنت کی پیروی کرنے کی ترغیب۔"], "explanationAr": "يُخْبِرُ ابنُ عباس رضي الله عنهما أنه كان مع النبيِّ صلى الله عليه وسلم يومَ النحر صباحَ رَمي جمرةِ العقبةِ في حجة الوداع، \nفأمره أن يَلقُط له حصى الجمار، فلقط له سبعَ حصيات، الواحدة منها بحجم الحِمَّص أو البُنْدُق، فوضَعَها النبيُّ صلى الله عليه وسلم في يدِه ثم حَرَّكَها، وقال: \nبمثلِها في الحجم أرموا، \nثم حَذَّر النبيُّ صلى الله عليه وسلم مِن الغُلُوِّ والتشدد ومُجاوَزَةِ الحَدِّ في أمور الدين، فإنما أهلك الأمم السابقة مجاوزة الحد والإفراط والتشدد في الدين.", "hintsAr": ["النهي عن الغلو في الدين، وبيان سوء عاقبته، وأنه سبب للهلاك.", "الاعتبار بمن سبقنا من الأمم لِتَجَنُّبِ ما وقعوا فيه من الأخطاء.", "الحث على الاقتداء بالسُّنّة."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Ibn Abbas"}, {"id": "4801", "number": 39, "title": "Learning together and helping others", "section": 5, "sectionTitle": "A balanced Prophetic path", "slug": "39-learning-together-and-helping-others", "ref": "Sahih Muslim 2699", "primary": "https://sunnah.com/muslim:2699", "source": "https://hadeethenc.com/en/browse/hadith/4801", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/4801", "ar": "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَاللهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ، وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ، وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللهِ يَتْلُونَ كِتَابَ اللهِ وَيَتَدَارَسُونَهُ بَيْنَهُمْ إِلَّا نَزَلَتْ عَلَيْهِمِ السَّكِينَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَحَفَّتْهُمُ الْمَلَائِكَةُ، وَذَكَرَهُمُ اللهُ فِيمَنْ عِنْدَهُ، وَمَنْ بَطَّأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ».", "en": "Abu Hurayrah (may Allah be pleased with him) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever relieves a believer from one of the hardships of this world, Allah will relieve him from one of the hardships of the Day of Judgment. Whoever makes things easy for someone in difficulty, Allah will make things easy for him in this world and the Hereafter. Whoever covers a Muslim, Allah will cover him in this world and the Hereafter. Allah is in the aid of the slave as long as the slave is in the aid of his brother. Whoever treads a path seeking knowledge, Allah will make easy for him a path to Paradise. No group of people gather in one of the houses of Allah, reciting the Book of Allah and studying it among themselves, except that tranquility descends upon them, mercy envelops them, the angels surround them, and Allah mentions them to those near Him. And whoever is slowed down by his deeds will not be hastened forward by his lineage.\"", "ur": "ابو ہریرہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ اللہ کے رسول ﷺ نے فرمایا: ”جس نے کسی مومن کی دنیا کی پریشانیوں میں سے کوئی پریشانی دور کردی، اللہ تعالیٰ بروز قیامت اس کی پریشانیوں میں سے ایک پریشانی دور کردے گا۔ جس نے کسی تنگ دست پر آسانی کی، اللہ اس پر دنیا وآخرت میں آسانی کرے گا۔ جس نے کسی مسلمان کی عیب پوشی کی، اللہ تعالیٰ دنیا و آخرت میں اس کی عیب پوشی فرمائے گا۔ اللہ تعالیٰ بندے کی مدد کرتا رہتا ہے جب تک بندہ اپنے بھائی کی مدد کرتا رہتا ہے۔ جو شخص علم کی تلاش میں کسی راستے پر چلا اللہ تعالیٰ اس كی وجہ سے اس کے لیے جنت کی راہ آسان کردیتا ہے۔ جب کوئی قوم اللہ کے کسی گھر میں جمع ہو کر اللہ کی کتاب کی تلاوت کرتی ہے اور اسے آپس میں پڑھتی پڑھاتی ہے، تو ان پر سکینت کا نزول ہوتا ہے، (اللہ تعالیٰ کی) رحمت ان کو ڈھانپ لیتی ہے اور اللہ اپنے پاس موجود فرشتوں میں ان کا ذکر کرتا ہے۔ اور جس کا عمل اسے پیچھے کردے، اس کا نسب اسے آگے نہیں لے جاسکتا۔“", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "The Prophet (may Allah's peace and blessings be upon him) clarified that the reward a Muslim receives from Allah is of the same nature as the actions he performs for other Muslims. Whoever relieves, alleviates, removes, or eliminates a hardship and a difficulty from a believer in this world, Allah will reward him by relieving him from one of the hardships of the Day of Judgment. And whoever facilitates and makes things easy for someone in difficulty and removes his difficulty, Allah will make it easy for him in this world and the Hereafter. And whoever conceals the faults of a Muslim, such as knowing what should not be exposed of slips and errors, Allah will conceal his faults in this world and the Hereafter. Allah supports His slave as long as the slave supports his brother in his religious and worldly interests. Support could be through supplication, physical action, money, etc. Whoever walks in pursuit of religious knowledge, doing it for the sake of Allah Almighty, Allah will facilitate for him a path to Paradise. No group of people gather in one of the houses of Allah, reciting the Book of Allah and studying it among themselves, except that tranquility and solemnity descend upon them, the mercy of Allah envelops and encompasses them, the angels surround them, and Allah praises them in the presence of those near Him. It is enough of an honor that Allah mentions the slave in the highest assembly. The one whose good deeds are insufficient will not be elevated to the rank of those with righteous deeds. Hence, he should not rely upon his noble lineage and the merit of his forefathers while neglecting the performance of good deeds.", "explanationUr": "اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا کہ اللہ کے نزدیک مسلمان کو اسی نوعیت کا اجر وثواب ملتا ہے، جو وہ دوسرے مسلمانوں کے ساتھ کرتا ہے۔ جس نے کسی مسلمان سے دنیا کی کوئى بھى پریشانی اور سختى دور کى، تو اللہ تعالیٰ بدلے کے طور پر اسے قیامت کے دن کى پریشانیوں اور مشکلات میں سے کسى ایک پریشانی اور سختى سے نجات عطا فرمائے گا۔ جس نے کسی تنگ دست پر آسانی کی، اسے سہولت فراہم کی اور اس کی تنگ دستی کو دور کیا، اللہ دنیا و آخرت میں اس کے لیے آسانی کی راہیں نکالے گا۔ جو شخص کسی مسلمان سے ہونے والی کسی لغزش سے واقف ہو گیا، جس کا شکار اسے نہيں ہونا چاہیے تھا، پھر اس پر پردہ ڈال دیا، تو اللہ دنیا و آخرت میں اس کی لغزشوں پر پردہ ڈالے گا۔ اللہ بندے کی مدد اس وقت تک کرتا رہتا ہے، جب تک بندہ اپنے بھائی کے دینی و دنیوی کاموں میں اس کی مدد کرنے کی راہ پر گام زن رہتا ہے۔ واضح رہے کہ یہ مدد دعا کے ذریعے بھی ہو سکتی ہے، بدن کے ذریعے بھی ہو سکتی ہے اور مال وغیرہ کے ذریعے بھی۔ جو شخص اللہ کی رضا جوئی کی خاطر علم شرعی کی تلاش میں چل پڑا، اس کے بدلے میں اللہ اس کے لیے جنت کا راستہ آسان کر دیتا ہے۔ جب کچھ لوگ اللہ کے کسی گھر میں جمع ہوتے ہيں، اللہ کی کتاب کی تلاوت کرتے ہیں اور اسے آپس میں پڑھتے پڑھاتے ہيں، تو ان پر وقار و اطمینان کی بارش ہوتی ہے، ان کو اللہ کی رحمت اپنے سایے میں لے لیتی ہے، فرشتے انھیں گھیر لیتے ہيں اور اللہ اپنے مقرب فرشتوں کے سامنے ان کی تعریف کرتا ہے۔ کتنے خوش نصیب ہیں وہ لوگ جن کا ذکر اللہ اپنے مقرب فرشتوں میں کر دے۔ جس کا عمل ناقص ہو، اس کا نسب اسے سرگرم عمل رہنے والے لوگوں کے مرتبے تک پہنچا نہیں سکتا۔ لہذا انسان کو اپنے اونچے حسب نسب اور آبا و اجداد کے فضل و شرف پر بھروسہ کر کے عمل کے میدان میں کوتاہی نہیں کرنی چاہیے۔", "hints": ["Ibn Daqīq al-‘Īd said: This is a great Hadīth, comprising various types of knowledge, rules, and etiquettes. It highlights the merit of fulfilling the needs of Muslims and benefiting them in whatever way is possible, whether through knowledge, wealth, assistance, offering useful advice, giving counsel, or other means.\r", "Encouraging the act of making things easy for the one in difficulty.\r", "A Muslim is encouraged to help other Muslims, as Allah Almighty helps the one who helps his brother in proportion to his help.\r", "Among the ways of concealing a Muslim’s faults is: to refrain from seeking out his shortcomings. One of the predecessors is reported to have said: I met people who had no faults, yet they spoke about the faults of others, so people started mentioning their faults. And I met people who had faults but refrained from mentioning the faults of others, so their faults were forgotten.\r", "It is not a requirement of concealing the faults of others to neglect the prohibition of evil and not to change it. Rather, it should be changed and concealed at the same time, and this applies to those who are not known for corruption or persistence in transgression. As for one who is known for such behavior, it is not recommended to conceal his faults; instead, his affair should be referred to those in authority, provided that this does not lead to greater harm. This is because concealing his faults encourages him in his corruption and emboldens him to harm others, as well as emboldening others from among the wicked and stubborn.\r", "Encouraging the act of seeking knowledge, reciting, and studying the Qur’an.\r", "An-Nawawi said: This is evidence of the merit of gathering to recite the Quran in the mosque... and similar gatherings in a school, a garrison, or the like also attain this merit, Allah willing.\r", "Allah has made the recompense contingent upon deeds, not upon lineages."], "hintsUr": ["ابن دقیق العید کہتے ہیں : یہ حدیث مختلف طرح کے علوم، قواعد اور آداب پر مشتمل ایک عظیم ترین حدیث ہے۔ اس میں مسلمانوں کی ضرورتیں پوری کرنے اور انھیں اپنے علم، مال، تعاون، مشورہ یا خیرخواہی وغیرہ سے مستفید کرنے کی فضیلت بیان کی گئی ہے۔\r", "تنگ دست انسان کے ساتھ آسانی کرنے کی ترغیب دی گئی ہے۔\r", "مسلم بندہ کی مدد کرنے پر ابھارا گیا ہے، کیوں کہ بندہ جس قدر اپنے بھائی کی مدد کرتا ہے، اسی قدر اللہ تعالی بھی اس کی مدد کرتا ہے۔\r", "مسلمان کی پردہ پوشی کے اندر اس کی کمیوں کی کھوج بین نہ کرنا بھی شامل ہے۔ کسی سلف نے کہا : میں نے کچھ لوگوں کو پایا جن کے عیوب نہيں تھے، لیکن جب انھوں نے لوگوں کے عیوب کا چرچا کرنا شروع کر دیا، تو لوگوں نے بھی ان کے عیوب کا ذکر کرنا شروع کر دیا۔ اس کے برخلاف میں نے کچھ لوگوں کو پایا، جن کے عیوب تھے، لیکن انھوں نے لوگوں کے عیوب کا ذکر نہيں کیا، تو ان کے عیوب بھلا دیے گئے۔\r", "پردہ پوشی کا مطلب یہ نہیں ہے کہ برائی کو ہونے دیا جائے اور اس کی نکیر کرنا چھوڑ دیا جائے۔ بلکہ برائی کی نکیر بھی کی جائے گی اور پردہ پوشی سے بھی کام لیا جائے گا۔ دراصل پردہ پوشی ایسے شخص کی کرنی ہے، جو برائی اور سرکشی میں معروف نہ ہو۔ جو برائی اور سرکشی میں معروف ہو چکا ہو، اس کا معاملہ حکومتی اہل کاروں تک پہنچا دیا جائے گا۔ بہ شرط یہ کہ اس سے کوئی دوسری برائی جنم لینے کا اندیشہ نہ ہو۔ کیوں کہ اس طرح کے شخص کی پردہ پوشی اس کی حوصلہ افزائی کرے گی، اسے بندوں کو تکلیف دینے پر آمادہ کرے گی اور دوسرے برائی کرنے والوں کو جری بنائے گی۔\r", "طلب علم، تلاوت قرآن اور قرآن کا دور کرنے کی ترغیب۔\r", "نووی کہتے ہیں : اس حدیث میں قرآن کریم کی تلاوت کے لیے مسجد میں یکجا ہونے کی دلیل موجود ہے۔ اس فضیلت کے حصول میں مدرسہ اور رباط وغیرہ میں جمع ہونے کو مسجد میں جمع ہونے کے زمرے میں رکھا جائے گا۔\r", "جزا و ثواب اعمال کی بنیاد پر ملتا ہے۔ حسب نسب کی بنیاد پر نہیں۔"], "explanationAr": "بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ جَزاء المسلم عند الله مِن جِنْس ما يَعمله المسلم مع المسلمين؛ فمَن نفَّس وفرَّج وأزال وكَشَفَ عن مؤمنٍ كُربةً وشدة من كُرَب الدنيا، جازاه الله بأن ينفَّس عنه كربةً من كرب يوم القيامة.\n\nومَن يَسَّر على معسرٍ وسهَّل عليه وأزال عسرته، يسَّر الله عليه في الدنيا والآخرة. \n\nومَن ستر مسلمًا كأن اطّلع منه على ما لا ينبغي إظهاره من الزّلات والعَثَرات، ستره الله في الدنيا والآخرة. \n\nوالله يكون مُعينًا لِعَبدِه، ما كان العبد سائرًا في إعانة أخيه في مصالحه الدينية والدنيوية، والإعانة تكون بالدعاء والبدن والمال وغير ذلك. \n\nومن مشى إلى تحصيل علمٍ شرعيٍ، قاصدًا به وجه الله تعالى؛ سهَّل الله له به طريقًا إلى الجنة. \n\nوما اجتمع قومٌ في بيتٍ من بيوت الله، يتلون كتاب الله ويتدارسونه بينهم، إلا نزلت عليهم الطمأنينة والوقار، وغطتهم وعمَّتهم رحمة الله، وحفَّتْهم الملائكة، وأثنى الله عليهم في المقرَّبين عنده، وكفى شرفًا ذِكرُ اللهِ العبدَ في الملأ الأعلى. \n\nومَن كان عمله ناقصًا، لم يُلْحِقْه بمرتبة أصحاب الأعمال، فينبغي ألا يَتَّكل على شرف النسب وفضيلة الآباء ويُقَصّر في العمل.", "hintsAr": ["قال ابن دقيق العيد: هذا حديث عظيم، جامع لأنواع من العلوم والقواعد والآداب، فيه فضل قضاء حوائج المسلمين ونفعهم بما يتيسر، مِن علم، أو مال، أو معاونة، أو إشارة بمصلحة، أو نصيحة، أو غير ذلك.", "الترغيب في التيسير على المعسر.", "الحث على عون العبد المسلم، وأن الله تعالى يُعين المعين حسب إعانته لأخيه.", "مِن سِتْر المسلم: عدمُ تتبُّع عوراته، وقد رُوي عن بعض السلف أنه قال: أدركت قومًا لم يكن لهم عيوب، فذكروا عيوبَ الناس، فَذَكَر الناسُ لهم عيوبًا، وأدركت قومًا كانت لهم عيوب، فَكَفُّوا عن عيوب الناس، فنُسِيت عيوبُهم.", "ليس من لوازم الستر على الناس ترك المنكر وعدم تغييره، بل يُغَيِّر ويَسْتُر، وهذا في حقِّ مَن لا يُعرَف بالفساد والتَّمَادِيْ في الطغيان، وأما من عُرِف بذلك فإنه لا يُستحب الستر عليه، بل يرفع أمره إلى مَن له الولاية، إذا لم يخَفْ مِن ذلك مفسدة؛ وذلك لأن الستر عليه يُغْرِيْهِ على الفساد، ويُجَرِّئهُ على أذية العباد، ويُجرّئ غيره من أهل الشر والعناد.", "الحث على طلب العلم وتلاوة القرآن وتدارسه.", "قال النووي: في هذا دليل لفضل الاجتماع على تلاوة القرآن في المسجد... ويلحق بالمسجد في تحصيل هذه الفضيلة الاجتماع في مدرسة ورباط ونحوهما إن شاء الله تعالى.", "الجزاء إنما رتَّبَه الله على الأعمال لا على الأنساب."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Hurayrah"}, {"id": "66272", "number": 40, "title": "Sent as a mercy", "section": 5, "sectionTitle": "A balanced Prophetic path", "slug": "40-sent-as-a-mercy", "ref": "Sahih Muslim 2599", "primary": "https://sunnah.com/muslim:2599", "source": "https://hadeethenc.com/en/browse/hadith/66272", "sourceUr": "https://hadeethenc.com/ur/browse/hadith/66272", "ar": "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قِيلَ: يَا رَسُولَ اللهِ ادْعُ عَلَى المُشْرِكِينَ قَالَ: «إِنِّي لَمْ أُبْعَثْ لَعَّانًا، وَإِنَّمَا بُعِثْتُ رَحْمَةً».", "en": "Abu Hurayrah (may Allah be pleased with him) reported: It was said: O Messenger of Allah, supplicate against the polytheists. He said: \"I have not been sent as an invoker of curses; rather, I have been sent as a mercy.\"", "ur": "ابوہریرہ رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں : کہا گیا: اے اللہ کے رسول ﷺ! مشرکوں پر بد دعا کردیں، تو آپ ﷺ نے فرمایا: \"مجھے لعنت کرنے والا بنا کر نہيں بھیجا گیا ہے۔ مجھے تو رحمت بنا کر بھیجا گیا ہے\"۔", "grade": "Authentic", "gradeAr": "صحيح", "attribution": "Narrated by Muslim", "explanation": "The Prophet (ﷺ) was asked to supplicate against those who associated partners with Allah, but he said: I was not sent by Allah as one who curses—invoking exclusion and expulsion from His mercy and cutting people off from good. I was not sent for that; rather, I was sent to be a source of goodness and mercy for all people, especially for the believers.", "explanationUr": "نبی ﷺ سے مشرکوں کے حق میں بد دعا کرنے کے لیے کہا گیا، تو آپ ﷺ نے فرمایا: مجھے اللہ کی طرف سے لعنت کرنے والا بنا کر نہیں بھیجا گیا کہ میں لوگوں کو بد دعا دوں اور انہیں اللہ کی رحمت سے دھتکار کر خیر سے محروم کر دوں۔ مجھے اس مقصد کے لیے مبعوث نہیں کیا گیا، بلکہ مجھے تو تمام لوگوں کے لیے بالعموم، اور مومنوں کے لیے بالخصوص، خیر ورحمت کا سبب بنا کر بھیجا گیا ہے۔", "hints": ["The perfection of the Prophet's (ﷺ) character.\r", "The importance of keeping one's tongue pure from swearing and cursing, following the example of the Prophet (ﷺ).\r", "It indicates the prohibition of cursing.\r", "Encouragement to show mercy to people."], "hintsUr": ["آپ ﷺ کا کمالِ اخلاق۔\r", "نبی ﷺ کی اقتدا میں زبان کو گالی گلوچ اور لعن طعن سے پاک رکھنے کی اہمیت۔\r", "لعنت کرنے کی ممانعت۔\r", "لوگوں پر رحم کرنے کی ترغیب۔"], "explanationAr": "طُلب من النبي صلى الله عليه وسلم أن يدعوَ على المشركين بالله، فقال: إني لم أبعث من الله وأُرسل لعانًا أدعو على الناس بالإبعاد والطرد من رحمة الله فأقطعهم عن الخير، إني لم أبعث لهذا، وإنما بُعثتُ لأكون سبب خير ورحمة للناس عامة، وللمؤمنين خاصة.", "hintsAr": ["كمال خلقه صلى الله عليه وسلم.", "أهمية تنزيه اللسان من السباب واللعن اقتداءً بالنبي صلى الله عليه وسلم.", "فيه النهي عن اللعن.", "الحث على الرحمة بالناس."], "words": [], "publisher": "HadeethEnc.com", "retrieved": "2026-10-17", "narrator": "Abu Hurayrah"}];window.SECTIONS=[{"title": "Receiving revelation", "subtitle": "How revelation came and was preserved", "icon": "spark"}, {"title": "Following the Messenger", "subtitle": "Authority, obedience and the Prophetic way", "icon": "shield"}, {"title": "Learning and transmission", "subtitle": "Understand carefully and transmit faithfully", "icon": "book"}, {"title": "Living by the Quran", "subtitle": "Learn, retain and respond to revelation", "icon": "leaf"}, {"title": "A balanced Prophetic path", "subtitle": "Mercy, moderation and beneficial example", "icon": "heart"}];window.LEARNING_DATA={"65050": {"revision": "topic001-coverage-2026-10-17", "narrator": "Ibn Abbas", "qa": [{"id": "65050-focus-qa-1", "group": "Meaning and understanding", "q": "How does this report place revelation and migration within the Prophet's life?", "a": "Revelation began when he was forty. He then spent thirteen years in Makkah, migrated by command, and lived ten years in Madinah. The explanation gives his age at death as sixty-three.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65050", "evidence": {"label": "Published explanation", "text": "Then, he (may Allah's peace and blessings be upon him) passed away at the age of sixty-three.", "url": "https://hadeethenc.com/en/browse/hadith/65050", "anchor": "age of sixty-three", "field": "E"}}], "mcq": [{"id": "65050-focus-mc-1", "q": "Which sequence matches the report?", "options": ["Migration, ten Makkan years, revelation, thirteen Madinan years", "Revelation, thirteen Makkan years, migration, ten Madinan years", "Revelation, ten Makkan years, migration, thirteen Madinan years", "Thirteen Madinan years, migration, revelation, ten Makkan years"], "correct": 1, "feedback": ["The supported answer is: Revelation, thirteen Makkan years, migration, ten Madinan years. The narration places the migration between the thirteen-year Makkan mission and the ten-year Madinan period.", "The narration places the migration between the thirteen-year Makkan mission and the ten-year Madinan period.", "The supported answer is: Revelation, thirteen Makkan years, migration, ten Madinan years. The narration places the migration between the thirteen-year Makkan mission and the ten-year Madinan period.", "The supported answer is: Revelation, thirteen Makkan years, migration, ten Madinan years. The narration places the migration between the thirteen-year Makkan mission and the ten-year Madinan period."], "hint": "Identify the event separating the two city periods.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65050", "evidence": {"label": "Published English selection", "text": "Then, he was commanded to immigrate, and he immigrated to Madīnah, where he stayed for 10 years.", "url": "https://hadeethenc.com/en/browse/hadith/65050", "anchor": "commanded to immigrate", "field": "T"}}, {"id": "65050-focus-mc-2", "q": "Which age at death follows the chronology explained by the publisher?", "options": ["Sixty-three", "Fifty-three", "Sixty", "Seventy-three"], "correct": 0, "feedback": ["The explanation places the start at forty, followed by thirteen Makkan years and ten Madinan years.", "The supported answer is: Sixty-three. The explanation places the start at forty, followed by thirteen Makkan years and ten Madinan years.", "The supported answer is: Sixty-three. The explanation places the start at forty, followed by thirteen Makkan years and ten Madinan years.", "The supported answer is: Sixty-three. The explanation places the start at forty, followed by thirteen Makkan years and ten Madinan years."], "hint": "Keep the age at the beginning distinct from the lengths of the two periods.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65050", "evidence": {"label": "Published explanation", "text": "Then, he (may Allah's peace and blessings be upon him) passed away at the age of sixty-three.", "url": "https://hadeethenc.com/en/browse/hadith/65050", "anchor": "sixty-three", "field": "E"}}], "coverage": {"focusedAnswers": 1, "thematicQuestions": 2, "completeSanadProvided": false, "topics": [{"point": "Age at first revelation and the lengths of the Makkan and Madinan periods", "qa": [1], "mcq": [1, 2]}, {"point": "Migration by command and the sequence ending in his death", "qa": [1], "mcq": [1, 2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/65050"}, "66304": {"revision": "topic001-coverage-2026-10-17", "narrator": "Jabir ibn Abdullah", "qa": [{"id": "66304-focus-qa-1", "group": "Meaning and understanding", "q": "Was al-Muddaththir the beginning of all revelation, or the renewal after its pause?", "a": "This account concerns revelation after a pause. The publisher places the initial command to read before that pause and the opening of al-Muddaththir after it. The angel was the same one who had previously come at Hira. Keeping that sequence clear prevents confusing the two occasions.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66304", "evidence": {"label": "Published benefit 1", "text": "The revelation to the Prophet (ﷺ) ceased for a short period after the descent of Allah's word: {Read}.", "url": "https://hadeethenc.com/en/browse/hadith/66304", "anchor": "ceased for a short period", "field": "B1"}}, {"id": "66304-focus-qa-2", "group": "Meaning and understanding", "q": "What responsibilities accompany the command to arise and warn?", "a": "The explanation joins calling people to the message with proclaiming Allah's greatness, purifying garments, and abandoning idol worship. The passage moves from being covered after fear to carrying the responsibility of proclamation. It describes duties, not merely an emotional experience.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66304", "evidence": {"label": "Published explanation", "text": "So Allah Almighty revealed: {O you covered} in your cloak, {arise} to call people to the message, {and warn} those who have not yet believed in your message.", "url": "https://hadeethenc.com/en/browse/hadith/66304", "anchor": "call people to the message", "field": "E"}}, {"id": "66304-focus-qa-3", "group": "Meaning and understanding", "q": "What does the account show about fear and receiving the command to proclaim the message?", "a": "The Prophet describes being terrified and asking to be covered. The command to arise and warn follows that experience, and revelation then becomes continuous. The account does not present the initial fear as refusal to carry the message.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66304", "evidence": {"label": "Published English selection", "text": "I was terrified of him, so I returned and said: Cover me!", "url": "https://hadeethenc.com/en/browse/hadith/66304", "anchor": "I was terrified", "field": "T"}}, {"id": "66304-focus-qa-4", "group": "Meaning and understanding", "q": "Which practical aspect of purification does the publisher identify?", "a": "The explanation speaks of cleaning garments from impurities, and the sixth benefit connects the verse with purifying clothes for prayer. This is a practical instruction alongside proclaiming Allah's greatness and rejecting idol worship.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66304", "evidence": {"label": "Published benefit 6", "text": "The obligation to purify one's clothes for prayer, as inferred from Allah's saying: {And purify your garments}.", "url": "https://hadeethenc.com/en/browse/hadith/66304", "anchor": "purify", "field": "B6"}}], "mcq": [{"id": "66304-focus-mc-1", "q": "What duty is conveyed by the command to arise and warn?", "options": ["Keep the message within the household", "Wait for public approval before proclaiming it", "Limit the message to those already believing", "Proclaim the message and warn those who reject it"], "correct": 3, "feedback": ["The supported answer is: Proclaim the message and warn those who reject it. The explanation connects arising with calling people to the message, not withdrawing from it.", "The supported answer is: Proclaim the message and warn those who reject it. The explanation connects arising with calling people to the message, not withdrawing from it.", "The supported answer is: Proclaim the message and warn those who reject it. The explanation connects arising with calling people to the message, not withdrawing from it.", "The explanation connects arising with calling people to the message, not withdrawing from it."], "hint": "Read how the explanation expands the command to arise.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66304", "evidence": {"label": "Published explanation", "text": "So Allah Almighty revealed: {O you covered} in your cloak, {arise} to call people to the message, {and warn} those who have not yet believed in your message.", "url": "https://hadeethenc.com/en/browse/hadith/66304", "anchor": "call people to the message", "field": "E"}}, {"id": "66304-focus-mc-2", "q": "What does the source distinguish about the opening of al-Muddaththir?", "options": ["It preceded the first revelation at Hira", "It was first revealed after the migration", "It marked the end of all revelation", "It followed the initial revelation and its pause"], "correct": 3, "feedback": ["The supported answer is: It followed the initial revelation and its pause. The benefits place this passage after the initial command to read and the pause in revelation.", "The supported answer is: It followed the initial revelation and its pause. The benefits place this passage after the initial command to read and the pause in revelation.", "The supported answer is: It followed the initial revelation and its pause. The benefits place this passage after the initial command to read and the pause in revelation.", "The benefits place this passage after the initial command to read and the pause in revelation."], "hint": "Separate the first revelation from the first passage after the pause.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66304", "evidence": {"label": "Published benefit 1", "text": "The revelation to the Prophet (ﷺ) ceased for a short period after the descent of Allah's word: {Read}.", "url": "https://hadeethenc.com/en/browse/hadith/66304", "anchor": "ceased for a short period", "field": "B1"}}, {"id": "66304-focus-mc-3", "q": "Which action belongs to the explanation of purifying garments?", "options": ["Seeking public praise through clothing", "Cleaning clothing from impurities", "Replacing proclamation with attention to appearance", "Treating idol worship as a form of purification"], "correct": 1, "feedback": ["The supported answer is: Cleaning clothing from impurities. The explanation explicitly interprets the instruction in relation to clean garments, alongside the other duties.", "The explanation explicitly interprets the instruction in relation to clean garments, alongside the other duties.", "The supported answer is: Cleaning clothing from impurities. The explanation explicitly interprets the instruction in relation to clean garments, alongside the other duties.", "The supported answer is: Cleaning clothing from impurities. The explanation explicitly interprets the instruction in relation to clean garments, alongside the other duties."], "hint": "Read the practical explanation of the command about garments.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66304", "evidence": {"label": "Published explanation", "text": "{And your garments} and clothes {purify them} and clean them from impurities.", "url": "https://hadeethenc.com/en/browse/hadith/66304", "anchor": "impurities", "field": "E"}}, {"id": "66304-focus-mc-4", "q": "What change in revelation follows the events described in this account?", "options": ["It ends permanently at that moment", "It becomes strong and continuous", "It is postponed until the migration", "It is replaced by the companions' personal judgments"], "correct": 1, "feedback": ["The supported answer is: It becomes strong and continuous. The account ends by describing the continuing flow of revelation after the command to arise.", "The account ends by describing the continuing flow of revelation after the command to arise.", "The supported answer is: It becomes strong and continuous. The account ends by describing the continuing flow of revelation after the command to arise.", "The supported answer is: It becomes strong and continuous. The account ends by describing the continuing flow of revelation after the command to arise."], "hint": "Follow the report to its closing sentence.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66304", "evidence": {"label": "Published English selection", "text": "Then Allah Almighty revealed: {O you covered [in your cloak], arise and warn} [Surat al-Muddaththir: 1-2] until His saying: {and shun idol worshiping.} [Surat al-Muddaththir: 5] After that, the revelation became intense and continuous.\"", "url": "https://hadeethenc.com/en/browse/hadith/66304", "anchor": "intense and continuous", "field": "T"}}], "coverage": {"focusedAnswers": 4, "thematicQuestions": 4, "completeSanadProvided": false, "topics": [{"point": "Renewal after the pause, distinguished from the first revelation", "qa": [1], "mcq": [2]}, {"point": "The angel at Hira, the Prophet's fear and the command to arise", "qa": [1, 3], "mcq": [1]}, {"point": "Proclamation, glorifying Allah and abandoning idol worship", "qa": [2], "mcq": [1]}, {"point": "Purification of garments and the prayer-related benefit", "qa": [4], "mcq": [3]}, {"point": "Revelation becoming continuous after the renewed call", "qa": [1, 3], "mcq": [4]}]}, "source": "https://hadeethenc.com/en/browse/hadith/66304"}, "10840": {"revision": "topic001-coverage-2026-10-17", "narrator": "Aishah", "qa": [{"id": "10840-focus-qa-1", "group": "Meaning and understanding", "q": "What do the two forms of revelation show about receiving and retaining it?", "a": "The Prophet describes a bell-like experience and the angel appearing as a man and speaking. The first was harder, yet he retained what had been conveyed; in the second, he understood the angel's speech. The account distinguishes the manner of reception from the certainty of retaining the message.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10840", "evidence": {"label": "Published English selection", "text": "When it leaves me I remember what it has said.", "url": "https://hadeethenc.com/en/browse/hadith/10840", "anchor": "I remember what it has said", "field": "T"}}, {"id": "10840-focus-qa-2", "group": "Meaning and understanding", "q": "Why does Aishah mention sweat on a very cold day?", "a": "The contrast makes the physical burden of revelation clear: the sweating was observed despite the cold. Her eyewitness detail complements the Prophet's own description of the difficult experience. The source relates the bodily effect to receiving revelation, not to uncertainty about its wording.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10840", "evidence": {"label": "Published English selection", "text": "When it had left him, his forehead was dripping with sweat.\"", "url": "https://hadeethenc.com/en/browse/hadith/10840", "anchor": "forehead was dripping", "field": "T"}}, {"id": "10840-focus-qa-3", "group": "Meaning and understanding", "q": "Who asks about revelation, and who supplies the eyewitness observation?", "a": "Al-Harith ibn Hisham asks the Prophet how revelation comes. Aishah narrates that exchange and adds her observation of his forehead sweating on a cold day. Distinguishing the questioner from the narrator preserves the account's attribution.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10840", "evidence": {"label": "Published English selection", "text": "‘Ā'ishah (may Allah be pleased with her) reported: Al-Hārith ibn Hishām (may Allah be pleased with him) asked the Messenger of Allah (may Allah's peace and blessings be upon him): \"O Messenger of Allah, how does the revelation come to you?\" The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Sometimes it comes to me like the ringing of a bell, and that is the hardest for me.", "url": "https://hadeethenc.com/en/browse/hadith/10840", "anchor": "Al-Hārith", "field": "T"}}], "mcq": [{"id": "10840-focus-mc-1", "q": "Which comparison describes the more difficult form of revelation?", "options": ["An angel speaking in human form", "A conversation with al-Harith", "A sound like the ringing of a bell", "A written message handed to Aishah"], "correct": 2, "feedback": ["The supported answer is: A sound like the ringing of a bell. The Prophet identifies the bell-like form as the hardest of the forms described.", "The supported answer is: A sound like the ringing of a bell. The Prophet identifies the bell-like form as the hardest of the forms described.", "The Prophet identifies the bell-like form as the hardest of the forms described.", "The supported answer is: A sound like the ringing of a bell. The Prophet identifies the bell-like form as the hardest of the forms described."], "hint": "Notice which form he explicitly calls hardest.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10840", "evidence": {"label": "Published English selection", "text": "‘Ā'ishah (may Allah be pleased with her) reported: Al-Hārith ibn Hishām (may Allah be pleased with him) asked the Messenger of Allah (may Allah's peace and blessings be upon him): \"O Messenger of Allah, how does the revelation come to you?\" The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Sometimes it comes to me like the ringing of a bell, and that is the hardest for me.", "url": "https://hadeethenc.com/en/browse/hadith/10840", "anchor": "ringing of a bell", "field": "T"}}, {"id": "10840-focus-mc-2", "q": "What followed the end of that difficult experience?", "options": ["He needed the listeners to reconstruct it", "He understood only its general subject", "He retained what had been conveyed", "He waited for a second delivery to remember it"], "correct": 2, "feedback": ["The supported answer is: He retained what had been conveyed. The narration affirms retention after the experience; its difficulty did not prevent understanding.", "The supported answer is: He retained what had been conveyed. The narration affirms retention after the experience; its difficulty did not prevent understanding.", "The narration affirms retention after the experience; its difficulty did not prevent understanding.", "The supported answer is: He retained what had been conveyed. The narration affirms retention after the experience; its difficulty did not prevent understanding."], "hint": "Read the statement about what happened when it left him.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10840", "evidence": {"label": "Published English selection", "text": "When it leaves me I remember what it has said.", "url": "https://hadeethenc.com/en/browse/hadith/10840", "anchor": "I remember what it has said", "field": "T"}}, {"id": "10840-focus-mc-3", "q": "How is the experience in which the angel appears as a man described?", "options": ["The Prophet reconstructs the message from others afterward", "The angel speaks and the Prophet understands him", "The angel remains silent and communicates no wording", "The questioning companion supplies the revelation"], "correct": 1, "feedback": ["The supported answer is: The angel speaks and the Prophet understands him. The second form is described as speech understood by the Prophet.", "The second form is described as speech understood by the Prophet.", "The supported answer is: The angel speaks and the Prophet understands him. The second form is described as speech understood by the Prophet.", "The supported answer is: The angel speaks and the Prophet understands him. The second form is described as speech understood by the Prophet."], "hint": "Separate the two modes of reception in the report.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10840", "evidence": {"label": "Published English selection", "text": "And sometimes the angel appears to me in the shape of a man, he talks to me, and I understand what he says.\" ‘Ā'ishah (may Allah be pleased with her) said: \"I saw him when the revelation was descending upon him on a very cold day.", "url": "https://hadeethenc.com/en/browse/hadith/10840", "anchor": "shape of a man", "field": "T"}}, {"id": "10840-focus-mc-4", "q": "What makes Aishah's observation of sweating particularly striking?", "options": ["It occurs during a journey through summer heat", "It occurs on a very cold day", "It follows strenuous agricultural work", "It is described only as a later conjecture"], "correct": 1, "feedback": ["The supported answer is: It occurs on a very cold day. The cold-day setting makes the bodily strain observable without attributing it to heat.", "The cold-day setting makes the bodily strain observable without attributing it to heat.", "The supported answer is: It occurs on a very cold day. The cold-day setting makes the bodily strain observable without attributing it to heat.", "The supported answer is: It occurs on a very cold day. The cold-day setting makes the bodily strain observable without attributing it to heat."], "hint": "Notice the contrast between the weather and the physical effect.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10840", "evidence": {"label": "Published English selection", "text": "And sometimes the angel appears to me in the shape of a man, he talks to me, and I understand what he says.\" ‘Ā'ishah (may Allah be pleased with her) said: \"I saw him when the revelation was descending upon him on a very cold day.", "url": "https://hadeethenc.com/en/browse/hadith/10840", "anchor": "very cold day", "field": "T"}}], "coverage": {"focusedAnswers": 3, "thematicQuestions": 4, "completeSanadProvided": false, "topics": [{"point": "Two modes of reception: bell-like sound and the angel in human form", "qa": [1], "mcq": [1, 3]}, {"point": "Difficulty of reception without loss of the conveyed message", "qa": [1], "mcq": [2]}, {"point": "Aishah's cold-day observation and the physical burden", "qa": [2], "mcq": [4]}, {"point": "Al-Harith as questioner and Aishah as narrator and observer", "qa": [3], "mcq": [3, 4]}]}, "source": "https://hadeethenc.com/en/browse/hadith/10840"}, "10841": {"revision": "topic001-coverage-2026-10-17", "narrator": "Ubadah ibn al-Samit", "qa": [{"id": "10841-focus-qa-1", "group": "Meaning and understanding", "q": "How does the explanation connect the Prophet's visible distress with his response to revelation?", "a": "Ubadah observed distress and a change in facial color. The explanation relates these effects to the gravity of receiving revelation and to the Prophet's attentive reverence for Allah's commands and reports. The point is the weight of the responsibility.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10841", "evidence": {"label": "Published explanation", "text": "Whenever the Prophet (may Allah's peace and blessings be upon him) received revelation, he would experience hardship and distress to the extent that the color of his face would change due to the gravity and difficulty of that matter.", "url": "https://hadeethenc.com/en/browse/hadith/10841", "anchor": "gravity and difficulty", "field": "E"}}], "mcq": [{"id": "10841-focus-mc-1", "q": "What does the explanation associate with these effects?", "options": ["Doubt about the message's truth", "Disagreement about its wording", "Fear of a particular human messenger", "The gravity of receiving revelation"], "correct": 3, "feedback": ["The supported answer is: The gravity of receiving revelation. The explanation connects the physical difficulty with the weight of receiving revelation.", "The supported answer is: The gravity of receiving revelation. The explanation connects the physical difficulty with the weight of receiving revelation.", "The supported answer is: The gravity of receiving revelation. The explanation connects the physical difficulty with the weight of receiving revelation.", "The explanation connects the physical difficulty with the weight of receiving revelation."], "hint": "Read the reason given for the hardship.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10841", "evidence": {"label": "Published explanation", "text": "Whenever the Prophet (may Allah's peace and blessings be upon him) received revelation, he would experience hardship and distress to the extent that the color of his face would change due to the gravity and difficulty of that matter.", "url": "https://hadeethenc.com/en/browse/hadith/10841", "anchor": "gravity and difficulty", "field": "E"}}, {"id": "10841-focus-mc-2", "q": "Which visible change does Ubadah report during revelation?", "options": ["A loss of the ability to recall the message afterward", "A request that Ubadah compose the message", "A change in the color of the Prophet's face", "An uncertainty about whether the speaker was human"], "correct": 2, "feedback": ["The supported answer is: A change in the color of the Prophet's face. The report describes distress and a change in facial color; the explanation connects them with revelation's gravity.", "The supported answer is: A change in the color of the Prophet's face. The report describes distress and a change in facial color; the explanation connects them with revelation's gravity.", "The report describes distress and a change in facial color; the explanation connects them with revelation's gravity.", "The supported answer is: A change in the color of the Prophet's face. The report describes distress and a change in facial color; the explanation connects them with revelation's gravity."], "hint": "Distinguish what was observed from explanations the account does not give.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10841", "evidence": {"label": "Published English selection", "text": "‘Ubādah ibn As-Sāmit (may Allah be pleased with him) reported: When the Messenger of Allah (may Allah's peace and blessings be upon him) received revelation, he felt distressed and the color of his face changed", "url": "https://hadeethenc.com/en/browse/hadith/10841", "anchor": "color of his face", "field": "T"}}], "coverage": {"focusedAnswers": 1, "thematicQuestions": 2, "completeSanadProvided": false, "topics": [{"point": "Visible distress, facial change and the gravity of revelation", "qa": [1], "mcq": [1, 2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/10841"}, "10843": {"revision": "topic001-coverage-2026-10-17", "narrator": "Ibn Abbas", "qa": [{"id": "10843-focus-qa-1", "group": "Meaning and understanding", "q": "Why was the Prophet instructed to listen before reciting?", "a": "He had been moving his lips from concern to retain the revelation before Jibril departed. Allah assured its gathering in his heart and its recitation. He thereafter listened while Jibril recited and then recited as he had been taught. The account brings together attentive reception, divine assurance, and faithful recitation.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10843", "evidence": {"label": "Published explanation", "text": "Then, Allah, the Almighty, revealed another verse telling the Prophet to listen attentively when Jibrīl recited the Qur'an to him, for Allah ensured that the Prophet would recite it just as Jibrīl had recited it.", "url": "https://hadeethenc.com/en/browse/hadith/10843", "anchor": "listen attentively", "field": "E"}}, {"id": "10843-focus-qa-2", "group": "Meaning and understanding", "q": "What is the significance of Ibn Abbas and Said demonstrating the lip movement?", "a": "They did not merely describe an action in general terms; each demonstrated the movement received from the earlier transmitter. That detail shows how an observed action was conveyed. It does not turn the earlier hastening into an instruction for learners to recite over a teacher.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10843", "evidence": {"label": "Published English selection", "text": "Ibn ‘Abbās (may Allah be pleased with him) commented about the verse: {Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur'an} [Sūrat al-Qiyāmah: 16], saying: \"The Prophet (may Allah's peace and blessings be upon him) used to experience hardship while the revelation was being sent down upon him, and he used to move his lips (quickly) with what was being revealed to him.\" Ibn ‘Abbās moved his lips saying: \"I am moving my lips in front of you as the Messenger of Allah (may Allah's peace and blessings be upon him) used to move his.\" Sa‘īd (the sub-narrator) also moved his lips saying: \"I am moving my lips just as I saw Ibn ‘Abbās moving his.\" Ibn ‘Abbās added: \"So Allah revealed the following verses: {Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur'an.", "url": "https://hadeethenc.com/en/browse/hadith/10843", "anchor": "Sa‘īd", "field": "T"}}], "mcq": [{"id": "10843-focus-mc-1", "q": "Why did the Prophet initially move his lips during revelation?", "options": ["To correct mistakes in Jibril's recitation", "To recite a different passage at the same time", "To retain the words before Jibril departed", "To signal that the revelation had ended"], "correct": 2, "feedback": ["The supported answer is: To retain the words before Jibril departed. The explanation identifies concern about memorizing what was being revealed.", "The supported answer is: To retain the words before Jibril departed. The explanation identifies concern about memorizing what was being revealed.", "The explanation identifies concern about memorizing what was being revealed.", "The supported answer is: To retain the words before Jibril departed. The explanation identifies concern about memorizing what was being revealed."], "hint": "Look for the reason he began reciting before the angel finished.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10843", "evidence": {"label": "Published explanation", "text": "He used to move his lips with what he received from Jibrīl before Jibrīl had finished the revelation, fearing that he would not be able to memorize it before Jibrīl left.", "url": "https://hadeethenc.com/en/browse/hadith/10843", "anchor": "fearing that he would not", "field": "E"}}, {"id": "10843-focus-mc-2", "q": "What did the revealed instruction require him to do first?", "options": ["Repeat every word before hearing its end", "Listen attentively to Jibril", "Ask the audience to supply the next verse", "Write the passage before listening"], "correct": 1, "feedback": ["The supported answer is: Listen attentively to Jibril. The explanation describes attentive listening before subsequent recitation.", "The explanation describes attentive listening before subsequent recitation.", "The supported answer is: Listen attentively to Jibril. The explanation describes attentive listening before subsequent recitation.", "The supported answer is: Listen attentively to Jibril. The explanation describes attentive listening before subsequent recitation."], "hint": "Distinguish the order of receiving and then reciting.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10843", "evidence": {"label": "Published explanation", "text": "Then, Allah, the Almighty, revealed another verse telling the Prophet to listen attentively when Jibrīl recited the Qur'an to him, for Allah ensured that the Prophet would recite it just as Jibrīl had recited it.", "url": "https://hadeethenc.com/en/browse/hadith/10843", "anchor": "listen attentively", "field": "E"}}, {"id": "10843-focus-mc-3", "q": "Why are the lip movements of Ibn Abbas and Said mentioned?", "options": ["They show two independent sources of revelation", "They demonstrate how the earlier action was transmitted", "They prescribe rapid lip movement for all reciters", "They identify the authors of the Quranic verses"], "correct": 1, "feedback": ["The supported answer is: They demonstrate how the earlier action was transmitted. The report preserves a demonstrated action across transmitters; the movements are not a new instruction to hasten.", "The report preserves a demonstrated action across transmitters; the movements are not a new instruction to hasten.", "The supported answer is: They demonstrate how the earlier action was transmitted. The report preserves a demonstrated action across transmitters; the movements are not a new instruction to hasten.", "The supported answer is: They demonstrate how the earlier action was transmitted. The report preserves a demonstrated action across transmitters; the movements are not a new instruction to hasten."], "hint": "Track who imitates whose action.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10843", "evidence": {"label": "Published English selection", "text": "Ibn ‘Abbās (may Allah be pleased with him) commented about the verse: {Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur'an} [Sūrat al-Qiyāmah: 16], saying: \"The Prophet (may Allah's peace and blessings be upon him) used to experience hardship while the revelation was being sent down upon him, and he used to move his lips (quickly) with what was being revealed to him.\" Ibn ‘Abbās moved his lips saying: \"I am moving my lips in front of you as the Messenger of Allah (may Allah's peace and blessings be upon him) used to move his.\" Sa‘īd (the sub-narrator) also moved his lips saying: \"I am moving my lips just as I saw Ibn ‘Abbās moving his.\" Ibn ‘Abbās added: \"So Allah revealed the following verses: {Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur'an.", "url": "https://hadeethenc.com/en/browse/hadith/10843", "anchor": "Sa‘īd", "field": "T"}}, {"id": "10843-focus-mc-4", "q": "What assurance allowed listening to replace hurried repetition?", "options": ["Every listener would supply a missing part later", "Allah would gather the revelation in his heart and enable its recitation", "Written notes would replace the delivered wording", "The wording did not need to be retained accurately"], "correct": 1, "feedback": ["The supported answer is: Allah would gather the revelation in his heart and enable its recitation. The verses assure collection and recitation; the subsequent conduct follows that assurance.", "The verses assure collection and recitation; the subsequent conduct follows that assurance.", "The supported answer is: Allah would gather the revelation in his heart and enable its recitation. The verses assure collection and recitation; the subsequent conduct follows that assurance.", "The supported answer is: Allah would gather the revelation in his heart and enable its recitation. The verses assure collection and recitation; the subsequent conduct follows that assurance."], "hint": "Read the promise between the prohibition of haste and the command to follow.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10843", "evidence": {"label": "Published English selection", "text": "Indeed, upon Us is its collection [in your heart] and [to make possible] its recitation.} [Sūrat al-Qiyāmah: 16-17] which means that Allah will make him (the Prophet) remember the portion of the Qur'an which was revealed to him at that time by heart and recite it.", "url": "https://hadeethenc.com/en/browse/hadith/10843", "anchor": "its collection", "field": "T"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 4, "completeSanadProvided": false, "topics": [{"point": "Concern to memorize, divine assurance and listening before recitation", "qa": [1], "mcq": [1, 2, 4]}, {"point": "Reciting faithfully after Jibril's departure", "qa": [1], "mcq": [2, 4]}, {"point": "Demonstrated lip movements and care in transmitting an observed action", "qa": [2], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/10843"}, "65051": {"revision": "topic001-coverage-2026-10-17", "narrator": "Ibn Abbas", "qa": [{"id": "65051-focus-qa-1", "group": "Meaning and understanding", "q": "How did the basmalah identify surah boundaries, and what exception does the source note?", "a": "The revelation of In the name of Allah, the Most Compassionate, the Most Merciful marked the end of the preceding surah and the beginning of another. The supplied benefit notes the exception between al-Anfal and at-Tawbah. The subject here is the recognition of surah divisions.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65051", "evidence": {"label": "Published benefit 1", "text": "Basmalah \"In the name of Allah, the Most Compassionate, the Most Merciful\" separates between surahs, except between Surat al-Anfāl and Surat at-Tawbah.", "url": "https://hadeethenc.com/en/browse/hadith/65051", "anchor": "al-Anfāl", "field": "B1"}}], "mcq": [{"id": "65051-focus-mc-1", "q": "What revealed wording marked the separation of surahs?", "options": ["The call to prayer", "The testimony of faith", "The opening of Ayat al-Kursi", "The basmalah"], "correct": 3, "feedback": ["The supported answer is: The basmalah. The report identifies the revelation of the basmalah as the sign of separation.", "The supported answer is: The basmalah. The report identifies the revelation of the basmalah as the sign of separation.", "The supported answer is: The basmalah. The report identifies the revelation of the basmalah as the sign of separation.", "The report identifies the revelation of the basmalah as the sign of separation."], "hint": "Look at the wording quoted in this brief narration.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65051", "evidence": {"label": "Published English selection", "text": "Ibn ‘Abbās (may Allah be pleased with him) reported: The Prophet (may Allah’s peace and blessings be upon him) did not know where Surahs were to be separated until \"In the name of Allah, the Most Compassionate, the Most Merciful\" was revealed to him.", "url": "https://hadeethenc.com/en/browse/hadith/65051", "anchor": "Most Compassionate", "field": "T"}}, {"id": "65051-focus-mc-2", "q": "Which exception does the published benefit identify?", "options": ["Between al-Fatihah and al-Baqarah", "Between al-Baqarah and Al Imran", "Between al-Falaq and an-Nas", "Between al-Anfal and at-Tawbah"], "correct": 3, "feedback": ["The supported answer is: Between al-Anfal and at-Tawbah. The benefit specifically names the boundary between al-Anfal and at-Tawbah.", "The supported answer is: Between al-Anfal and at-Tawbah. The benefit specifically names the boundary between al-Anfal and at-Tawbah.", "The supported answer is: Between al-Anfal and at-Tawbah. The benefit specifically names the boundary between al-Anfal and at-Tawbah.", "The benefit specifically names the boundary between al-Anfal and at-Tawbah."], "hint": "Read the exception attached to the general statement.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65051", "evidence": {"label": "Published benefit 1", "text": "Basmalah \"In the name of Allah, the Most Compassionate, the Most Merciful\" separates between surahs, except between Surat al-Anfāl and Surat at-Tawbah.", "url": "https://hadeethenc.com/en/browse/hadith/65051", "anchor": "al-Anfāl", "field": "B1"}}], "coverage": {"focusedAnswers": 1, "thematicQuestions": 2, "completeSanadProvided": false, "topics": [{"point": "Basmalah as the revealed marker of surah boundaries", "qa": [1], "mcq": [1]}, {"point": "The stated exception between al-Anfal and at-Tawbah", "qa": [1], "mcq": [2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/65051"}, "65231": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Hurayrah", "qa": [{"id": "65231-focus-qa-1", "group": "Meaning and understanding", "q": "Why is the Quran described as an enduring prophetic sign?", "a": "The explanation presents it as both revelation and a lasting proof of the mission. Its guidance and benefit extend beyond the first witnesses to later generations. This gives the report a wider focus than the number of miracles witnessed at one moment or in one place.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65231", "evidence": {"label": "Published explanation", "text": "Thus, its benefit extends to those present and absent, to those who have existed and those who will exist.", "url": "https://hadeethenc.com/en/browse/hadith/65231", "anchor": "those who will exist", "field": "E"}}, {"id": "65231-focus-qa-2", "group": "Meaning and understanding", "q": "Does emphasizing revelation deny that the Prophet had other miracles?", "a": "No. The quoted clarification by Ibn Hajar expressly rejects that reading. The Quran is emphasized as his greatest and distinctive miracle, while other miracles are not denied. The report also expresses his hope to have the greatest number of followers on the Day of Judgment.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65231", "evidence": {"label": "Published benefit 4", "text": "Ibn Hajar said regarding the Prophet's words: \"But what I have been given is revelation which Allah has revealed to me\": The meaning is not to confine all his miracles to this one, nor to deny that he was granted other miracles like those given to previous prophets; rather, the intent is that the Qur’an is his greatest and most distinctive miracle, unique to him alone.", "url": "https://hadeethenc.com/en/browse/hadith/65231", "anchor": "not to confine", "field": "B4"}}, {"id": "65231-focus-qa-3", "group": "Meaning and understanding", "q": "How do the signs given to earlier prophets relate to the Quran's role here?", "a": "The report first affirms that earlier prophets received signs through which people believed. It then highlights the Quran as the distinctive revelation given to Muhammad. The comparison affirms prophetic signs while explaining the enduring benefit of this particular sign.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65231", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported: The Prophet (ﷺ) said: \"There was no prophet among the prophets except that he was given miracles through which people believed in him.", "url": "https://hadeethenc.com/en/browse/hadith/65231", "anchor": "miracles", "field": "T"}}, {"id": "65231-focus-qa-4", "group": "Meaning and understanding", "q": "Why does the publisher quote al-Nawawi on the hope of having many followers?", "a": "Al-Nawawi connects the statement with its being made when Muslims were few, followed by the later spread of Islam. The benefit presents that contrast as a sign of prophethood, while identifying the observation as a scholar's commentary on the report.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65231", "evidence": {"label": "Published benefit 5", "text": "An-Nawawi said: (And I hope to have the most followers among them)— this is one of the signs of his prophethood, for the Prophet (ﷺ) said this at a time when the number of Muslims was very small.", "url": "https://hadeethenc.com/en/browse/hadith/65231", "anchor": "very small", "field": "B5"}}], "mcq": [{"id": "65231-focus-mc-1", "q": "Why does the explanation call the Quran an enduring sign?", "options": ["Its guidance benefits later as well as present generations", "Its benefit is limited to people who saw its first revelation", "Its proof depends only on a large number of followers", "Its message applies only to the first hearers' language skills"], "correct": 0, "feedback": ["The explanation extends its benefit to those present, absent, and yet to come.", "The supported answer is: Its guidance benefits later as well as present generations. The explanation extends its benefit to those present, absent, and yet to come.", "The supported answer is: Its guidance benefits later as well as present generations. The explanation extends its benefit to those present, absent, and yet to come.", "The supported answer is: Its guidance benefits later as well as present generations. The explanation extends its benefit to those present, absent, and yet to come."], "hint": "Notice the different generations mentioned.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65231", "evidence": {"label": "Published explanation", "text": "Thus, its benefit extends to those present and absent, to those who have existed and those who will exist.", "url": "https://hadeethenc.com/en/browse/hadith/65231", "anchor": "those who will exist", "field": "E"}}, {"id": "65231-focus-mc-2", "q": "How does the quoted explanation by Ibn Hajar qualify this emphasis?", "options": ["It excludes every miracle other than the Quran", "It restricts the Quran's benefit to one generation", "It does not deny the Prophet's other miracles", "It makes followers the source of revelation"], "correct": 2, "feedback": ["The supported answer is: It does not deny the Prophet's other miracles. The published benefit explicitly cautions against reading the emphasis as an exclusive list of miracles.", "The supported answer is: It does not deny the Prophet's other miracles. The published benefit explicitly cautions against reading the emphasis as an exclusive list of miracles.", "The published benefit explicitly cautions against reading the emphasis as an exclusive list of miracles.", "The supported answer is: It does not deny the Prophet's other miracles. The published benefit explicitly cautions against reading the emphasis as an exclusive list of miracles."], "hint": "Check the clarification about confining all his miracles to one.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65231", "evidence": {"label": "Published benefit 4", "text": "Ibn Hajar said regarding the Prophet's words: \"But what I have been given is revelation which Allah has revealed to me\": The meaning is not to confine all his miracles to this one, nor to deny that he was granted other miracles like those given to previous prophets; rather, the intent is that the Qur’an is his greatest and most distinctive miracle, unique to him alone.", "url": "https://hadeethenc.com/en/browse/hadith/65231", "anchor": "not to confine", "field": "B4"}}, {"id": "65231-focus-mc-3", "q": "What hope closes the comparison with earlier prophets' signs?", "options": ["Having no followers until after the migration", "Making the earlier prophets' signs unnecessary in their own times", "Receiving public approval as the condition for revelation", "Having the greatest number of followers on the Day of Judgment"], "correct": 3, "feedback": ["The supported answer is: Having the greatest number of followers on the Day of Judgment. The concluding hope concerns the number of followers on the Day of Judgment.", "The supported answer is: Having the greatest number of followers on the Day of Judgment. The concluding hope concerns the number of followers on the Day of Judgment.", "The supported answer is: Having the greatest number of followers on the Day of Judgment. The concluding hope concerns the number of followers on the Day of Judgment.", "The concluding hope concerns the number of followers on the Day of Judgment."], "hint": "Read the final clause after the description of revelation.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65231", "evidence": {"label": "Published English selection", "text": "But what I have been given is a revelation which Allah has revealed to me, and I hope to have the most followers among them on the Day of Judgment.\"", "url": "https://hadeethenc.com/en/browse/hadith/65231", "anchor": "most followers", "field": "T"}}], "coverage": {"focusedAnswers": 4, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Miracles as support for earlier prophets and the Quran's enduring guidance", "qa": [1, 3], "mcq": [1]}, {"point": "Emphasis on the Quran without denying other miracles", "qa": [2], "mcq": [2]}, {"point": "Hope for many followers and al-Nawawi's historical observation", "qa": [2, 4], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/65231"}, "4217": {"revision": "topic001-coverage-2026-10-17", "narrator": "Anas ibn Malik", "qa": [{"id": "4217-focus-qa-1", "group": "Meaning and understanding", "q": "What is the significance of abundant revelation near the end of the Prophet's life?", "a": "Anas reports especially abundant revelation in that final period. The explanation connects it with completing the Shariah. The account therefore directs attention to the continuing reception of guidance near the end of the mission.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4217", "evidence": {"label": "Published explanation", "text": "Allah, Exalted and Glorified, increased the revelation that was sent down to the Messenger of Allah (may Allah's peace and blessings be upon him) before his death to complete the Shariah, up until the Messenger (may Allah's peace and blessings be upon him) died at a time when the revelation was most abundant.", "url": "https://hadeethenc.com/en/browse/hadith/4217", "anchor": "complete the Shariah", "field": "E"}}], "mcq": [{"id": "4217-focus-mc-1", "q": "How does the explanation relate this abundance to the Shariah?", "options": ["It served the completion of the Shariah", "It made the earlier revelation irrelevant", "It postponed all religious guidance until after his death", "It transferred revelation to the community after his death"], "correct": 0, "feedback": ["The explanation connects the late abundance with completing the Shariah.", "The supported answer is: It served the completion of the Shariah. The explanation connects the late abundance with completing the Shariah.", "The supported answer is: It served the completion of the Shariah. The explanation connects the late abundance with completing the Shariah.", "The supported answer is: It served the completion of the Shariah. The explanation connects the late abundance with completing the Shariah."], "hint": "Look for the purpose stated in the explanation.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4217", "evidence": {"label": "Published explanation", "text": "Allah, Exalted and Glorified, increased the revelation that was sent down to the Messenger of Allah (may Allah's peace and blessings be upon him) before his death to complete the Shariah, up until the Messenger (may Allah's peace and blessings be upon him) died at a time when the revelation was most abundant.", "url": "https://hadeethenc.com/en/browse/hadith/4217", "anchor": "complete the Shariah", "field": "E"}}, {"id": "4217-focus-mc-2", "q": "Which description correctly places the intensity of revelation in this narration?", "options": ["It stops several years before his death", "It declines because the Shariah has already ceased to be revealed", "It concerns only the period before the first migration", "It is especially abundant near the end of his life"], "correct": 3, "feedback": ["The supported answer is: It is especially abundant near the end of his life. Anas describes abundant revelation in the period preceding the Prophet's death.", "The supported answer is: It is especially abundant near the end of his life. Anas describes abundant revelation in the period preceding the Prophet's death.", "The supported answer is: It is especially abundant near the end of his life. Anas describes abundant revelation in the period preceding the Prophet's death.", "Anas describes abundant revelation in the period preceding the Prophet's death."], "hint": "Keep the period being described distinct from the initial revelation.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4217", "evidence": {"label": "Published English selection", "text": "Anas ibn Mālik (may Allah be pleased with him) reported: Allah, Exalted and Glorified, sent down the Divine Revelation to the Messenger of Allah (may Allah's peace and blessings be upon him) abundantly during the period preceding his death until he died at a time when the revelation had never been more abundant.", "url": "https://hadeethenc.com/en/browse/hadith/4217", "anchor": "preceding his death", "field": "T"}}], "coverage": {"focusedAnswers": 1, "thematicQuestions": 2, "completeSanadProvided": false, "topics": [{"point": "Abundance of revelation near the end of life and completion of the Shariah", "qa": [1], "mcq": [1, 2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/4217"}, "4947": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Hurayrah", "qa": [{"id": "4947-focus-qa-1", "group": "Meaning and understanding", "q": "What does refusal of Paradise mean in this exchange?", "a": "The Companions were puzzled that anyone would refuse Paradise. The Prophet explained the expression through obedience and disobedience to him. The published benefits connect obedience to the Messenger with obedience to Allah. The warning makes response to his guidance central, rather than mere knowledge of his name.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4947", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Everyone of my Ummah will enter Paradise except those who refuse.\" They said: \"And who would refuse, O Messenger of Allah?\" He said: \"He who obeys me will enter Paradise, and who disobeys me has refused.\"", "url": "https://hadeethenc.com/en/browse/hadith/4947", "anchor": "who disobeys me", "field": "T"}}], "mcq": [{"id": "4947-focus-mc-1", "q": "How does the Prophet explain refusal here?", "options": ["Asking him to clarify his words", "Hearing the report from another Companion", "Needing instruction before acting", "Disobeying him"], "correct": 3, "feedback": ["The supported answer is: Disobeying him. The narration connects refusal with disobedience, rather than with sincere clarification.", "The supported answer is: Disobeying him. The narration connects refusal with disobedience, rather than with sincere clarification.", "The supported answer is: Disobeying him. The narration connects refusal with disobedience, rather than with sincere clarification.", "The narration connects refusal with disobedience, rather than with sincere clarification."], "hint": "Read the contrast in the final sentence.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4947", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Everyone of my Ummah will enter Paradise except those who refuse.\" They said: \"And who would refuse, O Messenger of Allah?\" He said: \"He who obeys me will enter Paradise, and who disobeys me has refused.\"", "url": "https://hadeethenc.com/en/browse/hadith/4947", "anchor": "who disobeys me", "field": "T"}}, {"id": "4947-focus-mc-2", "q": "How do the published benefits connect obedience to the Messenger with obedience to Allah?", "options": ["They are unrelated obligations", "Obedience to the Messenger replaces obedience to Allah", "They are connected, not competing loyalties", "Obedience to Allah excludes following the Messenger"], "correct": 2, "feedback": ["The supported answer is: They are connected, not competing loyalties. The first benefit explicitly states this connection.", "The supported answer is: They are connected, not competing loyalties. The first benefit explicitly states this connection.", "The first benefit explicitly states this connection.", "The supported answer is: They are connected, not competing loyalties. The first benefit explicitly states this connection."], "hint": "Read the first published benefit.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4947", "evidence": {"label": "Published benefit 1", "text": "Obeying the Messenger (may Allah's peace and blessings be upon him) is part of obedience to Allah, and disobeying him is disobedience to Allah.", "url": "https://hadeethenc.com/en/browse/hadith/4947", "anchor": "part of obedience to Allah", "field": "B1"}}, {"id": "4947-focus-mc-3", "q": "What connects the warning to the Prophet's concern for his community in the benefits?", "options": ["His keenness to guide them toward Paradise through obedience", "His wish that guidance remain inaccessible to ordinary people", "A claim that the community's conduct has no consequences", "An instruction to replace following him with inherited reputation"], "correct": 0, "feedback": ["The final benefit identifies compassion and keenness to guide the community.", "The supported answer is: His keenness to guide them toward Paradise through obedience. The final benefit identifies compassion and keenness to guide the community.", "The supported answer is: His keenness to guide them toward Paradise through obedience. The final benefit identifies compassion and keenness to guide the community.", "The supported answer is: His keenness to guide them toward Paradise through obedience. The final benefit identifies compassion and keenness to guide the community."], "hint": "Consider why the opening statement prompts an explanatory question.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4947", "evidence": {"label": "Published benefit 4", "text": "It shows the Prophet's compassion towards his Ummah and keenness to guide them.", "url": "https://hadeethenc.com/en/browse/hadith/4947", "anchor": "keenness to guide", "field": "B4"}}], "coverage": {"focusedAnswers": 1, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Refusal explained through obedience and disobedience", "qa": [1], "mcq": [1]}, {"point": "Obedience to the Messenger as obedience to Allah", "qa": [1], "mcq": [2]}, {"point": "Concern for guiding the community toward Paradise", "qa": [1], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/4947"}, "3272": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Hurayrah", "qa": [{"id": "3272-focus-qa-1", "group": "Meaning and understanding", "q": "What conditions must remain attached to this report's warning?", "a": "The wording concerns hearing of the Messenger and dying without believing in the message he brought. The mention of Jews and Christians does not restrict the mission to those two communities; the source explains its universal reach. A careful explanation retains the stated conditions rather than turning the passage into unsupported verdicts about individuals.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3272", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"By the One in Whose Hand Muhammad's soul is, there is nobody of this Ummah (community), whether they be Jewish or Christian, who hears of me and then dies without believing in what I was sent with except that he will be among the people of Hellfire.\"", "url": "https://hadeethenc.com/en/browse/hadith/3272", "anchor": "who hears of me", "field": "T"}}, {"id": "3272-focus-qa-2", "group": "Meaning and understanding", "q": "How does the publisher distinguish those whom the call has not reached?", "a": "Its third benefit states that those who have not heard of the Prophet and have not been reached by the call are excused, with their case in the Hereafter left to Allah. This qualification should remain visible when explaining the warning about those who hear and do not believe.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3272", "evidence": {"label": "Published benefit 3", "text": "Those who have not heard about the Prophet (may Allah's peace and blessings be upon him) and the call of Islam has not reached them are excused and their case in the Hereafter is left to Allah Almighty.", "url": "https://hadeethenc.com/en/browse/hadith/3272", "anchor": "left to Allah", "field": "B3"}}, {"id": "3272-focus-qa-3", "group": "Meaning and understanding", "q": "Does the account treat a person's earlier rejection as removing every later opportunity to believe?", "a": "No. The warning concerns dying without belief after hearing the message. The fourth benefit expressly recognizes embracing Islam before the final onset of death, rather than treating a person's earlier state as unchangeable.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3272", "evidence": {"label": "Published benefit 4", "text": "A person can embrace Islam even shortly before death, even if he is in severe illness, so long as the soul did not reach the throat (did not witness death).", "url": "https://hadeethenc.com/en/browse/hadith/3272", "anchor": "shortly before death", "field": "B4"}}], "mcq": [{"id": "3272-focus-mc-1", "q": "Which condition is explicitly part of this warning?", "options": ["Never hearing of the Messenger at all", "Living outside Arabia without any further condition", "Hearing of the Messenger and dying without belief in his message", "Belonging to a named ancestry without any further condition"], "correct": 2, "feedback": ["The supported answer is: Hearing of the Messenger and dying without belief in his message. The wording includes both hearing and dying without belief; those conditions must be retained.", "The supported answer is: Hearing of the Messenger and dying without belief in his message. The wording includes both hearing and dying without belief; those conditions must be retained.", "The wording includes both hearing and dying without belief; those conditions must be retained.", "The supported answer is: Hearing of the Messenger and dying without belief in his message. The wording includes both hearing and dying without belief; those conditions must be retained."], "hint": "Read the whole condition, not only the groups mentioned.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3272", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"By the One in Whose Hand Muhammad's soul is, there is nobody of this Ummah (community), whether they be Jewish or Christian, who hears of me and then dies without believing in what I was sent with except that he will be among the people of Hellfire.\"", "url": "https://hadeethenc.com/en/browse/hadith/3272", "anchor": "who hears of me", "field": "T"}}, {"id": "3272-focus-mc-2", "q": "How does the source treat those not reached by the call of Islam?", "options": ["They are expressly identical to the hearers in this warning", "Their nationality alone determines the outcome", "Their case in the Hereafter is left to Allah", "The hadith supplies individual verdicts about each of them"], "correct": 2, "feedback": ["The supported answer is: Their case in the Hereafter is left to Allah. The third benefit explicitly distinguishes those whom the call has not reached.", "The supported answer is: Their case in the Hereafter is left to Allah. The third benefit explicitly distinguishes those whom the call has not reached.", "The third benefit explicitly distinguishes those whom the call has not reached.", "The supported answer is: Their case in the Hereafter is left to Allah. The third benefit explicitly distinguishes those whom the call has not reached."], "hint": "Look for the benefit concerning those who have not heard.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3272", "evidence": {"label": "Published benefit 3", "text": "Those who have not heard about the Prophet (may Allah's peace and blessings be upon him) and the call of Islam has not reached them are excused and their case in the Hereafter is left to Allah Almighty.", "url": "https://hadeethenc.com/en/browse/hadith/3272", "anchor": "left to Allah", "field": "B3"}}, {"id": "3272-focus-mc-3", "q": "What does mentioning Jews and Christians establish in the published explanation?", "options": ["The message applies only to those two communities", "People outside those communities are excluded from the warning", "Earlier scripture does not exempt a community from the universal message", "Hearing the message is absent from the conditions stated"], "correct": 2, "feedback": ["The supported answer is: Earlier scripture does not exempt a community from the universal message. The benefits explain the universal reach of the message while preserving the stated conditions.", "The supported answer is: Earlier scripture does not exempt a community from the universal message. The benefits explain the universal reach of the message while preserving the stated conditions.", "The benefits explain the universal reach of the message while preserving the stated conditions.", "The supported answer is: Earlier scripture does not exempt a community from the universal message. The benefits explain the universal reach of the message while preserving the stated conditions."], "hint": "Do not turn named examples into an exclusive list.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3272", "evidence": {"label": "Published benefit 6", "text": "The reference in this Hadīth to the Jews and the Christians indicates that the ruling includes the people of other faiths as well.", "url": "https://hadeethenc.com/en/browse/hadith/3272", "anchor": "other faiths", "field": "B6"}}, {"id": "3272-focus-mc-4", "q": "How does the benefit describe the possibility of accepting Islam before death?", "options": ["It remains possible before the soul reaches the throat", "It becomes impossible after any earlier rejection", "It requires having accepted before illness began", "It is automatically replaced by knowledge of earlier scripture"], "correct": 0, "feedback": ["The fourth benefit recognizes acceptance before the final onset of death.", "The supported answer is: It remains possible before the soul reaches the throat. The fourth benefit recognizes acceptance before the final onset of death.", "The supported answer is: It remains possible before the soul reaches the throat. The fourth benefit recognizes acceptance before the final onset of death.", "The supported answer is: It remains possible before the soul reaches the throat. The fourth benefit recognizes acceptance before the final onset of death."], "hint": "Keep the final condition distinct from a person's earlier life.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3272", "evidence": {"label": "Published benefit 4", "text": "A person can embrace Islam even shortly before death, even if he is in severe illness, so long as the soul did not reach the throat (did not witness death).", "url": "https://hadeethenc.com/en/browse/hadith/3272", "anchor": "soul did not reach the throat", "field": "B4"}}], "coverage": {"focusedAnswers": 3, "thematicQuestions": 4, "completeSanadProvided": false, "topics": [{"point": "Hearing the message, dying without belief and the stated warning", "qa": [1], "mcq": [1]}, {"point": "Those not reached by the call and leaving their case to Allah", "qa": [2], "mcq": [2]}, {"point": "Universality, including people of earlier scriptures", "qa": [1], "mcq": [3]}, {"point": "Opportunity for belief before the final onset of death", "qa": [3], "mcq": [4]}]}, "source": "https://hadeethenc.com/en/browse/hadith/3272"}, "66529": {"revision": "topic001-coverage-2026-10-17", "narrator": "Al-Irbad ibn Sariyah", "qa": [{"id": "66529-focus-qa-1", "group": "Meaning and understanding", "q": "What guidance does the report give for facing religious disagreement?", "a": "The advice begins with consciousness of Allah and directs firm adherence to the Prophet's Sunnah and that of the rightly guided caliphs. The explanation names Abu Bakr, Umar, Uthman, and Ali. Its response to discord is adherence to received guidance, not choosing a position merely because it is new or popular.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66529", "evidence": {"label": "Published English selection", "text": "So hold fast to my Sunnah and the Sunnah of the Rightly-Guided Caliphs, and cling to them firmly.", "url": "https://hadeethenc.com/en/browse/hadith/66529", "anchor": "Rightly-Guided Caliphs", "field": "T"}}, {"id": "66529-focus-qa-2", "group": "Meaning and understanding", "q": "How is obedience to a leader qualified in the source benefits?", "a": "The advice rejects making a leader's social status the basis for refusing obedience. The supplied benefit also states the limit: obedience must not involve disobeying Allah. Both points matter; neither contempt for status nor an unrestricted demand for obedience reflects the complete explanation.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66529", "evidence": {"label": "Published benefit 5", "text": "Hearing and obeying whoever is in charge of the believers without disobeying Allah.", "url": "https://hadeethenc.com/en/browse/hadith/66529", "anchor": "without disobeying Allah", "field": "B5"}}, {"id": "66529-focus-qa-3", "group": "Meaning and understanding", "q": "What are the new matters warned against here?", "a": "The wording concerns newly introduced matters in religion. It is a warning about religious innovation and departure from the given guidance. It should not be detached from that subject and applied simply to every new tool, teaching format, or worldly arrangement.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66529", "evidence": {"label": "Published English selection", "text": "Beware of new things (in religion) because every religious innovation is a misguidance.\"", "url": "https://hadeethenc.com/en/browse/hadith/66529", "anchor": "new things (in religion)", "field": "T"}}, {"id": "66529-focus-qa-4", "group": "Meaning and understanding", "q": "What does fearing Allah mean in the opening advice?", "a": "The explanation describes it through carrying out duties and avoiding prohibitions. It is a practical foundation for the subsequent advice about authority, disagreement and adherence to the Sunnah.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66529", "evidence": {"label": "Published explanation", "text": "He said: I advise you to fear Allah Almighty by carrying out duties and avoiding prohibitions.", "url": "https://hadeethenc.com/en/browse/hadith/66529", "anchor": "carrying out duties", "field": "E"}}, {"id": "66529-focus-qa-5", "group": "Meaning and understanding", "q": "Why do the companions ask for advice after the exhortation?", "a": "Its seriousness moves them, and they understand it as resembling a farewell. They therefore ask for guidance to hold onto after the Prophet, making the ensuing instructions a response to their need for lasting direction.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66529", "evidence": {"label": "Published explanation", "text": "Hence, they asked him to give them advice that they would hold onto after him.", "url": "https://hadeethenc.com/en/browse/hadith/66529", "anchor": "hold onto after him", "field": "E"}}], "mcq": [{"id": "66529-focus-mc-1", "q": "Which response to future disagreement is prescribed?", "options": ["Follow the position with the largest audience", "Hold firmly to the Prophetic Sunnah and rightly guided caliphs' Sunnah", "Treat every later practice as equally authoritative", "Leave transmitted guidance until disagreement ends"], "correct": 1, "feedback": ["The supported answer is: Hold firmly to the Prophetic Sunnah and rightly guided caliphs' Sunnah. The report directs firm adherence to these sources of guidance when discord appears.", "The report directs firm adherence to these sources of guidance when discord appears.", "The supported answer is: Hold firmly to the Prophetic Sunnah and rightly guided caliphs' Sunnah. The report directs firm adherence to these sources of guidance when discord appears.", "The supported answer is: Hold firmly to the Prophetic Sunnah and rightly guided caliphs' Sunnah. The report directs firm adherence to these sources of guidance when discord appears."], "hint": "Identify the guidance named after the warning of discord.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66529", "evidence": {"label": "Published English selection", "text": "So hold fast to my Sunnah and the Sunnah of the Rightly-Guided Caliphs, and cling to them firmly.", "url": "https://hadeethenc.com/en/browse/hadith/66529", "anchor": "Rightly-Guided Caliphs", "field": "T"}}, {"id": "66529-focus-mc-2", "q": "Which limit accompanies obedience to those in authority in the benefits?", "options": ["It must not involve disobeying Allah", "It applies only when the leader has high social status", "It permits abandoning the Sunnah during discord", "It depends solely on personal admiration for the leader"], "correct": 0, "feedback": ["The fifth benefit explicitly preserves obedience to Allah as the limit.", "The supported answer is: It must not involve disobeying Allah. The fifth benefit explicitly preserves obedience to Allah as the limit.", "The supported answer is: It must not involve disobeying Allah. The fifth benefit explicitly preserves obedience to Allah as the limit.", "The supported answer is: It must not involve disobeying Allah. The fifth benefit explicitly preserves obedience to Allah as the limit."], "hint": "Check the qualification attached to hearing and obeying.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66529", "evidence": {"label": "Published benefit 5", "text": "Hearing and obeying whoever is in charge of the believers without disobeying Allah.", "url": "https://hadeethenc.com/en/browse/hadith/66529", "anchor": "without disobeying Allah", "field": "B5"}}, {"id": "66529-focus-mc-3", "q": "What does the warning against new matters specifically concern?", "options": ["Newly introduced matters in religion", "Every new tool used to preserve learning", "Every change in clothing or transport", "Every newly asked question in a lesson"], "correct": 0, "feedback": ["The report's wording and benefits concern religious innovation, not novelty in every worldly matter.", "The supported answer is: Newly introduced matters in religion. The report's wording and benefits concern religious innovation, not novelty in every worldly matter.", "The supported answer is: Newly introduced matters in religion. The report's wording and benefits concern religious innovation, not novelty in every worldly matter.", "The supported answer is: Newly introduced matters in religion. The report's wording and benefits concern religious innovation, not novelty in every worldly matter."], "hint": "Keep the words in religion attached to the warning.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66529", "evidence": {"label": "Published English selection", "text": "Beware of new things (in religion) because every religious innovation is a misguidance.\"", "url": "https://hadeethenc.com/en/browse/hadith/66529", "anchor": "new things (in religion)", "field": "T"}}, {"id": "66529-focus-mc-4", "q": "Which description defines fearing Allah in the explanation of the opening advice?", "options": ["Treating emotion alone as a substitute for obedience", "Ignoring duties whenever discord appears", "Carrying out duties and avoiding prohibitions", "Restricting devotion to public displays"], "correct": 2, "feedback": ["The supported answer is: Carrying out duties and avoiding prohibitions. The explanation gives a practical definition before discussing authority and the Sunnah.", "The supported answer is: Carrying out duties and avoiding prohibitions. The explanation gives a practical definition before discussing authority and the Sunnah.", "The explanation gives a practical definition before discussing authority and the Sunnah.", "The supported answer is: Carrying out duties and avoiding prohibitions. The explanation gives a practical definition before discussing authority and the Sunnah."], "hint": "Read how the opening advice is explained before the later instructions.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66529", "evidence": {"label": "Published explanation", "text": "He said: I advise you to fear Allah Almighty by carrying out duties and avoiding prohibitions.", "url": "https://hadeethenc.com/en/browse/hadith/66529", "anchor": "carrying out duties", "field": "E"}}, {"id": "66529-focus-mc-5", "q": "Who are the four caliphs named in the explanation of the guided precedent?", "options": ["Abu Bakr, Bilal, Muawiyah and Abu Hurayrah", "Umar, Khalid, Ibn Abbas and Ubayy", "Abu Bakr, Umar, Uthman and Ali", "Uthman, Anas, Salman and Abu Musa"], "correct": 2, "feedback": ["The supported answer is: Abu Bakr, Umar, Uthman and Ali. The third benefit explicitly identifies the four Rightly-Guided Caliphs.", "The supported answer is: Abu Bakr, Umar, Uthman and Ali. The third benefit explicitly identifies the four Rightly-Guided Caliphs.", "The third benefit explicitly identifies the four Rightly-Guided Caliphs.", "The supported answer is: Abu Bakr, Umar, Uthman and Ali. The third benefit explicitly identifies the four Rightly-Guided Caliphs."], "hint": "Use the source's named group rather than a list of prominent companions generally.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66529", "evidence": {"label": "Published benefit 3", "text": "The commandment to follow the four rightly guided Caliphs, namely Abu Bakr, ‘Umar, ‘Uthmān, and ‘Ali (may Allah be pleased with them all), after the Prophet.", "url": "https://hadeethenc.com/en/browse/hadith/66529", "anchor": "Abu Bakr", "field": "B3"}}], "coverage": {"focusedAnswers": 5, "thematicQuestions": 5, "completeSanadProvided": false, "topics": [{"point": "The serious exhortation and request for lasting advice", "qa": [5], "mcq": [1]}, {"point": "Fearing Allah through duties and avoidance of prohibitions", "qa": [4], "mcq": [4]}, {"point": "Obedience independent of social status, without disobeying Allah", "qa": [2], "mcq": [2]}, {"point": "Future discord and adherence to the Sunnah and four guided caliphs", "qa": [1], "mcq": [1, 5]}, {"point": "Religious innovation distinguished from new worldly tools", "qa": [3], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/66529"}, "65005": {"revision": "topic001-coverage-2026-10-17", "narrator": "Al-Miqdam ibn Madikarib", "qa": [{"id": "65005-focus-qa-1", "group": "Meaning and understanding", "q": "Why does this report reject using the Quran as a reason to dismiss the Sunnah?", "a": "The listener claims that only what he finds in the Quran can determine lawful and unlawful. The Prophet responds by affirming the religious authority of his prohibitions. The explanation grounds this in his conveying from Allah. The central issue is rejection of authentic Prophetic authority, not the use of a couch or a sincere request to verify a report.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65005", "evidence": {"label": "Published explanation", "text": "Then, the Prophet (may Allah's peace and blessings be upon him) pointed out that anything he prohibited or forbade in his Sunnah is the same as what Allah prohibited in His Book, for he only conveys from his Lord.", "url": "https://hadeethenc.com/en/browse/hadith/65005", "anchor": "conveys from his Lord", "field": "E"}}], "mcq": [{"id": "65005-focus-mc-1", "q": "What claim does the reclining listener use to reject a hadith?", "options": ["A report must have a reliable attribution before use", "Only what he finds in the Quran determines lawful and unlawful", "The meaning of a difficult phrase should be explained", "The Quran and Sunnah should be studied together"], "correct": 1, "feedback": ["The supported answer is: Only what he finds in the Quran determines lawful and unlawful. The criticized claim dismisses Prophetic teaching because it is not separately found in Quranic wording.", "The criticized claim dismisses Prophetic teaching because it is not separately found in Quranic wording.", "The supported answer is: Only what he finds in the Quran determines lawful and unlawful. The criticized claim dismisses Prophetic teaching because it is not separately found in Quranic wording.", "The supported answer is: Only what he finds in the Quran determines lawful and unlawful. The criticized claim dismisses Prophetic teaching because it is not separately found in Quranic wording."], "hint": "Distinguish rejecting authority from checking a report's reliability.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65005", "evidence": {"label": "Published English selection", "text": "Soon a Hadīth from me will be conveyed to a man, while he is reclining on his couch, and he says: ‘Between us and you is Allah’s Book.", "url": "https://hadeethenc.com/en/browse/hadith/65005", "anchor": "Between us and you", "field": "T"}}, {"id": "65005-focus-mc-2", "q": "How does the explanation account for this authority?", "options": ["The audience assigns it by agreement", "The authority comes from the couch-bound listener", "Every individual preference becomes revelation", "The Messenger conveys from his Lord"], "correct": 3, "feedback": ["The supported answer is: The Messenger conveys from his Lord. The source grounds the authority in his conveying from Allah, not in audience approval.", "The supported answer is: The Messenger conveys from his Lord. The source grounds the authority in his conveying from Allah, not in audience approval.", "The supported answer is: The Messenger conveys from his Lord. The source grounds the authority in his conveying from Allah, not in audience approval.", "The source grounds the authority in his conveying from Allah, not in audience approval."], "hint": "Look at the explanation's final reason.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65005", "evidence": {"label": "Published explanation", "text": "Then, the Prophet (may Allah's peace and blessings be upon him) pointed out that anything he prohibited or forbade in his Sunnah is the same as what Allah prohibited in His Book, for he only conveys from his Lord.", "url": "https://hadeethenc.com/en/browse/hadith/65005", "anchor": "conveys from his Lord", "field": "E"}}], "coverage": {"focusedAnswers": 1, "thematicQuestions": 2, "completeSanadProvided": false, "topics": [{"point": "The claim that the Quran alone makes the Sunnah unnecessary", "qa": [1], "mcq": [1]}, {"point": "Authority of Prophetic prohibitions as conveying from Allah", "qa": [1], "mcq": [2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/65005"}, "4792": {"revision": "topic001-coverage-2026-10-17", "narrator": "Aishah", "qa": [{"id": "4792-focus-qa-1", "group": "Meaning and understanding", "q": "What standard of acceptance is expressed by the two wordings of this hadith?", "a": "The first wording rejects introducing into religion what does not belong to it. The second also covers performing an act that does not conform to it, even if someone else introduced it. The explanation grounds religious practice in evidence from the Quran and Sunnah; good intention does not remove the need for conformity.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4792", "evidence": {"label": "Published English selection", "text": "‘Ā’ishah (may Allah be pleased with her) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever introduces into this matter of ours (Islam) something that does not belong to it shall have it rejected.\" [Agreed upon] A narration by Muslim reads: \"Whoever does something that is not in accordance with this matter of ours shall have it rejected.\"", "url": "https://hadeethenc.com/en/browse/hadith/4792", "anchor": "Whoever does something", "field": "T"}}, {"id": "4792-focus-qa-2", "group": "Meaning and understanding", "q": "How should this criterion be distinguished from opposition to every new development?", "a": "The source distinguishes religious additions from worldly affairs. A new means of teaching or preserving knowledge is not rejected merely because it is new. Likewise, Hadith 37 concerns implementing an established good through charity; its explanation does not authorize inventing unsupported rituals.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4792", "evidence": {"label": "Published benefit 6", "text": "The prohibited innovations are those related to religion and not those related to worldly affairs.", "url": "https://hadeethenc.com/en/browse/hadith/4792", "anchor": "worldly affairs", "field": "B6"}}], "mcq": [{"id": "4792-focus-mc-1", "q": "How does the second wording broaden the application?", "options": ["It limits rejection to the first inventor alone", "It excludes all acts already performed by others", "It makes popularity the standard of acceptance", "It includes performing an unsupported act, not only introducing it"], "correct": 3, "feedback": ["The supported answer is: It includes performing an unsupported act, not only introducing it. The Muslim wording speaks of whoever does an act not in accordance with the religion.", "The supported answer is: It includes performing an unsupported act, not only introducing it. The Muslim wording speaks of whoever does an act not in accordance with the religion.", "The supported answer is: It includes performing an unsupported act, not only introducing it. The Muslim wording speaks of whoever does an act not in accordance with the religion.", "The Muslim wording speaks of whoever does an act not in accordance with the religion."], "hint": "Compare introduces with does something.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4792", "evidence": {"label": "Published English selection", "text": "‘Ā’ishah (may Allah be pleased with her) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever introduces into this matter of ours (Islam) something that does not belong to it shall have it rejected.\" [Agreed upon] A narration by Muslim reads: \"Whoever does something that is not in accordance with this matter of ours shall have it rejected.\"", "url": "https://hadeethenc.com/en/browse/hadith/4792", "anchor": "Whoever does something", "field": "T"}}, {"id": "4792-focus-mc-2", "q": "How should good intention relate to conformity in an act of worship?", "options": ["Good intention makes every proposed ritual acceptable", "Conformity matters only when intention is weak", "Conformity can be replaced by community popularity", "Good intention does not remove the need to conform"], "correct": 3, "feedback": ["The supported answer is: Good intention does not remove the need to conform. The fifth benefit connects acceptance with devotion to Allah and conformity to the Sunnah.", "The supported answer is: Good intention does not remove the need to conform. The fifth benefit connects acceptance with devotion to Allah and conformity to the Sunnah.", "The supported answer is: Good intention does not remove the need to conform. The fifth benefit connects acceptance with devotion to Allah and conformity to the Sunnah.", "The fifth benefit connects acceptance with devotion to Allah and conformity to the Sunnah."], "hint": "Consider the two requirements discussed in the longer benefit.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4792", "evidence": {"label": "Published benefit 5", "text": "Every deed that is not exclusively devoted to Allah Almighty, its doer will not be rewarded for it and the same rule applies to every deed that does not conform with the Prophet's Sunnah will be rejected upon its doer.", "url": "https://hadeethenc.com/en/browse/hadith/4792", "anchor": "not exclusively devoted", "field": "B5"}}, {"id": "4792-focus-mc-3", "q": "Which distinction does the final benefit make?", "options": ["Every worldly arrangement is an act of worship by itself", "Religious innovation differs from new worldly arrangements", "New transport is rejected merely because it is new", "All religious customs are accepted because they are old"], "correct": 1, "feedback": ["The supported answer is: Religious innovation differs from new worldly arrangements. The source distinguishes prohibited religious additions from worldly affairs.", "The source distinguishes prohibited religious additions from worldly affairs.", "The supported answer is: Religious innovation differs from new worldly arrangements. The source distinguishes prohibited religious additions from worldly affairs.", "The supported answer is: Religious innovation differs from new worldly arrangements. The source distinguishes prohibited religious additions from worldly affairs."], "hint": "Read the final benefit before applying the rule to modern tools.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4792", "evidence": {"label": "Published benefit 6", "text": "The prohibited innovations are those related to religion and not those related to worldly affairs.", "url": "https://hadeethenc.com/en/browse/hadith/4792", "anchor": "worldly affairs", "field": "B6"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Introducing an unsupported religious act and performing it", "qa": [1], "mcq": [1]}, {"point": "Conformity rather than good intention alone as the criterion", "qa": [1], "mcq": [2]}, {"point": "Religious additions distinguished from new worldly means", "qa": [2], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/4792"}, "4725": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Hurayrah", "qa": [{"id": "4725-focus-qa-1", "group": "Meaning and understanding", "q": "How does the hadith relate obedience to a person's ability?", "a": "It directs avoidance of prohibitions and performance of commands to the extent one is able. Capacity is therefore relevant to carrying out a command, without making willingness to obey optional. The instruction holds responsibility and real human limitations together.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4725", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"Avoid what I have forbidden you from; and do as much as you can, of what I have ordered you.", "url": "https://hadeethenc.com/en/browse/hadith/4725", "anchor": "as much as you can", "field": "T"}}, {"id": "4725-focus-qa-2", "group": "Meaning and understanding", "q": "Does the warning against excessive questioning discourage necessary learning?", "a": "The benefits expressly distinguish questions needed to learn the religion from questioning driven by obstinacy or artificial difficulty. The warning concerns destructive questioning and disagreement with the prophets. A sincere question about understanding or carrying out a duty belongs to the approved kind of learning.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4725", "evidence": {"label": "Published benefit 3", "text": "The scholars divided questions into two types, one of which aims at learning things needed in the religion.", "url": "https://hadeethenc.com/en/browse/hadith/4725", "anchor": "aims at learning", "field": "B3"}}, {"id": "4725-focus-qa-3", "group": "Meaning and understanding", "q": "How far does the instruction to avoid a prohibition extend in the benefits?", "a": "The benefits apply avoidance to small as well as large amounts of a prohibited act and also warn against means leading to it. Their example is usury: a small amount is not made acceptable simply because it is small.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4725", "evidence": {"label": "Published benefit 5", "text": "For example, we are prohibited from usury, and this applies to any amount of it, big or small.", "url": "https://hadeethenc.com/en/browse/hadith/4725", "anchor": "usury", "field": "B5"}}, {"id": "4725-focus-qa-4", "group": "Meaning and understanding", "q": "Why do the benefits mention avoiding the means leading to a prohibited act?", "a": "They explain avoidance as including steps that lead to the prohibited act, not merely rejecting its final form after arranging its causes. This is stated as a further implication of the command to avoid what is forbidden.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4725", "evidence": {"label": "Published benefit 6", "text": "We are required to shun the means conducive to something prohibited, for this falls under the meaning of avoidance.", "url": "https://hadeethenc.com/en/browse/hadith/4725", "anchor": "means conducive", "field": "B6"}}], "mcq": [{"id": "4725-focus-mc-1", "q": "How does the wording distinguish prohibitions from commands?", "options": ["Treat both as optional when inconvenient", "Fulfill commands only when no effort is involved", "Avoid prohibitions; fulfill commands according to ability", "Avoid only the largest instances of a prohibition"], "correct": 2, "feedback": ["The supported answer is: Avoid prohibitions; fulfill commands according to ability. The text expressly attaches ability to performing commands while directing avoidance of what is forbidden.", "The supported answer is: Avoid prohibitions; fulfill commands according to ability. The text expressly attaches ability to performing commands while directing avoidance of what is forbidden.", "The text expressly attaches ability to performing commands while directing avoidance of what is forbidden.", "The supported answer is: Avoid prohibitions; fulfill commands according to ability. The text expressly attaches ability to performing commands while directing avoidance of what is forbidden."], "hint": "Read both halves of the opening instruction.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4725", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"Avoid what I have forbidden you from; and do as much as you can, of what I have ordered you.", "url": "https://hadeethenc.com/en/browse/hadith/4725", "anchor": "as much as you can", "field": "T"}}, {"id": "4725-focus-mc-2", "q": "Which kind of questioning do the benefits explicitly approve?", "options": ["Questions used to resist a clear duty", "Questions pursued as stubborn argument", "Questions needed to learn the religion", "Questions asked merely to create difficulty"], "correct": 2, "feedback": ["The supported answer is: Questions needed to learn the religion. The third benefit distinguishes needed learning from obstinacy and artificial difficulty.", "The supported answer is: Questions needed to learn the religion. The third benefit distinguishes needed learning from obstinacy and artificial difficulty.", "The third benefit distinguishes needed learning from obstinacy and artificial difficulty.", "The supported answer is: Questions needed to learn the religion. The third benefit distinguishes needed learning from obstinacy and artificial difficulty."], "hint": "Read the source's division of questions into two types.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4725", "evidence": {"label": "Published benefit 3", "text": "The scholars divided questions into two types, one of which aims at learning things needed in the religion.", "url": "https://hadeethenc.com/en/browse/hadith/4725", "anchor": "aims at learning", "field": "B3"}}, {"id": "4725-focus-mc-3", "q": "How does the source apply avoidance to a small amount of a prohibited act?", "options": ["A small amount is not permitted merely because it is small", "Only a large amount falls under the prohibition", "The amount becomes lawful when hidden", "Avoidance concerns names rather than the act itself"], "correct": 0, "feedback": ["The fifth benefit uses usury to explain that the prohibition includes small and large amounts.", "The supported answer is: A small amount is not permitted merely because it is small. The fifth benefit uses usury to explain that the prohibition includes small and large amounts.", "The supported answer is: A small amount is not permitted merely because it is small. The fifth benefit uses usury to explain that the prohibition includes small and large amounts.", "The supported answer is: A small amount is not permitted merely because it is small. The fifth benefit uses usury to explain that the prohibition includes small and large amounts."], "hint": "Read the example used to explain the scope of avoidance.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4725", "evidence": {"label": "Published benefit 5", "text": "For example, we are prohibited from usury, and this applies to any amount of it, big or small.", "url": "https://hadeethenc.com/en/browse/hadith/4725", "anchor": "usury", "field": "B5"}}, {"id": "4725-focus-mc-4", "q": "Which pair of causes is named in the warning about earlier communities?", "options": ["Necessary learning and sincere obedience", "Excessive questioning and disagreement with their prophets", "Seeking clarification and accepting guidance", "Limited ability and use of a lawful concession"], "correct": 1, "feedback": ["The supported answer is: Excessive questioning and disagreement with their prophets. Both excessive questioning and disagreement appear in the final sentence.", "Both excessive questioning and disagreement appear in the final sentence.", "The supported answer is: Excessive questioning and disagreement with their prophets. Both excessive questioning and disagreement appear in the final sentence.", "The supported answer is: Excessive questioning and disagreement with their prophets. Both excessive questioning and disagreement appear in the final sentence."], "hint": "Do not omit the second element of the warning.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4725", "evidence": {"label": "Published English selection", "text": "Indeed, those before you were ruined because of their excessive questioning and disagreeing with their prophets.\"", "url": "https://hadeethenc.com/en/browse/hadith/4725", "anchor": "disagreeing with their prophets", "field": "T"}}, {"id": "4725-focus-mc-5", "q": "Which conduct reflects the additional instruction concerning prohibited acts?", "options": ["Arranging its means while claiming to reject only the final step", "Avoiding means that lead to the prohibited act", "Allowing it whenever the amount is small", "Treating sincere questions as forbidden acts"], "correct": 1, "feedback": ["The supported answer is: Avoiding means that lead to the prohibited act. The sixth benefit expressly includes shunning the means conducive to the prohibition.", "The sixth benefit expressly includes shunning the means conducive to the prohibition.", "The supported answer is: Avoiding means that lead to the prohibited act. The sixth benefit expressly includes shunning the means conducive to the prohibition.", "The supported answer is: Avoiding means that lead to the prohibited act. The sixth benefit expressly includes shunning the means conducive to the prohibition."], "hint": "Read the benefit that expands the meaning of avoidance.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4725", "evidence": {"label": "Published benefit 6", "text": "We are required to shun the means conducive to something prohibited, for this falls under the meaning of avoidance.", "url": "https://hadeethenc.com/en/browse/hadith/4725", "anchor": "means conducive", "field": "B6"}}], "coverage": {"focusedAnswers": 4, "thematicQuestions": 5, "completeSanadProvided": false, "topics": [{"point": "Avoid prohibitions and perform commands within ability", "qa": [1], "mcq": [1]}, {"point": "Necessary learning distinguished from obstinate questioning", "qa": [2], "mcq": [2]}, {"point": "Excessive questioning and disagreement with earlier prophets", "qa": [2], "mcq": [4]}, {"point": "Avoidance includes small amounts and means leading to a prohibition", "qa": [3, 4], "mcq": [3, 5]}]}, "source": "https://hadeethenc.com/en/browse/hadith/4725"}, "6078": {"revision": "topic001-coverage-2026-10-17", "narrator": "Anas ibn Malik", "qa": [{"id": "6078-focus-qa-1", "group": "Meaning and understanding", "q": "Why were the proposed commitments corrected despite the Companions' desire for worship?", "a": "They reasoned that they needed greater severity because the Prophet's sins had been forgiven. He corrected the idea of seeking greater perfection outside his example: he prayed and slept, fasted and broke the fast, and married. Their good aim did not make an excessive method the better path.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/6078", "evidence": {"label": "Published explanation", "text": "Whoever turns away from my way, sees perfection in something else, and follows a path other than that of mine does not belong to me.", "url": "https://hadeethenc.com/en/browse/hadith/6078", "anchor": "sees perfection in something else", "field": "E"}}, {"id": "6078-focus-qa-2", "group": "Meaning and understanding", "q": "What kind of balance does the source recommend?", "a": "Its benefits recommend maintaining worship, including obligatory and voluntary acts, while fulfilling others' rights. Moderation is not idleness, and devotion is not measured by abandoning every lawful need. The Prophet's household life and worship provide the model discussed in this account.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/6078", "evidence": {"label": "Published benefit 8", "text": "The command to be lenient in worship while maintaining it along with the obligatory and voluntary acts, so that a Muslim can fulfill the rights of others upon him.", "url": "https://hadeethenc.com/en/browse/hadith/6078", "anchor": "rights of others", "field": "B8"}}, {"id": "6078-focus-qa-3", "group": "Meaning and understanding", "q": "How did the Prophet correct the mistaken proposals without making greater hardship the goal?", "a": "He addressed the proposals in a sermon and described his own balanced practice. The explanation links rest and breaking the fast with strength for further worship, so lawful human needs support devotion rather than oppose it.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/6078", "evidence": {"label": "Published explanation", "text": "By Allah, I am the most fearful of Allah among you and the most conscious of Him, but I sleep to strengthen myself for standing in prayer, I break my fast to strengthen myself for fasting, and I marry women.", "url": "https://hadeethenc.com/en/browse/hadith/6078", "anchor": "strengthen myself", "field": "E"}}], "mcq": [{"id": "6078-focus-mc-1", "q": "What assumption led them toward excessive commitments?", "options": ["They thought they needed greater severity because he was forgiven", "They thought all voluntary worship had been prohibited", "They thought the Prophet never performed private worship", "They thought marriage was a condition of receiving revelation"], "correct": 0, "feedback": ["The explanation identifies their reasoning and the Prophet's correction of it.", "The supported answer is: They thought they needed greater severity because he was forgiven. The explanation identifies their reasoning and the Prophet's correction of it.", "The supported answer is: They thought they needed greater severity because he was forgiven. The explanation identifies their reasoning and the Prophet's correction of it.", "The supported answer is: They thought they needed greater severity because he was forgiven. The explanation identifies their reasoning and the Prophet's correction of it."], "hint": "Look at how they compared their situation with his.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6078", "evidence": {"label": "Published explanation", "text": "His past and future sins have been forgiven, unlike those who do not know if they have attained forgiveness, so they need to exaggerate in worship in the hope of attaining it.", "url": "https://hadeethenc.com/en/browse/hadith/6078", "anchor": "past and future sins", "field": "E"}}, {"id": "6078-focus-mc-2", "q": "How do the benefits explain moderation in worship?", "options": ["Replace voluntary worship with permanent inactivity", "Choose the most exhausting routine regardless of consequences", "Maintain worship while fulfilling the rights of others", "Measure devotion only by abstaining from lawful things"], "correct": 2, "feedback": ["The supported answer is: Maintain worship while fulfilling the rights of others. The eighth benefit joins continued worship with fulfilling others' rights.", "The supported answer is: Maintain worship while fulfilling the rights of others. The eighth benefit joins continued worship with fulfilling others' rights.", "The eighth benefit joins continued worship with fulfilling others' rights.", "The supported answer is: Maintain worship while fulfilling the rights of others. The eighth benefit joins continued worship with fulfilling others' rights."], "hint": "Look for the benefit about rights as well as personal devotion.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6078", "evidence": {"label": "Published benefit 8", "text": "The command to be lenient in worship while maintaining it along with the obligatory and voluntary acts, so that a Muslim can fulfill the rights of others upon him.", "url": "https://hadeethenc.com/en/browse/hadith/6078", "anchor": "rights of others", "field": "B8"}}, {"id": "6078-focus-mc-3", "q": "How does the explanation connect sleep and breaking the fast with worship?", "options": ["They provide strength for further prayer and fasting", "They are concessions that the Prophet never used himself", "They remove the need for any further worship", "They are presented as the goal replacing worship"], "correct": 0, "feedback": ["The explanation makes lawful rest and nourishment supports for continued devotion.", "The supported answer is: They provide strength for further prayer and fasting. The explanation makes lawful rest and nourishment supports for continued devotion.", "The supported answer is: They provide strength for further prayer and fasting. The explanation makes lawful rest and nourishment supports for continued devotion.", "The supported answer is: They provide strength for further prayer and fasting. The explanation makes lawful rest and nourishment supports for continued devotion."], "hint": "Look at the purpose attached to his own balanced practice.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6078", "evidence": {"label": "Published explanation", "text": "By Allah, I am the most fearful of Allah among you and the most conscious of Him, but I sleep to strengthen myself for standing in prayer, I break my fast to strengthen myself for fasting, and I marry women.", "url": "https://hadeethenc.com/en/browse/hadith/6078", "anchor": "strengthen myself", "field": "E"}}], "coverage": {"focusedAnswers": 3, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "The companions' concern and mistaken reasoning about forgiveness", "qa": [1], "mcq": [1]}, {"point": "Prayer and sleep, fasting and eating, and marriage within the Sunnah", "qa": [1, 3], "mcq": [1, 3]}, {"point": "Moderation sustains obligatory and voluntary worship and others' rights", "qa": [2, 3], "mcq": [2, 3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/6078"}, "65121": {"revision": "topic001-coverage-2026-10-17", "narrator": "Aishah", "qa": [{"id": "65121-focus-qa-1", "group": "Meaning and understanding", "q": "Why did manageable deeds not indicate a lower level of devotion?", "a": "The Companions asked for harder deeds, reasoning from the Prophet's forgiven status. He answered that he knew Allah best and feared Him most. The explanation connects manageable commands with consistency. Knowing Allah and revering Him therefore support following this guidance, rather than treating severity itself as the measure of devotion.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65121", "evidence": {"label": "Published explanation", "text": "The Mother of the Believers ‘Ā’ishah (may Allah be pleased with her) informs that the Prophet (ﷺ), when commanding people to perform deeds, would instruct them to do only what was easy for them and not burdensome—out of concern that they might be unable to maintain it consistently.", "url": "https://hadeethenc.com/en/browse/hadith/65121", "anchor": "maintain it consistently", "field": "E"}}, {"id": "65121-focus-qa-2", "group": "Meaning and understanding", "q": "Does a high spiritual standing justify giving up further effort?", "a": "No. The benefits say that a righteous person should not rely on righteousness and stop striving. They describe preserving and increasing the blessing of worship through continued practice and gratitude.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65121", "evidence": {"label": "Published benefit 2", "text": "A righteous man should not abandon striving in good deeds, relying merely on his righteousness.", "url": "https://hadeethenc.com/en/browse/hadith/65121", "anchor": "should not abandon", "field": "B2"}}, {"id": "65121-focus-qa-3", "group": "Meaning and understanding", "q": "How does the source distinguish stating a virtue for a purpose from arrogant self-praise?", "a": "The third benefit permits mentioning a personal virtue when there is a need and the speaker is safe from pride. In this account, the Prophet's statement corrects a mistaken assumption about knowledge of Allah and the harder path in worship.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65121", "evidence": {"label": "Published benefit 3", "text": "It is permissible for a person to speak about his own virtue when there is a need to do so, provided he is safe from pride and arrogance.", "url": "https://hadeethenc.com/en/browse/hadith/65121", "anchor": "pride and arrogance", "field": "B3"}}], "mcq": [{"id": "65121-focus-mc-1", "q": "How did he answer the assumption that easier guidance implied lesser devotion?", "options": ["He accepted that hardship alone measures religious rank", "He withdrew the guidance because it was too easy", "He affirmed his greater knowledge of Allah and fear of Him", "He said knowledge of Allah removes the need for deeds"], "correct": 2, "feedback": ["The supported answer is: He affirmed his greater knowledge of Allah and fear of Him. His reply corrects the idea that moderation results from less knowledge or reverence.", "The supported answer is: He affirmed his greater knowledge of Allah and fear of Him. His reply corrects the idea that moderation results from less knowledge or reverence.", "His reply corrects the idea that moderation results from less knowledge or reverence.", "The supported answer is: He affirmed his greater knowledge of Allah and fear of Him. His reply corrects the idea that moderation results from less knowledge or reverence."], "hint": "Notice the two qualities he names about himself.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65121", "evidence": {"label": "Published English selection", "text": "He would then become angry until his anger would be visible on his face, and say: \"Indeed, I am the most God-fearing among you and the most knowledgeable of Allah.\"", "url": "https://hadeethenc.com/en/browse/hadith/65121", "anchor": "most God-fearing", "field": "T"}}, {"id": "65121-focus-mc-2", "q": "What is the source's stated benefit of manageable commands?", "options": ["They can be practiced consistently", "They eliminate the distinction between duties and preferences", "They make every voluntary deed obligatory", "They require identical routines for all people"], "correct": 0, "feedback": ["The explanation links manageable practice with maintaining deeds rather than abandoning them.", "The supported answer is: They can be practiced consistently. The explanation links manageable practice with maintaining deeds rather than abandoning them.", "The supported answer is: They can be practiced consistently. The explanation links manageable practice with maintaining deeds rather than abandoning them.", "The supported answer is: They can be practiced consistently. The explanation links manageable practice with maintaining deeds rather than abandoning them."], "hint": "Look for the concern about continuity.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65121", "evidence": {"label": "Published explanation", "text": "The Mother of the Believers ‘Ā’ishah (may Allah be pleased with her) informs that the Prophet (ﷺ), when commanding people to perform deeds, would instruct them to do only what was easy for them and not burdensome—out of concern that they might be unable to maintain it consistently.", "url": "https://hadeethenc.com/en/browse/hadith/65121", "anchor": "maintain it consistently", "field": "E"}}, {"id": "65121-focus-mc-3", "q": "Which response to an advanced spiritual standing matches the benefits?", "options": ["Stop striving because previous righteousness is enough", "Seek increasingly severe acts regardless of capacity", "Continue good deeds and preserve the blessing through gratitude", "Treat manageable worship as evidence of deficient knowledge"], "correct": 2, "feedback": ["The supported answer is: Continue good deeds and preserve the blessing through gratitude. The benefits reject relying on righteousness as a reason to abandon further effort.", "The supported answer is: Continue good deeds and preserve the blessing through gratitude. The benefits reject relying on righteousness as a reason to abandon further effort.", "The benefits reject relying on righteousness as a reason to abandon further effort.", "The supported answer is: Continue good deeds and preserve the blessing through gratitude. The benefits reject relying on righteousness as a reason to abandon further effort."], "hint": "Distinguish gratitude for a blessing from becoming complacent about it.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65121", "evidence": {"label": "Published benefit 2", "text": "A righteous man should not abandon striving in good deeds, relying merely on his righteousness.", "url": "https://hadeethenc.com/en/browse/hadith/65121", "anchor": "should not abandon", "field": "B2"}}], "coverage": {"focusedAnswers": 3, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Knowledge and fear of Allah support manageable Prophetic guidance", "qa": [1], "mcq": [1]}, {"point": "Consistency instead of exhausting severity", "qa": [1], "mcq": [2]}, {"point": "Spiritual standing does not replace continued effort and gratitude", "qa": [2], "mcq": [3]}, {"point": "Mentioning a virtue to correct a misunderstanding without arrogance", "qa": [3], "mcq": [1]}]}, "source": "https://hadeethenc.com/en/browse/hadith/65121"}, "5518": {"revision": "topic001-coverage-2026-10-17", "narrator": "Muawiyah", "qa": [{"id": "5518-focus-qa-1", "group": "Meaning and understanding", "q": "What is meant by understanding the religion as a sign of good?", "a": "The report identifies understanding the religion as a gift from Allah. The benefits consequently urge seeking and learning religious knowledge. Its focus is understanding the guidance, rather than equating religious good with collecting information, public recognition, or success in argument.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/5518", "evidence": {"label": "Published English selection", "text": "Mu‘āwiyah (may Allah be pleased with him) reported: I heard the Prophet (may Allah's peace and blessings be upon him) say: \"When Allah intends good for someone, He grants him the understanding of the religion.", "url": "https://hadeethenc.com/en/browse/hadith/5518", "anchor": "understanding of the religion", "field": "T"}}, {"id": "5518-focus-qa-2", "group": "Meaning and understanding", "q": "Why does the Prophet distinguish distributing from giving?", "a": "He describes himself as a distributor and Allah as the Giver. The explanation includes sustenance and knowledge among what Allah granted him to distribute. The distinction recognizes the means through which a benefit arrives while affirming its dependence on Allah.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/5518", "evidence": {"label": "Published explanation", "text": "He also states that he is only a distributor who distributes the sustenance, knowledge, and other things that Allah Almighty gave him, and that the true Giver is Allah, and all else are mere causes that can only bring benefit with Allah's permission.", "url": "https://hadeethenc.com/en/browse/hadith/5518", "anchor": "sustenance, knowledge", "field": "E"}}, {"id": "5518-focus-qa-3", "group": "Meaning and understanding", "q": "What continuity does the closing assurance concern?", "a": "It concerns continued adherence to Allah's laws within the Ummah despite opposition. The benefits explain that if one group forsakes the truth, another will follow it. This is not a statement that every member will always agree or that believers will experience no worldly difficulty.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/5518", "evidence": {"label": "Published benefit 2", "text": "If one group forsakes it, another will follow it.", "url": "https://hadeethenc.com/en/browse/hadith/5518", "anchor": "another will follow", "field": "B2"}}], "mcq": [{"id": "5518-focus-mc-1", "q": "What is a sign that Allah intends good for a person?", "options": ["Remembering names without understanding", "A reputation for winning arguments", "A large number of listeners alone", "Understanding the religion"], "correct": 3, "feedback": ["The supported answer is: Understanding the religion. The report explicitly names understanding of the religion as this gift.", "The supported answer is: Understanding the religion. The report explicitly names understanding of the religion as this gift.", "The supported answer is: Understanding the religion. The report explicitly names understanding of the religion as this gift.", "The report explicitly names understanding of the religion as this gift."], "hint": "Identify the gift in the opening sentence.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5518", "evidence": {"label": "Published English selection", "text": "Mu‘āwiyah (may Allah be pleased with him) reported: I heard the Prophet (may Allah's peace and blessings be upon him) say: \"When Allah intends good for someone, He grants him the understanding of the religion.", "url": "https://hadeethenc.com/en/browse/hadith/5518", "anchor": "understanding of the religion", "field": "T"}}, {"id": "5518-focus-mc-2", "q": "How are the roles of distributor and Giver distinguished?", "options": ["The Prophet gives independently; Allah only witnesses", "The audience gives authority to both roles", "The Prophet distributes; Allah is the true Giver", "The narrator replaces both roles through transmission"], "correct": 2, "feedback": ["The supported answer is: The Prophet distributes; Allah is the true Giver. The explanation treats created means as dependent on Allah's giving and permission.", "The supported answer is: The Prophet distributes; Allah is the true Giver. The explanation treats created means as dependent on Allah's giving and permission.", "The explanation treats created means as dependent on Allah's giving and permission.", "The supported answer is: The Prophet distributes; Allah is the true Giver. The explanation treats created means as dependent on Allah's giving and permission."], "hint": "Keep the stated roles distinct without separating them from Allah's will.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5518", "evidence": {"label": "Published English selection", "text": "Indeed, I am only a distributor, and Allah is the Giver.", "url": "https://hadeethenc.com/en/browse/hadith/5518", "anchor": "Allah is the Giver", "field": "T"}}, {"id": "5518-focus-mc-3", "q": "What assurance does the final part of the report give?", "options": ["Every member will always agree on every question", "No believer will ever experience opposition", "Religious understanding will become unnecessary", "Adherence to Allah's laws will continue within the Ummah"], "correct": 3, "feedback": ["The supported answer is: Adherence to Allah's laws will continue within the Ummah. The benefit clarifies that adherence persists: if one group abandons it, another follows it.", "The supported answer is: Adherence to Allah's laws will continue within the Ummah. The benefit clarifies that adherence persists: if one group abandons it, another follows it.", "The supported answer is: Adherence to Allah's laws will continue within the Ummah. The benefit clarifies that adherence persists: if one group abandons it, another follows it.", "The benefit clarifies that adherence persists: if one group abandons it, another follows it."], "hint": "Distinguish continuing adherence from universal agreement.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5518", "evidence": {"label": "Published benefit 2", "text": "If one group forsakes it, another will follow it.", "url": "https://hadeethenc.com/en/browse/hadith/5518", "anchor": "another will follow", "field": "B2"}}], "coverage": {"focusedAnswers": 3, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Understanding religion as Allah's gift and a reason to seek knowledge", "qa": [1], "mcq": [1]}, {"point": "The Prophet as distributor and Allah as the true Giver", "qa": [2], "mcq": [2]}, {"point": "Continuing adherence to truth despite opposition", "qa": [3], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/5518"}, "4233": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Musa al-Ashari", "qa": [{"id": "4233-focus-qa-1", "group": "Meaning and understanding", "q": "What distinguishes the three responses represented by the land?", "a": "Fertile ground represents understanding, practicing, and teaching guidance. Water-retaining ground represents preserving knowledge from which others benefit, even without the same depth of understanding. Barren ground represents neither retaining the guidance nor benefiting oneself or others through it. The same rain produces different results because its recipients respond differently.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4233", "evidence": {"label": "Published explanation", "text": "This land, in turn, is of three types: The first type: a pure and fertile land that absorbs the rainwater, causing abundant vegetation—both fresh and dry—to grow, from which people benefit.", "url": "https://hadeethenc.com/en/browse/hadith/4233", "anchor": "three types", "field": "E"}}, {"id": "4233-focus-qa-2", "group": "Meaning and understanding", "q": "Why is preserving knowledge still valuable when another person understands it more deeply?", "a": "The second type of ground does not grow vegetation but keeps water available for others. The explanation uses this to show the benefit of preserving and transmitting knowledge without claiming the highest level of deduction. The parable values that contribution while also showing the fuller benefit of understanding and practice.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4233", "evidence": {"label": "Published explanation", "text": "The second type: land that holds water but does not grow vegetation.", "url": "https://hadeethenc.com/en/browse/hadith/4233", "anchor": "holds water", "field": "E"}}], "mcq": [{"id": "4233-focus-mc-1", "q": "What benefit does water-retaining ground provide?", "options": ["Vegetation produced without holding any water", "No benefit until it becomes fertile soil itself", "Water that others use for drinking and cultivation", "Protection from every future period of drought"], "correct": 2, "feedback": ["The supported answer is: Water that others use for drinking and cultivation. The second type remains beneficial even though it does not itself produce vegetation.", "The supported answer is: Water that others use for drinking and cultivation. The second type remains beneficial even though it does not itself produce vegetation.", "The second type remains beneficial even though it does not itself produce vegetation.", "The supported answer is: Water that others use for drinking and cultivation. The second type remains beneficial even though it does not itself produce vegetation."], "hint": "Notice how others benefit from what is preserved.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4233", "evidence": {"label": "Published English selection", "text": "A part of it was good, absorbing the water, so it brought forth abundant herbage and pasture; and there were some bare patches in it that retained the water by which Allah gave benefit to people who drank, watered, and grew plants.", "url": "https://hadeethenc.com/en/browse/hadith/4233", "anchor": "drank, watered, and grew plants", "field": "T"}}, {"id": "4233-focus-mc-2", "q": "Which person corresponds most fully to the fertile ground?", "options": ["One who preserves material for others without deep understanding", "One who understands, practices, and teaches the guidance", "One who neither preserves nor acts on what they hear", "One who declines to receive the guidance"], "correct": 1, "feedback": ["The supported answer is: One who understands, practices, and teaches the guidance. The explanation joins understanding, action, and teaching in its first human category.", "The explanation joins understanding, action, and teaching in its first human category.", "The supported answer is: One who understands, practices, and teaches the guidance. The explanation joins understanding, action, and teaching in its first human category.", "The supported answer is: One who understands, practices, and teaches the guidance. The explanation joins understanding, action, and teaching in its first human category."], "hint": "Match all three characteristics rather than only memory.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4233", "evidence": {"label": "Published explanation", "text": "The first type: the scholar who understands the religion of Allah, acts upon his knowledge, and teaches it to others.", "url": "https://hadeethenc.com/en/browse/hadith/4233", "anchor": "acts upon his knowledge", "field": "E"}}, {"id": "4233-focus-mc-3", "q": "Which response corresponds to the barren ground?", "options": ["Memorizing a report so another person can study it", "Understanding guidance and applying it", "Neither preserving, practicing, nor conveying the guidance", "Teaching what one has understood accurately"], "correct": 2, "feedback": ["The supported answer is: Neither preserving, practicing, nor conveying the guidance. The third type provides neither personal benefit nor benefit to others from the knowledge received.", "The supported answer is: Neither preserving, practicing, nor conveying the guidance. The third type provides neither personal benefit nor benefit to others from the knowledge received.", "The third type provides neither personal benefit nor benefit to others from the knowledge received.", "The supported answer is: Neither preserving, practicing, nor conveying the guidance. The third type provides neither personal benefit nor benefit to others from the knowledge received."], "hint": "Consider what is absent in both the land and the human response.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4233", "evidence": {"label": "Published explanation", "text": "The third type: the one who hears knowledge but neither preserves it, nor acts upon it, nor conveys it to others.", "url": "https://hadeethenc.com/en/browse/hadith/4233", "anchor": "neither preserves it", "field": "E"}}, {"id": "4233-focus-mc-4", "q": "What corresponds to the rain itself in the parable?", "options": ["The different ambitions of competing teachers", "The material wealth retained by each listener", "The praise that follows a public lesson", "The guidance and knowledge with which the Prophet was sent"], "correct": 3, "feedback": ["The supported answer is: The guidance and knowledge with which the Prophet was sent. The opening comparison identifies the rain with guidance and knowledge; the ground represents differing responses.", "The supported answer is: The guidance and knowledge with which the Prophet was sent. The opening comparison identifies the rain with guidance and knowledge; the ground represents differing responses.", "The supported answer is: The guidance and knowledge with which the Prophet was sent. The opening comparison identifies the rain with guidance and knowledge; the ground represents differing responses.", "The opening comparison identifies the rain with guidance and knowledge; the ground represents differing responses."], "hint": "Separate what falls on the ground from the ground's response.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4233", "evidence": {"label": "Published English selection", "text": "Abu Mūsa (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"The guidance and knowledge with which Allah has sent me are like abundant rain that fell on some ground.", "url": "https://hadeethenc.com/en/browse/hadith/4233", "anchor": "guidance and knowledge", "field": "T"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 4, "completeSanadProvided": false, "topics": [{"point": "Guidance and knowledge compared to the same life-giving rain", "qa": [1], "mcq": [4]}, {"point": "Fertile ground: understanding, acting and teaching", "qa": [1], "mcq": [2]}, {"point": "Water-retaining ground: preservation benefiting other people", "qa": [2], "mcq": [1]}, {"point": "Barren ground: neither retaining nor conveying benefit", "qa": [1], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/4233"}, "6820": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abdullah ibn Masud", "qa": [{"id": "6820-focus-qa-1", "group": "Meaning and understanding", "q": "Why can the recipient of a hadith understand more than its first hearer?", "a": "Faithful preservation and deep comprehension are related but distinct abilities. The transmitter may convey accurately, while a recipient has greater insight or ability to derive rulings. The report honors reliable transmission without making the first hearer automatically the strongest interpreter.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/6820", "evidence": {"label": "Published explanation", "text": "Perhaps the one to whom the Hadīth is conveyed understands it better, has deeper insight, and is more capable of deriving rulings than the one who originally transmitted it.", "url": "https://hadeethenc.com/en/browse/hadith/6820", "anchor": "deeper insight", "field": "E"}}, {"id": "6820-focus-qa-2", "group": "Meaning and understanding", "q": "How does the source understand preservation for faithful transmission?", "a": "The benefits include both preservation in memory and preservation in writing. These serve conveying the teaching accurately. The distinction also explains why a person's strength in transmission need not mean that they can independently derive every ruling contained in a report.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/6820", "evidence": {"label": "Published benefit 7", "text": "Memorization, according to the scholars of Hadīth, is of two types: memorization of the heart and mind, and memorization through writing in books and lines.", "url": "https://hadeethenc.com/en/browse/hadith/6820", "anchor": "two types", "field": "B7"}}, {"id": "6820-focus-qa-3", "group": "Meaning and understanding", "q": "What does the opening supplication add to the instruction about accurate transmission?", "a": "It honors the person who hears, preserves and conveys the teaching faithfully. The explanation describes brightness and joy in this life and radiance in the Hereafter, making faithful transmission a valued religious service.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/6820", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) prayed for brightness, joy, and beauty in this world, and that Allah grants the person the radiance, bliss, and bloom of Paradise in the Hereafter for whoever hears his Hadīth and memorizes it to convey it to others.", "url": "https://hadeethenc.com/en/browse/hadith/6820", "anchor": "brightness", "field": "E"}}], "mcq": [{"id": "6820-focus-mc-1", "q": "Why can a recipient understand more than the original hearer?", "options": ["Later hearers automatically receive new revelation", "Being first to hear guarantees complete understanding", "Memorization makes interpretation unnecessary for every recipient", "People differ in understanding and ability to derive rulings"], "correct": 3, "feedback": ["The supported answer is: People differ in understanding and ability to derive rulings. The report distinguishes faithful transmission from depth of comprehension.", "The supported answer is: People differ in understanding and ability to derive rulings. The report distinguishes faithful transmission from depth of comprehension.", "The supported answer is: People differ in understanding and ability to derive rulings. The report distinguishes faithful transmission from depth of comprehension.", "The report distinguishes faithful transmission from depth of comprehension."], "hint": "Compare the transmitter's role with the recipient's possible strength.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6820", "evidence": {"label": "Published explanation", "text": "Perhaps the one to whom the Hadīth is conveyed understands it better, has deeper insight, and is more capable of deriving rulings than the one who originally transmitted it.", "url": "https://hadeethenc.com/en/browse/hadith/6820", "anchor": "deeper insight", "field": "E"}}, {"id": "6820-focus-mc-2", "q": "Which forms of preservation do the benefits recognize?", "options": ["Memory and writing", "Memory alone, excluding written records", "Writing alone, excluding remembered material", "Public recitation alone, excluding private study"], "correct": 0, "feedback": ["The seventh benefit includes preservation in mind and in books.", "The supported answer is: Memory and writing. The seventh benefit includes preservation in mind and in books.", "The supported answer is: Memory and writing. The seventh benefit includes preservation in mind and in books.", "The supported answer is: Memory and writing. The seventh benefit includes preservation in mind and in books."], "hint": "Look for the two types of memorization described.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6820", "evidence": {"label": "Published benefit 7", "text": "Memorization, according to the scholars of Hadīth, is of two types: memorization of the heart and mind, and memorization through writing in books and lines.", "url": "https://hadeethenc.com/en/browse/hadith/6820", "anchor": "two types", "field": "B7"}}, {"id": "6820-focus-mc-3", "q": "Which transmission best reflects the wording of the supplication?", "options": ["Improving a report by adding a more dramatic promise", "Conveying the teaching as it was heard, without altering its attribution", "Treating a popular paraphrase as the Prophet's exact words", "Omitting a qualification because the recipient may understand more"], "correct": 1, "feedback": ["The supported answer is: Conveying the teaching as it was heard, without altering its attribution. The report praises hearing and conveying faithfully; deeper understanding is not permission to alter the message.", "The report praises hearing and conveying faithfully; deeper understanding is not permission to alter the message.", "The supported answer is: Conveying the teaching as it was heard, without altering its attribution. The report praises hearing and conveying faithfully; deeper understanding is not permission to alter the message.", "The supported answer is: Conveying the teaching as it was heard, without altering its attribution. The report praises hearing and conveying faithfully; deeper understanding is not permission to alter the message."], "hint": "Connect the prayer for the transmitter with the phrase about how to convey.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6820", "evidence": {"label": "Published English selection", "text": "‘Abdullah ibn Mas‘ūd (may Allah be pleased with him) reported: I heard the Prophet (may Allah's peace and blessings be upon him) say: \"May Allah brighten the person who hears something from us and conveys it as he heard it, for perhaps the one to whom it is conveyed is more mindful than the hearer.\"", "url": "https://hadeethenc.com/en/browse/hadith/6820", "anchor": "as he heard it", "field": "T"}}], "coverage": {"focusedAnswers": 3, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "The supplication honoring faithful hearing, preservation and conveyance", "qa": [3], "mcq": [3]}, {"point": "Recipient's greater understanding without altering the transmitted text", "qa": [1], "mcq": [1, 3]}, {"point": "Preservation through memory and writing, distinct from deduction", "qa": [2], "mcq": [2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/6820"}, "3686": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abdullah ibn Amr", "qa": [{"id": "3686-focus-qa-1", "group": "Meaning and understanding", "q": "How does conveying even a little remain compatible with responsible teaching?", "a": "The explanation permits passing on a small amount, provided the person knows what they convey. The closing warning against deliberate false attribution makes accuracy essential. Limited knowledge is not a reason to invent missing material, but neither must a learner know everything before responsibly sharing something verified.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3686", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) commands us to convey knowledge from him, from the Qur’an or the Sunnah, even if it is something short, like a verse from the Qur’an or a Hadīth, provided that a person should have knowledge of what he conveys and invites people to it.", "url": "https://hadeethenc.com/en/browse/hadith/3686", "anchor": "knowledge of what he conveys", "field": "E"}}, {"id": "3686-focus-qa-2", "group": "Meaning and understanding", "q": "What limit applies to narrating accounts of the Children of Israel?", "a": "The explanation permits such narration when it does not conflict with the Shariah. Permission to mention an account is not a declaration that every earlier story is authenticated as Prophetic teaching. The distinction matters when selecting historical or illustrative material for a lesson.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3686", "evidence": {"label": "Published explanation", "text": "Then, the Prophet (may Allah's peace and blessings be upon him) points out that there is no sin in narrating about the Children of Israel and the events that happened to them, in a way that does not run counter to our Shariah.", "url": "https://hadeethenc.com/en/browse/hadith/3686", "anchor": "does not run counter", "field": "E"}}], "mcq": [{"id": "3686-focus-mc-1", "q": "What does even one verse emphasize about conveying knowledge?", "options": ["A small amount of known teaching can be conveyed", "Any remembered phrase may be attributed without checking", "Only complete books may be taught", "A speaker may fill missing words from personal judgment"], "correct": 0, "feedback": ["The explanation permits conveying something short while requiring knowledge of what is conveyed.", "The supported answer is: A small amount of known teaching can be conveyed. The explanation permits conveying something short while requiring knowledge of what is conveyed.", "The supported answer is: A small amount of known teaching can be conveyed. The explanation permits conveying something short while requiring knowledge of what is conveyed.", "The supported answer is: A small amount of known teaching can be conveyed. The explanation permits conveying something short while requiring knowledge of what is conveyed."], "hint": "Read the qualification attached to passing on a little.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3686", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) commands us to convey knowledge from him, from the Qur’an or the Sunnah, even if it is something short, like a verse from the Qur’an or a Hadīth, provided that a person should have knowledge of what he conveys and invites people to it.", "url": "https://hadeethenc.com/en/browse/hadith/3686", "anchor": "knowledge of what he conveys", "field": "E"}}, {"id": "3686-focus-mc-2", "q": "How does the source qualify narrating accounts of the Children of Israel?", "options": ["Every such account is automatically an authenticated hadith", "They replace the need for Quranic guidance", "Their dramatic effect is enough to establish their truth", "They must not conflict with the Shariah"], "correct": 3, "feedback": ["The supported answer is: They must not conflict with the Shariah. The explanation gives permission with a stated limit, not blanket authentication of every account.", "The supported answer is: They must not conflict with the Shariah. The explanation gives permission with a stated limit, not blanket authentication of every account.", "The supported answer is: They must not conflict with the Shariah. The explanation gives permission with a stated limit, not blanket authentication of every account.", "The explanation gives permission with a stated limit, not blanket authentication of every account."], "hint": "Notice the condition in the explanation of this permission.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3686", "evidence": {"label": "Published explanation", "text": "Then, the Prophet (may Allah's peace and blessings be upon him) points out that there is no sin in narrating about the Children of Israel and the events that happened to them, in a way that does not run counter to our Shariah.", "url": "https://hadeethenc.com/en/browse/hadith/3686", "anchor": "does not run counter", "field": "E"}}, {"id": "3686-focus-mc-3", "q": "What must be checked before spreading a hadith according to the benefits?", "options": ["Whether it is emotionally moving", "Whether it has been shared many times", "Its authentic attribution", "Whether its wording fits a preferred argument"], "correct": 2, "feedback": ["The supported answer is: Its authentic attribution. The third benefit explicitly requires ascertainment of authenticity.", "The supported answer is: Its authentic attribution. The third benefit explicitly requires ascertainment of authenticity.", "The third benefit explicitly requires ascertainment of authenticity.", "The supported answer is: Its authentic attribution. The third benefit explicitly requires ascertainment of authenticity."], "hint": "Read the responsibility paired with the encouragement to convey.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3686", "evidence": {"label": "Published benefit 3", "text": "We are obligated to ascertain the authenticity of any Hadīth before we convey and spread it, lest we fall under this stern warning.", "url": "https://hadeethenc.com/en/browse/hadith/3686", "anchor": "ascertain the authenticity", "field": "B3"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Convey even a little with knowledge and responsible attribution", "qa": [1], "mcq": [1, 3]}, {"point": "Accounts of the Children of Israel and their stated limit", "qa": [2], "mcq": [2]}, {"point": "The warning against intentional falsehood and need to verify reports", "qa": [1], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/3686"}, "65043": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Hurayrah", "qa": [{"id": "65043-focus-qa-1", "group": "Meaning and understanding", "q": "Why can an uplifting purpose not justify inventing a hadith?", "a": "The warning concerns deliberately attributing a false statement or action to the Prophet. A desirable lesson does not make that attribution true. The benefits emphasize its serious religious and worldly consequences and require verification before a report is spread.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65043", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) clarified that whoever deliberately tells a lie about him, by falsely attributing a statement or action to him, will have a seat in Hellfire in the Hereafter as a recompense for lying about him.", "url": "https://hadeethenc.com/en/browse/hadith/65043", "anchor": "statement or action", "field": "E"}}], "mcq": [{"id": "65043-focus-mc-1", "q": "Does an uplifting purpose make a knowingly invented hadith acceptable?", "options": ["No; the good aim does not remove deliberate false attribution", "Yes, when it encourages a popular virtue", "Yes, when its wording resembles authentic teaching", "Yes, when no financial benefit is involved"], "correct": 0, "feedback": ["The warning is against intentional false attribution; it gives no exception for an attractive message.", "The supported answer is: No; the good aim does not remove deliberate false attribution. The warning is against intentional false attribution; it gives no exception for an attractive message.", "The supported answer is: No; the good aim does not remove deliberate false attribution. The warning is against intentional false attribution; it gives no exception for an attractive message.", "The supported answer is: No; the good aim does not remove deliberate false attribution. The warning is against intentional false attribution; it gives no exception for an attractive message."], "hint": "Distinguish a useful message from a truthful attribution.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65043", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever tells a lie about me intentionally, let him take his seat in Hellfire.\"", "url": "https://hadeethenc.com/en/browse/hadith/65043", "anchor": "Whoever tells a lie", "field": "T"}}, {"id": "65043-focus-mc-2", "q": "Which fabricated item falls within the explanation of lying about the Prophet?", "options": ["Only a quotation placed inside quotation marks", "Only an error in a modern author's personal biography", "Only a statement falsely attributed to an unnamed companion", "An invented action attributed to him as well as invented speech"], "correct": 3, "feedback": ["The supported answer is: An invented action attributed to him as well as invented speech. The explanation expressly includes both a statement and an action.", "The supported answer is: An invented action attributed to him as well as invented speech. The explanation expressly includes both a statement and an action.", "The supported answer is: An invented action attributed to him as well as invented speech. The explanation expressly includes both a statement and an action.", "The explanation expressly includes both a statement and an action."], "hint": "Do not reduce false attribution to a single written format.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65043", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) clarified that whoever deliberately tells a lie about him, by falsely attributing a statement or action to him, will have a seat in Hellfire in the Hereafter as a recompense for lying about him.", "url": "https://hadeethenc.com/en/browse/hadith/65043", "anchor": "statement or action", "field": "E"}}], "coverage": {"focusedAnswers": 1, "thematicQuestions": 2, "completeSanadProvided": false, "topics": [{"point": "Deliberately inventing speech or actions attributed to the Prophet", "qa": [1], "mcq": [1, 2]}, {"point": "Good purposes do not justify fabrication; verify before circulation", "qa": [1], "mcq": [1, 2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/65043"}, "65077": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abdullah ibn Amr", "qa": [{"id": "65077-focus-qa-1", "group": "Meaning and understanding", "q": "How did the permission to write answer the objection raised to Abdullah ibn Amr?", "a": "The objection concerned recording speech uttered in anger as well as pleasure. Abdullah referred the matter to the Prophet, who directed him to write and affirmed that nothing came from his mouth except truth. The response addresses the reliability of the teaching he was recording.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65077", "evidence": {"label": "Published English selection", "text": "Thereupon, he pointed his finger to his mouth and said: \"Write down; for by the One in Whose Hand my soul is, nothing comes out of it except the truth.\"", "url": "https://hadeethenc.com/en/browse/hadith/65077", "anchor": "nothing comes out of it except the truth", "field": "T"}}, {"id": "65077-focus-qa-2", "group": "Meaning and understanding", "q": "What role does writing have in this account of preservation?", "a": "Abdullah wrote to preserve what he heard, and the benefits identify writing as a principal means of preserving knowledge. This establishes the value of recording teaching; it does not mean that every later copy or every statement found in writing is automatically accurate.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65077", "evidence": {"label": "Published benefit 4", "text": "Writing down knowledge is one of the main methods for preserving it.", "url": "https://hadeethenc.com/en/browse/hadith/65077", "anchor": "methods for preserving", "field": "B4"}}, {"id": "65077-focus-qa-3", "group": "Meaning and understanding", "q": "What does the oath contribute to the Prophet's answer about writing?", "a": "It emphasizes the assurance that what comes from his mouth is true. The third benefit recognizes an oath used to reinforce an important point even when no one has demanded one.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65077", "evidence": {"label": "Published benefit 3", "text": "It is permissible to swear an oath, even without being asked to swear an oath, for the sake of a certain interest, like putting emphasis on something.", "url": "https://hadeethenc.com/en/browse/hadith/65077", "anchor": "putting emphasis", "field": "B3"}}], "mcq": [{"id": "65077-focus-mc-1", "q": "What objection caused him to stop writing temporarily?", "options": ["That writing materials were forbidden property", "That the Prophet spoke in both anger and pleasure", "That the Quran had not yet been recited publicly", "That only people in Madinah could record hadith"], "correct": 1, "feedback": ["The supported answer is: That the Prophet spoke in both anger and pleasure. The quoted objection questioned recording speech made in different emotional states.", "The quoted objection questioned recording speech made in different emotional states.", "The supported answer is: That the Prophet spoke in both anger and pleasure. The quoted objection questioned recording speech made in different emotional states.", "The supported answer is: That the Prophet spoke in both anger and pleasure. The quoted objection questioned recording speech made in different emotional states."], "hint": "Identify the reason given by the men from Quraysh.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65077", "evidence": {"label": "Published English selection", "text": "The Quraysh prohibited me, saying: \"Do you write down everything that you hear from the Messenger of Allah (may Allah's peace and blessings be upon him) while the Messenger of Allah (may Allah's peace and blessings be upon him) is a human being who speaks in anger and pleasure?\" So, I stopped writing and mentioned that to the Messenger of Allah (may Allah's peace and blessings be upon him).", "url": "https://hadeethenc.com/en/browse/hadith/65077", "anchor": "anger and pleasure", "field": "T"}}, {"id": "65077-focus-mc-2", "q": "What assurance accompanied the permission to write?", "options": ["That every listener could add helpful wording", "That only angry speech should be written", "That writing itself guarantees every later copy is accurate", "That nothing from his mouth came out except truth"], "correct": 3, "feedback": ["The supported answer is: That nothing from his mouth came out except truth. The Prophet's reply directly addresses the objection about his speech.", "The supported answer is: That nothing from his mouth came out except truth. The Prophet's reply directly addresses the objection about his speech.", "The supported answer is: That nothing from his mouth came out except truth. The Prophet's reply directly addresses the objection about his speech.", "The Prophet's reply directly addresses the objection about his speech."], "hint": "Read the statement following the gesture to his mouth.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65077", "evidence": {"label": "Published English selection", "text": "Thereupon, he pointed his finger to his mouth and said: \"Write down; for by the One in Whose Hand my soul is, nothing comes out of it except the truth.\"", "url": "https://hadeethenc.com/en/browse/hadith/65077", "anchor": "nothing comes out of it except the truth", "field": "T"}}, {"id": "65077-focus-mc-3", "q": "Why does the source identify an oath as appropriate in this reply?", "options": ["It replaces the need to answer the objection", "It reinforces an important assurance about the truth of what is conveyed", "It makes every later written copy free from error", "It proves that the companions were never allowed to ask questions"], "correct": 1, "feedback": ["The supported answer is: It reinforces an important assurance about the truth of what is conveyed. The third benefit recognizes an oath for emphasis even without a request for one.", "The third benefit recognizes an oath for emphasis even without a request for one.", "The supported answer is: It reinforces an important assurance about the truth of what is conveyed. The third benefit recognizes an oath for emphasis even without a request for one.", "The supported answer is: It reinforces an important assurance about the truth of what is conveyed. The third benefit recognizes an oath for emphasis even without a request for one."], "hint": "Look at the purpose of the oath, not just the act of swearing.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65077", "evidence": {"label": "Published benefit 3", "text": "It is permissible to swear an oath, even without being asked to swear an oath, for the sake of a certain interest, like putting emphasis on something.", "url": "https://hadeethenc.com/en/browse/hadith/65077", "anchor": "putting emphasis", "field": "B3"}}], "coverage": {"focusedAnswers": 3, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "The objection about anger and pleasure and the assurance of truth", "qa": [1], "mcq": [1, 2]}, {"point": "Writing as a means of preserving the teaching", "qa": [2], "mcq": [2]}, {"point": "The oath reinforcing an important assurance", "qa": [3], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/65077"}, "10849": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Said al-Khudri", "qa": [{"id": "10849-focus-qa-1", "group": "Meaning and understanding", "q": "How does the publisher reconcile this writing restriction with permission to write hadith?", "a": "It prefers an earlier restriction followed by later permission, citing the instruction to write for Abu Shah and the permission given to Abdullah ibn Amr. It also mentions other explanations, including avoiding hadith and Quran on the same scroll. The preferred reconciliation should be identified as the publisher's preference, not the only explanation ever proposed.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10849", "evidence": {"label": "Published explanation", "text": "The first probability, i.e.", "url": "https://hadeethenc.com/en/browse/hadith/10849", "anchor": "first probability", "field": "E"}}, {"id": "10849-focus-qa-2", "group": "Meaning and understanding", "q": "Why is Hammam's uncertainty about the word deliberately retained?", "a": "The transmitted account expressly says that he thought the word had been included. Preserving that qualification distinguishes what the narrator reports confidently from what he reports with uncertainty. It is an example of care in transmission, not permission to silently regularize a text.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10849", "evidence": {"label": "Published English selection", "text": "Whoever attributes any falsehood to me - Hammām said: I think he also said 'deliberately' - let him occupy his seat in Hellfire.”", "url": "https://hadeethenc.com/en/browse/hadith/10849", "anchor": "I think he also said", "field": "T"}}, {"id": "10849-focus-qa-3", "group": "Meaning and understanding", "q": "What remains permitted within the report even while writing is restricted?", "a": "Narrating from the Prophet remains permitted, but the explanation requires truthfulness in transmission. The restriction on writing in this account is not a command to stop conveying his teaching altogether.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10849", "evidence": {"label": "Published English selection", "text": "But, narrate from me, for there is nothing wrong in doing so.", "url": "https://hadeethenc.com/en/browse/hadith/10849", "anchor": "narrate from me", "field": "T"}}], "mcq": [{"id": "10849-focus-mc-1", "q": "Which reconciliation does the publisher prefer?", "options": ["A permanent ban on all hadith writing", "A later ban canceling every earlier permission", "The view that all writing reports are fabricated", "An earlier restriction followed by later permission"], "correct": 3, "feedback": ["The supported answer is: An earlier restriction followed by later permission. The explanation explicitly prefers abrogation while mentioning other proposed reconciliations.", "The supported answer is: An earlier restriction followed by later permission. The explanation explicitly prefers abrogation while mentioning other proposed reconciliations.", "The supported answer is: An earlier restriction followed by later permission. The explanation explicitly prefers abrogation while mentioning other proposed reconciliations.", "The explanation explicitly prefers abrogation while mentioning other proposed reconciliations."], "hint": "Read which explanation is called more preponderant.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10849", "evidence": {"label": "Published explanation", "text": "The first probability, i.e.", "url": "https://hadeethenc.com/en/browse/hadith/10849", "anchor": "first probability", "field": "E"}}, {"id": "10849-focus-mc-2", "q": "What other explanation does the source mention without preferring it?", "options": ["Restricting writing to a particular modern language", "Forbidding every personal letter", "Avoiding hadith and Quran being written on the same scroll", "Requiring all transmitters to rely only on dreams"], "correct": 2, "feedback": ["The supported answer is: Avoiding hadith and Quran being written on the same scroll. The source also discusses writing together on the same scroll and avoiding confusion, while preferring later abrogation.", "The supported answer is: Avoiding hadith and Quran being written on the same scroll. The source also discusses writing together on the same scroll and avoiding confusion, while preferring later abrogation.", "The source also discusses writing together on the same scroll and avoiding confusion, while preferring later abrogation.", "The supported answer is: Avoiding hadith and Quran being written on the same scroll. The source also discusses writing together on the same scroll and avoiding confusion, while preferring later abrogation."], "hint": "Look for an alternative introduced after the main historical explanation.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10849", "evidence": {"label": "Published explanation", "text": "The prohibition in the Hadīth in hand is said to refer to the writing of Hadīth along with the Qur'an in the same scroll; or that it is specific to the time when the Qur'an was being revealed, so that it would not be confused with something else.", "url": "https://hadeethenc.com/en/browse/hadith/10849", "anchor": "same scroll", "field": "E"}}, {"id": "10849-focus-mc-3", "q": "Why should Hammam's reported uncertainty remain visible?", "options": ["It makes the entire report a fabricated narration", "It gives permission to invent the rest of the text", "It identifies Hammam as the Prophet's Companion here", "It marks uncertainty about the inclusion of deliberately in this wording"], "correct": 3, "feedback": ["The supported answer is: It marks uncertainty about the inclusion of deliberately in this wording. The narrator explicitly qualifies whether deliberately was said; faithful presentation preserves that qualification.", "The supported answer is: It marks uncertainty about the inclusion of deliberately in this wording. The narrator explicitly qualifies whether deliberately was said; faithful presentation preserves that qualification.", "The supported answer is: It marks uncertainty about the inclusion of deliberately in this wording. The narrator explicitly qualifies whether deliberately was said; faithful presentation preserves that qualification.", "The narrator explicitly qualifies whether deliberately was said; faithful presentation preserves that qualification."], "hint": "Notice the words I think within the transmitted account.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10849", "evidence": {"label": "Published English selection", "text": "Whoever attributes any falsehood to me - Hammām said: I think he also said 'deliberately' - let him occupy his seat in Hellfire.”", "url": "https://hadeethenc.com/en/browse/hadith/10849", "anchor": "I think he also said", "field": "T"}}, {"id": "10849-focus-mc-4", "q": "What is allowed in the same report that restricts writing?", "options": ["Inventing explanations and attributing them to him", "Truthful narration from the Prophet", "Writing other material as Quranic wording", "Treating every report as certain without checking"], "correct": 1, "feedback": ["The supported answer is: Truthful narration from the Prophet. The report permits narration, while the explanation retains the demand for truthfulness.", "The report permits narration, while the explanation retains the demand for truthfulness.", "The supported answer is: Truthful narration from the Prophet. The report permits narration, while the explanation retains the demand for truthfulness.", "The supported answer is: Truthful narration from the Prophet. The report permits narration, while the explanation retains the demand for truthfulness."], "hint": "Read beyond the writing restriction to the next instruction.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10849", "evidence": {"label": "Published English selection", "text": "But, narrate from me, for there is nothing wrong in doing so.", "url": "https://hadeethenc.com/en/browse/hadith/10849", "anchor": "narrate from me", "field": "T"}}, {"id": "10849-focus-mc-5", "q": "Which later example is cited for permission to write?", "options": ["An instruction to remove the Quran from written records", "A ban on every form of memorization", "A permission to merge commentary into Quranic verses", "The instruction to write for Abu Shah"], "correct": 3, "feedback": ["The supported answer is: The instruction to write for Abu Shah. The publisher cites Abu Shah alongside Abdullah ibn Amr in explaining later permission.", "The supported answer is: The instruction to write for Abu Shah. The publisher cites Abu Shah alongside Abdullah ibn Amr in explaining later permission.", "The supported answer is: The instruction to write for Abu Shah. The publisher cites Abu Shah alongside Abdullah ibn Amr in explaining later permission.", "The publisher cites Abu Shah alongside Abdullah ibn Amr in explaining later permission."], "hint": "Look for an example used in the discussion of the chronology of permission.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10849", "evidence": {"label": "Published explanation", "text": "In this respect, he said in his sermon: ''Write for Abu Shāh'' when Abu Shāh asked for a written record.", "url": "https://hadeethenc.com/en/browse/hadith/10849", "anchor": "Abu Shāh", "field": "E"}}], "coverage": {"focusedAnswers": 3, "thematicQuestions": 5, "completeSanadProvided": false, "topics": [{"point": "The writing restriction, its Quran exception and permitted truthful narration", "qa": [3], "mcq": [4]}, {"point": "Later permission and the publisher's preferred reconciliation", "qa": [1], "mcq": [1, 5]}, {"point": "Alternative same-scroll explanation distinguished from the preferred account", "qa": [1], "mcq": [2]}, {"point": "Hammam's explicit uncertainty retained in transmission", "qa": [2], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/10849"}, "6982": {"revision": "topic001-coverage-2026-10-17", "narrator": "Samurah ibn Jundab and al-Mughirah ibn Shubah", "qa": [{"id": "6982-focus-qa-1", "group": "Meaning and understanding", "q": "How can someone other than the original fabricator share responsibility for a false report?", "a": "The explanation concerns a person who reports what they know or strongly judge to be false. Culpable circulation can therefore extend the false attribution beyond its originator. The point is not that every learner's uncertainty amounts to fabrication; it is knowingly or culpably passing falsehood on as Prophetic teaching.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/6982", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) informs that if a person reports a Hadīth from him which he knows, thinks, or deems it highly likely to be false, he has lied about him (may Allah's peace and blessings be upon him).", "url": "https://hadeethenc.com/en/browse/hadith/6982", "anchor": "highly likely to be false", "field": "E"}}, {"id": "6982-focus-qa-2", "group": "Meaning and understanding", "q": "When may a fabricated report be mentioned according to the supplied benefit?", "a": "It may be mentioned to warn against it. That purpose must remain clear: identifying a report as fabricated is different from presenting it as authentic to encourage an audience. The exception reinforces verification rather than weakening it.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/6982", "evidence": {"label": "Published benefit 3", "text": "It is forbidden to narrate a fabricated Hadīth if one knows it is fabricated or deems it is likely to be fabricated, except if the purpose is to warn against it.", "url": "https://hadeethenc.com/en/browse/hadith/6982", "anchor": "warn against it", "field": "B3"}}], "mcq": [{"id": "6982-focus-mc-1", "q": "What is the relevant condition for sharing in the false attribution here?", "options": ["Transmitting any report that is short", "Transmitting a verified report in translation", "Transmitting a report one knows or strongly suspects is false", "Transmitting only after checking its primary source"], "correct": 2, "feedback": ["The supported answer is: Transmitting a report one knows or strongly suspects is false. The explanation concerns knowledge or a strong judgment of falsehood, not every uncertainty in learning.", "The supported answer is: Transmitting a report one knows or strongly suspects is false. The explanation concerns knowledge or a strong judgment of falsehood, not every uncertainty in learning.", "The explanation concerns knowledge or a strong judgment of falsehood, not every uncertainty in learning.", "The supported answer is: Transmitting a report one knows or strongly suspects is false. The explanation concerns knowledge or a strong judgment of falsehood, not every uncertainty in learning."], "hint": "Read the states of awareness listed in the explanation.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6982", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) informs that if a person reports a Hadīth from him which he knows, thinks, or deems it highly likely to be false, he has lied about him (may Allah's peace and blessings be upon him).", "url": "https://hadeethenc.com/en/browse/hadith/6982", "anchor": "highly likely to be false", "field": "E"}}, {"id": "6982-focus-mc-2", "q": "What exception does the source give for mentioning a fabricated report?", "options": ["Mentioning it as authentic for a good cause", "Mentioning it to warn against it", "Mentioning it because many people enjoy it", "Mentioning it with an invented reference"], "correct": 1, "feedback": ["The supported answer is: Mentioning it to warn against it. The final benefit expressly permits warning against the fabricated report; it is not permission to present it as genuine.", "The final benefit expressly permits warning against the fabricated report; it is not permission to present it as genuine.", "The supported answer is: Mentioning it to warn against it. The final benefit expressly permits warning against the fabricated report; it is not permission to present it as genuine.", "The supported answer is: Mentioning it to warn against it. The final benefit expressly permits warning against the fabricated report; it is not permission to present it as genuine."], "hint": "Look at the purpose stated in the exception.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6982", "evidence": {"label": "Published benefit 3", "text": "It is forbidden to narrate a fabricated Hadīth if one knows it is fabricated or deems it is likely to be fabricated, except if the purpose is to warn against it.", "url": "https://hadeethenc.com/en/browse/hadith/6982", "anchor": "warn against it", "field": "B3"}}, {"id": "6982-focus-mc-3", "q": "Which excuse fails to address the responsibility described here?", "options": ["I identified the fabrication clearly in order to warn against it", "I withheld attribution until I could verify the source", "I forwarded it because another person sent it, despite strongly suspecting it was false", "I distinguished an author's reflection from a Prophetic report"], "correct": 2, "feedback": ["The supported answer is: I forwarded it because another person sent it, despite strongly suspecting it was false. The explanation includes a transmitter who knows or considers the report highly likely to be false.", "The supported answer is: I forwarded it because another person sent it, despite strongly suspecting it was false. The explanation includes a transmitter who knows or considers the report highly likely to be false.", "The explanation includes a transmitter who knows or considers the report highly likely to be false.", "The supported answer is: I forwarded it because another person sent it, despite strongly suspecting it was false. The explanation includes a transmitter who knows or considers the report highly likely to be false."], "hint": "Focus on the transmitter's awareness rather than who first wrote the message.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6982", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) informs that if a person reports a Hadīth from him which he knows, thinks, or deems it highly likely to be false, he has lied about him (may Allah's peace and blessings be upon him).", "url": "https://hadeethenc.com/en/browse/hadith/6982", "anchor": "highly likely", "field": "E"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Responsibility of the fabricator and the knowing or strongly suspecting relay", "qa": [1], "mcq": [1, 3]}, {"point": "Verification before transmission, without equating every doubt with fabrication", "qa": [1], "mcq": [1, 3]}, {"point": "Mentioning a fabrication clearly to warn against it", "qa": [2], "mcq": [2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/6982"}, "5913": {"revision": "topic001-coverage-2026-10-17", "narrator": "Uthman ibn Affan", "qa": [{"id": "5913-focus-qa-1", "group": "Meaning and understanding", "q": "What does learning and teaching the Quran include beyond pronunciation?", "a": "The explanation includes recitation, memorization, measured reading, understanding, and interpretation, together with acting on the knowledge. The benefits also mention meanings and rulings. Teaching thus involves responsibly conveying what one has learned, rather than treating fluent reading as the whole of Quranic education.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/5913", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) informs that the best and higher-standing among Muslims in the sight of Allah are those who learn the Qur’an - in terms of recitation, memorization, tartīl (measured recitation), understanding, and interpretation - and teach others the knowledge of the Qur’an that they possess, along with acting upon it.", "url": "https://hadeethenc.com/en/browse/hadith/5913", "anchor": "understanding, and interpretation", "field": "E"}}, {"id": "5913-focus-qa-2", "group": "Meaning and understanding", "q": "Why are learning and teaching praised together?", "a": "Learning equips a person with knowledge; teaching enables others to benefit from it. The source praises those who do not keep their learning entirely to themselves. The explanation also links both activities with practice, so conveying knowledge does not replace responding to it personally.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/5913", "evidence": {"label": "Published benefit 2", "text": "The best learners are those who teach others and do not keep the knowledge to themselves only.", "url": "https://hadeethenc.com/en/browse/hadith/5913", "anchor": "do not keep the knowledge", "field": "B2"}}], "mcq": [{"id": "5913-focus-mc-1", "q": "What does learning the Quran include in the explanation?", "options": ["Only collecting printed copies", "Recitation, memorization, understanding, and interpretation", "Only knowing the order of surah names", "Only learning the biographical names of reciters"], "correct": 1, "feedback": ["The supported answer is: Recitation, memorization, understanding, and interpretation. The explanation describes both recitational skill and understanding.", "The explanation describes both recitational skill and understanding.", "The supported answer is: Recitation, memorization, understanding, and interpretation. The explanation describes both recitational skill and understanding.", "The supported answer is: Recitation, memorization, understanding, and interpretation. The explanation describes both recitational skill and understanding."], "hint": "Look for the list expanding learn.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5913", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) informs that the best and higher-standing among Muslims in the sight of Allah are those who learn the Qur’an - in terms of recitation, memorization, tartīl (measured recitation), understanding, and interpretation - and teach others the knowledge of the Qur’an that they possess, along with acting upon it.", "url": "https://hadeethenc.com/en/browse/hadith/5913", "anchor": "understanding, and interpretation", "field": "E"}}, {"id": "5913-focus-mc-2", "q": "How is practice related to teaching in the source explanation?", "options": ["Teachers should act on the knowledge they convey", "Teaching makes personal practice unnecessary", "Practice is relevant only before teaching begins", "Recitation skill alone replaces every practical duty"], "correct": 0, "feedback": ["The explanation explicitly includes acting upon the knowledge learned and taught.", "The supported answer is: Teachers should act on the knowledge they convey. The explanation explicitly includes acting upon the knowledge learned and taught.", "The supported answer is: Teachers should act on the knowledge they convey. The explanation explicitly includes acting upon the knowledge learned and taught.", "The supported answer is: Teachers should act on the knowledge they convey. The explanation explicitly includes acting upon the knowledge learned and taught."], "hint": "Notice the qualification at the end of the explanation.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5913", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) informs that the best and higher-standing among Muslims in the sight of Allah are those who learn the Qur’an - in terms of recitation, memorization, tartīl (measured recitation), understanding, and interpretation - and teach others the knowledge of the Qur’an that they possess, along with acting upon it.", "url": "https://hadeethenc.com/en/browse/hadith/5913", "anchor": "acting upon it", "field": "E"}}, {"id": "5913-focus-mc-3", "q": "Which learning plan fits the breadth of the published explanation?", "options": ["Master pronunciation while deliberately disregarding meaning", "Memorize a title without studying the passage", "Teach unsupported interpretations to make a lesson more impressive", "Develop recitation, understanding, practice and the ability to teach responsibly"], "correct": 3, "feedback": ["The supported answer is: Develop recitation, understanding, practice and the ability to teach responsibly. The explanation and benefits include recitation, meaning, rulings, practice and teaching.", "The supported answer is: Develop recitation, understanding, practice and the ability to teach responsibly. The explanation and benefits include recitation, meaning, rulings, practice and teaching.", "The supported answer is: Develop recitation, understanding, practice and the ability to teach responsibly. The explanation and benefits include recitation, meaning, rulings, practice and teaching.", "The explanation and benefits include recitation, meaning, rulings, practice and teaching."], "hint": "Join the separate elements rather than choosing only one technical skill.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5913", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) informs that the best and higher-standing among Muslims in the sight of Allah are those who learn the Qur’an - in terms of recitation, memorization, tartīl (measured recitation), understanding, and interpretation - and teach others the knowledge of the Qur’an that they possess, along with acting upon it.", "url": "https://hadeethenc.com/en/browse/hadith/5913", "anchor": "acting upon it", "field": "E"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Recitation, memorization, measured reading, meanings and rulings", "qa": [1], "mcq": [1, 3]}, {"point": "Teaching benefits others and remains joined to acting on knowledge", "qa": [2], "mcq": [2, 3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/5913"}, "10113": {"revision": "topic001-coverage-2026-10-17", "narrator": "Aishah", "qa": [{"id": "10113-focus-qa-1", "group": "Meaning and understanding", "q": "How does the report encourage both proficiency and perseverance?", "a": "It gives the proficient reciter the distinction of being with the noble and obedient angel-scribes, while promising two rewards to the reader who continues despite difficulty. The explanation identifies rewards for recitation and struggle. Both descriptions encourage learning; neither makes avoidable mistakes a goal.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10113", "evidence": {"label": "Published explanation", "text": "As for the one who recites the Qur’an while stuttering and rehearsing in his recitation due to weak memorization, yet continues to maintain his connection with the Qur’an despite its difficulty for him, he will have two rewards: one reward for his recitation and another for the difficulty and his rehearsing in his recitation.", "url": "https://hadeethenc.com/en/browse/hadith/10113", "anchor": "one reward for his recitation", "field": "E"}}, {"id": "10113-focus-qa-2", "group": "Meaning and understanding", "q": "Do two rewards mean that struggling is necessarily superior to proficiency?", "a": "The quoted benefit expressly rejects that conclusion. The proficient reciter has a special rank and reward; the number two should not be used to erase it. A struggling learner is encouraged to continue while improving, rather than deliberately remaining inaccurate.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10113", "evidence": {"label": "Published benefit 2", "text": "Al-Qādi said: It does not mean that the one who stutters in the recitation has a greater reward than the proficient reciter.", "url": "https://hadeethenc.com/en/browse/hadith/10113", "anchor": "greater reward than the proficient", "field": "B2"}}], "mcq": [{"id": "10113-focus-mc-1", "q": "How does the explanation account for those two rewards?", "options": ["Speed and the size of the audience", "Memorization and social recognition", "Recitation and the difficulty involved", "Reading aloud and owning a copy"], "correct": 2, "feedback": ["The supported answer is: Recitation and the difficulty involved. The explanation distinguishes the reward for reading from the reward connected with the struggle.", "The supported answer is: Recitation and the difficulty involved. The explanation distinguishes the reward for reading from the reward connected with the struggle.", "The explanation distinguishes the reward for reading from the reward connected with the struggle.", "The supported answer is: Recitation and the difficulty involved. The explanation distinguishes the reward for reading from the reward connected with the struggle."], "hint": "Read the explanation of the two rewards.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10113", "evidence": {"label": "Published explanation", "text": "As for the one who recites the Qur’an while stuttering and rehearsing in his recitation due to weak memorization, yet continues to maintain his connection with the Qur’an despite its difficulty for him, he will have two rewards: one reward for his recitation and another for the difficulty and his rehearsing in his recitation.", "url": "https://hadeethenc.com/en/browse/hadith/10113", "anchor": "one reward for his recitation", "field": "E"}}, {"id": "10113-focus-mc-2", "q": "Which conclusion does the quoted benefit explicitly reject?", "options": ["That the struggling reader receives encouragement", "That the struggling reader must therefore outrank the proficient reciter", "That proficiency has a special merit", "That continued recitation despite difficulty is rewarded"], "correct": 1, "feedback": ["The supported answer is: That the struggling reader must therefore outrank the proficient reciter. Al-Qadi's quoted explanation prevents using the number two to erase the special rank of proficiency.", "Al-Qadi's quoted explanation prevents using the number two to erase the special rank of proficiency.", "The supported answer is: That the struggling reader must therefore outrank the proficient reciter. Al-Qadi's quoted explanation prevents using the number two to erase the special rank of proficiency.", "The supported answer is: That the struggling reader must therefore outrank the proficient reciter. Al-Qadi's quoted explanation prevents using the number two to erase the special rank of proficiency."], "hint": "Compare the two descriptions without reducing rank to a simple numeral.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10113", "evidence": {"label": "Published benefit 2", "text": "Al-Qādi said: It does not mean that the one who stutters in the recitation has a greater reward than the proficient reciter.", "url": "https://hadeethenc.com/en/browse/hadith/10113", "anchor": "greater reward than the proficient", "field": "B2"}}, {"id": "10113-focus-mc-3", "q": "Which honor is specifically attached to proficiency in this narration?", "options": ["Being with the noble and obedient angel-scribes", "Being exempt from acting upon the Quran", "Receiving permission never to revise memorization", "Having every interpretation accepted without evidence"], "correct": 0, "feedback": ["The first clause gives this honor to the proficient reciter; the second encourages the struggling reader.", "The supported answer is: Being with the noble and obedient angel-scribes. The first clause gives this honor to the proficient reciter; the second encourages the struggling reader.", "The supported answer is: Being with the noble and obedient angel-scribes. The first clause gives this honor to the proficient reciter; the second encourages the struggling reader.", "The supported answer is: Being with the noble and obedient angel-scribes. The first clause gives this honor to the proficient reciter; the second encourages the struggling reader."], "hint": "Keep the promises for the two readers distinct.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10113", "evidence": {"label": "Published English selection", "text": "‘Ā’ishah (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"The proficient reciter of the Qur’an will be with the noble and obedient angel-scribes, and the one who recites the Qur’an stutteringly and finds it difficult will have two rewards.\"", "url": "https://hadeethenc.com/en/browse/hadith/10113", "anchor": "angel-scribes", "field": "T"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "The proficient reader's rank with the angel-scribes", "qa": [1], "mcq": [3]}, {"point": "Rewards for recitation and persevering through difficulty", "qa": [1], "mcq": [1]}, {"point": "Two rewards do not establish superiority over proficiency or encourage errors", "qa": [2], "mcq": [2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/10113"}, "5907": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Musa al-Ashari", "qa": [{"id": "5907-focus-qa-1", "group": "Meaning and understanding", "q": "Why does the Prophet compare memorized Quran to tethered camels?", "a": "The comparison explains the need for continued attention after memorization. Just as a shepherd's care keeps the camels from wandering, regular recitation helps preserve what has been learned. A practical response is to review earlier passages alongside learning new ones, rather than assuming initial memorization is permanent.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/5907", "evidence": {"label": "Published explanation", "text": "If their shepherd pays attention to them, they remain with him, and if he releases them, they go away and will be lost.", "url": "https://hadeethenc.com/en/browse/hadith/5907", "anchor": "pays attention", "field": "E"}}], "mcq": [{"id": "5907-focus-mc-1", "q": "Which revision plan most directly applies this teaching?", "options": ["Focus only on new memorization and never review", "Wait until a complete surah is lost before reviewing", "Return regularly to previously memorized passages", "Use confidence alone as proof that revision is unnecessary"], "correct": 2, "feedback": ["The supported answer is: Return regularly to previously memorized passages. The explanation encourages regular attention after memorization.", "The supported answer is: Return regularly to previously memorized passages. The explanation encourages regular attention after memorization.", "The explanation encourages regular attention after memorization.", "The supported answer is: Return regularly to previously memorized passages. The explanation encourages regular attention after memorization."], "hint": "Distinguish gaining new material from maintaining earlier learning.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5907", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) ordered the Companions to recite the Qur'an regularly and not to forget it after they had learned it by heart.", "url": "https://hadeethenc.com/en/browse/hadith/5907", "anchor": "regularly", "field": "E"}}], "coverage": {"focusedAnswers": 1, "thematicQuestions": 1, "completeSanadProvided": false, "topics": [{"point": "Regular recitation and review after memorization", "qa": [1], "mcq": [1]}, {"point": "Tethered camels as the comparison for continued attention", "qa": [1], "mcq": [1]}]}, "source": "https://hadeethenc.com/en/browse/hadith/5907"}, "3772": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abdullah ibn Masud and Abdullah ibn Umar", "qa": [{"id": "3772-focus-qa-1", "group": "Meaning and understanding", "q": "What separates praiseworthy aspiration from blameworthy envy?", "a": "The explanation distinguishes wishing for similar good from wishing that another person lose their blessing. The praised examples concern beneficial use: rightful spending, applying wisdom, teaching, and sustained Quran recitation. The desire is directed toward sharing in good, rather than resenting someone else's possession of it.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3772", "evidence": {"label": "Published explanation", "text": "So one hopes to be like him, and envies him, the kind of envy that is free from malice, for that blessing.", "url": "https://hadeethenc.com/en/browse/hadith/3772", "anchor": "free from malice", "field": "E"}}, {"id": "3772-focus-qa-2", "group": "Meaning and understanding", "q": "Why are the gifts described through what their recipients do with them?", "a": "Wealth is praised here through rightful spending, wisdom through application and teaching, and Quranic knowledge through recitation. The entry includes the wisdom wording from Ibn Masud and the accompanying Quran wording from Ibn Umar. The shared lesson is beneficial use of Allah's gifts, rather than possession or reputation alone.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3772", "evidence": {"label": "Published explanation", "text": "When there is a knowledgeable man whom Allah has given beneficial knowledge which he acts upon, teaches to others, and judges between the people according to.", "url": "https://hadeethenc.com/en/browse/hadith/3772", "anchor": "beneficial knowledge", "field": "E"}}, {"id": "3772-focus-qa-3", "group": "Meaning and understanding", "q": "Does the explanation give the same ruling to every wish for a blessing like another person's?", "a": "No. It distinguishes malicious envy, a permissible wish for a similar worldly benefit, and a commendable wish for religious good. The praise in this report concerns using wealth or knowledge well, without wishing for another's loss.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3772", "evidence": {"label": "Published explanation", "text": "The permissible type of envy is when one sees someone enjoying a worldly blessing and he hopes to have the same for himself.", "url": "https://hadeethenc.com/en/browse/hadith/3772", "anchor": "permissible", "field": "E"}}], "mcq": [{"id": "3772-focus-mc-1", "q": "What kind of desire for another's blessing is praised in the explanation?", "options": ["Wishing that the other person lose it", "Wishing for similar good without wishing its removal", "Resenting the good whenever others benefit", "Wanting the blessing only to surpass others in status"], "correct": 1, "feedback": ["The supported answer is: Wishing for similar good without wishing its removal. The explanation distinguishes admirable aspiration from malicious envy.", "The explanation distinguishes admirable aspiration from malicious envy.", "The supported answer is: Wishing for similar good without wishing its removal. The explanation distinguishes admirable aspiration from malicious envy.", "The supported answer is: Wishing for similar good without wishing its removal. The explanation distinguishes admirable aspiration from malicious envy."], "hint": "Ask whether the other person's blessing is wished away.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3772", "evidence": {"label": "Published explanation", "text": "So one hopes to be like him, and envies him, the kind of envy that is free from malice, for that blessing.", "url": "https://hadeethenc.com/en/browse/hadith/3772", "anchor": "free from malice", "field": "E"}}, {"id": "3772-focus-mc-2", "q": "Which feature links the praised examples?", "options": ["Allah's gifts are put to beneficial use", "Their owners hide every benefit from others", "Social rank makes their conduct irrelevant", "The gifts remove all need for continued effort"], "correct": 0, "feedback": ["The examples involve spending, applying knowledge, teaching, or reciting, rather than possession alone.", "The supported answer is: Allah's gifts are put to beneficial use. The examples involve spending, applying knowledge, teaching, or reciting, rather than possession alone.", "The supported answer is: Allah's gifts are put to beneficial use. The examples involve spending, applying knowledge, teaching, or reciting, rather than possession alone.", "The supported answer is: Allah's gifts are put to beneficial use. The examples involve spending, applying knowledge, teaching, or reciting, rather than possession alone."], "hint": "Look for actions following each gift.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3772", "evidence": {"label": "Published explanation", "text": "When there is a knowledgeable man whom Allah has given beneficial knowledge which he acts upon, teaches to others, and judges between the people according to.", "url": "https://hadeethenc.com/en/browse/hadith/3772", "anchor": "beneficial knowledge", "field": "E"}}, {"id": "3772-focus-mc-3", "q": "Which action is added in the second narration's example of Quran knowledge?", "options": ["Storing the text without returning to it", "Recitation during the night and day", "Measuring devotion by material wealth alone", "Wishing that another person's knowledge be removed"], "correct": 1, "feedback": ["The supported answer is: Recitation during the night and day. The second narration describes repeated recitation, while retaining the paired example of generous spending.", "The second narration describes repeated recitation, while retaining the paired example of generous spending.", "The supported answer is: Recitation during the night and day. The second narration describes repeated recitation, while retaining the paired example of generous spending.", "The supported answer is: Recitation during the night and day. The second narration describes repeated recitation, while retaining the paired example of generous spending."], "hint": "Compare the two narrated examples of beneficial knowledge.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3772", "evidence": {"label": "Published English selection", "text": "‘Abdullāh ibn ‘Umar (may Allah be pleased with him) reported that the Prophet (may Allah's peace and blessings be upon him) said: \"There should be no envy except in two (cases): a man whom Allah has given (knowledge of) the Qur'an, and he recites it during the night and day, and a man whom Allah has given wealth, and he spends it during the night and day (in a rightful way).”", "url": "https://hadeethenc.com/en/browse/hadith/3772", "anchor": "night and day", "field": "T"}}], "coverage": {"focusedAnswers": 3, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Malicious envy distinguished from wishing for a similar blessing", "qa": [1], "mcq": [1]}, {"point": "Permissible worldly aspiration and commendable religious aspiration", "qa": [3], "mcq": [1]}, {"point": "Rightful spending and wisdom applied in judgment and teaching", "qa": [2], "mcq": [2]}, {"point": "The accompanying Ibn Umar narration about Quran recitation night and day", "qa": [2], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/3772"}, "65285": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Hurayrah", "qa": [{"id": "65285-focus-qa-1", "group": "Meaning and understanding", "q": "Why did the Companions find the verse about inward accountability difficult?", "a": "They were accustomed to duties they could perform, such as prayer and fasting, but feared accountability even for thoughts passing through their hearts. They sought clarification. The account then joins their concern with the Prophet's instruction, their willing response, and the assurance that Allah does not burden a soul beyond its capacity.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published explanation", "text": "When the Companions heard this verse, it was hard on them, for it implied being held accountable even for the thoughts that pass through the heart.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "thoughts that pass through the heart", "field": "E"}}, {"id": "65285-focus-qa-2", "group": "Meaning and understanding", "q": "What does hearing and obeying mean in the course of this account?", "a": "It is a response of submission accompanied by seeking forgiveness and acknowledging the final return to Allah. The explanation describes both tongues and hearts responding. Their question did not prevent obedience; it led to clarification and a willing response rather than rejection of the command.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published explanation", "text": "When the Muslims spoke those words with their tongues and their hearts submitted to them, Allah revealed—as a commendation for the Prophet (ﷺ) and his Ummah—His saying: {The Messenger believes in what has been sent down to him from his Lord, as do the believers} and their tongues and hearts submitted to Allah's command.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "hearts submitted", "field": "E"}}, {"id": "65285-focus-qa-3", "group": "Meaning and understanding", "q": "How does the source distinguish passing thoughts from deliberate engagement?", "a": "The explanation excludes mere passing thoughts and whispers from the accountability they feared. The benefits distinguish these from dwelling on, being content with, or acting upon them. This qualification should be retained so that the account neither creates needless fear of involuntary thoughts nor removes responsibility for chosen conduct.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published benefit 8", "text": "The passing thoughts and whispers that occur in our hearts do not harm us as long as we do not dwell upon them, feel content with them, or act upon them.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "passing thoughts", "field": "B8"}}, {"id": "65285-focus-qa-4", "group": "Meaning and understanding", "q": "Which beliefs are included in the revealed response of the Messenger and the believers?", "a": "The passage names belief in Allah, His angels, His Books and His messengers. It adds that they make no distinction between the messengers in accepting them, joining comprehensive belief with hearing, obeying and seeking forgiveness.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published English selection", "text": "All of them believe in Allah, His angels, His Books, and His messengers, [saying], “We make no distinction between any of His messengers.” And they say, “We hear and obey.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "His angels", "field": "T"}}, {"id": "65285-focus-qa-5", "group": "Meaning and understanding", "q": "How does the report present accountability for good and evil deeds?", "a": "The explanation reads the final verse as assigning a person the reward of what they earn and the responsibility for the evil they incur. It specifically says a person is not held accountable for another person's sin.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published explanation", "text": "Thus, Allah does not hold anyone accountable for another's sin, nor for the whispers and passing thoughts within one's own self.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "another's sin", "field": "E"}}, {"id": "65285-focus-qa-6", "group": "Meaning and understanding", "q": "What do the closing supplications ask Allah to remove or grant?", "a": "They ask not to be held accountable for forgetfulness and error, not to bear the heavy burdens of earlier communities or what exceeds their strength, and to receive pardon, forgiveness, mercy and help. The report repeatedly records Allah's affirmative response.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published English selection", "text": "Our Lord, do not hold us accountable if we forget or fall into error.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Our Lord, do not place on us such a burden as You have placed on those before us.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Our Lord, do not burden us with that which we cannot bear.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Pardon us, forgive us, and have mercy on us.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "if we forget", "field": "T"}}, {"id": "65285-focus-qa-7", "group": "Meaning and understanding", "q": "What does abrogation mean in the publisher's discussion of these verses?", "a": "The source describes an earlier ruling being lifted while its verse remains recited. That is the explanation used here for the easing of the companions' concern; it does not mean that the earlier verse was removed from the Quran.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published benefit 2", "text": "Affirming the abrogation in the Noble Qur’an, and that within it are verses that are still recited, yet their rulings have been abrogated and are no longer acted upon.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "still recited", "field": "B2"}}], "mcq": [{"id": "65285-focus-mc-1", "q": "What concerned the Companions when al-Baqarah 284 was revealed?", "options": ["Accountability for what passed through their hearts", "The order of the surahs in a written copy", "The number of units in Duha prayer", "A new timetable for fasting during travel"], "correct": 0, "feedback": ["The explanation connects their difficulty with inward thoughts, beyond bodily acts they could bear.", "The supported answer is: Accountability for what passed through their hearts. The explanation connects their difficulty with inward thoughts, beyond bodily acts they could bear.", "The supported answer is: Accountability for what passed through their hearts. The explanation connects their difficulty with inward thoughts, beyond bodily acts they could bear.", "The supported answer is: Accountability for what passed through their hearts. The explanation connects their difficulty with inward thoughts, beyond bodily acts they could bear."], "hint": "Look for the contrast between bodily duties and inner thoughts.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published explanation", "text": "When the Companions heard this verse, it was hard on them, for it implied being held accountable even for the thoughts that pass through the heart.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "thoughts that pass through the heart", "field": "E"}}, {"id": "65285-focus-mc-2", "q": "What assurance appears in al-Baqarah 286 in the account?", "options": ["Allah does not burden a soul beyond its capacity", "All bodily duties are canceled permanently", "No conduct has any consequence in the Hereafter", "Only ancestry determines accountability"], "correct": 0, "feedback": ["The account closes the difficulty with assurance concerning capacity and supplications for mercy.", "The supported answer is: Allah does not burden a soul beyond its capacity. The account closes the difficulty with assurance concerning capacity and supplications for mercy.", "The supported answer is: Allah does not burden a soul beyond its capacity. The account closes the difficulty with assurance concerning capacity and supplications for mercy.", "The supported answer is: Allah does not burden a soul beyond its capacity. The account closes the difficulty with assurance concerning capacity and supplications for mercy."], "hint": "Notice the statement beginning Allah does not burden.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published English selection", "text": "Grant us Your forgiveness, our Lord, and to You is the [final] destination.”} [Surat al-Baqarah: 285] Then Allah Almighty, out of His mercy, abrogated the previous ruling and revealed: {Allah does not burden any soul greater than it can bear.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "greater than it can bear", "field": "T"}}, {"id": "65285-focus-mc-3", "q": "What does the explanation distinguish from culpable action?", "options": ["Passing thoughts and whispers within oneself", "Every deliberately maintained belief", "Every harm knowingly done to another person", "All choices that a person has already acted upon"], "correct": 0, "feedback": ["The source explicitly discusses passing thoughts; the benefits qualify this by distinguishing dwelling on or acting upon them.", "The supported answer is: Passing thoughts and whispers within oneself. The source explicitly discusses passing thoughts; the benefits qualify this by distinguishing dwelling on or acting upon them.", "The supported answer is: Passing thoughts and whispers within oneself. The source explicitly discusses passing thoughts; the benefits qualify this by distinguishing dwelling on or acting upon them.", "The supported answer is: Passing thoughts and whispers within oneself. The source explicitly discusses passing thoughts; the benefits qualify this by distinguishing dwelling on or acting upon them."], "hint": "Read the assurance about inward thoughts with its qualifications.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published explanation", "text": "Thus, Allah does not hold anyone accountable for another's sin, nor for the whispers and passing thoughts within one's own self.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "passing thoughts", "field": "E"}}, {"id": "65285-focus-mc-4", "q": "What does making no distinction between the messengers mean in the explanation?", "options": ["Claiming that no messenger ever had a distinct mission", "Believing in all of them rather than accepting some and rejecting others", "Denying the need for any revelation", "Treating obedience as unrelated to belief"], "correct": 1, "feedback": ["The supported answer is: Believing in all of them rather than accepting some and rejecting others. The explanation explicitly says that believers believe in all the messengers.", "The explanation explicitly says that believers believe in all the messengers.", "The supported answer is: Believing in all of them rather than accepting some and rejecting others. The explanation explicitly says that believers believe in all the messengers.", "The supported answer is: Believing in all of them rather than accepting some and rejecting others. The explanation explicitly says that believers believe in all the messengers."], "hint": "Read the explanation immediately after the named beliefs.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published explanation", "text": "{All of them believe in Allah, His angels, His Books, and His messengers, [saying], “We make no distinction between any of His messengers.”} Rather, we believe in all of them.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "believe in all of them", "field": "E"}}, {"id": "65285-focus-mc-5", "q": "Which request is explicitly included in the closing supplications?", "options": ["Not being held accountable for forgetfulness or error", "Being freed from every obligation by choice", "Being rewarded for another person's sins", "Possessing independent knowledge of the unseen"], "correct": 0, "feedback": ["The final verse includes this request, and the account records Allah's affirmative response.", "The supported answer is: Not being held accountable for forgetfulness or error. The final verse includes this request, and the account records Allah's affirmative response.", "The supported answer is: Not being held accountable for forgetfulness or error. The final verse includes this request, and the account records Allah's affirmative response.", "The supported answer is: Not being held accountable for forgetfulness or error. The final verse includes this request, and the account records Allah's affirmative response."], "hint": "Separate the requests for mercy from an imagined cancellation of all responsibility.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published English selection", "text": "Our Lord, do not hold us accountable if we forget or fall into error.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Our Lord, do not place on us such a burden as You have placed on those before us.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Our Lord, do not burden us with that which we cannot bear.} [Surat al-Baqarah: 286] He said: \"Yes.\" {Pardon us, forgive us, and have mercy on us.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "if we forget", "field": "T"}}, {"id": "65285-focus-mc-6", "q": "How does the source describe the abrogation discussed here?", "options": ["The verse disappears from every copy of the Quran", "A ruling is lifted while its verse remains recited", "All earlier revelations become historically unknowable", "The companions replace revelation with their own wording"], "correct": 1, "feedback": ["The supported answer is: A ruling is lifted while its verse remains recited. The second benefit makes the distinction between continued recitation and an abrogated ruling.", "The second benefit makes the distinction between continued recitation and an abrogated ruling.", "The supported answer is: A ruling is lifted while its verse remains recited. The second benefit makes the distinction between continued recitation and an abrogated ruling.", "The supported answer is: A ruling is lifted while its verse remains recited. The second benefit makes the distinction between continued recitation and an abrogated ruling."], "hint": "Keep a verse's recitation distinct from the continued operation of its ruling.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published benefit 2", "text": "Affirming the abrogation in the Noble Qur’an, and that within it are verses that are still recited, yet their rulings have been abrogated and are no longer acted upon.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "still recited", "field": "B2"}}, {"id": "65285-focus-mc-7", "q": "Whose sinful deeds does the explanation say a person is not charged with?", "options": ["Their own deliberate evil deeds", "Another person's sins", "Their own earned good deeds", "Their own duties within their capacity"], "correct": 1, "feedback": ["The supported answer is: Another person's sins. The explanation states individual accountability when expanding what a soul earns and incurs.", "The explanation states individual accountability when expanding what a soul earns and incurs.", "The supported answer is: Another person's sins. The explanation states individual accountability when expanding what a soul earns and incurs.", "The supported answer is: Another person's sins. The explanation states individual accountability when expanding what a soul earns and incurs."], "hint": "Read the distinction after the assurance about capacity.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65285", "evidence": {"label": "Published explanation", "text": "Thus, Allah does not hold anyone accountable for another's sin, nor for the whispers and passing thoughts within one's own self.", "url": "https://hadeethenc.com/en/browse/hadith/65285", "anchor": "another's sin", "field": "E"}}], "coverage": {"focusedAnswers": 7, "thematicQuestions": 7, "completeSanadProvided": false, "topics": [{"point": "Concern about inward accountability and seeking clarification", "qa": [1], "mcq": [1]}, {"point": "Hearing, obeying, seeking forgiveness and returning to Allah", "qa": [2], "mcq": [2]}, {"point": "Belief in Allah, angels, Books and all messengers", "qa": [4], "mcq": [4]}, {"point": "Capacity, involuntary thoughts and chosen conduct", "qa": [1, 3], "mcq": [2, 3]}, {"point": "Individual accountability for earned good and incurred evil", "qa": [5], "mcq": [7]}, {"point": "Supplications concerning forgetfulness, error, burdens, pardon, mercy and help", "qa": [6], "mcq": [5]}, {"point": "Affirmative divine response and mercy toward the community", "qa": [6], "mcq": [5]}, {"point": "Abrogated ruling while the verse remains recited, as explained by the publisher", "qa": [7], "mcq": [6]}]}, "source": "https://hadeethenc.com/en/browse/hadith/65285"}, "10851": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Umamah al-Bahili", "qa": [{"id": "10851-focus-qa-1", "group": "Meaning and understanding", "q": "Who are the Quran's companions in the explanation of intercession?", "a": "The source describes those who recite it and act on its guidance. It particularly encourages al-Baqarah and Al Imran, the two radiant surahs, with recitation, reflection, and practice. The promise is presented through sustained engagement with the Quran, not merely owning a copy.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10851", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) encouraged the regular recitation of the Qur’an, for it will intercede on the Day of Judgment for those who recite it and act upon it.", "url": "https://hadeethenc.com/en/browse/hadith/10851", "anchor": "recite it and act upon it", "field": "E"}}, {"id": "10851-focus-qa-2", "group": "Meaning and understanding", "q": "What particular encouragement is given regarding al-Baqarah?", "a": "The narration contrasts blessing in taking recourse to it with grief in abandoning it and states that magicians cannot confront it. The explanation connects engagement with reciting, reflecting, and acting. These stated virtues should be taught without adding unrelated guarantees that the report does not give.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10851", "evidence": {"label": "Published English selection", "text": "Recite Surat al-Baqarah, for taking recourse to it is a blessing and abandoning it is a cause of grief, and magicians cannot confront it.\"", "url": "https://hadeethenc.com/en/browse/hadith/10851", "anchor": "cause of grief", "field": "T"}}, {"id": "10851-focus-qa-3", "group": "Meaning and understanding", "q": "What do the images of clouds, shade and birds convey in the explanation of the two bright surahs?", "a": "The explanation describes the reward of reciting, reflecting on and acting upon al-Baqarah and Al Imran as coming to shade and defend their companion on the Day of Judgment. The images explain their promised intercession, rather than replacing engagement with their guidance.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10851", "evidence": {"label": "Published explanation", "text": "The reward of reciting them, reflecting on their meanings, and acting upon their teachings will come on the Day of Judgment in the form of two clouds, or something similar, or two flocks of birds with outstretched wings joined together, offering shade to their companion and defending him.", "url": "https://hadeethenc.com/en/browse/hadith/10851", "anchor": "offering shade", "field": "E"}}], "mcq": [{"id": "10851-focus-mc-1", "q": "What role is promised for the Quran on the Day of Judgment?", "options": ["Intercession for its companions", "Exemption from acting on its guidance", "A reward based only on owning a copy", "Replacement of every other responsibility"], "correct": 0, "feedback": ["The explanation identifies its companions through recitation and action, not possession alone.", "The supported answer is: Intercession for its companions. The explanation identifies its companions through recitation and action, not possession alone.", "The supported answer is: Intercession for its companions. The explanation identifies its companions through recitation and action, not possession alone.", "The supported answer is: Intercession for its companions. The explanation identifies its companions through recitation and action, not possession alone."], "hint": "Read the promise with the explanation of its recipients.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10851", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) encouraged the regular recitation of the Qur’an, for it will intercede on the Day of Judgment for those who recite it and act upon it.", "url": "https://hadeethenc.com/en/browse/hadith/10851", "anchor": "recite it and act upon it", "field": "E"}}, {"id": "10851-focus-mc-2", "q": "What contrast is made specifically about al-Baqarah?", "options": ["Owning it brings rank even if its guidance is rejected", "Its benefit is confined to historical information", "Taking recourse to it brings blessing; abandoning it brings grief", "Its recitation replaces the need to understand it"], "correct": 2, "feedback": ["The supported answer is: Taking recourse to it brings blessing; abandoning it brings grief. The closing clause contrasts blessing with regret; the explanation joins recitation, reflection, and action.", "The supported answer is: Taking recourse to it brings blessing; abandoning it brings grief. The closing clause contrasts blessing with regret; the explanation joins recitation, reflection, and action.", "The closing clause contrasts blessing with regret; the explanation joins recitation, reflection, and action.", "The supported answer is: Taking recourse to it brings blessing; abandoning it brings grief. The closing clause contrasts blessing with regret; the explanation joins recitation, reflection, and action."], "hint": "Read the statement after the renewed command to recite al-Baqarah.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10851", "evidence": {"label": "Published English selection", "text": "Recite Surat al-Baqarah, for taking recourse to it is a blessing and abandoning it is a cause of grief, and magicians cannot confront it.\"", "url": "https://hadeethenc.com/en/browse/hadith/10851", "anchor": "cause of grief", "field": "T"}}, {"id": "10851-focus-mc-3", "q": "Which pair is identified as Az-Zahrawayn in this report?", "options": ["Al-Fatihah and Al-Ikhlas", "Al-Anfal and At-Tawbah", "Al-Baqarah and Al Imran", "Al-Falaq and An-Nas"], "correct": 2, "feedback": ["The supported answer is: Al-Baqarah and Al Imran. The report names the two surahs before describing their intercession.", "The supported answer is: Al-Baqarah and Al Imran. The report names the two surahs before describing their intercession.", "The report names the two surahs before describing their intercession.", "The supported answer is: Al-Baqarah and Al Imran. The report names the two surahs before describing their intercession."], "hint": "Use the names in the narration rather than another familiar pair of surahs.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10851", "evidence": {"label": "Published English selection", "text": "Recite Az-Zahrāwayn (the two bright ones), Al-Baqarah, and Āl ‘Imrān, for on the Day of Judgment, they will come as two clouds or two shades, or two flocks of birds in ranks, pleading for those who recite them.", "url": "https://hadeethenc.com/en/browse/hadith/10851", "anchor": "Āl ‘Imrān", "field": "T"}}, {"id": "10851-focus-mc-4", "q": "Which particular merit belongs to al-Baqarah in the closing instruction?", "options": ["Its recitation removes the need to follow any command", "Magicians cannot confront it", "Its blessings depend on paying for a newly invented ritual", "It is useful only when studied without recitation"], "correct": 1, "feedback": ["The supported answer is: Magicians cannot confront it. The final clause and the third benefit identify protection from magic as one of this surah's merits.", "The final clause and the third benefit identify protection from magic as one of this surah's merits.", "The supported answer is: Magicians cannot confront it. The final clause and the third benefit identify protection from magic as one of this surah's merits.", "The supported answer is: Magicians cannot confront it. The final clause and the third benefit identify protection from magic as one of this surah's merits."], "hint": "Keep the wording of the merit distinct from rituals not specified here.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10851", "evidence": {"label": "Published benefit 3", "text": "The merit of Surat al-Baqarah and that it protects its companion from magic.", "url": "https://hadeethenc.com/en/browse/hadith/10851", "anchor": "magic", "field": "B3"}}], "coverage": {"focusedAnswers": 3, "thematicQuestions": 4, "completeSanadProvided": false, "topics": [{"point": "Quran intercession for those who recite and follow its guidance", "qa": [1], "mcq": [1]}, {"point": "Al-Baqarah and Al Imran as the two bright surahs", "qa": [1, 3], "mcq": [3]}, {"point": "Clouds, shade and birds as images of defending and shading their companion", "qa": [3], "mcq": [1]}, {"point": "Blessing in engagement with al-Baqarah and grief in abandoning it", "qa": [2], "mcq": [2]}, {"point": "Al-Baqarah's stated merit concerning magic without added ritual guarantees", "qa": [2], "mcq": [4]}]}, "source": "https://hadeethenc.com/en/browse/hadith/10851"}, "10119": {"revision": "topic001-coverage-2026-10-17", "narrator": "Umar ibn al-Khattab", "qa": [{"id": "10119-focus-qa-1", "group": "Meaning and understanding", "q": "Why can the same Book be associated with elevation for some and lowering for others?", "a": "The explanation locates the difference in people's response. Those elevated believe its reports, observe its commands, and adopt its conduct. Others may recite well yet arrogantly reject its guidance. The lesson concerns how a person receives and follows the Book, rather than fluency or possession alone.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10119", "evidence": {"label": "Published explanation", "text": "On the other hand, the people whom Allah degrades by means of the Qur'an are those who read the Qur'an and even recite it well, but are arrogant toward it.", "url": "https://hadeethenc.com/en/browse/hadith/10119", "anchor": "recite it well", "field": "E"}}, {"id": "10119-focus-qa-2", "group": "Meaning and understanding", "q": "Where does the explanation place the elevation or lowering mentioned in this report?", "a": "It applies the contrast to this world and the Hereafter. Its explanation is tied to belief and conduct toward the Quran, not to a promise that every proficient reader will gain worldly office or wealth.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/10119", "evidence": {"label": "Published explanation", "text": "Allah elevates by means of the Qur'an some people in the world and afterlife, and demotes by means of which others in both worlds.", "url": "https://hadeethenc.com/en/browse/hadith/10119", "anchor": "both worlds", "field": "E"}}], "mcq": [{"id": "10119-focus-mc-1", "q": "Why is fluent recitation alone not the whole criterion in the explanation?", "options": ["A person may recite well yet arrogantly reject its teachings", "Every fluent reciter must be insincere", "Good pronunciation has no value at all", "Understanding automatically cancels the need to recite"], "correct": 0, "feedback": ["The explanation expressly describes people who read well but neither believe nor implement its rulings.", "The supported answer is: A person may recite well yet arrogantly reject its teachings. The explanation expressly describes people who read well but neither believe nor implement its rulings.", "The supported answer is: A person may recite well yet arrogantly reject its teachings. The explanation expressly describes people who read well but neither believe nor implement its rulings.", "The supported answer is: A person may recite well yet arrogantly reject its teachings. The explanation expressly describes people who read well but neither believe nor implement its rulings."], "hint": "Distinguish technical skill from response to the message.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10119", "evidence": {"label": "Published explanation", "text": "On the other hand, the people whom Allah degrades by means of the Qur'an are those who read the Qur'an and even recite it well, but are arrogant toward it.", "url": "https://hadeethenc.com/en/browse/hadith/10119", "anchor": "recite it well", "field": "E"}}, {"id": "10119-focus-mc-2", "q": "Which response to the Quran explains elevation in the publisher's account?", "options": ["Fluent reading accompanied by deliberate rejection of its guidance", "Possessing a copy while refusing to learn from it", "Using family prestige instead of personal conduct", "Believing its reports, observing its rulings and adopting its ethics"], "correct": 3, "feedback": ["The supported answer is: Believing its reports, observing its rulings and adopting its ethics. The explanation identifies belief, commands, prohibitions and ethical example as the response of those elevated.", "The supported answer is: Believing its reports, observing its rulings and adopting its ethics. The explanation identifies belief, commands, prohibitions and ethical example as the response of those elevated.", "The supported answer is: Believing its reports, observing its rulings and adopting its ethics. The explanation identifies belief, commands, prohibitions and ethical example as the response of those elevated.", "The explanation identifies belief, commands, prohibitions and ethical example as the response of those elevated."], "hint": "Look for how the explanation describes those who follow the Book.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/10119", "evidence": {"label": "Published explanation", "text": "Those who are elevated are those who follow the Qur'an, believe in its news, observe its commands and prohibitions, and take as their model the ethics it promotes.", "url": "https://hadeethenc.com/en/browse/hadith/10119", "anchor": "ethics", "field": "E"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 2, "completeSanadProvided": false, "topics": [{"point": "Elevation through belief, rulings and ethical response to the Book", "qa": [1], "mcq": [2]}, {"point": "Arrogant rejection despite fluent recitation and consequences in both worlds", "qa": [1, 2], "mcq": [1]}]}, "source": "https://hadeethenc.com/en/browse/hadith/10119"}, "65059": {"revision": "topic001-coverage-2026-10-17", "narrator": "Ubayy ibn Kab", "qa": [{"id": "65059-focus-qa-1", "group": "Meaning and understanding", "q": "Why is the exchange about Ayat al-Kursi more than a test of a verse's name?", "a": "Ubayy first defers, then identifies the verse beginning with Allah's oneness and the attributes Ever-Living and All-Sustaining. The Prophet affirms his answer and encourages his knowledge. The published benefit directs learners to memorize the verse, reflect on its meaning, and act accordingly.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/65059", "evidence": {"label": "Published benefit 2", "text": "So, we should memorize it, ponder its meanings, and act accordingly.", "url": "https://hadeethenc.com/en/browse/hadith/65059", "anchor": "ponder its meanings", "field": "B2"}}], "mcq": [{"id": "65059-focus-mc-1", "q": "Which verse did Ubayy identify as the greatest?", "options": ["The final verse of al-Baqarah, 2:286", "The opening verse of al-Fatihah, 1:1", "Ayat al-Kursi, al-Baqarah 2:255", "The opening verse of al-Ikhlas, 112:1"], "correct": 2, "feedback": ["The supported answer is: Ayat al-Kursi, al-Baqarah 2:255. The report quotes the beginning of Ayat al-Kursi and gives its reference.", "The supported answer is: Ayat al-Kursi, al-Baqarah 2:255. The report quotes the beginning of Ayat al-Kursi and gives its reference.", "The report quotes the beginning of Ayat al-Kursi and gives its reference.", "The supported answer is: Ayat al-Kursi, al-Baqarah 2:255. The report quotes the beginning of Ayat al-Kursi and gives its reference."], "hint": "Match the quoted opening to its verse reference.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65059", "evidence": {"label": "Published English selection", "text": "Ubayy ibn Ka‘b (may Allah be pleased with him) reported: The Messenger of Allah (may Allah’s peace and blessings be upon him) said: \"O Abu al-Mundhir, do you know which verse of Allah's Book that you have is the greatest?\" I replied: \"Allah and His Messenger know best.\" He said: \"O Abu al-Mundhir, do you know which verse of Allah's Book that you have is the greatest?\" I said: \"{Allah: none has the right to be worshiped except Him, the Ever-Living, All-Sustaining...} [Surat al-Baqarah: 255].\" Thereupon, he struck me on the chest and said: \"May knowledge be pleasant for you, O Abu al-Mundhir!\"", "url": "https://hadeethenc.com/en/browse/hadith/65059", "anchor": "255", "field": "T"}}, {"id": "65059-focus-mc-2", "q": "What practice does the published benefit encourage regarding this verse?", "options": ["Learn only its title without its meaning", "Treat its excellence as a reason to ignore other verses", "Avoid studying it because its subject is difficult", "Memorize it, reflect on it, and act accordingly"], "correct": 3, "feedback": ["The supported answer is: Memorize it, reflect on it, and act accordingly. The benefit joins memorization with thought and action.", "The supported answer is: Memorize it, reflect on it, and act accordingly. The benefit joins memorization with thought and action.", "The supported answer is: Memorize it, reflect on it, and act accordingly. The benefit joins memorization with thought and action.", "The benefit joins memorization with thought and action."], "hint": "Read all three activities in the final benefit.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65059", "evidence": {"label": "Published benefit 2", "text": "So, we should memorize it, ponder its meanings, and act accordingly.", "url": "https://hadeethenc.com/en/browse/hadith/65059", "anchor": "ponder its meanings", "field": "B2"}}, {"id": "65059-focus-mc-3", "q": "What does the response to Ubayy's answer communicate in the explanation?", "options": ["A rejection of his identification of the verse", "A statement that knowledge makes practice unnecessary", "Affirmation of his knowledge and a supplication for it to be pleasant", "A demand that he avoid reflecting on the verse"], "correct": 2, "feedback": ["The supported answer is: Affirmation of his knowledge and a supplication for it to be pleasant. The explanation treats the response as recognition of knowledge and wisdom.", "The supported answer is: Affirmation of his knowledge and a supplication for it to be pleasant. The explanation treats the response as recognition of knowledge and wisdom.", "The explanation treats the response as recognition of knowledge and wisdom.", "The supported answer is: Affirmation of his knowledge and a supplication for it to be pleasant. The explanation treats the response as recognition of knowledge and wisdom."], "hint": "Read the Prophet's response after the correct identification.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/65059", "evidence": {"label": "Published explanation", "text": "He initially hesitated about the answer and then said: {Allah: none has the right to be worshiped except Him, the Ever-Living, All-Sustaining...} The Prophet (may Allah's peace and blessings be upon him) agreed with him and struck him on the chest, indicating that it is filled with knowledge and wisdom.", "url": "https://hadeethenc.com/en/browse/hadith/65059", "anchor": "knowledge and wisdom", "field": "E"}}], "coverage": {"focusedAnswers": 1, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Ubayy's initial deference, identification of Ayat al-Kursi and confirmation", "qa": [1], "mcq": [1, 3]}, {"point": "Recognition of knowledge and supplication for its benefit", "qa": [1], "mcq": [3]}, {"point": "Memorizing, reflecting on and acting upon the greatest verse", "qa": [1], "mcq": [2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/65059"}, "5795": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Hurayrah", "qa": [{"id": "5795-focus-qa-1", "group": "Meaning and understanding", "q": "Where does the source place the boundary between sustained worship and excess?", "a": "It recommends fulfilling duties within one's ability while avoiding both neglect and burdens that lead to abandoning deeds. The benefits give the example of excessive voluntary night prayer causing someone to miss the obligatory Fajr prayer. A greater quantity of voluntary activity is not beneficial when it undermines a more important duty.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/5795", "evidence": {"label": "Published benefit 6", "text": "Rather, it is to prevent excess that leads to boredom, or exaggeration in voluntary acts that lead to abandoning what is better or performing an obligatory act beyond its time, such as someone who spends the whole night praying and then sleeps and does not offer the Fajr prayer in congregation, or until the sun rises and the time for the obligatory prayer has passed.", "url": "https://hadeethenc.com/en/browse/hadith/5795", "anchor": "sleeps", "field": "B6"}}, {"id": "5795-focus-qa-2", "group": "Meaning and understanding", "q": "Why are active times and part of the night mentioned?", "a": "The explanation develops the image of a traveler who needs a sustainable pace. Suitable periods of energy help a person continue, whereas uninterrupted exertion can exhaust them. The qualification part of the night supports this point; it does not prescribe wakefulness throughout every night.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/5795", "evidence": {"label": "Published explanation", "text": "Since work at night is harder than the daytime, he enjoined part of it, saying: and part of the Duljah.", "url": "https://hadeethenc.com/en/browse/hadith/5795", "anchor": "work at night is harder", "field": "E"}}, {"id": "5795-focus-qa-3", "group": "Meaning and understanding", "q": "How can using a lawful concession support devotion?", "a": "The benefits discuss a prescribed concession, such as tayammum when water cannot be used, as proper obedience rather than failure. Refusing the concession merely to choose a harder course can be excess. Its use remains tied to the circumstances and conditions for which it is prescribed.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/5795", "evidence": {"label": "Published benefit 5", "text": "For example, a person refuses to perform Tayammum (dry ablution) when he is unable to use water, and his use of it leads to a harmful effect.", "url": "https://hadeethenc.com/en/browse/hadith/5795", "anchor": "Tayammum", "field": "B5"}}, {"id": "5795-focus-qa-4", "group": "Meaning and understanding", "q": "What does being close to uprightness mean when complete performance is genuinely beyond a person's capacity?", "a": "The explanation directs a person to perform what is close to the intended deed without neglecting duties or overburdening themselves. Its glad tidings concern genuine inability rather than using ease as an excuse for avoidable neglect.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/5795", "evidence": {"label": "Published explanation", "text": "This is because if the inability is not due to their own fault, it does not entail a reduction in their reward.", "url": "https://hadeethenc.com/en/browse/hadith/5795", "anchor": "not due to their own fault", "field": "E"}}], "mcq": [{"id": "5795-focus-mc-1", "q": "How do the references to morning, afternoon, and part of the night support the lesson?", "options": ["Stay awake throughout every night regardless of duties", "Use suitable active times to sustain worship", "Treat these times as a new replacement for obligatory prayers", "Avoid worship at every other permitted time"], "correct": 1, "feedback": ["The supported answer is: Use suitable active times to sustain worship. The source explains the traveling imagery through choosing times that help continuity.", "The source explains the traveling imagery through choosing times that help continuity.", "The supported answer is: Use suitable active times to sustain worship. The source explains the traveling imagery through choosing times that help continuity.", "The supported answer is: Use suitable active times to sustain worship. The source explains the traveling imagery through choosing times that help continuity."], "hint": "Connect active periods with the journey comparison.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5795", "evidence": {"label": "Published explanation", "text": "Since this world is in reality a place of travel and transfer to the Hereafter, the Prophet (may Allah's peace and blessings be upon him) commanded us to seek help, for the regular performance of worship, in the three times of activeness:", "url": "https://hadeethenc.com/en/browse/hadith/5795", "anchor": "times of activeness", "field": "E"}}, {"id": "5795-focus-mc-2", "q": "Which example of excess does the quoted benefit warn about?", "options": ["Rest that helps a person fulfill obligatory prayer", "Using a lawful concession when unable to use water", "Voluntary night prayer that leads to missing the obligatory Fajr prayer", "Maintaining a modest routine that one can continue"], "correct": 2, "feedback": ["The supported answer is: Voluntary night prayer that leads to missing the obligatory Fajr prayer. The final benefit warns against voluntary excess that undermines a greater or obligatory duty.", "The supported answer is: Voluntary night prayer that leads to missing the obligatory Fajr prayer. The final benefit warns against voluntary excess that undermines a greater or obligatory duty.", "The final benefit warns against voluntary excess that undermines a greater or obligatory duty.", "The supported answer is: Voluntary night prayer that leads to missing the obligatory Fajr prayer. The final benefit warns against voluntary excess that undermines a greater or obligatory duty."], "hint": "Compare the rank of the two acts in the example.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5795", "evidence": {"label": "Published benefit 6", "text": "Rather, it is to prevent excess that leads to boredom, or exaggeration in voluntary acts that lead to abandoning what is better or performing an obligatory act beyond its time, such as someone who spends the whole night praying and then sleeps and does not offer the Fajr prayer in congregation, or until the sun rises and the time for the obligatory prayer has passed.", "url": "https://hadeethenc.com/en/browse/hadith/5795", "anchor": "sleeps", "field": "B6"}}, {"id": "5795-focus-mc-3", "q": "What does the source say about lawful concessions when needed?", "options": ["They can support proper practice rather than represent failure", "They always show weak faith", "They must be refused whenever a harder path exists", "They remove the need to observe their conditions"], "correct": 0, "feedback": ["The fifth benefit discusses using a prescribed concession instead of harmful insistence on a harder course.", "The supported answer is: They can support proper practice rather than represent failure. The fifth benefit discusses using a prescribed concession instead of harmful insistence on a harder course.", "The supported answer is: They can support proper practice rather than represent failure. The fifth benefit discusses using a prescribed concession instead of harmful insistence on a harder course.", "The supported answer is: They can support proper practice rather than represent failure. The fifth benefit discusses using a prescribed concession instead of harmful insistence on a harder course."], "hint": "Read the example of inability to use water.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5795", "evidence": {"label": "Published benefit 5", "text": "For example, a person refuses to perform Tayammum (dry ablution) when he is unable to use water, and his use of it leads to a harmful effect.", "url": "https://hadeethenc.com/en/browse/hadith/5795", "anchor": "Tayammum", "field": "B5"}}, {"id": "5795-focus-mc-4", "q": "Which case belongs to the glad tidings explained for incomplete performance?", "options": ["Deliberately neglecting an obligation because it is inconvenient", "Genuine inability not caused by the person's own fault", "Choosing excess until a more important duty is missed", "Assuming every demanding act should be abandoned"], "correct": 1, "feedback": ["The supported answer is: Genuine inability not caused by the person's own fault. The explanation gives glad tidings for those unable to perform completely when the inability is not their own fault.", "The explanation gives glad tidings for those unable to perform completely when the inability is not their own fault.", "The supported answer is: Genuine inability not caused by the person's own fault. The explanation gives glad tidings for those unable to perform completely when the inability is not their own fault.", "The supported answer is: Genuine inability not caused by the person's own fault. The explanation gives glad tidings for those unable to perform completely when the inability is not their own fault."], "hint": "Keep real incapacity distinct from avoidable neglect.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/5795", "evidence": {"label": "Published explanation", "text": "This is because if the inability is not due to their own fault, it does not entail a reduction in their reward.", "url": "https://hadeethenc.com/en/browse/hadith/5795", "anchor": "not due to their own fault", "field": "E"}}], "coverage": {"focusedAnswers": 4, "thematicQuestions": 4, "completeSanadProvided": false, "topics": [{"point": "Ease between neglect and excess, without abandoning excellence", "qa": [1], "mcq": [2]}, {"point": "Genuine incapacity, approximation and glad tidings", "qa": [4], "mcq": [4]}, {"point": "Morning, afternoon and part of the night as a sustainable journey", "qa": [2], "mcq": [1]}, {"point": "A lawful concession such as tayammum when its conditions apply", "qa": [3], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/5795"}, "6389": {"revision": "topic001-coverage-2026-10-17", "narrator": "Aishah", "qa": [{"id": "6389-focus-qa-1", "group": "Meaning and understanding", "q": "What makes the choice of ease principled rather than a search for convenience at any cost?", "a": "Aishah states the limit expressly: the easier option must not be sinful. If it involved sin, the Prophet kept far from it. Ease is therefore a preference within obedience, not a rule that makes any convenient choice acceptable.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/6389", "evidence": {"label": "Published English selection", "text": "‘Ā’ishah, Mother of the Believers, (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) was never given a choice between two things except that he would choose the easier of the two unless it were a sin.", "url": "https://hadeethenc.com/en/browse/hadith/6389", "anchor": "unless it were a sin", "field": "T"}}, {"id": "6389-focus-qa-2", "group": "Meaning and understanding", "q": "How does the account distinguish personal forbearance from concern for Allah's limits?", "a": "He did not seek revenge merely for himself, yet the report distinguishes violations of Allah's sanctities. The explanation describes forgiveness of personal injury alongside adherence to divine limits. The distinction does not turn every private grievance or angry reaction into enforcement of Allah's rights.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/6389", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) never sought revenge for himself exclusively; rather, he would forgive and overlook his own rights.", "url": "https://hadeethenc.com/en/browse/hadith/6389", "anchor": "own rights", "field": "E"}}], "mcq": [{"id": "6389-focus-mc-1", "q": "What limits the preference for the easier of two options?", "options": ["The easier option must not involve sin", "It must attract more public approval", "It must always take less time", "It must require no sacrifice at all"], "correct": 0, "feedback": ["The narration makes lawfulness the explicit qualification on choosing ease.", "The supported answer is: The easier option must not involve sin. The narration makes lawfulness the explicit qualification on choosing ease.", "The supported answer is: The easier option must not involve sin. The narration makes lawfulness the explicit qualification on choosing ease.", "The supported answer is: The easier option must not involve sin. The narration makes lawfulness the explicit qualification on choosing ease."], "hint": "Keep the unless clause attached to the preference.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6389", "evidence": {"label": "Published English selection", "text": "‘Ā’ishah, Mother of the Believers, (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) was never given a choice between two things except that he would choose the easier of the two unless it were a sin.", "url": "https://hadeethenc.com/en/browse/hadith/6389", "anchor": "unless it were a sin", "field": "T"}}, {"id": "6389-focus-mc-2", "q": "What distinction must be preserved in reading the final clause?", "options": ["Every personal grievance automatically becomes a religious violation", "Forgiveness means that no religious limit matters", "Any angry reaction automatically enforces Allah's rights", "Personal grievance differs from violation of Allah's sanctities"], "correct": 3, "feedback": ["The supported answer is: Personal grievance differs from violation of Allah's sanctities. The account distinguishes motives and grounds of response; it is not an unrestricted license for personal retaliation.", "The supported answer is: Personal grievance differs from violation of Allah's sanctities. The account distinguishes motives and grounds of response; it is not an unrestricted license for personal retaliation.", "The supported answer is: Personal grievance differs from violation of Allah's sanctities. The account distinguishes motives and grounds of response; it is not an unrestricted license for personal retaliation.", "The account distinguishes motives and grounds of response; it is not an unrestricted license for personal retaliation."], "hint": "Read the two kinds of concern separately.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/6389", "evidence": {"label": "Published explanation", "text": "The Prophet (may Allah's peace and blessings be upon him) never sought revenge for himself exclusively; rather, he would forgive and overlook his own rights.", "url": "https://hadeethenc.com/en/browse/hadith/6389", "anchor": "own rights", "field": "E"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 2, "completeSanadProvided": false, "topics": [{"point": "Choosing ease only within lawful limits", "qa": [1], "mcq": [1]}, {"point": "Personal forgiveness distinguished from concern for Allah's sanctities", "qa": [2], "mcq": [2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/6389"}, "11282": {"revision": "topic001-coverage-2026-10-17", "narrator": "Aishah", "qa": [{"id": "11282-focus-qa-1", "group": "Meaning and understanding", "q": "Why is leaving a deed not necessarily evidence that the Prophet disliked it?", "a": "Aishah explicitly says that he might like a deed yet leave it out of concern that people would follow him and it could become obligatory for them. The reason for omission therefore matters. This account highlights compassion for the community rather than rejection of worship.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/11282", "evidence": {"label": "Published English selection", "text": "‘Ā’ishah (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) would give up a deed, even though he liked to perform it, for fear that people would follow him and perform it, and it would thus become obligatory for them.", "url": "https://hadeethenc.com/en/browse/hadith/11282", "anchor": "even though he liked", "field": "T"}}, {"id": "11282-focus-qa-2", "group": "Meaning and understanding", "q": "How does the explanation qualify Aishah's statement about Duha prayer?", "a": "It reads the apparent negation as lack of regular performance, not denial of every occurrence. The explanation says he sometimes offered it and sometimes left it for the concern already described. Aishah's own statement that she offered it should also be read as part of the account.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/11282", "evidence": {"label": "Published explanation", "text": "Then, she says that the Prophet would not perform the Duha prayer, but the scholars took this negation to refer to lack of regular performance; that is the Prophet would offer it sometimes, for its merit, and abandon it at other times lest it might beccome obligatory for people, as she mentions early in the Hadīth.", "url": "https://hadeethenc.com/en/browse/hadith/11282", "anchor": "lack of regular performance", "field": "E"}}], "mcq": [{"id": "11282-focus-mc-1", "q": "Why might the Prophet leave a deed he liked?", "options": ["Dislike of every voluntary act", "A wish that no one learn from his conduct", "A belief that private worship had no value", "Concern that following him could make it obligatory for the people"], "correct": 3, "feedback": ["The supported answer is: Concern that following him could make it obligatory for the people. The narration explicitly links his omission with concern for the community's burden.", "The supported answer is: Concern that following him could make it obligatory for the people. The narration explicitly links his omission with concern for the community's burden.", "The supported answer is: Concern that following him could make it obligatory for the people. The narration explicitly links his omission with concern for the community's burden.", "The narration explicitly links his omission with concern for the community's burden."], "hint": "Distinguish liking the deed from the reason for leaving it.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/11282", "evidence": {"label": "Published English selection", "text": "‘Ā’ishah (may Allah be pleased with her) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) would give up a deed, even though he liked to perform it, for fear that people would follow him and perform it, and it would thus become obligatory for them.", "url": "https://hadeethenc.com/en/browse/hadith/11282", "anchor": "become obligatory", "field": "T"}}, {"id": "11282-focus-mc-2", "q": "How does the publisher explain Aishah's statement about Duha?", "options": ["As a negation of regular performance, not every occurrence", "As a denial that any report of Duha can be true", "As proof that Duha was forbidden to all Muslims", "As a command that everyone must offer Duha daily"], "correct": 0, "feedback": ["The explanation states that scholars read the negation in terms of regularity, considering connected evidence.", "The supported answer is: As a negation of regular performance, not every occurrence. The explanation states that scholars read the negation in terms of regularity, considering connected evidence.", "The supported answer is: As a negation of regular performance, not every occurrence. The explanation states that scholars read the negation in terms of regularity, considering connected evidence.", "The supported answer is: As a negation of regular performance, not every occurrence. The explanation states that scholars read the negation in terms of regularity, considering connected evidence."], "hint": "Look for the qualification supplied by the explanation.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/11282", "evidence": {"label": "Published explanation", "text": "Then, she says that the Prophet would not perform the Duha prayer, but the scholars took this negation to refer to lack of regular performance; that is the Prophet would offer it sometimes, for its merit, and abandon it at other times lest it might beccome obligatory for people, as she mentions early in the Hadīth.", "url": "https://hadeethenc.com/en/browse/hadith/11282", "anchor": "lack of regular performance", "field": "E"}}, {"id": "11282-focus-mc-3", "q": "Who says that she personally offers Duha prayer in the final clause?", "options": ["The Prophet quoting a divine saying", "Bilal as the caller to prayer", "The companions speaking as a group", "Aishah"], "correct": 3, "feedback": ["The supported answer is: Aishah. The final phrase is Aishah's own statement within her narration.", "The supported answer is: Aishah. The final phrase is Aishah's own statement within her narration.", "The supported answer is: Aishah. The final phrase is Aishah's own statement within her narration.", "The final phrase is Aishah's own statement within her narration."], "hint": "Keep the narrator's comment distinct from a direct Prophetic saying.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/11282", "evidence": {"label": "Published English selection", "text": "The Prophet (may Allah's peace and blessings be upon him) never prayed the Duha prayer, but I offer it.", "url": "https://hadeethenc.com/en/browse/hadith/11282", "anchor": "I offer it", "field": "T"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Leaving a liked deed out of concern about its becoming obligatory", "qa": [1], "mcq": [1]}, {"point": "The publisher's qualification of the report about regular Duha prayer", "qa": [2], "mcq": [2]}, {"point": "Aishah's own practice distinguished from the Prophet's words", "qa": [2], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/11282"}, "3373": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Hurayrah", "qa": [{"id": "3373-focus-qa-1", "group": "Meaning and understanding", "q": "How does reward for guiding others relate to their own reward?", "a": "The caller receives a reward like that of those who follow, without diminishing theirs. The warning about misguidance follows the same structure: the influence can bring corresponding guilt without removing the followers' responsibility. The report treats moral influence as consequential rather than transferring all responsibility to one person.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3373", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever calls to guidance shall receive a reward similar to the rewards obtained by those who followed him without diminishing anything from their rewards.", "url": "https://hadeethenc.com/en/browse/hadith/3373", "anchor": "without diminishing anything from their rewards", "field": "T"}}, {"id": "3373-focus-qa-2", "group": "Meaning and understanding", "q": "Can conduct influence others without an explicit invitation?", "a": "Yes. The explanation includes words and deeds, and the final benefit warns about public wrongdoing that others imitate even without being urged. The lesson applies to the example a person sets as well as what they formally teach.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3373", "evidence": {"label": "Published benefit 4", "text": "A Muslim must beware of being taken as an example if he commits a sin publicly and people see him, as he will be held sinful because of those who imitate him, even if he does not urge them to do that.", "url": "https://hadeethenc.com/en/browse/hadith/3373", "anchor": "even if he does not urge", "field": "B4"}}], "mcq": [{"id": "3373-focus-mc-1", "q": "What happens to the followers' reward?", "options": ["It is not diminished by the caller's reward", "It is divided equally between caller and followers", "It is transferred entirely to the caller", "It disappears if another teacher repeats the guidance"], "correct": 0, "feedback": ["The report expressly rules out reduction of their rewards.", "The supported answer is: It is not diminished by the caller's reward. The report expressly rules out reduction of their rewards.", "The supported answer is: It is not diminished by the caller's reward. The report expressly rules out reduction of their rewards.", "The supported answer is: It is not diminished by the caller's reward. The report expressly rules out reduction of their rewards."], "hint": "Read the qualification attached to the promised reward.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3373", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported that the Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever calls to guidance shall receive a reward similar to the rewards obtained by those who followed him without diminishing anything from their rewards.", "url": "https://hadeethenc.com/en/browse/hadith/3373", "anchor": "without diminishing anything from their rewards", "field": "T"}}, {"id": "3373-focus-mc-2", "q": "Why does the final benefit warn about public wrongdoing?", "options": ["Every unseen mistake automatically becomes a public lesson", "Only spoken commands can influence other people", "Publicity removes the original person's responsibility", "Others may imitate it even without an explicit invitation"], "correct": 3, "feedback": ["The supported answer is: Others may imitate it even without an explicit invitation. The benefit warns about becoming an example through visible conduct.", "The supported answer is: Others may imitate it even without an explicit invitation. The benefit warns about becoming an example through visible conduct.", "The supported answer is: Others may imitate it even without an explicit invitation. The benefit warns about becoming an example through visible conduct.", "The benefit warns about becoming an example through visible conduct."], "hint": "Notice that imitation can occur without a spoken request.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3373", "evidence": {"label": "Published benefit 4", "text": "A Muslim must beware of being taken as an example if he commits a sin publicly and people see him, as he will be held sinful because of those who imitate him, even if he does not urge them to do that.", "url": "https://hadeethenc.com/en/browse/hadith/3373", "anchor": "even if he does not urge", "field": "B4"}}, {"id": "3373-focus-mc-3", "q": "What happens to the followers' sins when the caller incurs a corresponding burden?", "options": ["Their responsibility is transferred entirely to the caller", "Their actions become morally neutral", "Their own sins are not diminished", "Their responsibility depends only on the caller's reputation"], "correct": 2, "feedback": ["The supported answer is: Their own sins are not diminished. The report expressly preserves the followers' responsibility on the side of misguidance as well as guidance.", "The supported answer is: Their own sins are not diminished. The report expressly preserves the followers' responsibility on the side of misguidance as well as guidance.", "The report expressly preserves the followers' responsibility on the side of misguidance as well as guidance.", "The supported answer is: Their own sins are not diminished. The report expressly preserves the followers' responsibility on the side of misguidance as well as guidance."], "hint": "Compare the two parallel halves of the narration.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3373", "evidence": {"label": "Published English selection", "text": "And whoever calls to misguidance shall incur a sin similar to the sins incurred by those who followed him without diminishing anything from their sins.\"", "url": "https://hadeethenc.com/en/browse/hadith/3373", "anchor": "without diminishing anything from their sins", "field": "T"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Reward for guidance without diminishing followers' rewards", "qa": [1], "mcq": [1]}, {"point": "Sin for misguidance without diminishing followers' responsibility", "qa": [1], "mcq": [3]}, {"point": "Influence through actions as well as explicit invitations", "qa": [2], "mcq": [2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/3373"}, "3506": {"revision": "topic001-coverage-2026-10-17", "narrator": "Jarir ibn Abdullah", "qa": [{"id": "3506-focus-qa-1", "group": "Meaning and understanding", "q": "Why must the saying about a good precedent be read within the charity account?", "a": "People in poverty prompted an appeal, and one donor's example encouraged further giving. The explanation identifies a good practice here as already established in the religion. It concerns bringing a known good into action, not making an unsupported ritual valid simply because others copy it.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3506", "evidence": {"label": "Published explanation", "text": "And whosoever introduces an evil practice in Islam will shoulder its sin and the sins of all those who will act upon it, without diminishing in any way their burden.\" \"A good practice\" here refers to something already established and rooted in the religion, not contrived and added to it.", "url": "https://hadeethenc.com/en/browse/hadith/3506", "anchor": "already established and rooted", "field": "E"}}, {"id": "3506-focus-qa-2", "group": "Meaning and understanding", "q": "What does encouraging even half a date contribute to the lesson?", "a": "The appeal includes different kinds and amounts of giving. Mentioning a small gift allows people of modest means to participate, while the substantial donation also becomes an example that encourages others. The lesson concerns responding to need according to one's means, not requiring one fixed amount from everyone.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3506", "evidence": {"label": "Published English selection", "text": "And let every one look what he has sent forth for the tomorrow.) Thereafter, every man gave in charity dinar, dirham, clothes, measure-fulls of wheat and measure-fulls of dates till he said: \"(Give in charity) be it half a date.\" Then a man from the Ansār came with a bag which was difficult for him to hold in his hand.", "url": "https://hadeethenc.com/en/browse/hadith/3506", "anchor": "half a date", "field": "T"}}, {"id": "3506-focus-qa-3", "group": "Meaning and understanding", "q": "What changed in the gathering after the first generous contribution?", "a": "The account describes people bringing further gifts until food and clothing accumulated in two heaps. The Prophet's visible distress at poverty changed to joy at the practical response, showing what the beneficial precedent achieved.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3506", "evidence": {"label": "Published English selection", "text": "Thereafter, the people came successively (with charity) till I saw two heaps of food and clothes.", "url": "https://hadeethenc.com/en/browse/hadith/3506", "anchor": "two heaps", "field": "T"}}, {"id": "3506-focus-qa-4", "group": "Meaning and understanding", "q": "Which Quranic reminders accompany the appeal for charity?", "a": "The sermon recalls a common human origin, duties of kinship and Allah's observation, followed by preparing what one sends ahead for tomorrow. These reminders connect immediate assistance with responsibility before Allah.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3506", "evidence": {"label": "Published English selection", "text": "And let every one look what he has sent forth for the tomorrow.) Thereafter, every man gave in charity dinar, dirham, clothes, measure-fulls of wheat and measure-fulls of dates till he said: \"(Give in charity) be it half a date.\" Then a man from the Ansār came with a bag which was difficult for him to hold in his hand.", "url": "https://hadeethenc.com/en/browse/hadith/3506", "anchor": "sent forth for the tomorrow", "field": "T"}}, {"id": "3506-focus-qa-5", "group": "Meaning and understanding", "q": "How does the closing warning balance the promise for setting a good example?", "a": "A person who begins an evil practice bears its sin and a corresponding burden for those who follow, without reducing their own responsibility. The narrative therefore teaches responsibility for harmful influence as well as reward for encouraging a known good.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3506", "evidence": {"label": "Published English selection", "text": "And whosoever introduces an evil practice in Islam will shoulder its sin and the sins of all those who will act upon it, without diminishing in any way their burden.\"", "url": "https://hadeethenc.com/en/browse/hadith/3506", "anchor": "evil practice", "field": "T"}}], "mcq": [{"id": "3506-focus-mc-1", "q": "Why did the Prophet mention even half a date?", "options": ["To require that every gift be exactly half a date", "To encourage giving according to one's means", "To exclude clothing and grain from charity", "To make large donations invalid"], "correct": 1, "feedback": ["The supported answer is: To encourage giving according to one's means. The appeal includes small and larger gifts; the text also records money, clothing, wheat, and dates.", "The appeal includes small and larger gifts; the text also records money, clothing, wheat, and dates.", "The supported answer is: To encourage giving according to one's means. The appeal includes small and larger gifts; the text also records money, clothing, wheat, and dates.", "The supported answer is: To encourage giving according to one's means. The appeal includes small and larger gifts; the text also records money, clothing, wheat, and dates."], "hint": "Compare the small example with the other gifts listed.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3506", "evidence": {"label": "Published English selection", "text": "And let every one look what he has sent forth for the tomorrow.) Thereafter, every man gave in charity dinar, dirham, clothes, measure-fulls of wheat and measure-fulls of dates till he said: \"(Give in charity) be it half a date.\" Then a man from the Ansār came with a bag which was difficult for him to hold in his hand.", "url": "https://hadeethenc.com/en/browse/hadith/3506", "anchor": "half a date", "field": "T"}}, {"id": "3506-focus-mc-2", "q": "What does good practice mean in the source explanation here?", "options": ["An already established religious good put into practice", "An unsupported new ritual made valid by enthusiasm", "Any custom made binding by repetition", "Every action copied by a large crowd"], "correct": 0, "feedback": ["The explanation expressly says established and rooted in religion, illustrated here by charity.", "The supported answer is: An already established religious good put into practice. The explanation expressly says established and rooted in religion, illustrated here by charity.", "The supported answer is: An already established religious good put into practice. The explanation expressly says established and rooted in religion, illustrated here by charity.", "The supported answer is: An already established religious good put into practice. The explanation expressly says established and rooted in religion, illustrated here by charity."], "hint": "Use the setting and the explanation together.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3506", "evidence": {"label": "Published explanation", "text": "And whosoever introduces an evil practice in Islam will shoulder its sin and the sins of all those who will act upon it, without diminishing in any way their burden.\" \"A good practice\" here refers to something already established and rooted in the religion, not contrived and added to it.", "url": "https://hadeethenc.com/en/browse/hadith/3506", "anchor": "already established and rooted", "field": "E"}}, {"id": "3506-focus-mc-3", "q": "What follows the generous example of the man from the Ansar?", "options": ["Further contributions accumulate into heaps of food and clothes", "The need for assistance is dismissed as unimportant", "Every companion is required to bring the same amount", "Giving small amounts is declared unacceptable"], "correct": 0, "feedback": ["The account connects an initiating example with others' practical response.", "The supported answer is: Further contributions accumulate into heaps of food and clothes. The account connects an initiating example with others' practical response.", "The supported answer is: Further contributions accumulate into heaps of food and clothes. The account connects an initiating example with others' practical response.", "The supported answer is: Further contributions accumulate into heaps of food and clothes. The account connects an initiating example with others' practical response."], "hint": "Trace the sequence after the first large contribution.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3506", "evidence": {"label": "Published English selection", "text": "Thereafter, the people came successively (with charity) till I saw two heaps of food and clothes.", "url": "https://hadeethenc.com/en/browse/hadith/3506", "anchor": "two heaps", "field": "T"}}, {"id": "3506-focus-mc-4", "q": "Which reminder from the sermon connects charity with future accountability?", "options": ["Consider what one has sent ahead for tomorrow", "Judge a gift only by how much praise it receives", "Let ancestry replace personal responsibility", "Assume hidden need cannot be a community concern"], "correct": 0, "feedback": ["The verse from al-Hashr directs each person to consider what they send ahead.", "The supported answer is: Consider what one has sent ahead for tomorrow. The verse from al-Hashr directs each person to consider what they send ahead.", "The supported answer is: Consider what one has sent ahead for tomorrow. The verse from al-Hashr directs each person to consider what they send ahead.", "The supported answer is: Consider what one has sent ahead for tomorrow. The verse from al-Hashr directs each person to consider what they send ahead."], "hint": "Look for the sermon passage about tomorrow rather than the amounts donated.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3506", "evidence": {"label": "Published English selection", "text": "And let every one look what he has sent forth for the tomorrow.) Thereafter, every man gave in charity dinar, dirham, clothes, measure-fulls of wheat and measure-fulls of dates till he said: \"(Give in charity) be it half a date.\" Then a man from the Ansār came with a bag which was difficult for him to hold in his hand.", "url": "https://hadeethenc.com/en/browse/hadith/3506", "anchor": "sent forth for the tomorrow", "field": "T"}}, {"id": "3506-focus-mc-5", "q": "What does the final warning say about followers of an evil precedent?", "options": ["Their sins are removed entirely from them", "Their conduct becomes lawful because someone acted first", "Only the most recent follower bears any responsibility", "They retain their burden even when the initiator bears a corresponding sin"], "correct": 3, "feedback": ["The supported answer is: They retain their burden even when the initiator bears a corresponding sin. The final sentence does not diminish the burden of those who act upon the evil practice.", "The supported answer is: They retain their burden even when the initiator bears a corresponding sin. The final sentence does not diminish the burden of those who act upon the evil practice.", "The supported answer is: They retain their burden even when the initiator bears a corresponding sin. The final sentence does not diminish the burden of those who act upon the evil practice.", "The final sentence does not diminish the burden of those who act upon the evil practice."], "hint": "Compare the warning with the promise concerning a good precedent.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3506", "evidence": {"label": "Published English selection", "text": "And whosoever introduces an evil practice in Islam will shoulder its sin and the sins of all those who will act upon it, without diminishing in any way their burden.\"", "url": "https://hadeethenc.com/en/browse/hadith/3506", "anchor": "without diminishing in any way their burden", "field": "T"}}], "coverage": {"focusedAnswers": 5, "thematicQuestions": 5, "completeSanadProvided": false, "topics": [{"point": "Poverty, compassion and the appeal leading to practical relief", "qa": [1, 3], "mcq": [3]}, {"point": "Quranic reminders of human origin, kinship and preparing for tomorrow", "qa": [4], "mcq": [4]}, {"point": "Different gifts, including half a date, within one's means", "qa": [2], "mcq": [1]}, {"point": "The initiating donor and further gifts accumulating for those in need", "qa": [3], "mcq": [3]}, {"point": "Good precedent rooted in established charity, rather than invented rituals", "qa": [1], "mcq": [2]}, {"point": "Evil precedent and undiminished responsibility of those who follow it", "qa": [5], "mcq": [5]}]}, "source": "https://hadeethenc.com/en/browse/hadith/3506"}, "3395": {"revision": "topic001-coverage-2026-10-17", "narrator": "Ibn Abbas", "qa": [{"id": "3395-focus-qa-1", "group": "Meaning and understanding", "q": "How does the example of the Hajj pebbles explain the warning against excess?", "a": "The Prophet showed the small pebbles and instructed people to use their like, then warned against exceeding religious limits. The practical setting makes the principle concrete: greater size or severity is not automatically greater devotion. Following the demonstrated guidance is the relevant standard.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/3395", "evidence": {"label": "Published English selection", "text": "He started shaking them in his hand and saying: \"Throw the like of these.\" Then, he said: \"O people, beware of immoderation in religion, for those before you were doomed because of immoderation in religion.\"", "url": "https://hadeethenc.com/en/browse/hadith/3395", "anchor": "Throw the like of these", "field": "T"}}], "mcq": [{"id": "3395-focus-mc-1", "q": "Which lesson best fits the example of the pebbles?", "options": ["Every small act is superior to every large act", "Greater severity is not a substitute for following the prescribed guidance", "The size of an object is irrelevant to every rite", "Devotion requires exceeding the demonstrated amount"], "correct": 1, "feedback": ["The supported answer is: Greater severity is not a substitute for following the prescribed guidance. The example and warning together direct adherence rather than an assumption that more severe means more devout.", "The example and warning together direct adherence rather than an assumption that more severe means more devout.", "The supported answer is: Greater severity is not a substitute for following the prescribed guidance. The example and warning together direct adherence rather than an assumption that more severe means more devout.", "The supported answer is: Greater severity is not a substitute for following the prescribed guidance. The example and warning together direct adherence rather than an assumption that more severe means more devout."], "hint": "Keep the concrete instruction and its warning together.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3395", "evidence": {"label": "Published benefit 3", "text": "Encouragement of adherence to the Sunnah.", "url": "https://hadeethenc.com/en/browse/hadith/3395", "anchor": "adherence to the Sunnah", "field": "B3"}}, {"id": "3395-focus-mc-2", "q": "What does the warning draw from the experience of earlier nations?", "options": ["A reason to intensify every practice beyond its prescribed measure", "A permission to replace the demonstrated practice with personal severity", "A lesson to avoid the excess that brought their destruction", "A claim that religious excess has no practical consequences"], "correct": 2, "feedback": ["The supported answer is: A lesson to avoid the excess that brought their destruction. The closing warning explicitly connects immoderation with the fate of those before.", "The supported answer is: A lesson to avoid the excess that brought their destruction. The closing warning explicitly connects immoderation with the fate of those before.", "The closing warning explicitly connects immoderation with the fate of those before.", "The supported answer is: A lesson to avoid the excess that brought their destruction. The closing warning explicitly connects immoderation with the fate of those before."], "hint": "Join the practical demonstration to the stated historical warning.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3395", "evidence": {"label": "Published English selection", "text": "He started shaking them in his hand and saying: \"Throw the like of these.\" Then, he said: \"O people, beware of immoderation in religion, for those before you were doomed because of immoderation in religion.\"", "url": "https://hadeethenc.com/en/browse/hadith/3395", "anchor": "those before you", "field": "T"}}, {"id": "3395-focus-mc-3", "q": "Which selection matches the practical demonstration at Jamrat al-Aqabah?", "options": ["Seven large stones chosen to make the act more severe", "One large stone in place of the seven pebbles", "Seven small pebbles of the demonstrated size", "An unrestricted number with size left to personal severity"], "correct": 2, "feedback": ["The supported answer is: Seven small pebbles of the demonstrated size. The account names seven small pebbles and makes their size the model, linking the practical detail with avoiding excess.", "The supported answer is: Seven small pebbles of the demonstrated size. The account names seven small pebbles and makes their size the model, linking the practical detail with avoiding excess.", "The account names seven small pebbles and makes their size the model, linking the practical detail with avoiding excess.", "The supported answer is: Seven small pebbles of the demonstrated size. The account names seven small pebbles and makes their size the model, linking the practical detail with avoiding excess."], "hint": "Keep the number and the demonstrated size together.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/3395", "evidence": {"label": "Published English selection", "text": "Ibn ‘Abbās (may Allah be pleased with him and his father) reported: On the morning of ‘Aqabah, when the Messenger of Allah (may Allah's peace and blessings be upon him) was atop his she-camel, he said: \"Pick up some pebbles for me.\" So I picked up seven pebbles for him, which were the size of pebbles used for flinging with fingers.", "url": "https://hadeethenc.com/en/browse/hadith/3395", "anchor": "seven pebbles", "field": "T"}}], "coverage": {"focusedAnswers": 1, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Seven small pebbles and the demonstrated measure at Jamrat al-Aqabah", "qa": [1], "mcq": [1, 3]}, {"point": "The general warning against excess and the fate of earlier nations", "qa": [1], "mcq": [2]}]}, "source": "https://hadeethenc.com/en/browse/hadith/3395"}, "4801": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Hurayrah", "qa": [{"id": "4801-focus-qa-1", "group": "Meaning and understanding", "q": "How are relieving hardship and helping others related to recompense?", "a": "The report promises corresponding divine relief for easing a believer's difficulty and states that Allah helps a person who helps their brother. The explanation includes practical assistance, money, and supplication. Service is therefore broader than a single form of charity, while the promised relief should not be replaced with an invented fixed worldly payment.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published explanation", "text": "Support could be through supplication, physical action, money, etc.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "supplication, physical action, money", "field": "E"}}, {"id": "4801-focus-qa-2", "group": "Meaning and understanding", "q": "When can concealing a fault become protection of wrongdoing?", "a": "The benefits distinguish a private slip from persistence in corruption and harm. Concealment must not cancel correcting evil; the source discusses referring persistent wrongdoing to those in authority while considering the risk of greater harm. The instruction should not be used as a blanket reason to hide ongoing harm.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published benefit 5", "text": "Rather, it should be changed and concealed at the same time, and this applies to those who are not known for corruption or persistence in transgression.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "persistence in transgression", "field": "B5"}}, {"id": "4801-focus-qa-3", "group": "Meaning and understanding", "q": "What joins the promise about seeking knowledge with the blessing of Quran study gatherings?", "a": "The report encourages a path of learning and describes gathering to recite and study the Quran. The explanation connects sincere pursuit of religious knowledge with a path to Paradise, and names tranquillity, mercy, angels, and Allah's mention among the gathering's blessings. These are reasons for serious study, not substitutes for learning accurately.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published explanation", "text": "Whoever walks in pursuit of religious knowledge, doing it for the sake of Allah Almighty, Allah will facilitate for him a path to Paradise.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "for the sake of Allah", "field": "E"}}, {"id": "4801-focus-qa-4", "group": "Meaning and understanding", "q": "Why does the narration end by mentioning lineage?", "a": "It warns that ancestry cannot make up for deficient deeds. The explanation specifically cautions against relying on noble forefathers while neglecting one's own conduct. This closing point brings the preceding encouragements back to personal action: helping, learning, and responding to guidance.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published English selection", "text": "And whoever is slowed down by his deeds will not be hastened forward by his lineage.\"", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "lineage", "field": "T"}}, {"id": "4801-focus-qa-5", "group": "Meaning and understanding", "q": "What distinct promise is given for easing the situation of someone in difficulty?", "a": "The report promises ease from Allah in both this world and the Hereafter. This is stated separately from the promise of relief on the Day of Judgment for relieving a believer's worldly hardship.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published English selection", "text": "Whoever makes things easy for someone in difficulty, Allah will make things easy for him in this world and the Hereafter.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "make things easy for him", "field": "T"}}, {"id": "4801-focus-qa-6", "group": "Meaning and understanding", "q": "Must the merit of joint Quran study be restricted to the particular mosque setting named in the narration?", "a": "The narration names one of Allah's houses. The quoted explanation from al-Nawawi also includes similar gatherings in a school or comparable setting, Allah willing. That extension is identified as commentary rather than silently inserted into the transmitted wording.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published benefit 7", "text": "and similar gatherings in a school, a garrison, or the like also attain this merit, Allah willing.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "school", "field": "B7"}}, {"id": "4801-focus-qa-7", "group": "Meaning and understanding", "q": "What positive promise accompanies concealing another Muslim's fault?", "a": "The narration promises that Allah will cover the person in this world and the Hereafter. The explanation concerns faults that should not be exposed; the qualification about persistent harmful conduct must be kept alongside this encouragement.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published English selection", "text": "Whoever covers a Muslim, Allah will cover him in this world and the Hereafter.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "Whoever covers a Muslim", "field": "T"}}], "mcq": [{"id": "4801-focus-mc-1", "q": "What is promised for relieving a believer's worldly hardship?", "options": ["Relief from a hardship on the Day of Judgment", "Exemption from every remaining obligation", "An exact sum of wealth in every case", "Immunity from every later worldly difficulty"], "correct": 0, "feedback": ["The first clause names a corresponding form of relief in the Hereafter, not a fixed worldly payment.", "The supported answer is: Relief from a hardship on the Day of Judgment. The first clause names a corresponding form of relief in the Hereafter, not a fixed worldly payment.", "The supported answer is: Relief from a hardship on the Day of Judgment. The first clause names a corresponding form of relief in the Hereafter, not a fixed worldly payment.", "The supported answer is: Relief from a hardship on the Day of Judgment. The first clause names a corresponding form of relief in the Hereafter, not a fixed worldly payment."], "hint": "Read the time attached to the promised relief.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published English selection", "text": "Abu Hurayrah (may Allah be pleased with him) reported: The Messenger of Allah (may Allah's peace and blessings be upon him) said: \"Whoever relieves a believer from one of the hardships of this world, Allah will relieve him from one of the hardships of the Day of Judgment.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "Day of Judgment", "field": "T"}}, {"id": "4801-focus-mc-2", "q": "What is promised for sincerely pursuing religious knowledge?", "options": ["An easier path to Paradise", "Automatic expertise without study", "Freedom from checking the accuracy of reports", "A rank determined only by family lineage"], "correct": 0, "feedback": ["The explanation connects seeking religious knowledge for Allah's sake with the promised path.", "The supported answer is: An easier path to Paradise. The explanation connects seeking religious knowledge for Allah's sake with the promised path.", "The supported answer is: An easier path to Paradise. The explanation connects seeking religious knowledge for Allah's sake with the promised path.", "The supported answer is: An easier path to Paradise. The explanation connects seeking religious knowledge for Allah's sake with the promised path."], "hint": "Read the condition concerning purpose in the explanation.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published explanation", "text": "Whoever walks in pursuit of religious knowledge, doing it for the sake of Allah Almighty, Allah will facilitate for him a path to Paradise.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "for the sake of Allah", "field": "E"}}, {"id": "4801-focus-mc-3", "q": "Which benefits are named for gathering to recite and study the Quran?", "options": ["Wealth, office, immunity, and public praise", "Expertise without study and freedom from duties", "A guarantee that every interpretation offered is sound", "Tranquillity, mercy, angels' presence, and Allah's mention"], "correct": 3, "feedback": ["The supported answer is: Tranquillity, mercy, angels' presence, and Allah's mention. The report enumerates these blessings; it does not authenticate every claim made in a gathering.", "The supported answer is: Tranquillity, mercy, angels' presence, and Allah's mention. The report enumerates these blessings; it does not authenticate every claim made in a gathering.", "The supported answer is: Tranquillity, mercy, angels' presence, and Allah's mention. The report enumerates these blessings; it does not authenticate every claim made in a gathering.", "The report enumerates these blessings; it does not authenticate every claim made in a gathering."], "hint": "Count the benefits stated after the description of the gathering.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published English selection", "text": "No group of people gather in one of the houses of Allah, reciting the Book of Allah and studying it among themselves, except that tranquility descends upon them, mercy envelops them, the angels surround them, and Allah mentions them to those near Him.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "tranquility descends", "field": "T"}}, {"id": "4801-focus-mc-4", "q": "What qualification does the source give about concealing faults?", "options": ["It requires hiding ongoing harm from the proper authorities", "It must not protect persistent wrongdoing or neglect correcting evil", "It cancels the need to protect people from wrongdoing", "It requires publicizing every private slip"], "correct": 1, "feedback": ["The supported answer is: It must not protect persistent wrongdoing or neglect correcting evil. The fifth benefit distinguishes private faults from persistent corruption and discusses referral to authority with attention to harm.", "The fifth benefit distinguishes private faults from persistent corruption and discusses referral to authority with attention to harm.", "The supported answer is: It must not protect persistent wrongdoing or neglect correcting evil. The fifth benefit distinguishes private faults from persistent corruption and discusses referral to authority with attention to harm.", "The supported answer is: It must not protect persistent wrongdoing or neglect correcting evil. The fifth benefit distinguishes private faults from persistent corruption and discusses referral to authority with attention to harm."], "hint": "Read the longer benefit rather than treating concealment as an unrestricted rule.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published benefit 5", "text": "Rather, it should be changed and concealed at the same time, and this applies to those who are not known for corruption or persistence in transgression.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "persistence in transgression", "field": "B5"}}, {"id": "4801-focus-mc-5", "q": "What limit on relying on ancestry closes the narration?", "options": ["Ancestry guarantees the reward of others' good deeds", "Family reputation removes the need to seek knowledge", "Lineage determines whether helping others has value", "Noble lineage cannot make up for deficient deeds"], "correct": 3, "feedback": ["The supported answer is: Noble lineage cannot make up for deficient deeds. The final clause makes deeds, rather than lineage, central to advancement.", "The supported answer is: Noble lineage cannot make up for deficient deeds. The final clause makes deeds, rather than lineage, central to advancement.", "The supported answer is: Noble lineage cannot make up for deficient deeds. The final clause makes deeds, rather than lineage, central to advancement.", "The final clause makes deeds, rather than lineage, central to advancement."], "hint": "Read the last sentence alongside the explanation of forefathers.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published English selection", "text": "And whoever is slowed down by his deeds will not be hastened forward by his lineage.\"", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "lineage", "field": "T"}}, {"id": "4801-focus-mc-6", "q": "What is promised for making things easy for a person in difficulty?", "options": ["A guarantee of a particular worldly salary", "Allah's ease in this world and the Hereafter", "Freedom from every responsibility toward that person", "A reward restricted to family prestige"], "correct": 1, "feedback": ["The supported answer is: Allah's ease in this world and the Hereafter. This promise has its own wording and scope alongside the relief of hardship on the Day of Judgment.", "This promise has its own wording and scope alongside the relief of hardship on the Day of Judgment.", "The supported answer is: Allah's ease in this world and the Hereafter. This promise has its own wording and scope alongside the relief of hardship on the Day of Judgment.", "The supported answer is: Allah's ease in this world and the Hereafter. This promise has its own wording and scope alongside the relief of hardship on the Day of Judgment."], "hint": "Read the separate sentence about the person in difficulty.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published English selection", "text": "Whoever makes things easy for someone in difficulty, Allah will make things easy for him in this world and the Hereafter.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "make things easy for him", "field": "T"}}, {"id": "4801-focus-mc-7", "q": "Which form of helping is included in the explanation even without giving money?", "options": ["Public praise that conceals ongoing harm", "Inventing a religious report to encourage the person", "Exposing every private error to entertain others", "Useful physical assistance or sincere supplication"], "correct": 3, "feedback": ["The supported answer is: Useful physical assistance or sincere supplication. The explanation includes supplication, physical action and money, and the benefits add knowledge and advice.", "The supported answer is: Useful physical assistance or sincere supplication. The explanation includes supplication, physical action and money, and the benefits add knowledge and advice.", "The supported answer is: Useful physical assistance or sincere supplication. The explanation includes supplication, physical action and money, and the benefits add knowledge and advice.", "The explanation includes supplication, physical action and money, and the benefits add knowledge and advice."], "hint": "Do not reduce help to one material form.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published explanation", "text": "Support could be through supplication, physical action, money, etc.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "physical action", "field": "E"}}, {"id": "4801-focus-mc-8", "q": "What does the quoted commentary say about comparable Quran-study gatherings in a school?", "options": ["They are explicitly named in the transmitted sentence as mosques", "They remove the need for careful teaching", "They may attain the merit too, Allah willing", "They are guaranteed to make every participant a qualified jurist"], "correct": 2, "feedback": ["The supported answer is: They may attain the merit too, Allah willing. The seventh benefit gives al-Nawawi's extension to similar settings; the distinction from the narrated wording remains clear.", "The supported answer is: They may attain the merit too, Allah willing. The seventh benefit gives al-Nawawi's extension to similar settings; the distinction from the narrated wording remains clear.", "The seventh benefit gives al-Nawawi's extension to similar settings; the distinction from the narrated wording remains clear.", "The supported answer is: They may attain the merit too, Allah willing. The seventh benefit gives al-Nawawi's extension to similar settings; the distinction from the narrated wording remains clear."], "hint": "Distinguish a commentator's extension from the exact setting named in the hadith.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published benefit 7", "text": "and similar gatherings in a school, a garrison, or the like also attain this merit, Allah willing.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "school", "field": "B7"}}, {"id": "4801-focus-mc-9", "q": "What does concealing a Muslim's fault receive in the narration, subject to the commentary's qualifications?", "options": ["Permission to protect persistent harmful conduct", "Allah's concealment in this world and the Hereafter", "A guarantee that no wrongdoing needs correction", "An exemption from every duty toward others"], "correct": 1, "feedback": ["The supported answer is: Allah's concealment in this world and the Hereafter. The positive promise is stated alongside benefits distinguishing private faults from persistent corruption.", "The positive promise is stated alongside benefits distinguishing private faults from persistent corruption.", "The supported answer is: Allah's concealment in this world and the Hereafter. The positive promise is stated alongside benefits distinguishing private faults from persistent corruption.", "The supported answer is: Allah's concealment in this world and the Hereafter. The positive promise is stated alongside benefits distinguishing private faults from persistent corruption."], "hint": "Keep the promise and its published qualification together.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/4801", "evidence": {"label": "Published English selection", "text": "Whoever covers a Muslim, Allah will cover him in this world and the Hereafter.", "url": "https://hadeethenc.com/en/browse/hadith/4801", "anchor": "Whoever covers a Muslim", "field": "T"}}], "coverage": {"focusedAnswers": 7, "thematicQuestions": 9, "completeSanadProvided": false, "topics": [{"point": "Relief of worldly hardship and relief on the Day of Judgment", "qa": [1], "mcq": [1]}, {"point": "Ease for a person in difficulty and ease in both worlds", "qa": [5], "mcq": [6]}, {"point": "Concealing a private fault and Allah's concealment in both worlds", "qa": [7], "mcq": [9]}, {"point": "Concealment must not shield persistent harmful conduct", "qa": [2], "mcq": [4, 9]}, {"point": "Allah's aid and practical help through action, money, supplication and advice", "qa": [1], "mcq": [7]}, {"point": "Sincere pursuit of knowledge and an easier path to Paradise", "qa": [3], "mcq": [2]}, {"point": "Joint Quran recitation and study: tranquillity, mercy, angels and Allah's mention", "qa": [3], "mcq": [3]}, {"point": "Al-Nawawi's commentary on similar gatherings in a school", "qa": [6], "mcq": [8]}, {"point": "Deeds rather than ancestry as the basis of advancement", "qa": [4], "mcq": [5]}]}, "source": "https://hadeethenc.com/en/browse/hadith/4801"}, "66272": {"revision": "topic001-coverage-2026-10-17", "narrator": "Abu Hurayrah", "qa": [{"id": "66272-focus-qa-1", "group": "Meaning and understanding", "q": "How does the response to a request for curses express the Prophet's mission?", "a": "Instead of accepting cursing as his defining task, he states that he was sent as a mercy. The explanation describes a source of goodness for people and explains cursing as invoking exclusion from Allah's mercy. The response makes merciful purpose central to how the request is answered.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66272", "evidence": {"label": "Published explanation", "text": "The Prophet (ﷺ) was asked to supplicate against those who associated partners with Allah, but he said: I was not sent by Allah as one who curses—invoking exclusion and expulsion from His mercy and cutting people off from good.", "url": "https://hadeethenc.com/en/browse/hadith/66272", "anchor": "exclusion and expulsion", "field": "E"}}, {"id": "66272-focus-qa-2", "group": "Meaning and understanding", "q": "What change in everyday speech follows from this example?", "a": "The benefits connect following the Prophet with guarding the tongue against swearing and cursing and showing mercy to people. Religious commitment should therefore be expressed through disciplined, constructive speech rather than eagerness to insult or invoke harm in a disagreement.", "origin": "Editorial explanation based on the linked source", "lang": "en", "source": "https://hadeethenc.com/en/browse/hadith/66272", "evidence": {"label": "Published benefit 2", "text": "The importance of keeping one's tongue pure from swearing and cursing, following the example of the Prophet (ﷺ).", "url": "https://hadeethenc.com/en/browse/hadith/66272", "anchor": "tongue pure", "field": "B2"}}], "mcq": [{"id": "66272-focus-mc-1", "q": "How does the explanation define the cursing mentioned here?", "options": ["Invoking exclusion from Allah's mercy", "Offering a reasoned disagreement", "Identifying a quotation's source", "Explaining a religious duty clearly"], "correct": 0, "feedback": ["The explanation defines the term through exclusion and expulsion from mercy, not every disagreement.", "The supported answer is: Invoking exclusion from Allah's mercy. The explanation defines the term through exclusion and expulsion from mercy, not every disagreement.", "The supported answer is: Invoking exclusion from Allah's mercy. The explanation defines the term through exclusion and expulsion from mercy, not every disagreement.", "The supported answer is: Invoking exclusion from Allah's mercy. The explanation defines the term through exclusion and expulsion from mercy, not every disagreement."], "hint": "Read the definition before applying it to speech.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66272", "evidence": {"label": "Published explanation", "text": "The Prophet (ﷺ) was asked to supplicate against those who associated partners with Allah, but he said: I was not sent by Allah as one who curses—invoking exclusion and expulsion from His mercy and cutting people off from good.", "url": "https://hadeethenc.com/en/browse/hadith/66272", "anchor": "exclusion and expulsion", "field": "E"}}, {"id": "66272-focus-mc-2", "q": "Which application best reflects this response?", "options": ["Make personal anger the measure of religious loyalty", "Replace sincere advice with insulting labels", "Treat mercy as permission to disregard every duty", "Respond with principled restraint rather than eagerness to curse"], "correct": 3, "feedback": ["The supported answer is: Respond with principled restraint rather than eagerness to curse. The narrated refusal and the benefits support merciful conduct and disciplined speech.", "The supported answer is: Respond with principled restraint rather than eagerness to curse. The narrated refusal and the benefits support merciful conduct and disciplined speech.", "The supported answer is: Respond with principled restraint rather than eagerness to curse. The narrated refusal and the benefits support merciful conduct and disciplined speech.", "The narrated refusal and the benefits support merciful conduct and disciplined speech."], "hint": "Connect the particular request with the character the response teaches.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66272", "evidence": {"label": "Published benefit 4", "text": "Encouragement to show mercy to people.", "url": "https://hadeethenc.com/en/browse/hadith/66272", "anchor": "mercy to people", "field": "B4"}}, {"id": "66272-focus-mc-3", "q": "To whom does the explanation describe the mission's goodness and mercy as extending?", "options": ["People generally, especially the believers", "Only those who first requested the curse", "Only people already belonging to the same family", "No one outside a single gathering"], "correct": 0, "feedback": ["The explanation describes mercy for all people, with special mention of believers.", "The supported answer is: People generally, especially the believers. The explanation describes mercy for all people, with special mention of believers.", "The supported answer is: People generally, especially the believers. The explanation describes mercy for all people, with special mention of believers.", "The supported answer is: People generally, especially the believers. The explanation describes mercy for all people, with special mention of believers."], "hint": "Read the explanation's description of the mission's reach.", "category": "Content practice", "source": "https://hadeethenc.com/en/browse/hadith/66272", "evidence": {"label": "Published explanation", "text": "I was not sent for that; rather, I was sent to be a source of goodness and mercy for all people, especially for the believers.", "url": "https://hadeethenc.com/en/browse/hadith/66272", "anchor": "all people", "field": "E"}}], "coverage": {"focusedAnswers": 2, "thematicQuestions": 3, "completeSanadProvided": false, "topics": [{"point": "Refusal of the request for curses and a mission of mercy", "qa": [1], "mcq": [1, 2]}, {"point": "Cursing as exclusion from mercy and disciplined everyday speech", "qa": [1, 2], "mcq": [1, 2]}, {"point": "Goodness for people generally, especially believers", "qa": [1], "mcq": [3]}]}, "source": "https://hadeethenc.com/en/browse/hadith/66272"}};